protected const array ID2DESC = [
0=>['No Skill','Empty skill slot','Empty slot'],
1=>['Sygnet Uzdrowienia','Sygnet. Otrzymujesz 82...172 pkt. żywotności. W czasie używania tej umiejętności wartość twojego pancerza zmniejsza się o 40 pkt.','Sygnet. Otrzymujesz 82...172 pkt. żywotności. W czasie używania tej umiejętności twój pancerz zmniejsza się o 40.'],
2=>['Sygnet Wskrzeszenia','Sygnet. Wskrzeszasz wybranego członka drużyny. Wraca on do życia z 100% punktów żywotności i 25% punktów energii. Ten sygnet odnawia się tylko, gdy podniesie się twoje morale.','Sygnet. Wskrzesza wybranego członka drużyny (100% żywotności, 25% energii). Ten sygnet odnowi się tylko po tym, jak otrzymasz premię "zwiększone morale".'],
3=>['Sygnet Przechwycenia','Sygnet. Wybierz umiejętność, spośród tych, które posiada martwy boss twojej profesji leżący w pobliżu. Sygnet Przechwycenia zostanie na stałe zamieniony na tą umiejętność. Jeśli była to umiejętność elitarna, to za każdy swój poziom otrzymujesz 250 PD.','Sygnet. Wybierz umiejętność, spośród tych które posiada martwy boss twojej profesji leżący w pobliżu. Sygnet Przechwycenia zostanie na stałe zamieniony na tą umiejętność. Jeśli była to umiejętność elitarna, to za każdy swój poziom otrzymujesz po 250 PD.'],
5=>['Blokada Mocy','Elitarny czar. Jeśli cel rzuca właśnie czar lub pieśń, umiejętność ta oraz wszystkie umiejętności tego atrybutu zostają zablokowane na 1...12 sek., a użycie umiejętności zostaje przerwane.','Elitarny czar. Jeśli cel rzuca właśnie czar lub pieśń, umiejętność ta oraz wszystkie umiejętności tego atrybutu zostają zablokowane (1...12 sek.), a użycie umiejętności zostaje przerwane.'],
6=>['Mantra Ziemi','Postawa. Przez 30...90 sek., za każdym razem, kiedy otrzymujesz obrażenia od ziemi, obrażenia zostają zmniejszone o 26...50% i zyskujesz 2 punkty energii.','Postawa. (30...90 sek.) Obrażenia od ziemi, jakie otrzymujesz, zmniejszane są o 26...50%. Kiedy otrzymujesz obrażenia od ziemi, dostajesz 2 pkt. energii.'],
7=>['Mantra Płomienia','Postawa. Przez 30...90 sek., za każdym razem, kiedy otrzymujesz obrażenia od ognia, obrażenia zostają zmniejszone o 26...50% i zyskujesz 2 punkty energii.','Postawa. (30...90 sek.) Obrażenia od ognia, jakie otrzymujesz, zmniejszane są o 26...50%. Kiedy otrzymujesz obrażenia od ognia, dostajesz 2 pkt. energii.'],
8=>['Mantra Mrozu','Postawa. Przez 30...90 sek., za każdym razem, kiedy otrzymujesz obrażenia od zimna, obrażenia są zmniejszone o 26...50% i zyskujesz 2 punkty energii.','Postawa. (30...90 sek.) Obrażenia od zimna, jakie otrzymujesz, zmniejszane są o 26...50%. Kiedy otrzymujesz obrażenia od zimna, dostajesz 2 pkt. energii.'],
9=>['Mantra Błyskawicy','Postawa. Przez 30...90 sek., za każdym razem, kiedy otrzymujesz obrażenia od błyskawic, obrażenia zostają zmniejszone o 26...50% i zyskujesz 2 punkty energii.','Postawa. (30...90 sek.) Obrażenia od błyskawic, jakie otrzymujesz, zmniejszane są o 26...50%. Kiedy otrzymujesz obrażenia od błyskawic, dostajesz 2 pkt. energii.'],
10=>['Łamacz Klątw','Postawa. Przez 5...80 sek., następnym razem, gdy jesteś celem klątwy, klątwa ta nie zadziała, a rzucający ją otrzymuje 10...46 pkt. obrażeń.','Postawa. (5...80 sek.) Następna klątwa rzucana na ciebie nie dochodzi do skutku, a rzucający ją otrzymuje 10...46 pkt. obrażeń.'],
11=>['Zniekształcenie','Postawa. Przez 1...5 sek., masz 75% szans na zablokowanie ataków. Za każdym razem, kiedy zablokujesz w ten sposób atak, tracisz 2 pkt. energii albo Zniekształcenie przestanie działać.','Postawa. (1...5 sek.) Masz 75% szans na blokowanie. Koszt blokowania: tracisz 2 pkt. energii lub Zniekształcenie przestaje działać.'],
13=>['Mantra Odzyskiwania','Postawa elitarna. Przez 5...20 sek., rzucane przez ciebie czary odnawiają się o 33% szybciej.','Postawa elitarna. (5...20 sek.) Twoje czary odnawiają się o 33% szybciej.'],
14=>['Mantra Wytrwałości','Postawa. Przez 5...25 sek. twoje klątwy z Magii Iluzji trwają o 10...40% dłużej.','Postawa. (5...25 sek.) Klątwy Magii Iluzji jakie rzucasz trwają o 10...40% dłużej.'],
15=>['Mantra Inskrypcji','Postawa. Przez 5...25 sek. twoje sygnety, które z powodzeniem aktywujesz przyjąwszy tę postawę, odnawiają się o 10...40% szybciej.','Postawa. (5...25 sek.) Twoje sygnety, które z powodzeniem aktywujesz przyjąwszy tę postawę, odnawiają się o 10...40% szybciej.'],
16=>['Mantra Koncentracji','Postawa. Przez 1...38 sek., następnym razem, gdy twoje czynności byłyby przerwane, nie są one przerywane.','Postawa. (1...38 sek.) Następnym razem, gdy twoje czynności byłyby przerwane, nie są one przerywane.'],
17=>['Mantra Zdecydowania','Postawa. Przez 30...90 sek., twoje czynności nie mogą być przerwane, ale za każdym razem, gdy byłyby przerwane, tracisz 10...4 pkt. energii albo Mantra Zdecydowania przestanie działać.','Postawa. (30...90 sek.) Chroni cię przed przerwaniami. Koszt ochrony: utrata 10...4 pkt. energii lub koniec Mantry Zdecydowania.'],
18=>['Mantra Sygnetów','Postawa. Przez 10...40 sek., otrzymujesz +3 do pancerza za każdy sygnet na wyposażeniu. Za każdym razem gdy użyjesz jakiegoś sygnetu, otrzymujesz 5...60 żywotności.','Postawa. (10...40 sek.) Otrzymujesz +3 do pancerza za każdy sygnet na wyposażeniu. Za każdym razem gdy użyjesz jakiegoś sygnetu, otrzymujesz 5...60 żywotności.'],
19=>['Kruchość','Klątwa (czar). Przez 8...20 sek., wybrany cel i sąsiadujący przeciwnicy otrzymują 5...20 pkt. obrażeń za każdym razem, kiedy zaczynają cierpieć lub zdrowieć z przypadłości.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (8...20 sek.). Przeciwnicy ci otrzymują 5...20 obrażeń za każdym razem gdy tracą lub otrzymują jakąś przypadłość.'],
21=>['Inspirujące Zaklęcie','Czar. Z wybranego przeciwnika zdejmujesz jedno zaklęcie i otrzymujesz 3...15 pkt. energii. Na 20 sekund Inspirujące Zaklęcie zostaje zastąpione zdjętym zaklęciem.','Czar. Z wybranego przeciwnika usuwa zaklęcie. Efekty usunięcia: otrzymujesz 3...15 pkt. energii; ten czar zamieniany jest na to zaklęcie (20 sek.).'],
22=>['Inspirująca Klątwa','Czar. Z wybranego sojusznika zdejmujesz jedną klątwę i otrzymujesz 4...10 pkt. energii. Na 20 sekund Inspirująca Klątwa zostaje zastąpiona zdjętą klątwą.','Czar. Z wybranego sojusznika usuwa jedną klątwę. Efekty usunięcia: otrzymujesz 4...10 pkt. energii; ten czar zamieniany jest na tę klątwę (20 sek.).'],
23=>['Uderzenie Mocy','Czar. Jeśli wybrany przeciwnik rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a cel otrzymuje 30...120 pkt. obrażeń.','Czar. Przerywa użycie czaru lub pieśni. Skutek przerwania: zadaje 30...120 pkt. obrażeń.'],
24=>['Wyciek Mocy','Czar. Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a cel traci 3...17 pkt. energii.','Czar. Przerywa użycie czaru lub pieśni. Skutek przerwania: powoduje utratę 3...17 pkt. energii.'],
25=>['Wyssanie Mocy','Czar. Jeśli wybrany przeciwnik rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a ty otrzymujesz 1...31 pkt. energii.','Czar. Przerywa czar lub zaśpiew. Efekt przerwania: otrzymujesz 1...31 pkt. energii.'],
26=>['Empatia','Klątwa (czar). Przez 5...15 sek., za każdym razem, kiedy wybrany przeciwnik atakuje, ten przeciwnik otrzymuje 10...55 pkt. obrażeń, a sam zadaje 1...15 obrażeń mniej.','Klątwa (czar). (5...15 sek.) Wybrany przeciwnik otrzymuje 10...55 pkt. obrażeń za każdym razem, kiedy atakuje, i zadaje 1...15 pkt. obrażeń mniej każdym swoim atakiem.'],
27=>['Rozbicie Urojeń','Czar. Zdejmij jedną klątwę mesmera z wybranego przeciwnika. Jeśli klątwa zostanie usunięta, to ten przeciwnik odniesie 15...75 pkt. obrażeń, wszyscy wrogowie w jego bezpośrednim sąsiedztwie odniosą 75% tych obrażeń.','Czar. Zdejmuje jedną klątwę mesmera z wyznaczonego przeciwnika. Skutek zdjęcia: 15...75 pkt. obrażeń dla celu i 75% tych obrażeń dla wszystkich sąsiednich przeciwników.'],
28=>['Wypalanie','Klątwa (czar). Przez 10 sek., za każdym razem, kiedy wybrany przeciwnik rzuca czar, ten przeciwnik otrzymuje 35...140 pkt. obrażeń.','Klątwa (czar). (10 sek.) Wybrany przeciwnik otrzymuje 35...140 pkt. obrażeń, za każdym razem, kiedy rzuca czar.'],
29=>['Zaciemnienie','Umiejętność. Przez 2...8 sek., wszystkie umiejętności wybranego dotkniętego przeciwnika zostają wyłączone, a twoje umiejętności zostają wyłączone na 5 sek.','Umiejętność dotykowa. (2...8 sek.) Wyłącza umiejętności. Twoje umiejętności są wyłączone (5 sek.).'],
30=>['Dywersja','Klątwa (czar). Przez 6 sek., następnym razem, gdy wybrany przeciwnik użyje umiejętności, ta umiejętność odnawia się o 10...56 sek. dłużej.','Klątwa (czar). (6 sek.) Następna umiejętność wybranego przeciwnika będzie się odnawiała o +10...56 sek. dłużej.'],
31=>['Przyzwanie Widziadła','Klątwa (czar). Przez 4...18 sek., wybrany przeciwnik odczuwa -5 degeneracji żywotności.','Klątwa (czar). (4...18 sek.) Powoduje degenerację żywotności -5.'],
32=>['Iluzja Słabości','Zaklęcie (czar). Tracisz 50...240 pkt. żywotności. Iluzja Słabości przestanie działać jeżeli obrażenia spowodują spadek pkt. żywotności poniżej 25% wartości maksymalnej. Gdy Iluzja Słabości przestanie działać, otrzymujesz 50...240 pkt. żywotności.','Zaklęcie (czar). Utrata 50...240 pkt. żywotności. Efekt końcowy: otrzymujesz 50...240 pkt. żywotności. Koniec, jeżeli obrażenia sprowadzą twoją żywotność poniżej 25% jej maksymalnej wartości.'],
33=>['Iluzoryczna Broń','Elitarne zaklęcie (czar). Przez 30 sekund, twoje ataki wręcz nie trafiają ani nie chybiają. Zamiast tego Iluzoryczna Broń zadajee 20...60 pkt. obrażeń twoim celom przy każdym ataku wręcz. Otrzymujesz +5 do pancerza za każdą umiejętność magii iluzji, jaką masz na wyposażeniu.','Elitarne zaklęcie (czar). (30 sek.) Zadaje 20...60 pkt. obrażeń przeciwnikom zamiast innych obrażeń lub efektów z ataków wręcz. Otrzymujesz +5 do pancerza za każdą umiejętność magii iluzji na wyposażeniu. Twoje ataki wręcz nie trafiają ani nie chybiają.'],
34=>['Życzliwe Oblicze','Zaklęcie (czar). Przez 4...10 sek., za każdym razem, kiedy wybrany sojusznik zostanie trafiony atakiem wręcz, wszyscy przeciwnicy bezpośrednio przy nim stracą całą adrenalinę i 3 punkty energii.','Zaklęcie (czar). (4...10 sek.) Wszyscy przeciwnicy w kontakcie tracą adrenalinę i 3 pkt. energii, za każdym razem, kiedy atak wręcz trafi wybranego sojusznika.'],
35=>['Ignorancja','Klątwa (czar). Przez 8...20 sek. wybrany przeciwnik nie może używać sygnetów.','Klątwa (czar). (8...20 sek.) Wybrany przeciwnik nie może używać sygnetów.'],
36=>['Magiczna Zagadka','Klątwa (czar). Przez 5...15 sek., wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim rzucają czary dwa razy dłużej niż normalnie. Kiedy ta klątwa się skończy, otrzymujesz 1...7 energii.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (5...15 sek.). Podwaja czas rzucania czarów. Efekt końcowy: otrzymujesz 1...7 energii.'],
37=>['Iluzja Pośpiechu','Zaklęcie (czar). Przez 5...11 sek., nie jesteś już okulawiony i poruszasz się o 33% szybciej. Gdy Iluzja Pośpiechu przestanie działać, zostajesz okulawiony na 3 sek.','Zaklęcie (czar). (5...11 sek.) Poruszasz się o 33% szybciej. Efekt początkowy: usuwa przypadłość okulawienia. Efekt końcowy: zostajesz okulawiony (3 sek.).'],
38=>['Czerpanie Mocy','Zaklęcie (czar). Przez 8...56 sek., za każdym razem, kiedy rzucasz czar, zyskujesz 1 punkt energii za każdego przeciwnika w okolicy.','Zaklęcie (czar). (8...56 sek.) Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 pkt. energii za każdego przeciwnika w okolicy.'],
39=>['Udar Energetyczny','Elitarny czar. Wybrany przeciwnik traci 1...10 pkt. energii. Za każdy stracony punkt energii, ten przeciwnik odnosi 7 pkt. obrażeń, a wszyscy przeciwnicy znajdujący się w jego bezpośrednim sąsiedztwie odnoszą 75% tych obrażeń.','Elitarny czar. Powoduje utratę 1...10 pkt. energii. Za każdy punkt straconej energii wybrany przeciwnik otrzymuje 7 pkt. obrażeń, a przeciwnicy w pobliżu otrzymują 75% tych obrażeń.'],
40=>['Eteryczna Uczta','Czar. Wybrany przeciwnik traci 3 punkty energii. Zyskujesz 20...65 pkt. życia za każdy stracony przez przeciwnika punkt energii.','Czar. Powoduje utratę 3 pkt. energii. Za każdy punkt straconej energii otrzymujesz 20...65 pkt. żywotności.'],
41=>['Władca Eteru','Klątwa (czar). Tracisz całą energię. Przez 5...10 sek., wybrany przeciwnik cierpi na -1...3 degeneracji energii, a ty otrzymujesz +1...3 regeneracji energii.','Klątwa (czar). Tracisz całą energię. Wybrany przeciwnik posiada degenerację energii -1...3, a ty posiadasz regenerację energii +1...3 (5...10 sek.).'],
42=>['Wypalanie Energii','Czar. Wybrany przeciwnik traci 1...10 pkt. energii i otrzymuje 9 pkt. obrażeń za każdy stracony punkt energii.','Czar. Powoduje utratę 1...10 pkt. energii. Za każdy punkt straconej energii zadaje 9 pkt. obrażeń.'],
43=>['Niezgrabność','Klątwa (czar). Przez 4 sek. wybrany przeciwnik i przeciwnicy w bezpośredniej odległości znajdują się pod wpływem klątwy Niezgrabność. Kiedy następnym razem każdy z nich spróbuje zaatakować, atak zostanie przerwany, a przeciwnik otrzyma 10...80 pkt. obrażeń.','Klątwa (czar). (4 sek.) Klątwa działa także na przeciwników w bezpośredniej odległości. Przerywa następny atak wybranego przeciwnika. Efekt przerwania: zadaje 10...80 pkt. obrażeń.'],
44=>['Widmowy Ból','Klątwa (czar). Przez 10 sek., wybrany przeciwnik cierpi -1...4 degeneracji żywotności. Gdy Widmowy Ból przestanie działać, ten przeciwnik otrzymuje Głęboką Ranę, obniżając maksymalną żywotność przeciwnika o 20% na 5...20 sek.','Klątwa (czar). (10 sek.) Powoduje degenerację żywotności -1...4. Efekt końcowy: wywołuje przypadłość głęboka rana (5...20 sek.).'],
45=>['Eteryczne Brzemię','Klątwa (czar). Przez 6...12 sek., wybrany przeciwnik porusza się 50% wolniej. Gdy Eteryczne Brzemię przestanie działać, otrzymujesz 10...18 pkt. energii.','Klątwa (czar). (6...12 sek.) Wybrany przeciwnik porusza się o 50% wolniej. Efekt końcowy: otrzymujesz 10...18 pkt. energii.'],
46=>['Wina','Klątwa (czar). Przez 6 sek., następnym razem, kiedy wybrany przeciwnik rzuca czar wymierzony we wroga, czar zawodzi, a ty wykradasz przeciwnikowi do 5...14 pkt. energii.','Klątwa (czar). (6 sek.) Następny czar wybranego przeciwnika nie zadziała, a ty wykradasz 5...14 pkt. energii. Bez efektu, chyba że jeden z twoich sojuszników jest celem czaru tego przeciwnika.'],
47=>['Niezdarność','Elitarna klątwa (czar). Przez 4 sek., następnym razem, kiedy wybrany przeciwnik lub jakikolwiek wróg w sąsiedztwie zaatakuje, otrzyma 30...135 pkt. obrażeń i zostanie oślepiony na 10 sek.','Elitarna klątwa (czar). (4 sek.) Klątwa działa także na wrogów bezpośrednio przy celu. Zadaje 30...135 pkt. obrażeń. Powoduje oślepienie (10 sekund). Bez efektu, jeśli wróg pod działaniem tej klątwy nie zaatakuje.'],
48=>['Duch Porażki','Klątwa (czar). Przez 30 sek., wybrany przeciwnik ma 25% szans na nieudany atak. Zyskujesz 1...3 pkt. energii za każdym razem, kiedy ten przeciwnik nie trafi.','Klątwa (czar). (30 sek.) Wybrany przeciwnik ma 25% szans na nietrafianie. Ty otrzymujesz 1...3 pkt. energii, za każdym razem, kiedy ten przeciwnik nie trafia.'],
49=>['Spustoszenie Umysłu','Klątwa (czar). Przez 5...40 sek., za każdym razem gdy wybrany przeciwnik jest celem dowolnej z twoich umiejętności mesmera (oprócz klątw), traci on 1 pkt. energii i otrzymuje 5...25 pkt. obrażeń za każdy stracony punkt energii. Jeśli energia wroga spadnie do 0, Spustoszenie Umysłu przestaje działać, a przeciwnik otrzymuje 15...100 pkt. obrażeń.','Klątwa (czar). (5...40 sek.) Powoduje utratę 1 pkt. energii, za każdym razem gdy przeciwnik jest celem twoich umiejętności mesmera (oprócz klątw). Zadaje 5...25 obrażeń za każdy stracony punkt energii. Jeśli energia wroga spadnie do 0, otrzymuje on 15...100 pkt. obrażeń, a Spustoszenie Umysłu dobiega końca.'],
50=>['Zmartwienie Marnotrawcy','Klątwa (czar). Po 3 sek. wybrany przeciwnik odniesie 20...100 pkt. obrażeń, a wszyscy sąsiadujący z nim wrogowie odniosą 75% tych obrażeń. Jeśli wybrany przeciwnik zdoła użyć umiejętności, Zmartwienie Marnotrawcy przestanie działać i nie zadaje obrażeń.','Klątwa (czar). (3 sek.). Efekt końcowy: zadaje 20...100 pkt. obrażeń przeciwnikowi i 75% tych obrażeń sąsiadującym z nim wrogom. Nie ma efektu i kończy się wcześniej, jeżeli wybrany przeciwnik używa umiejętności.'],
51=>['Wstyd','Klątwa (czar). Przez 6 sek., następnym razem, kiedy wybrany przeciwnik rzuca czar wymierzony w swojego sojusznika, czar zawodzi, a ty wykradasz przeciwnikowi do 5...14 pkt. energii.','Klątwa (czar). (6 sek.) Następny czar wybranego przeciwnika nie zadziała, a ty wykradasz 5...14 pkt. energii. Bez efektu, chyba że celem czaru tego przeciwnika jest jeden z jego sojuszników.'],
52=>['Panika','Elitarna klątwa (czar). Przez 1...10 sek., wybrany przeciwnik i wszyscy wrogowie w jego pobliżu znajdują sie pod działaniem Paniki. Kiedy spanikowany przeciwnik użyje umiejętności, akcje wszystkich pobliskich wrogów zostają przerwane.','Elitarna klątwa (czar). Klątwa działa także na wrogów w pobliżu celu (1...10 sek.). Przerywa akcje wszystkich pobliskich wrogów, za każdym razem, gdy przeciwnik z klątwą uaktywni jakąś umiejętność.'],
53=>['Migrena','Elitarna klątwa (czar). Przez 5...20 sek., wybrany przeciwnik cierpi na -1...8 degeneracji pkt. żywotności oraz uaktywnia umiejętności 100% dłużej.','Elitarna klątwa (czar). (5...20 sek.) Powoduje degenerację żywotności -1...8 i dwukrotnie wydłuża czas aktywacji umiejętności.'],
54=>['Okulawiające Katusze','Elitarna klątwa (czar). Przez 5...20 sek., cel porusza się i atakuje 50% wolniej, otrzymuje też -1...8 do regeneracji zdrowia.','Elitarna klątwa (czar). (5...20 sek.) Cel porusza się i atakuje 50% wolniej, otrzymuje też -1...8 do regeneracji zdrowia.'],
55=>['Gorączkowe Sny','Elitarna klątwa (czar). Przez 10...25 sek., za każdym razem, kiedy wybrany przeciwnik zaczyna cierpieć na nową przypadłość, wszyscy przeciwnicy w okolicy zaczynają cierpieć na tą samą przypadłość. Jeśli przeciwnik cierpi na dwie lub więcej przypadłości, zostaje on ponadto oszołomiony na 1...3 sek.','Elitarna klątwa (czar). (10...25 sek.) Przeciwnicy w okolicy otrzymują wszystkie nowe przypadłości, które dostaje wybrany przeciwnik. Wywołuje przypadłość oszołomienie (1...3 sek.), jeżeli wybrany przeciwnik cierpi na dwie lub więcej przypadłości.'],
56=>['Kojące Wizje','Klątwa (czar). Przez 8...20 sek., wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim nie zdobywają adrenaliny.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (8...20 sek.). Przeciwnicy ci nie mogą otrzymywać adrenaliny.'],
57=>['Krzyk Frustracji','Czar. Jeżeli wybrany przeciwnik używa umiejętności, czynności tego przeciwnika i wszystkich wrogów w okolicy zostają przerwane. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń, a pobliscy wrogowie otrzymują 75% tych obrażeń.','Czar. Jeżeli wybrany przeciwnik używa umiejętności, czynności tego przeciwnika i wszystkich wrogów w okolicy zostają przerwane. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń, a pobliscy wrogowie otrzymują 75% tych obrażeń.'],
58=>['Sygnet Północy','Sygnet elitarny. Ty i wybrany dotknięty przeciwnik ślepniecie na 15 sekund.','Elitarny sygnet dotykowy. (15 sek.) Wywołuje przypadłość oślepienie. Zostajesz oślepiony (15 sek.).'],
59=>['Sygnet Zmęczenia','Sygnet. Wybrany przeciwnik i wszyscy pobliscy wrogowie tracą 3...8 energii i zostają Osłabieni na 1...12 sek.','Sygnet. Działa także na przeciwników w pobliżu celu. Powoduje utratę 3...8 energii oraz Osłabienie (1...12 sek).'],
61=>['Sygnet Pijawki','Sygnet. Przerywasz czynność wybranego przeciwnika. Jeżeli tą czynnością było rzucanie czaru, otrzymujesz 3...15 pkt. energii.','Sygnet. Przerywa czynność. Efekt przerwania: jeżeli czynnością było rzucanie czaru, otrzymujesz 3...15 pkt. energii.'],
62=>['Sygnet Pokory','Sygnet. Elitarna umiejętność wybranego przeciwnika zostaje wyłączona na 1...16 sek. Wszystkie twoje umiejętności nie należące do mesmera będą niedostępne przez 4 sek.','Sygnet. Wyłącza umiejętność elitarną (1...16 sek.). Wyłącza twoje umiejętności nie należące do mesmera (4 sek.).'],
63=>['Sygnet Klucza','Sygnet elitarny. Wszystkie twoje sygnety poza Sygnetem Klucza zostają odnowione. Przez 20 sek., następne 0...6 razy kiedy użyjesz sygnetu działającego na wroga, wszyscy wrogowie sąsiadujący z twoim celem otrzymają 15...60 pkt. obrażeń i przerwą wykonywanie akcji.','Sygnet elitarny. (20 sek.) Twoje kolejne (0...6) sygnety przerywają wykonywanie akcji przeciwników sąsiadujących z twoim celem i zadają im 15...60 pkt. obrażeń. Efekt początkowy: odnawia wszystkie twoje pozostałe sygnety.'],
65=>['Magiczna Mimikra','Czar. Na 20 sek. Magiczna Mimikra staje się elitarną umiejętnością nie związaną z przemianą, należącą do wybranego sojusznika innego niż ty.','Czar. Ta umiejętność zamieniana jest na umiejętność elitarną sojusznika (20 sek.). Na cel nie można wybrać siebie. Bez efektu, jeśli umiejętność elitarna związana jest z przemianą formy.'],
66=>['Duchowe Okowy','Klątwa (czar). Przez 5...20 sek., wybrany przeciwnik traci 5 pkt. energii za każdym razem, kiedy ten przeciwnik atakuje.','Klątwa (czar). (5...20 sek.) Wybrany przeciwnik traci 5 punkty energii, za każdym razem, kiedy zaatakuje.'],
67=>['Rozbicie Klątwy','Czar. Z wybranego sojusznika usuwasz jedną klątwę. Jeśli klątwa zostanie usunięta, to każdy przeciwnik w pobliżu sojusznika otrzyma 30...120 pkt. obrażeń.','Czar. Z wybranego sojusznika usuwa jedną klątwę. Efekt usunięcia: zadaje po 30...120 pkt. obrażeń przeciwnikom w pobliżu tego sojusznika.'],
68=>['Wyssanie Zaklęcia','Czar. Z wybranego przeciwnika usuwasz jedno zaklęcie. Jeżeli zaklęcie zostało usunięte, otrzymujesz 8...17 pkt. energii i 40...120 pkt. żywotności.','Czar. Z wybranego przeciwnika usuwa zaklęcie. Efekt usunięcia: otrzymujesz 8...17 pkt. energii i 40...120 pkt. żywotności.'],
69=>['Rozbicie Zaklęcia','Czar. Z wybranego przeciwnika usuwasz jedno zaklęcie. Jeśli zaklęcie zostanie usunięte, to ten przeciwnik otrzymuje 14...100 pkt. obrażeń.','Czar. Z wybranego przeciwnika usuwa zaklęcie. Efekt usunięcia: zadaje 14...100 pkt. obrażeń.'],
72=>['Odporność na Żywioły','Postawa. Przez 30...90 sek., zyskujesz +40 pkt. pancerza przeciw obrażeniom od żywiołów, ale tracisz 24...12 pkt. pancerza przeciw obrażeniom fizycznym.','Postawa. (30...90 sek.) Posiadasz +40 pkt. pancerza przeciwko obrażeniom od żywiołów. Przeciwko obrażeniom fizycznym posiadasz -24...12 pkt. pancerza.'],
73=>['Fizyczna Odporność','Postawa. Przez 30...90 sek., zyskujesz +40 pkt. pancerza przeciw obrażeniom fizycznym, ale tracisz 24...12 pkt. pancerza przeciw obrażeniom od żywiołów.','Postawa. (30...90 sek.) Posiadasz +40 pkt. pancerza przeciwko obrażeniom fizycznym. Przeciwko obrażeniom od żywiołów posiadasz -24...12 pkt. pancerza.'],
74=>['Echo','Elitarne zaklęcie (czar). W ciągu 30 sek. Echo zostaje zastąpione następną umiejętnością jakiej użyjesz. Echo zachowuje się jak ta umiejętność przez 30 sek.','Elitarne zaklęcie (czar). (30 sek.) Echo zamienia się w następną umiejętność, której użyjesz (30 sek.).'],
75=>['Magiczne Echo','Zaklęcie (czar). Jeżeli rzucisz czar w przeciągu następnych 20 sek., Magiczne Echo zostanie zastąpione przez ten czar na 20 sek. Magiczne Echo przestanie działać przedwcześnie, jeżeli użyjesz umiejętności innej niż czar.','Zaklęcie (czar). (20 sek.) Magiczne Echo zamienia się w następny czar, którego użyjesz (20 sek.). To zaklęcie przestanie działać, jeśli użyjesz umiejętność, która nie jest czarem.'],
76=>['Urojone Brzemię','Klątwa (czar). Przez 8...20 sek., wybrany przeciwnik porusza się 50% wolniej.','Klątwa (czar). (8...20 sek.) Cel porusza się 50% wolniej.'],
77=>['Burza Chaosu','Czar. Tworzy Burzę Chaosu w miejscu, w którym znajduje się wybrany przeciwnik. Burza trwa 10 sek. Przeciwnicy bezpośrednio przy tym miejscu co sekundę otrzymują 5...25 pkt. obrażeń i tracą 0...2 energii.','Czar. W każdej sekundzie zadaje 5...25 pkt. obrażeń i powoduje utratę 0...2 energii (10 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu pobytu celu.'],
78=>['Epidemia','Czar. Przenieś wszystkie przypadłości, wraz z ich pozostałymi czasami działania, z wybranego przeciwnika na wszystkich przeciwników bezpośrednio przy z nim.','Czar. Przypadłości wybranego przeciwnika przenoszą się na przeciwników bezpośrednio przy nim.'],
79=>['Wyssanie Energii','Elitarny czar. Wybrany przeciwnik traci 2...9 pkt. energii. Zyskujesz 3 punkty energii za każdy punkt energii stracony przez przeciwnika.','Elitarny czar. Powoduje utratę 2...9 pkt. energii. Otrzymujesz 3 punkty energii za każdy punkt straconej energii.'],
80=>['Pobranie Energii','Czar. Wybrany przeciwnik traci 4...7 pkt. energii. Zyskujesz 2 punkty energii za każdy stracony przez przeciwnika punkt energii.','Czar. Powoduje utratę 4...7 pkt. energii. Otrzymujesz 2 punkty energii za każdy punkt straconej energii.'],
81=>['Magiczne Złodziejstwo','Czar. Na 5...35 sek. jeden losowy czar wybranego przeciwnika zostaje wyłączony, a Magiczne Złodziejstwo zostaje zastąpione tym czarem.','Czar. (5...35 sek.) Wyłącza jeden losowy czar. Ta umiejętność staje się tym czarem.'],
82=>['Mantra Przypomnienia','Elitarne zaklęcie (czar). Przez 20 sek., nic nie zyskujesz. Gdy Mantra Przypomnienia przestanie działać, otrzymujesz 10...25 pkt. energii.','Elitarne zaklęcie (czar). (20 sek.) Efekt końcowy: otrzymujesz 10...25 pkt. energii.'],
83=>['Ożywienie Kościanej Poczwary','Czar. Wykorzystaj najbliższe zwłoki by ożywić Kościaną Poczwarę na 1...17 poziomie.','Czar. Tworzy kościaną poczwarę na poziomie 1...17. Zużywa świeże ciało.'],
84=>['Ożywienie Kościanego Biesa','Czar. Wykorzystaj najbliższe zwłoki, by ożywić Kościanego Biesa na 1...17 poziomie. Kościane biesy potrafią atakować z odległości.','Czar. Tworzy kościanego biesa na poziomie 1...17, który potrafi atakować na odległość. Zużywa świeże ciało.'],
85=>['Ożywienie Kościanych Sługusów','Czar. Wykorzystaj najbliższe zwłoki, by ożywić dwóch Kościanych Sługusów na 0...12 poziomie.','Czar. Tworzy dwóch kościanych sługusów na poziomie 0...12. Zużywa świeże ciało.'],
86=>['Równowaga Grentha','Elitarny czar. Jeżeli wybrany przeciwnik ma więcej pkt. żywotności niż ty, otrzymujesz połowę tej różnicy (aż do maksymalnego poziomu pkt. żywotności), a ten przeciwnik traci taką samą ilość. Jeżeli ten przeciwnik ma mniej pkt. żywotności niż ty, tracisz połowę tej różnicy, a ten przeciwnik otrzymuje taką samą ilość.','Elitarny czar. Otrzymujesz punkty żywotności w liczbie równej połowie różnicy pomiędzy żywotnością twoją, a przeciwnika, z kolei przeciwnik traci tę liczbę punktów żywotności. Jeżeli ten przeciwnik posiada mniej żywotności niż ty, to tracisz punkty żywotności w liczbie równej połowie tej różnicy, z kolei przeciwnik otrzymuje tę liczbę punktów żywotności.'],
87=>['Spojrzenie Veraty','Czar. Jeżeli wybrany wrogi wskrzeszony truposz ma pana, jego więź z panem zostaje zerwana, tworząc go wrogim wobec wszelkich stworzeń. Jeżeli nie miał pana, ty stajesz się jego panem i leczysz go, przywracając mu 60...80 żywotności. (50% szans na niepowodzenie, gdy wartość Magii Śmierci wynosi 4 lub mniej).','Czar. Powoduje, że wybrany nieumarły sługa staje się bezpańskim. Jeżeli już jest bezpański, to ty stajesz się jego panem i leczysz go, przywracając mu 60...80 żywotności. 50% szans na niepowodzenie, chyba że wartość Magii Śmierci wynosi 5 lub więcej.'],
88=>['Aura Veraty','Zaklęcie (czar). Wszystkie wrogie wskrzeszone sługi w okolicy stają się twoimi sługami. Aura Veraty przestanie działać po 120...300 sek. Gdy Aura Veraty przestanie działać, tracisz władzę nad wszystkimi truposzami. (50% szans na niepowodzenie, gdy Magia Śmierci wynosi 4 lub mniej.)','Zaklęcie (czar). (120...300 sek.) Zostajesz panem wszystkich wrogo nastawionych nieumarłych sług w okolicy. Efekt końcowy: twoi nieumarli słudzy stają się bezpańscy. 50% szans na niepowodzenie, chyba że wartość Magii Śmierci wynosi 5 lub więcej.'],
89=>['Trupi Chłód','Czar. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od zimna. Jeżeli ten przeciwnik ma ponad 50% pkt. żywotności, zdajesz dodatkowe 5...50 pkt. obrażeń od cienia.','Czar. Zadaje 5...50 pkt. obrażeń od zimna. Zadaje 5...50 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik ma powyżej 50% żywotności.'],
90=>['Ofiara Veraty','Czar. Przez 5...10 sek. twoje wskrzeszone sługi posiadają regenerację żywotności +10. Wszystkie przypadłości zostają z nich przeniesione na ciebie. Ten czar odnawia się natychmiastowo, jeżeli czar zadziałał, a ty dowodzisz 3 lub mniej sługami.','Czar. (5...10 sek.) Zaprzyjaźnieni nieumarli słudzy w liczbie 10 otrzymują regenerację żywotności +10. Natychmiast się odnawia, jeżeli władasz 3 lub mniej sługami. Przenosi wszystkie przypadłości z tych sług na ciebie.'],
91=>['Studnia Mocy','Elitarny czar studni. Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by utworzyć Studnię Mocy. Przez 10...30 sek. sojusznicy w zasięgu Studni Mocy otrzymują regenerację żywotności +1...6 i regenerację energii +2.','Elitarny czar studni. (10...30 sek.). Sojusznicy w tej studni mają regenerację żywotności +1...6 i regenerację energii +2. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
92=>['Studnia Krwi','Czar studni. Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by utworzyć Studnię Krwi. Przez 8...20 sek. sojusznicy w tym obszarze otrzymują +1...6 regeneracji żywotności.','Czar studni. (8...20 sek.). Sojusznicy w tej studni mają regenerację żywotności +1...6. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
93=>['Studnia Cierpienia','Czar studni. Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by utworzyć Studnię Cierpienia. Przez 10...30 sek. przeciwnicy w tym obszarze otrzymują -1...6 degeneracji żywotności.','Czar studni. (10...30 sek.). Przeciwnicy w tej studni mają degenerację żywotności -1...6. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
94=>['Studnia Profanacji','Czar studni. Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by utworzyć Studnię Profanacji. Przez 8...20 sek. przeciwnicy w tym obszarze tracą wszystkie zaklęcia i nie mogą być celem kolejnych zaklęć. (50% szans na niepowodzenie, gdy wartość Magii Śmierci wynosi 4 lub mniej).','Czar studni. (8...20 sek.). Przeciwnicy w tej studni tracą wszystkie zaklęcia i nie mogą być celem kolejnych zaklęć. Zużywa świeże ciało lub poświęca 66% zdrowia. 50% szans na niepowodzenie, chyba że wartość Magii Śmierci wynosi 5 lub więcej.'],
95=>['Eksplozja Zgnilizny','Czar. Zwłoki znajdujące się najbliżej twojego celu eksplodują, tworząc falę uderzeniową, która zadaje 24...120 pkt. obrażeń pobliskim wrogom.','Czar. Rozrywa ciało, zadając przeciwnikom w jego pobliżu po 24...120 pkt. obrażeń. Zużywa świeże ciało.'],
96=>['Uczta Duszy','Czar. Wykorzystaj najbliższe zwłoki by uzyskać 50...280 pkt. żywotności.','Czar. Otrzymujesz 50...280 pkt. żywotności. Zużywa świeże ciało.'],
97=>['Martwicze Przemieszczenie','Czar. Wykorzystaj przypadkowe zwłoki lub poświęć 30...20% zdrowia, aby przenieść się do wskazanego wroga. Na 6 sek. popadasz w chorobę, a wszyscy pobliscy wrogowie zostają zatruci na 5...20 sek.','Czar. Wykorzystaj przypadkowe zwłoki lub poświęć 30...20% zdrowia, aby przenieść się do wskazanego wroga. Na 6 sek. popadasz w chorobę, a wszyscy pobliscy wrogowie zostają zatruci na 5...20 sek.'],
98=>['Pożarcie Zwłok','Czar. Wykorzystaj przypadkowe zwłoki. Przenosisz się w miejsce tych zwłok i zyskujesz 25...100 pkt. żywotności oraz 5...20 pkt. energii.','Czar. Przenosisz się do wybranego ciała. Otrzymujesz 25...100 pkt. żywotności i 5...20 pkt. energii. Zużywa świeże ciało.'],
99=>['Pasożytnicza Więź','Klątwa (czar). Przez 20 sek., wybrany przeciwnik cierpi -1 degeneracji żywotności. Rzucający ten czar otrzymuje 30...120 pkt. Żywotności gdy Pasożytnicza Więź przestanie działać.','Klątwa (czar). (20 sek.) Powoduje degenerację żywotności -1. Efekt końcowy: odzyskujesz 30...120 pkt. żywotności.'],
100=>['Ciernie Duszy','Klątwa (czar). Przez 30 sek. wybrany przeciwnik otrzymuje 15...30 pkt. obrażeń za każdym razem, gdy jest na niego rzucane zaklęcie lub klątwa.','Klątwa (czar). (30 sek.) Zadaje 15...30 pkt. obrażeń, kiedy wybrany przeciwnik otrzymuje klątwę lub zaklęcie.'],
101=>['Ciernie','Klątwa (czar). Przez 30 sek., wybrany przeciwnik otrzymuje 4...16 dodatkowych obrażeń gdy otrzymuje fizyczne obrażenia.','Klątwa (czar). (30 sek.) Wybrany przeciwnik otrzymuje 4...16 pkt. obrażeń, za każdym razem, kiedy otrzymuje obrażenia fizyczne.'],
102=>['Uderzenie Cienia','Czar. Wybrany przeciwnik otrzymuje 12...48 pkt. obrażeń od cienia. Jeżeli ten przeciwnik ma ponad 50% pkt. żywotności, wykradasz mu 12...48 pkt. żywotności.','Czar. Zadaje 12...48 pkt. obrażeń. Wykrada do 12...48 pkt. żywotności, jeżeli ten przeciwnik miał powyżej 50% żywotności.'],
103=>['Cena Porażki','Klątwa (czar). Przez 30 sek., wybrany przeciwnik ma 25% szansy na nieudany atak i otrzymuje 1...46 pkt. obrażeń za każdym razem, kiedy spudłuje w walce.','Klątwa (czar). (30 sek.) 25% szans na nietrafianie. Wybrany przeciwnik otrzymuje 1...46 pkt. obrażeń, za każdym razem, kiedy nie trafi.'],
104=>['Zabójczy Wybuch','Zaklęcie (czar). Przez 30 sek., jeżeli wybrany sojusznik zginie, wszyscy przeciwnicy bezpośrednio przy nim otrzymają 26...100 pkt. obrażeń i zostaną zatruci na 15 sek.','Zaklęcie (czar). (30 sek.) Jeżeli wybrany sojusznik umrze, umiejętność zadaje 26...100 pkt. obrażeń przeciwnikom bezpośrednio przy nim i wywołuje u nich przypadłość zatrucie (15 sek.).'],
105=>['Śmiercionośny Rój','Czar. Śmiercionośny Rój wylatuje powoli i zadaje 30...90 pkt. obrażeń od zimna maksymalnie trzem przeciwnikom w okolicy.','Czar. Śmiercionośny Rój przemieszcza się powoli i zadaje 30...90 pkt. obrażeń od zimna. Dodatkowo trafia dwóch przeciwników w okolicy.'],
106=>['Gnijące Ciało','Czar. Wybrany cielesny przeciwnik zaczyna chorować na 10...25 sek., powoli tracąc punkty żywotności.','Czar. Wywołuje przypadłość choroba (10...25 sek.).'],
107=>['Zjadliwa Choroba','Elitarny czar. Jeżeli wybrany przeciwnik cierpi na jakąś przypadłość, to otrzymuje dodatkowo na 3...15 sek. chorobę, zatrucie i osłabienie.','Elitarny czar. Wywołuje przypadłości choroba, zatrucie oraz osłabienie (3...15 sek.). Bez efektu, chyba że ten przeciwnik już cierpi na przypadłość.'],
108=>['Cierpienie','Klątwa (czar). Przez 6...30 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu posiadają degenerację żywotności -0...3.','Klątwa (czar). Klątwa działa także na przeciwników w pobliżu celu (6...30 sek.). Ci przeciwnicy posiadają degenerację żywotności -0...3.'],
109=>['Wyssanie Życia','Klątwa (czar). Przez 12...24 sek. wybrany przeciwnik posiada degenerację żywotności -1...3, a ty posiadasz regenerację żywotności +1...3.','Klątwa (czar). (12...24 sek.) Wybrany przeciwnik posiada degenerację żywotności -1...3. Ty posiadasz regenerację żywotności +1...3.'],
110=>['Bluźniercza Uczta','Czar. Wykradasz do 10...65 pkt. żywotności od maksymalnie 1...4 przeciwników w okolicy.','Czar. Wykrada 10...65 pkt. żywotności od 1...4 przeciwników w twojej okolicy.'],
111=>['Przebudzenie Krwi','Zaklęcie (czar). Przez 20...44 sek., zyskujesz premię +2 do Magii Krwi i +2 do Klątw, ale za każdym razem, kiedy poświęcasz punkty żywotności, poświęcasz 50% więcej niż normalnie.','Zaklęcie (czar). (20...44 sek.) Otrzymujesz +2 pkt. do Magii Krwi i Klątw. Poświęcasz o 50% więcej żywotności niż normalnie.'],
112=>['Zbezczeszczenie Zaklęć','Czar. Wybrany przeciwnik i przeciwnicy w pobliżu otrzymują po 6...60 pkt. obrażeń od cienia oraz po 4...20 pkt. obrażeń od cienia za każde zaklęcie, które mają na sobie.','Czar. Wybranemu przeciwnikowi i przeciwnikom w pobliżu zadaje po 6...60 pkt. obrażeń. Zadaje 4...20 pkt. dodatkowych obrażeń za każde zaklęcie, pod którego są działaniem.'],
113=>['Skażone Ciało','Elitarne zaklęcie (czar). Przez 20...44 sek. pobliscy sojusznicy są odporni na choroby, a każdy, kto ich zaatakuje będzie chory przez 3...15 sek.','Elitarne zaklęcie (czar). (20...44 sek.) Przeciwnicy, którzy trafią sojuszników w okolicy atakiem wręcz, zachorują (3...15 sek.); sojusznik staje się niewrażliwy na chorobę.'],
114=>['Aura Licza','Elitarne zaklęcie (czar). Wszystkie ciała w zasięgu słuchu zostają zużyte, a ty wskrzeszasz kościaną poczwarę na poziomie 1...17, plus dodatkową poczwarę na każde ciało zużyte w ten sposób. Przez 5...45 sek. twój atrybut Magia Śmierci jest zwiększony o +1.','Elitarne zaklęcie (czar). Wykorzystuje wszystkie ciała w zasięgu słuchu. Wskrzesza kościaną poczwarę na poziomie 1...17, plus dodatkową poczwarę na każde zużyte ciało. Otrzymujesz +1 pkt. do Magii Śmierci (5...45 sek.).'],
115=>['Krwawa Odnowa','Zaklęcie (czar). Przez 7 sek., otrzymujesz regenerację żywotności równą +3...6. Gdy Krwawa Odnowa przestanie działać, otrzymujesz 40...190 pkt. żywotności.','Zaklęcie (czar). (7 sek.) Posiadasz regenerację żywotności +3...6. Efekt końcowy: otrzymujesz 40...190 pkt. żywotności.'],
116=>['Mroczna Aura','Zaklęcie (czar). Przez 30 sek., za każdym razem, kiedy wybrany sojusznik poświęca punkty żywotności, Mroczna Aura zadaje 5...50 pkt. obrażeń od cienia przeciwnikom bezpośrednio przy nim, a ty tracisz 5...20 pkt. żywotności.','Zaklęcie (czar). (30 sek.) Zadaje 5...50 pkt. obrażeń przeciwnikom bezpośrednio przy wybranym sojuszniku, za każdym razem, kiedy poświęca on żywotność. Koszt obrażeń: tracisz 5...20 pkt. żywotności.'],
117=>['Osłabienie','Czar. Wybrany przeciwnik cierpi na osłabienie przez 10...30 sek.','Czar. Wywołuje przypadłość osłabienie (10...30 sek.).'],
118=>['Osłabiająca Krew','Czar. Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu cierpią na osłabienie przez 5...20 sek.','Czar. Osłabia (5...20 sek.) wybranego przeciwnika i wszystkich przeciwników w pobliżu.'],
119=>['Krew to Potęga','Elitarne zaklęcie (czar). Przez 10 sek. wybrany sojusznik inny niż ty posiada regenerację energii +3...6.','Elitarne zaklęcie (czar). (10 sek.) Regeneracja energii +3...6. Na cel nie można wybrać siebie.'],
120=>['Krew Władcy','Czar. Wszyscy twoi nieumarli sojusznicy otrzymują 30...116 pkt. żywotności. Poświęcasz dodatkowe 2% maksymalnych punktów żywotności za każdego sługusa uleczonego w ten sposób.','Czar. Dodaje po 30...116 pkt. żywotności twoim nieumarłym sługom. Koszt uleczenia: +2% poświęcanej żywotności na uzdrowionego sługę.'],
121=>['Mściwy Duch','Elitarna klątwa (czar). Przez 10...25 sek., za każdym razem, kiedy wybrany przeciwnik atakuje lub używa umiejętności, Mściwy Duch zadaje jemu i jego sojusznikom bezpośrednio przy nim 15...45 pkt. obrażeń od cienia.','Elitarna klątwa (czar). (10...25 sek.) Wybranemu przeciwnikowi i przeciwnikom w bezpośredniej odległości zadaje 15...45 pkt. obrażeń, za każdym razem, kiedy ten przeciwnik atakuje lub używa umiejętności.'],
122=>['Szkodliwa Interwencja','Klątwa (czar). Przez 5...20 sek. wybrany przeciwnik otrzymuje o 20% mniej pkt. żywotności. Jeżeli wybrany przeciwnik zginie przeklęty Szkodliwą Interwencją, zostaje przywołana bezpańska kościana poczwara na poziomie 1...17.','Klątwa (czar). (5...20 sek.) Wybrany przeciwnik otrzymuje o 20% mniej pkt. żywotności. Jeżeli ten przeciwnik umrze, będąc pod działaniem tej klątwy, zostanie przyzwana bezpańska kościana poczwara na poziomie 1...17.'],
123=>['Podstępny Pasożyt','Klątwa (czar). Przez 5...15 sek., za każdym razem, kiedy wybrany przeciwnik trafi podczas ataku, wykradasz mu do 15...45 pkt. żywotności.','Klątwa (czar). (5...15 sek.) Wykrada 15...45 pkt. żywotności, za każdym razem, kiedy trafi atak wybranego przeciwnika.'],
124=>['Przejmujące Dreszcze','Klątwa (czar). Przez 10...40 sek., za każdym razem, kiedy wybrany przeciwnik otrzymuje obrażenia od zimna podczas używania umiejętności, ten przeciwnik zostaje rozproszony, a ty tracisz 8...3 pkt. energii albo Przejmujące Dreszcze przestają działać.','Klątwa (czar). (10...40 sek.) Obrażenia od zimna przerywają umiejętności wybranego przeciwnika. Koszt przerwania: tracisz 8...3 pkt. energii lub Przejmujące Dreszcze przestają działać.'],
125=>['Więdnięcie','Elitarna klątwa (czar). Przez 5...35 sek., wybrany przeciwnik posiada degenerację żywotności -2...4 oraz degeneracji energii -1. Jeżeli energia wybranego przeciwnika dojdzie do 0, otrzyma on 15...75 pkt. obrażeń, a Więdnięcie przestanie działać.','Elitarna klątwa (czar). (5...35 sek.) Powoduje degenerację żywotności -2...4 i degenerację energii -1. Zadaje 15...75 pkt. obrażeń, jeżeli energia wybranego przeciwnika spadnie do 0. Przestanie działać, jeśli energia tego przeciwnika spadnie do 0.'],
126=>['Przelanie Życia','Elitarna klątwa (czar). Przez 6...12 sek. wybrany przeciwnik i przeciwnicy bezpośrednio przy nim posiadają degenerację żywotności -3...8, z kolei ty posiadasz regenerację żywotności o tej samej wartości.','Elitarna klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (6...12 sek.). Powoduje degenerację żywotności -3...8. Posiadasz regenerację żywotności +3...8.'],
127=>['Piętno Przewrotu','Klątwa (czar). Przez 6 sek., następnym razem, kiedy wybrany przeciwnik rzuca czar wymierzony w swojego sojusznika, czar zawodzi, a ty wykradasz przeciwnikowi do 10...92 pkt. żywotności.','Klątwa (czar). (6 sek.) Następny czar wybranego przeciwnika nie zadziała, a ty wykradasz 10...92 pkt. żywotności. Bez efektu, chyba że celem czaru tego przeciwnika jest jeden z jego sojuszników.'],
128=>['Wyssanie Duszy','Elitarna klątwa (czar). Przez 10 sek., za każdym razem, kiedy wybrany przeciwnik rzuca czar, wykradasz mu do 16...80 pkt. żywotności.','Elitarna klątwa (czar). (10 sek.) Wykrada 16...80 pkt. żywotności, za każdym razem, kiedy wybrany przeciwnik rzuca czar.'],
129=>['Splugawienie Ciała','Klątwa (czar). Przez 5...35 sek. wybrany przeciwnik otrzymuje jedynie dwie trzecie punktów żywotności podczas leczenia.','Klątwa (czar). (5...35 sek.) Zmniejsza o 33% liczbę punktów żywotności jakie otrzymuje wybrany przeciwnik. Działa tylko na umiejętności zawierające w opisie słowo "otrzymuje".'],
130=>['Demoniczne Ciało','Zaklęcie (czar). Przez 30...60 sek., za każdym razem kiedy używasz umiejętności, której celem będzie jakiś przeciwnik, zadajesz 5...20 pkt. obrażeń od cienia wszystkim sąsiadującym z tobą wrogom.','Zaklęcie (czar). (30...60 sek.) Kiedy używasz umiejętności na przeciwniku, zadajesz 5...20 pkt. obrażeń od cienia wszystkim sąsiadującym z tobą wrogom.'],
131=>['Kolczasty Sygnet','Sygnet. Na 3...15 sek. powodujesz krwawienie u wybranego przeciwnika i wszystkich przeciwników bezpośrednio przy nim.','Sygnet. Cel i przeciwnicy w bezpośrednim sąsiedztwie cierpią z powodu krwawienia (3...15 sek.).'],
132=>['Sygnet Plagi','Sygnet elitarny. Przenosisz wszystkie przypadłości, wraz z ich pozostałymi czasami działania ( 100...200%), z siebie na wybranego przeciwnika. (50% szans na niepowodzenie, gdy wartość gdy wartość atrybutu Klątwy wynosi 4 lub mniej.)','Sygnet elitarny. Przenosi wszystkie przypadłości, wraz z ich pozostałymi czasami działania ( 100...200%), z ciebie na wybranego przeciwnika. 50% szans na niepowodzenie, chyba że wartość Klątw wynosi 5 lub więcej.'],
133=>['Mroczny Pakt','Czar. Wybranemu przeciwnikowi zadaje 20...60 pkt. obrażeń od cienia.','Czar. Zadaje 20...60 pkt. obrażeń.'],
134=>['Rozkaz Bólu','Zaklęcie (czar). Przez 5 sek., za każdym razem, kiedy członek drużyny trafi przeciwnika i zada mu obrażenia fizyczne, ten członek drużyny zada dodatkowo 3...16 pkt. obrażeń.','Zaklęcie (czar). Zaklina wszystkich członków drużyny (5 sek.). 3...16 pkt. dodatkowych obrażeń, za każdym razem, kiedy zadają oni fizyczne obrażenia.'],
135=>['Lękliwość','Klątwa (czar). Przez 4...18 sek., wybrany przeciwnik atakuje 50% wolniej oraz cierpi -1...3 degeneracji żywotności.','Klątwa (czar). (4...18 sek.) Wybrany przeciwnik atakuje o 50% wolniej i posiada degenerację żywotności -1...3.'],
136=>['Cień Strachu','Klątwa (czar). Wybrany przeciwnik i wszyscy przeciwnicy znajdujący się bezpośrednio przy nim atakują 50% wolniej przez następne 5...30 sek.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (5...30 sek.). Atakują oni o 50% wolniej.'],
137=>['Stężenie Pośmiertne','Klątwa (czar). Przez 8...20 sek., wybrany przeciwnik nie może blokować.','Klątwa (czar). (8...20 sek.) Wybrany przeciwnik nie może blokować.'],
138=>['Mroczne Więzy','Zaklęcie (czar). Przez 30...60 sek., za każdym razem, kiedy otrzymujesz obrażenia, najbliższy sługus otrzymuje zamiast ciebie 75% tych obrażeń.','Zaklęcie (czar). (30...60 sek.) Przenosi 75% obrażeń z ciebie na twojego najbliższego sługę.'],
139=>['Przenoszenie Przypadłości','Zaklęcie (czar). Przez 15...60 sek., za każdym razem, kiedy otrzymujesz nową przypadłość, najbliższy sługa otrzymuje tę przypadłość zamiast ciebie.','Zaklęcie (czar). (15...60 sek.) Za każdym razem, kiedy otrzymujesz przypadłość, zostaje ona przeniesiona na twojego najbliższego nieumarłego sługę.'],
140=>['Niemoc','Klątwa (czar). Przez 5...35 sek., wybrany przeciwnik posiada degenerację energii -1, zaś ty posiadasz degeneracją żywotności -1. Jeżeli energia wybranego przeciwnika dojdzie do 0, otrzyma on 5...50 pkt. obrażeń, a Niemoc przestanie działać.','Klątwa (czar). (5...35 sek.) Powoduje degenerację energii -1. Zadaje 5...50 pkt. obrażeń, jeżeli energia wybranego przeciwnika spadnie do 0. Posiadasz degenerację żywotności -1. Przestanie działać, jeśli energia tego przeciwnika spadnie do 0.'],
141=>['Rozerwanie Zaklęć','Czar. Z wybranego przeciwnika usuwasz zaklęcia w liczbie 5...9. Za każde usunięte zaklęcie mnicha, tracisz 55...25 pkt. żywotności.','Czar. Z wybranego przeciwnika usuwa zaklęcia w liczbie 5...9. Koszt usunięcia: za każde zdjęte zaklęcie mnicha tracisz 55...25 pkt. żywotności.'],
142=>['Przewlekła Klątwa','Elitarna klątwa (czar). Przez 6...30 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu posiadają degenerację żywotności -1...4 i w trakcie leczenia otrzymują o 25% mniej żywotności.','Elitarna klątwa (czar). (6...30 sek.) Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu posiadają degenerację żywotności -1...4 i w trakcie leczenia otrzymują o 25% mniej żywotności.'],
143=>['Zdarcie Zaklęcia','Czar. Z wybranego przeciwnika zdejmujesz zaklęcia w liczbie 0...2. Jeżeli zaklęcie zostało zdjęte, wykradasz 5...65 pkt. żywotności.','Czar. Z wybranego przeciwnika zdejmuje zaklęcia w liczbie 0...2. Efekt usunięcia: wykradasz 5...65 pkt. żywotności.'],
144=>['Odmrożenie','Czar. Zostajesz zatruty na 10 sekund. Przeciwnicy w okolicy twojego celu otrzymują po 10...44 pkt. obrażeń od zimna i tracą zaklęcia w liczbie 1...2.','Czar. Przeciwnikom w okolicy twojego celu zadaje po 10...44 pkt. obrażeń od zimna; zdejmuje z tych przeciwników zaklęcia w liczbie 1...2. Zostajesz zatruty (10 sek.).'],
145=>['Sygnet Agonii','Sygnet. Krwawisz przez 25 sek. Wszyscy przeciwnicy w pobliżu otrzymują 10...70 pkt. obrażeń.','Sygnet. Przeciwnikom w pobliżu ciebie zadaje po 10...70 pkt. obrażeń. Krwawisz (25 sek.).'],
146=>['Ofiara z Krwi','Elitarny czar. Otrzymujesz 8...20 pkt. energii.','Elitarny czar. Otrzymujesz 8...20 pkt. energii.'],
147=>['Mroczna Furia','Zaklęcie (czar). Przez 5 sek., za każdym razem, kiedy dowolny członek drużyny trafi przeciwnika, otrzyma jedną dawkę adrenaliny. (50% szans na niepowodzenie, gdy wartość Magii Krwi wynosi 4 lub mniej.)','Zaklęcie (czar). Zaklina członków drużyny (5 sek.). Ci członkowie drużyny otrzymują dawkę adrenaliny, za każdym razem, kiedy ich atak trafi. 50% szans na niepowodzenie, chyba że wartość Magii Krwi wynosi 5 lub więcej.'],
148=>['Rozkaz Wampira','Elitarne zaklęcie (czar). Przez 5 sek., za każdym razem, kiedy niebędący pod wpływem innych zaklęć nekromanty członek drużyny trafi przeciwnika i zada mu obrażenia fizyczne, ten członek drużyny wykrada 3...16 pkt. żywotności.','Elitarne zaklęcie (czar). Zaklina wszystkich członków drużyny (5 sek.). Ci członkowie drużyny, każdym atakiem zadającym obrażenia fizyczne, wykradają po 3...16 pkt. żywotności. Nie działa na członków drużyny znajdujących się pod działaniem innego zaklęcia nekromanty.'],
149=>['Przesyłanie Plagi','Czar. Przenosisz 1...3 przypadłości, wraz z pozostałym czasem działania, z siebie na wybranego przeciwnika i wszystkich przeciwników w bezpośredniej odległości.','Czar. Przenosisz 1...3 przypadłości, wraz z pozostałym czasem działania, z siebie na wybranego przeciwnika i wszystkich przeciwników w bezpośredniej odległości.'],
150=>['Piętno Bólu','Klątwa (czar). Przez 30 sek., za każdym razem, kiedy wybrany przeciwnik otrzymuje obrażenia fizyczne, Piętno Bólu zadaje przeciwnikom bezpośrednio przy nim po 10...40 pkt. obrażeń od cienia.','Klątwa (czar). (30 sek.) Przeciwnikom bezpośrednio przy wybranym przeciwniku zadaje po 10...40 pkt. obrażeń, za każdym razem, kiedy otrzymuje on obrażenia fizyczne.'],
151=>['Uczta Zepsucia','Elitarny czar. Wybrany przeciwnik i wszyscy przeciwnicy znajdujący się bezpośrednio przy nim otrzymują 16...80 pkt. obrażeń od cienia. Wykradasz do 8...40 pkt. żywotności od każdego zranionego przeciwnika, który jest pod wpływem klątwy.','Elitarny czar. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 16...80 pkt. obrażeń. Każdemu przeciwnikowi pod działaniem klątwy wykradasz 8...40 pkt. żywotności.'],
152=>['Posmak Śmierci','Czar. Wykradnij do 100...400 pkt. żywotności od wybranego sojuszniczego wskrzeszonego truposza.','Czar. Sojuszniczemu nieumarłemu słudze wykrada 100...400 pkt. żywotności.'],
153=>['Wampiryczne Spojrzenie','Czar. Wykradasz do 18...60 pkt. żywotności od wybranego przeciwnika.','Czar. Wykrada 18...60 pkt. żywotności.'],
154=>['Dotyk Plagi','Umiejętność. Na wybranego przeciwnika przenosisz przypadłości w liczbie 1...3, pod których działaniem się znajdujesz, wraz z ich pozostałym czasem działania.','Umiejętność dotykowa. Przenosi 1...3 przypadłości z ciebie na wybranego przeciwnika.'],
155=>['Podły Dotyk','Umiejętność. Dotknij wybranego przeciwnika by zadać 20...65 pkt. obrażeń.','Umiejętność dotykowa. Zadaje 20...65 pkt. obrażeń.'],
156=>['Wampiryczny Dotyk','Umiejętność. Dotknij wybranego przeciwnika by wykraść mu do 29...74 pkt. żywotności.','Umiejętność dotykowa. Wykrada 29...74 pkt. żywotności.'],
157=>['Rytuał Krwi','Zaklęcie (czar). Przez 8...14 sek. wybrany dotknięty sojusznik posiada regenerację energii +3. Rytuał Krwi nie może być użyty na rzucającym ten czar.','Zaklęcie (czar). (8...14 sek.) Regeneracja energii +3. Na cel nie można wybrać siebie.'],
158=>['Dotyk Agonii','Umiejętność. Wybrany dotknięty przeciwnik otrzymuje 20...58 pkt. obrażeń od cienia.','Umiejętność dotykowa. Zadaje 20...58 pkt. obrażeń.'],
159=>['Osłabienie Zbroi','Czar. Wybrany przeciwnik i przeciwnicy bezpośrednio przy twoim celu na 5...20 sek. otrzymują pękniętą zbroję.','Czar. Działa także na przeciwników w bezpośredniej odległości. Wywołuje przypadłość pęknięta zbroja (5...20 sek.).'],
160=>['Szybkość Wiatru','Zaklęcie (czar). Przez 5...13 sek., wybrany sojusznik porusza się 33% szybciej.','Zaklęcie (czar). (5...13 sek.) Wybrany sojusznik porusza się o 33% szybciej.'],
162=>['Podmuch','Czar. Powala wybranego przeciwnika na 2 sek. Ten czar powoduje wyczerpanie. (50% szans na niepowodzenie, gdy wartość Magii Powietrza wynosi 4 lub mniej.)','Czar. Powoduje powalenie. Powoduje u ciebie wyczerpanie. 50% szans na niepowodzenie, chyba że wartość Magii Powietrza wynosi 5 lub więcej.'],
163=>['Trąba Powietrzna','Czar. Wszyscy przeciwnicy w bezpośrednim sąsiedztwie otrzymują po 15...75 pkt. obrażeń od zimna. Atakujący przeciwnicy trafieni przez Tornado zostają powaleni. Jeśli jesteś pod wpływem Przemagicznienia, to zaklęcie trafia pobliskich wrogów, zamiast będących w bezpośrednim sąsiedztwie.','Czar. Trafia przeciwników w bezpośrednim sąsiedztwie. Zadaje 15...75 pkt. obrażeń od zimna. Powoduje powalenie atakujących przeciwników. Trafia pobliskich zamiast bezpośrednio sąsiadujących podczas Przemagicznienia.'],
164=>['Zestrojenie z Żywiołami','Elitarne zaklęcie (czar). Przez 25...60 sek. osiągasz dostrojenie do żywiołów powietrza, ognia, wody oraz ziemi i zyskujesz +1...2 pkt. do tych atrybutów. Zyskujesz 1 pkt. energii oraz 50% podstawowego kosztu energii umiejętności za każdym razem, gdy używasz czarów związanych z tymi żywiołami.','Elitarne zaklęcie (czar). (25...60 sek.) Twoje atrybuty związane z żywiołami są zwiększone o 1...2 pkt. Zyskujesz 1 pkt. energii oraz 50% podstawowego kosztu energii używanej umiejętności związanych z magią powietrza, ognia, wody i ziemi.'],
165=>['Zbroja Ziemi','Zaklęcie (czar). Przez 30 sek., otrzymujesz +24...60 pkt. pancerza, ale poruszasz się 50...14% wolniej.','Zaklęcie (czar). (30 sek.) Posiadasz +24...60 pkt. pancerza. Poruszasz się o 50...14% wolniej.'],
166=>['Kinetyczny Pancerz','Zaklęcie (czar). Przez 12 sek. masz +20...80 pkt. pancerza. Za każdym razem, kiedy rzucasz czar, Kinetyczny Pancerz zostaje odnowiony na 12 sek.','Zaklęcie (czar). (12 sek.) Masz +20...80 pkt. pancerza. Premiowe odnowienie: rzuć czar.'],
167=>['Erupcja','Czar. Wywołaj Erupcję w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy w tym obszarze otrzymują w każdej sekundzie 10...40 pkt. obrażeń od ziemi oraz zostają oślepieni na 10 sek.','Czar. W każdej sekundzie zadaje 10...40 pkt. obrażeń od ziemi (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca celu. Wywołuje przypadłość oślepienie (10 sek.).'],
168=>['Magnetyczna Aura','Zaklęcie (czar). Przez 1...8 sek., blokujesz następny atak przeciwko sobie i zadajesz 10...50 obrażeń atakującemu przeciwnikowi. Podczas Przemagicznienia wszyscy członkowie drużyny w zasięgu słuchu zostają wzmocnieni aurą.','Zaklęcie (czar). (1...8 sek.) Zablokuj następny atak i odbij 10...50 obrażeń do napastnika. Podczas Przemagicznienia wzmocnij aurą wszystkich członków drużyny w zasięgu słuchu.'],
169=>['Zestrojenie z Ziemią','Zaklęcie (czar). Przez 36...60 sek. postać jest dostrojona do ziemi. Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Ziemi, otrzymasz 1 pkt. energii plus 30% pkt. energetycznego kosztu tej umiejętności.','Zaklęcie (czar). (36...60 sek.) Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Ziemi, otrzymasz 1 pkt. energii plus 30% pkt. zużytej energii.'],
170=>['Trzęsienie Ziemi','Czar. W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Trzęsienie Ziemi. Wszyscy przeciwnicy w pobliżu tego miejsca zostają powaleni i otrzymują po 26...100 pkt. obrażeń od ziemi. Ten czar powoduje wyczerpanie.','Czar. Zadaje 26...100 pkt. obrażeń od ziemi. Trafia także przeciwników w pobliżu celu. Powoduje powalenie. Powoduje u ciebie wyczerpanie.'],
171=>['Ukamienowanie','Czar. Wyślij ogromny kamień, który, jeżeli trafi, zada wybranemu przeciwnikowi 45...105 pkt. obrażeń od ziemi. Jeśli Ukamienowanie trafi przeciwnika cierpiącego na osłabienie, to zostanie on powalony.','Czar. Pocisk: zadaje 45...105 pkt. obrażeń od ziemi. Powoduje powalenie, jeżeli wybrany przeciwnik jest osłabiony.'],
172=>['Kamienne Sztylety','Czar. Wyślij dwa Kamienne Sztylety. Każdy z Kamiennych Sztyletów zadaje 8...33 pkt. obrażeń od ziemi, jeżeli trafi wybranego przeciwnika. Będąc pod wpływem Przemagicznienia, każdy pocisk powoduje Krwawienie przez 1...5 sek.','Czar. Dwa pociski: każdy zadaje 8...33 pkt. obrażeń od ziemi. Podczas Przemagicznienia powoduje krwawienie przez 1...5 sek.'],
173=>['Grząska Ziemia','Klątwa (czar). Przez 5...20 sek., wszyscy przeciwnicy w pobliżu poruszają się o 50% wolniej.','Klątwa (czar). Klątwa działa na przeciwników w pobliżu ciebie (5...20 sek.). Ci przeciwnicy poruszają się o 50% wolniej.'],
174=>['Wstrząs Wtórny','Czar. Wszyscy przeciwnicy w pobliżu otrzymują 15...85 pkt. obrażeń od ziemi. Wszyscy powaleni przeciwnicy otrzymują 15...85 pkt. dodatkowych obrażeń od ziemi.','Czar. Zadaje 15...85 obrażeń od ziemi pobliskim wrogom. Zadaje 15...85 więcej obrażeń od ziemi powalonym wrogom.'],
175=>['Ochrona przed Żywiołami','Ochrona (czar). W miejscu, w którym przebywasz tworzysz Ochronę przed Żywiołami. Przez 8...20 sek. nie będący duchami sojusznicy w tej okolicy posiadają +24 punkty pancerza przeciwko obrażeniom od żywiołów.','Ochrona (czar). (8...20 sek.) Sojusznicy w granicach tej ochrony posiadają +24 pkt. pancerza przeciwko obrażeniom od żywiołów. Nie działa na duchy.'],
176=>['Ochrona przed Ciosami','Ochrona (czar). Tworzysz Ochronę przed Ciosami w miejscu, w którym przebywasz. Przez 5...20 sek. nie będący duchami sojusznicy na tym obszarze mają 50% szans na blokowanie ciosów wręcz.','Ochrona (czar). (5...20 sek.) Sojusznicy w granicach tej ochrony posiadają 50% szans na blokowanie ataków wręcz. Nie działa na sojusznicze duchy.'],
177=>['Ochrona przed Przeciwnikami','Ochrona (czar). Tworzysz Ochronę przed Przeciwnikami w miejscu, w którym przebywasz. Przez 8...20 sek. wszyscy nie będący duchami przeciwnicy w okolicy poruszają się o 50% wolniej.','Ochrona (czar). (8...20 sek.) Przeciwnicy w granicach tej ochrony poruszają się o 50% wolniej.'],
178=>['Eteryczny Cud','Elitarne zaklęcie (czar). Tracisz wszystkie zaklęcia. Przez 8...20 sek. posiadasz regenerację energii +6. Gdy Eteryczny Cud przestanie działać, tracisz 3 pkt. żywotności za każdy posiadany pkt. energii. Ten czar powoduje wyczerpanie.','Elitarne zaklęcie (czar). (8...20 sek.) Posiadasz regenerację energii +6. Efekt końcowy: za każdy punkt posiadanej energii tracisz 3 pkt. żywotności. Tracisz wszystkie zaklęcia. Powoduje u ciebie wyczerpanie.'],
179=>['Zapalające Więzy','Klątwa (czar). Po 3 sek., wybrany przeciwnik i przeciwnicy bezpośrednio przy nim otrzymują po 20...80 pkt. obrażeń od ognia oraz zostają podpaleni na 1...3 sek. Jeśli cel zginie, aktywuje się wcześniej.','Klątwa (czar). (3 sek.) Efekt końcowy: przeciwnikom w pobliżu twojego celu zadaje 20...80 pkt. obrażeń od ognia i wywołuje przypadłość płonięcie (1...3 sek.). Uruchamia się też po śmierci przeciwnika.'],
180=>['Aura Odnowy','Zaklęcie (czar). Przez 60 sek., za każdym razem, kiedy rzucisz czar, otrzymasz 0...1 pkt. energii i punkty żywotności w liczbie równej 200...500% energetycznego kosztu czaru.','Zaklęcie (czar). (60 sek.) Za każdym razem, kiedy rzucisz czar, otrzymasz 0...1 pkt. energii i punkty żywotności w liczbie równej 200...500% energetycznego kosztu czaru.'],
181=>['Eteryczna Odnowa','Elitarne zaklęcie (czar). Przez 5...20 sek., za każdym razem, kiedy rzucasz czar, otrzymujesz 1...4 pkt. energii i 5...20 pkt. żywotności za każde zaklęcie, które masz na sobie.','Elitarne zaklęcie (czar). (5...20 sek.) Za każdym razem, kiedy rzucasz czar, otrzymujesz 1...4 pkt. energii i 5...20 pkt. żywotności, za każde zaklęcie, które masz na sobie.'],
182=>['Przyzwanie Ognia','Zaklęcie (czar). Przez 60 sek., jeżeli posiadasz ognistą broń, twoje ataki zadają dodatkowe 5...20 pkt. obrażeń od ognia.','Zaklęcie (czar). (60 sek.) Twoje ataki zadają +5...20 pkt. obrażeń od ognia. Bez efektu, jeśli twoja broń nie zadaje obrażeń od ognia.'],
183=>['Piekło','Czar. Przeciwnicy w kontakcie otrzymują 30...135 pkt. obrażeń od ognia.','Czar. Przeciwnikom bezpośrednio przy tobie zadaje po 30...135 pkt. obrażeń od ognia.'],
184=>['Zestrojenie z Ogniem','Zaklęcie (czar). Przez 36...60 sek. postać jest dostrojona do ognia. Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Ognia, otrzymasz 1 pkt. energii plus 30% pkt. energetycznego kosztu tej umiejętności.','Zaklęcie (czar). (36...60 sek.) Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Ognia, otrzymasz 1 pkt. energii plus 30% pkt. zużytej energii.'],
185=>['Wypalanie Umysłu','Elitarny czar. Wybrany przeciwnik otrzymuje 15...60 pkt. obrażeń od ognia. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 15...60 pkt. obrażeń od ognia oraz zostaje podpalony na 1...10 sek. Ten czar powoduje wyczerpanie.','Elitarny czar. Zadaje 15...60 pkt. obrażeń od ognia. Jeżeli masz więcej energii niż wybrany przeciwnik, zadaje 15...60 pkt. dodatkowych obrażeń od ognia i wywołuje przypadłość płonięcie (1...10 sek.). Powoduje u ciebie wyczerpanie.'],
186=>['Kula Ognia','Czar. Wysyłasz kulę ognia, która uderza w cel i pobliskich przeciwników, zadając każdemu 7...112 pkt. obrażeń od ognia.','Czar. Pocisk: zadaje celowi i pobliskim przeciwnikom po 7...112 pkt. obrażeń od ognia.'],
187=>['Meteoryt','Czar. Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują 7...112 pkt. obrażeń od ognia i zostają powaleni. Ten czar powoduje wyczerpanie.','Czar. Zadaje 7...112 pkt. obrażeń od ognia i powala. Trafia także przeciwników bezpośrednio przy wybranym przeciwniku. Powoduje u ciebie wyczerpanie.'],
188=>['Ognisty Wybuch','Czar. Przeciwnicy w pobliżu otrzymują 15...120 pkt. obrażeń od ognia.','Czar. Wszystkim przeciwnikom w pobliżu ciebie zadaje po 15...120 pkt. obrażeń od ognia.'],
189=>['Inwokacja Rodgorta','Czar. Wybrany przeciwnik i przeciwnicy w pobliżu otrzymują 15...120 obrażeń od ognia oraz zostają podpaleni na 1...3 sek.','Czar. Zadaje 15...120 pkt. obrażeń od ognia. Działa także na przeciwników w pobliżu twojego celu. Wywołuje przypadłość płonięcie (1...3 sek.).'],
190=>['Piętno Rodgorta','Klątwa (czar). Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim znajdują się pod działaniem klątwy Piętna Rodgorta. Przez 10...35 sek., za każdym razem, kiedy jeden z tych przeciwników otrzymuje obrażenia od ognia, zostaje podpalony na 1...4 sek.','Klątwa (czar). Klątwa działa także na przeciwników w pobliżu twojego celu (10...35 sek.). Wywołuje przypadłość płonięcie (1...4 sek.), kiedy ci przeciwnicy otrzymują obrażenia od ognia.'],
191=>['Samospalenie','Czar. Wybrany przeciwnik otrzymuje 20...75 obrażeń od ognia oraz zostaje podpalony na 1...3 sek.','Czar. Zadaje 20...75 pkt. obrażeń od ognia. Wywołuje przypadłość płonięcie (1...3 sek.).'],
192=>['Deszcz Meteorytów','Czar. W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Deszcz Meteorytów. Przez 9 sek., co 3 sek. wszyscy przeciwnicy w tej okolicy otrzymują 7...112 pkt. obrażeń od ognia i zostają powaleni. Ten czar powoduje wyczerpanie.','Czar. Co 3 sek. zadaje 7...112 pkt. obrażeń od ognia i powala (9 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu. Powoduje u ciebie wyczerpanie.'],
193=>['Feniks','Czar. Ognisty Feniks pojawia się obok ciebie i leci w kierunku celu, wybuchając trafia w cel. Wybuch rani cel oraz pobliskich przeciwników za 10...60 pkt. obrażeń od ognia. Podczas Przemagicznienia, sojusznicy znajdujący się w zasięgu wybuchu zostają uzdrowieni o 20...80 pkt. żywotności.','Czar. Pocisk: wybranemu przeciwnikowi i pobliskim przeciwnikom zadaje po 10...60 pkt. obrażeń od ognia. Uzdrawia sojuszników o 20...80, jeśli jesteś pod wpływem Przemagicznienia.'],
194=>['Flara','Czar. Wystrzel Flarę, która po trafieniu zadaje wybranemu przeciwnikowi 20...65 pkt. obrażeń od ognia. Jeśli jesteś pod wpływem Przemagicznienia, Flara trafia również pobliskich wrogów.','Czar. Pocisk: zadaje 20...65 pkt. obrażeń od ognia. Podczas Przemagicznienia trafia pobliskich.'],
195=>['Krynica Lawy','Czar. Przez 5 sek. przeciwnicy znajdujący się bezpośrednio w miejscu, w którym ten czar został rzucony otrzymują w każdej sekundzie 5...50 pkt. obrażeń od ognia. Jeśli jesteś pod wpływem Przemagicznienia, to zaklęcie trafia pobliskich wrogów, zamiast tych będących w bezpośrednim sąsiedztwie.','Czar. Zadaje 5...50 pkt. obrażeń od ognia na sek. (przez 5 sek.). Trafia wrogów w pobliżu twojego początkowego położenia. Podczas Przemagicznienia zasięg zwiększony do pobliskich przeciwników.'],
196=>['Palący Żar','Czar. W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Palący Żar. Przez 5 sek., przeciwnicy w tej okolicy otrzymują w każdej sekundzie po 10...40 pkt. obrażeń od ognia. Gdy Palący Żar przestanie działać, przeciwnicy w okolicy zostaną podpaleni na 3 sek.','Czar. W każdej sekundzie zadaje 10...40 pkt. obrażeń od ognia (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca celu. Efekt końcowy: wywołuje przypadłość płonięcie (3 sek.).'],
197=>['Deszcz Ognia','Czar. Wywołaj Deszcz Ognia w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 10 sek., przeciwnicy w tym obszarze otrzymują w każdej sekundzie 5...35 pkt. obrażeń od ognia.','Czar. W każdej sekundzie zadaje 5...35 pkt. obrażeń od ognia (10 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu.'],
198=>['Glif Mocy Żywiołów','Glif. Przez 25 sek. twoje atrybuty związane z żywiołami zostają zwiększone o 2 dla następnych czarów w liczbie 10.','Glif. (25 sek.) Dla następnych czarów w liczbie 10 zwiększa twoje atrybuty związane z żywiołami o +2.'],
199=>['Glif Energii','Elitarny glif. Twoje kolejne zaklęcia 1...3 nie wywołują limitu aktywacyjnego i kosztują 10...25 mniej energii. Twoje atrybuty związane z żywiołami są zwiększane o 1...2.','Elitarny glif. Twoje kolejne zaklęcia 1...3 nie wywołują limitu aktywacyjnego i kosztują 10...25 mniej energii. Premia 1...2 do wszystkich atrybutów związanych z żywiołami.'],
200=>['Glif Mniejszej Energii','Glif. Przez następne 15 sek. twoje następne czary w liczbie 2 kosztują o 10...18 pkt. energii mniej.','Glif. (15 sek.) Twoje następne czary w liczbie 2 kosztują o 10...18 pkt. energii mniej.'],
201=>['Glif Koncentracji','Glif. Przez 15 sek. twoje następne czary w liczbie 1 nie mogą być przerwane i ignorują efekt oszołomienia.','Glif. (15 sek.) Twoje następne czary w liczbie 1 nie mogą zostać przerwane i nie działa na nie przypadłość oszołomienie.'],
202=>['Glif Ofiary','Glif. Przez 15 sek., twój następny czar zostaje rzucony natychmiast, ale odnawia się 30 sek. dłużej. Kończy się przedwcześnie, jeśli użyjesz umiejętności nie będącej czarem.','Glif. (15 sek.) Twój następny czar zostaje rzucony natychmiast, ale odnawia się 30 sek. dłużej. Kończy się, jeśli użyjesz umiejętności nie będącej czarem.'],
203=>['Glif Odnowy','Elitarny glif. Przez 15 sek. twój następny czar odnawia się natychmiast.','Elitarny glif. (15 sek.) Twój następny czar natychmiast się odnawia.'],
204=>['Rdza','Klątwa (czar). Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 10...85 pkt. obrażeń od zimna. Przez 5...20 sek. wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim potrzebują 2 razy więcej czasu na użycie sygnetów. Jeśli jesteś pod wpływem Przemagicznienia, przeciwnicy trafieni Rdzą nie mogą skorzystać ze swoich sygnetów przez 1...10 sek.','Klątwa (czar). Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 10...85 pkt. obrażeń od zimna. Nakłada klątwę na cel i przeciwników bezpośrednio przy nim (na 5...20 sek.). Podwaja czas aktywacji sygnetów. Przerywa i uniemożliwia wykorzystanie sygnetów na 1...10 sek., jeśli jesteś pod wpływem Przemagicznienia.'],
205=>['Fala Błyskawic','Elitarna klątwa (czar). Po 3 sek., wybrany przeciwnik zostaje powalony i otrzymuje 14...100 pkt. obrażeń od błyskawic.','Elitarna klątwa (czar). (3 sek.) Efekt końcowy: zadaje 14...100 pkt. obrażeń od piorunów i powala.'],
206=>['Zbroja Mrozu','Zaklęcie (czar). Przez 10...34 sek., przeciwko obrażeniom fizycznym posiadasz +40 pkt. pancerza. Zbroja Mrozu przestanie działać, jeżeli użyjesz Magii Ognia.','Zaklęcie (czar). (10...34 sek.) Posiadasz +40 pkt. pancerza przeciwko obrażeniom fizycznym. Przestanie działać, jeśli użyjesz Magii Ognia.'],
207=>['Przyzwanie Mrozu','Zaklęcie (czar). Przez 60 sek., jeżeli posiadasz zadającą obrażenia od zimna broń, twoje ataki zadają dodatkowe 5...20 pkt. obrażeń od zimna.','Zaklęcie (czar). (60 sek.) Twoje ataki zadają +5...20 pkt. obrażeń od zimna. Bez efektu, jeśli twoja broń nie zadaje obrażeń od zimna.'],
208=>['Zestrojenie z Wodą','Zaklęcie (czar). Przez 36...60 sek. postać jest dostrojona do wody. Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Wody, otrzymasz 1 pkt. energii plus 30% pkt. energetycznego kosztu tej umiejętności.','Zaklęcie (czar). (36...60 sek.) Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Wody, otrzymasz 1 pkt. energii plus 30% pkt. zużytej energii.'],
209=>['Zamrożenie Umysłu','Elitarna klątwa (czar). Wybrany przeciwnik otrzymuje 10...60 pkt. obrażeń od zimna. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 10...60 pkt. obrażeń od zimna oraz porusza się o 90% wolniej przez 1...5 sek. Ten czar powoduje wyczerpanie.','Elitarna klątwa (czar). Zadaje 10...60 pkt. obrażeń od zimna. Jeżeli masz więcej pkt. energii niż wybrany przeciwnik, to umiejętność zadaje 10...60 pkt. dodatkowych obrażeń od zimna i o 90% spowalnia ruch (1...5 sek.). Powoduje u ciebie wyczerpanie.'],
210=>['Lodowe Więzienie','Klątwa (czar). Przez 8...20 sek., nogi wybranego przeciwnika zostają uwięzione w lodzie, powodując jego spowolnienie o 66%. Działanie czaru skończy się, gdy cel otrzyma obrażenia od ognia.','Klątwa (czar). (8...20 sek.) Wybrany przeciwnik porusza się o 66% wolniej. Przestanie działać, jeśli ten przeciwnik otrzyma obrażenia od ognia.'],
211=>['Lodowe Kolce','Klątwa (czar). Wybrany przeciwnik i przeciwnicy bezpośrednio przy nim otrzymują 20...80 pkt. obrażeń od zimna oraz przez 2...6 sek. poruszają się o 66% wolniej.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (2...6 sek.). Ci przeciwnicy poruszają się o 66% wolniej. Efekt początkowy: zadaje 20...80 pkt. obrażeń od zimna.'],
212=>['Mroźny Wybuch','Klątwa (czar). Wszyscy przeciwnicy w pobliżu otrzymują 10...85 obrażeń od zimna oraz poruszają się o 66% wolniej przez 3...8 sek.','Klątwa (czar). Nakłada klątwę na przeciwników w pobliżu ciebie. Ci przeciwnicy poruszają się o 66% wolniej (3...8 sek.). Efekt początkowy: przeciwnikom w pobliżu ciebie zadaje po 10...85 pkt. obrażeń od zimna.'],
213=>['Lodowa Burza','Klątwa (czar). Wyrzuć lodowy odłamek, który zadaje wybranemu przeciwnikowi 10...85 obrażeń od zimna oraz spowalnia go o 66% na 2...6 sek.','Klątwa (czar). Pocisk: zadaje 10...85 pkt. obrażeń od zimna. Wybrany przeciwnik porusza się o 66% wolniej (2...6 sek.).'],
214=>['Lodowa Włócznia','Zaklęcie (czar). Wystrzeliwujesz Lodową Włócznię, która, jeżeli trafi, zadaje wybranemu przeciwnikowi 10...60 pkt. obrażeń od zimna. Będąc pod wpływem Przemagicznienia, otrzymujesz premię +1...4 do regeneracji żywotności przez 5 sek.','Zaklęcie (czar). Pocisk: zadaje 10...60 pkt. obrażeń od zimna. Bonus +1...4 do regeneracji żywotności przez 5 sek. podczas Przemagicznienia.'],
215=>['Wir','Czar. W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Wir. Przez 10 sek. przeciwnicy w tym obszarze otrzymują w każdej sekundzie 10...25 pkt. obrażeń od zimna. Wir przerywa rzucane czary, gdy trafia w przeciwnika. Ten czar powoduje wyczerpanie.','Czar. W każdej sekundzie zadaje 10...25 pkt. obrażeń od zimna i przerywa czary (10 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu. Powoduje u ciebie wyczerpanie.'],
216=>['Żelazna Mgła','Zaklęcie (czar). Na 8...15 sek. twój pancerz zwiększa się o +15. Twoje zaklęcia Magii Powietrza kierowane przeciwko wrogowi aktywują się i odnawiają 33% szybciej, ale otrzymujesz 2 pkt. przemagicznienia.','Zaklęcie (czar). (8...15 sek.) Twój pancerz zwiększa się o +15. Twoje zaklęcia Magii Powietrza kierowane przeciwko wrogowi aktywują się i odnawiają 33% szybciej, ale otrzymujesz 2 pkt. przemagicznienia.'],
217=>['Krystaliczna Fala','Czar. Przeciwnicy bezpośrednio przy tobie otrzymują 10...70 pkt. obrażeń, ale zostają wyleczeni z wszelkich przypadłości. Każda usunięta przypadłość zadaje 5...15 pkt. obrażeń.','Czar. Przeciwnikom bezpośrednio przy tobie zadaje po 10...70 pkt. obrażeń. Ci przeciwnicy tracą wszystkie przypadłości i otrzymują 5...15 pkt. obrażeń za każdą usuniętą przypadłość.'],
218=>['Obsydianowe Ciało','Elitarne zaklęcie (czar). Przez 8...20 sek., otrzymujesz +20 pkt. pancerza i nie możesz być celem czarów przeciwnika, ale nie możesz atakować i otrzymujesz -2 do degeneracji energii.','Elitarne zaklęcie (czar). (8...20 sek.) Otrzymujesz +20 do pancerza i nie możesz być celem czarów przeciwnika. Nie możesz atakować i otrzymujesz -2 do degeneracji energii.'],
219=>['Obsydianowy Płomień','Czar. Wybranemu przeciwnikowi zadajesz 22...112 pkt. obrażeń. Ten czar ignoruje pancerz, ale powoduje wyczerpanie.','Czar. Zadaje 22...112 pkt. obrażeń. Powoduje u ciebie wyczerpanie.'],
220=>['Oślepiający Błysk','Czar. Wybrany przeciwnik zostaje oślepiony na 3...8 sek.','Czar. Wywołuje przypadłość oślepienie (3...8 sek.).'],
221=>['Przyzwanie Błyskawicy','Zaklęcie (czar). Przez 60 sek., jeżeli posiadasz zadającą obrażenia od błyskawic broń, twoje ataki zadają dodatkowe 5...20 pkt. obrażeń od błyskawic.','Zaklęcie (czar). (60 sek.) Twoje ataki zadają +5...20 pkt. obrażeń od błyskawic. Bez efektu, jeśli twoja broń nie zadaje obrażeń od błyskawic.'],
222=>['Uderzenie Błyskawicą','Klątwa (czar). Wybranemu przeciwnikowi zadajesz 10...60 pkt. obrażeń od elektryczności. To zaklęcie ma 25% penetrację pancerza. Jeśli jesteś pod wpływem Przemagicznienia, ten przeciwnik zostanie przeklęty Uderzeniem Pioruna przez 3 sek. Gdy klątwa dobiega końca, cel zostaje raz jeszcze trafiony przez piorun za 20...40 pkt. obrażeń od elektryczności.','Klątwa (czar). Zadaje 10...60 pkt. obrażeń od elektryczności. 25% penetracji pancerza. Klątwa na 3 sek. podczas Przemagicznienia. Efekt końcowy: zadaje 20...40 pkt. obrażeń od elektryczności.'],
223=>['Wyładowanie Łańcuchowe','Czar. Wybrany przeciwnik i maksymalnie dwóch innych przeciwników w jego pobliżu otrzymuje 10...85 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicia pancerza oraz powoduje wyczerpanie, jeśli nie znajdujesz się pod wpływem zaklęcia.','Czar. Zadaje 10...85 pkt. obrażeń od błyskawic. Trafia także dwóch przeciwników w pobliżu twojego celu. 25% przebicie pancerza. Powoduje u ciebie wyczerpanie, jeśli nie znajdujesz się pod wpływem zaklęcia.'],
224=>['Osłabiający Ładunek','Czar. Wybrany przeciwnik otrzymuje 25...50 pkt. obrażeń od błyskawic oraz zostaje osłabiony na 5...20 sek. Ten czar posiada 25% przebicie pancerza.','Czar. Zadaje 25...50 pkt. obrażeń od błyskawic. Wywołuje przypadłość osłabienie (5...20 sek.). 25% przebicie pancerza.'],
225=>['Zestrojenie z Powietrzem','Zaklęcie (czar). Przez 36...60 sek. postać jest dostrojona do powietrza. Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Powietrza, otrzymasz 1 pkt. energii plus 30% pkt. energetycznego kosztu tej umiejętności.','Zaklęcie (czar). (36...60 sek.) Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Powietrza, otrzymasz 1 pkt. energii plus 30% pkt. zużytej energii.'],
226=>['Wstrząs Mózgu','Elitarny czar. Wybrany przeciwnik otrzymuje 10...50 pkt. obrażeń od błyskawic. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 10...50 pkt. obrażeń od błyskawic oraz zostaje powalony. Ten czar posiada 25% przebicia pancerza, ale powoduje wyczerpanie.','Elitarny czar. Zadaje 10...50 pkt. obrażeń od błyskawic. Zadaje 10...50 pkt. dodatkowych obrażeń od błyskawic i powala, jeżeli masz więcej energii niż ten przeciwnik. 25% przebicie pancerza. Powoduje u ciebie wyczerpanie.'],
227=>['Migoczące Piętno','Elitarna klątwa (czar). Przez 10 sek., wskazany wróg otrzymuje co sekundę 5...25 pkt. obrażeń. Klątwa ta kończy się, kiedy użyjesz innej umiejętności na tym celu.','Elitarna klątwa (czar). (10 sek.) Co sekundę zadaje 5...25 pkt. obrażeń. Przestaje działać, jeśli użyjesz umiejętności, której celem jest ten przeciwnik.'],
228=>['Grzmot','Elitarny czar. W miejscu, w którym znajduje się wybrany przeciwnik, wywołuje potężne uderzenie pioruna, zadające 10...50 pkt. obrażeń. Cel i wszyscy sąsiadujący z nim przeciwnicy mają pękniętą zbroję i zostają osłabieni na 5...20 sek. Ten czar ma 25% przebicia pancerza.','Elitarny czar. Zadaje 10...50 pkt. obrażeń. Trafia też pobliskich wrogów. Wywołuje pęknięcie zbroi i osłabienie (na 5...20 sek.). 25% przebicia pancerza.'],
229=>['Piorun Kulisty','Czar. Wystrzeliwujesz Błyskawicę Kulistą, która po trafieniu zadaje wybranemu przeciwnikowi 10...100 pkt. obrażeń od elektryczności. To zaklęcie ma 25% penetrację pancerza.','Czar. Pocisk: zadaje 10...100 pkt. obrażeń od elektryczności. 25% penetracji pancerza.'],
230=>['Oszczep Błyskawicy','Czar. Wystrzeliwuje Oszczep Błyskawicy, który po trafieniu zadaje 15...50 obrażeń od elektryczności. Oszczep Błyskawicy przerywa ataki przeciwników. To zaklęcie ma 25% penetracji pancerza i trafia wszystkich przeciwników między tobą a celem.','Czar. Pocisk: zadaje 15...50 pkt. obrażeń od elektryczności. Przerywa, jeśli twój cel wykonywał atak. 25% penetracji pancerza. Trafia wszystkich przeciwników między tobą a celem.'],
231=>['Wstrząs','Umiejętność. Wybrany dotknięty przeciwnik zostaje powalony i otrzymuje 10...60 pkt. obrażeń od błyskawic. Ta umiejętność posiada 25% przebicia pancerza, ale powoduje wyczerpanie.','Umiejętność dotykowa. Zadaje 10...60 pkt. obrażeń od błyskawic. Powoduje powalenie. 25% przebicie pancerza. Powoduje u ciebie wyczerpanie.'],
232=>['Elektryzujący Dotyk','Umiejętność. Dotknięty cel i będący w bezpośrednim sąsiedztwie przeciwnicy zostają uderzeni piorunem za 10...60 pkt. obrażeń od elektryczności, zostają oślepieni na 1...4 sek. i dostają przypadłość pękniętej zbroi na 1...10 sek. To zaklęcie ma 25% penetrację pancerza.','Umiejętność dotykowa. Zadaje 10...60 pkt. obrażeń od elektryczności. Trafia również wrogów stojących w bezpośrednim sąsiedztwie celu. Powoduje oślepienie (1...4 sek.) i pękniętą zbroję (1...10) u wszystkich trafionych przeciwników. 25% penetracji pancerza.'],
233=>['Wirująca Aura','Zaklęcie (czar). Przez 3...7 sek. wzmacnia cię Wirująca Aura i otrzymujesz +1...6 regeneracji żywotności oraz masz 50% szansy na zablokowanie pocisków. Podczas Przemagicznienia rzucenie tego zaklęcia spowoduje, że wszyscy członkowie drużyny w zasięgu słuchu zostają wzmocnieni aurą.','Zaklęcie (czar). (3...7 sek.) Daje +1...6 regeneracji żywotności oraz 50% szansy na zablokowanie pocisków. Podczas Przemagicznienia wzmacnia wszystkich członków drużyny w zasięgu słuchu.'],
234=>['Przenikliwy Chłód','Klątwa (czar). Wywołaj Przenikliwy Chłód w miejscu, gdzie znajduje się wybrany przeciwnik. Wszyscy przeciwnicy w okolicy otrzymują 10...85 pkt. obrażeń od zimna oraz przez 10 sek. poruszają się o 66% wolniej.','Klątwa (czar). Klątwa działa także na przeciwników w okolicy twojego celu (10 sek.). Ci przeciwnicy poruszają się o 66% wolniej. Efekt początkowy: zadaje 10...85 pkt. obrażeń od zimna.'],
235=>['Nieostry Wzrok','Klątwa (czar). Przez 4...10 sek. wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim są pod działaniem klątwy Nieostry Wzrok. Pod wpływem klątwy, ci przeciwnicy mają 50% szans na nietrafianie, kiedy atakują.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (4...10 sek.). Ci przeciwnicy posiadają 50% szans na nietrafianie.'],
236=>['Mglisty Kształt','Elitarne zaklęcie (czar). Przez 10...45 sek., nie możesz otrzymać, ani zadać obrażeń podczas ataku.','Elitarne zaklęcie (czar). (10...45 sek.) Nie otrzymujesz obrażeń z ataków. Twoje ataki nie zadają obrażeń.'],
237=>['Wodny Trójząb','Elitarny czar. Wyślij szybko poruszający się Wodny Trójząb, który przy trafieniu zadaje wybranemu przeciwnikowi 10...90 pkt. obrażeń od zimna. Jeśli atak trafi poruszającego się przeciwnika, przeciwnik ten zostaje powalony.','Elitarny czar. Szybki pocisk: zadaje 10...90 pkt. obrażeń od zimna; powala poruszających się przeciwników.'],
238=>['Mglista Zbroja','Zaklęcie (czar). Przez 8...20 sek., zyskujesz +10...40 pkt. pancerza oraz poruszasz się o 33% szybciej.','Zaklęcie (czar). (8...20 sek.) Posiadasz +10...40 pkt. pancerza i poruszasz się o 33% szybciej.'],
239=>['Ochrona przed Krzywdą','Elitarna ochrona (czar). W miejscu, w którym przebywasz, tworzysz Ochronę przed Krzywdą. Przez 5...15 sek. nie będący duchami sojusznicy w tej okolicy otrzymują po 12...24 pkt. pancerza przeciwko obrażeniom od ognia i po 1...3 pkt. pancerza przeciwko innym obrażeniom.','Elitarna ochrona (czar). (5...15 sek.) Sojusznicy w granicach tej ochrony posiadają +12...24 pkt. pancerza przeciwko obrażeniom od ognia i +1...3 pkt. pancerza przeciwko innym obrażeniom. Nie działa na duchy.'],
240=>['Pogrom','Czar. Atak zadaje 10...55 pkt. świętych obrażeń. Jeśli cel atakuje, otrzymuje dodatkowe 10...35 pkt. świętych obrażeń.','Czar. Zadaje 10...55 pkt. świętych obrażeń. Zadaje 10...35 pkt. dodatkowych świętych obrażeń, jeżeli cel atakuje.'],
241=>['Życiodajna Więź','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, za każdym razem, kiedy wybrany sojusznik inny niż ty otrzyma obrażenia pochodzące od ataków, połowa tych obrażeń zostanie przekierowana na ciebie. Obrażenia, które otrzymasz w ten sposób zostaną zmniejszone o 3...30 pkt.','Zaklęcie (czar). Połowa obrażeń jakie otrzymuje wybrany sojusznik z ataków jest przenoszona na ciebie. Przenoszone obrażenia zmniejszane są o 3...30. Na cel nie można wybrać siebie.'],
242=>['Duch Baltazara','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, kiedy wybrany sojusznik otrzyma obrażenia, zwiększy się jego adrenalina i energia. (Ilość otrzymywanej adrenaliny jest wprost proporcjonalna do wartości atrybutu Modlitwy Ofensywne.)','Zaklęcie (czar). Wybrany sojusznik dostaje adrenalinę i 1 pkt. energii, kiedy otrzymuje obrażenia.'],
243=>['Siła Honoru','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik zadaje w walce wręcz 5...25 pkt. dodatkowych obrażeń.','Zaklęcie (czar). W walce wręcz wybrany sojusznik zadaje 5...25 pkt. dodatkowych obrażeń.'],
244=>['Dostrojenie do Życia','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik zadaje o 30% mniej obrażeń w walce, ale podczas leczenia otrzymuje o 14...50% pkt. żywotności więcej.','Zaklęcie (czar). Wybrany sojusznik otrzymuje podczas uzdrawiania o 14...50% więcej żywotności. Ten sojusznik zadaje swoimi atakami o 30% mniej obrażeń.'],
245=>['Ochronny Duch','Zaklęcie (czar). Przez 5...23 sek. wybrany sojusznik na skutek pojedynczego ataku lub czaru nie może stracić więcej niż 10% maksymalnej żywotności.','Zaklęcie (czar). (5...23 sek.) Otrzymywane obrażenia zmniejszane są do 10% maksymalnej żywotności wybranego sojusznika.'],
246=>['Boska Interwencja','Zaklęcie (czar). Przez 10 sek., kiedy następnym razem wybrany sojusznik ma otrzymać śmiertelne obrażenia, to są one negowane i w zamian otrzyma on 26...240 pkt. żywotności.','Zaklęcie (czar). (10 sek.) Neguje następne śmiertelne obrażenia, jakie miałby otrzymać wybrany sojusznik. Efekt zanegowania: dodaje 26...240 pkt. żywotności.'],
247=>['Symbol Gniewu','Czar. Tworzysz Symbol Gniewu w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek. sąsiadujący wrogowie odnoszą co sekundę 10...40 pkt. świętych obrażeń.','Czar. W każdej sekundzie (przez 5 sek.) zadaje 10...40 pkt. obrażeń od zimna. Trafia przeciwników sąsiadujących z początkowej lokalizacji wybranego wroga.'],
248=>['Pomsta','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia pochodzące z ataków, czar zadaje atakującemu 33% tych obrażeń (maksymalnie 5...20 pkt. obrażeń).','Zaklęcie (czar). Przekazuje źródłu 33% obrażeń z każdego ataku (maksymalnie 5...20).'],
249=>['Święty Gniew','Zaklęcie (czar). Przez 10...30 sek., w kolejnych (1...10) sytuacjach kiedy wskazany sojusznik otrzymuje obrażenia od ataku, czar ten odbija 66% tych obrażeń z powrotem na ich źródło (maksymalnie 5...50 pkt. obrażeń).','Zaklęcie (czar). (10...30 sek.) Odbija 66% obrażeń z każdego ataku (maksymalnie 5...50) z powrotem na ich źródło. Kończy się po 1...10-krotnym zadaniu obrażeń. Na cel nie można wybrać siebie.'],
250=>['Więź Esencji','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, kiedy wybrany sojusznik otrzyma obrażenia fizyczne lub obrażenia od żywiołów, twoja energia zwiększy się o 1.','Zaklęcie (czar). Otrzymujesz 1 pkt. energii, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia fizyczne lub obrażenia od żywiołów.'],
251=>['Zgubne Leczenie','Klątwa (czar). Przez 30 sek., za każdym razem, kiedy wybrany przeciwnik będzie uzdrawiany, uzdrawiający otrzyma 15...80 pkt. świętych obrażeń.','Klątwa (czar). (30 sek.) Za każdym razem, kiedy wybrany przeciwnik będzie uzdrawiany, uzdrawiający otrzyma 15...80 pkt. świętych obrażeń.'],
252=>['Wygnanie','Czar. Wybrany przeciwnik otrzymuje 20...65 świętych obrażeń.','Czar. Zadaje 20...65 pkt. świętych obrażeń. Przyzwanym stworzeniom zadaje podwójne obrażenia.'],
253=>['Zgubna Ofiara','Klątwa (czar). Przez 8...20 sek., za każdym razem, kiedy wybrany przeciwnik i przeciwnicy bezpośrednio przy nim poświecą punkty żywotności, stracą podwójną ich liczbę.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (8...20 sek.). Podwaja poświęcaną żywotność.'],
254=>['Życiodajny Duch','Zaklęcie (czar). Przez 30 sek., za każdym razem, kiedy wybrany sojusznik atakuje lub rzuca czar, otrzymuje 5...20 pkt. żywotności.','Zaklęcie (czar). (30 sek.) Dodaje 5...20 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik atakuje lub rzuca czar.'],
255=>['Czujny Duch','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik posiada regenerację żywotności +2. Kiedy Czujny Duch przestanie działać, osoba, na którą działał otrzyma 30...180 pkt. żywotności.','Zaklęcie (czar). Regeneracja żywotności +2. Efekt końcowy: dodaje 30...180 pkt. żywotności.'],
256=>['Błogosławiona Aura','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, zaklęcia mnicha, które rzucasz trwają o 10...35% dłużej.','Zaklęcie (czar). Zaklęcia mnicha jakie rzucasz trwają o 10...35% dłużej.'],
257=>['Egida','Zaklęcie (czar). Przez 6...15 sek., wszyscy członkowie drużyny w zasięgu słuchu mają 50% szans na blokowanie ataków.','Zaklęcie (czar). Nakłada zaklęcie na wszystkich członków drużyny w zasięgu słuchu (6...15 sek.). 50% szans na blokowanie.'],
258=>['Strażnik','Zaklęcie (czar). Przez 2...7 sek., wybrany sojusznik ma 50% szans na blokowanie ataków.','Zaklęcie (czar). (2...7 sek.) 50% szans na blokowanie.'],
259=>['Tarcza Odbicia','Elitarne zaklęcie (czar). Przez 3...10 sek., wybrany sojusznik ma 75% szans na zablokowanie ataków i otrzymuje 15...30 pkt. pancerza.','Elitarne zaklęcie (czar). (3...10 sek.) 75% szans na blokowanie. +15...30 pkt. pancerza.'],
260=>['Aura Wiary','Elitarne zaklęcie (czar). Przez 3 sek. wybrany sojusznik otrzymuje podczas uzdrawiania o 50...100% więcej żywotności i otrzymuje o 5...50% mniej obrażeń.','Elitarne zaklęcie (czar). (3 sek.) Wybrany sojusznik otrzymuje podczas uzdrawiania o 50...100% więcej żywotności i otrzymuje o 5...50% mniej obrażeń.'],
261=>['Tarcza Regeneracji','Elitarne zaklęcie (czar). Przez 5...13 sek. wybrany sojusznik ma regenerację żywotności +3...10 i otrzymuje 20...45 pkt. pancerza.','Elitarne zaklęcie (czar). (5...13 sek.). Regeneracja żywotności +3...10 i +20...45 pkt. pancerza.'],
262=>['Tarcza Osądu','Elitarne zaklęcie (czar). Przez 8...20 sek., ktokolwiek zaatakuje wybranego sojusznika zostanie powalony i otrzyma 5...50 pkt. świętych obrażeń.','Elitarne zaklęcie (czar). (8...20 sek.) Przeciwnikom atakującym wybranego sojusznika zadaje 5...50 pkt. świętych obrażeń. Powoduje powalenie.'],
263=>['Ochronne Więzy','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik na skutek pojedynczego ataku lub czaru nie może stracić więcej niż 5% pkt. żywotności. Za każdym razem, kiedy Ochronne Więzy uchronią przed obrażeniami, tracisz 6...3 pkt. energii lub czar przestaje działać.','Zaklęcie (czar). Wybrany sojusznik nie może stracić więcej niż 5% maksymalnej żywotności na skutek pojedynczego ataku lub czaru. Za każdym razem, kiedy obrażenia są obniżane, tracisz 6...3 pkt. energii lub ten czar przestaje działać.'],
264=>['Pacyfizm','Klątwa (czar). Przez 4...8 sek., wybrany przeciwnik nie może atakować. Działanie czaru skończy się, gdy cel otrzyma obrażenia.','Klątwa (czar). (4...8 sek.) Wybrany przeciwnik nie może atakować. Przestanie działać, jeśli ten przeciwnik otrzyma obrażenia.'],
265=>['Zgoda','Elitarna klątwa (czar). Przez 4...12 sek., przeciwnicy bezpośrednio przy tobie nie mogą atakować. Zgoda skończy się, gdy jeden z tych przeciwników otrzyma obrażenia.','Elitarna klątwa (czar). (4...12 sek.) Przeciwnicy bezpośrednio przy tobie nie mogą atakować. Przestanie działać na danym przeciwniku, jeśli otrzyma on obrażenia.'],
266=>['Pokój i Harmonia','Elitarne zaklęcie (czar). Wybrany sojusznik traci klątwy i przypadłości w liczbie 0...9. Przez 1...3 sek. przypadłości i klątwy na tym sojuszniku trwają o 90% krócej. Wszystkie twoje umiejętności związane z Modlitwami Ofensywnymi zostają zablokowane na 20 sek.','Elitarne zaklęcie (czar). Wybrany sojusznik traci klątwy i przypadłości w liczbie 0...9. Przypadłości i klątwy na tym sojuszniku trwają o 90% krócej (1...3 sek.). Wyłącza twoje umiejętności Modlitw Ofensywnych (20 sek.).'],
267=>['Intuicja Sędziego','Zaklęcie (czar). Przez 8...20 sek., ataki wybranego sojusznika zadają święte obrażenia i mają +20% przebicie pancerza.','Zaklęcie (czar). (8...20 sek.) Powoduje, że ataki wybranego sojusznika zadają święte obrażenia i mają +20% przebicie pancerza.'],
268=>['Aura Nieustępliwości','Elitarne zaklęcie (czar). Kiedy utrzymujesz to zaklęcie twoje czary mnicha uzdrawiając, dodają +15...60% dodatkowych pkt. żywotności. Kiedy to zaklęcie przestanie działać, jeden z martwych członków drużyny innych niż ty (losowo wybrany), zmartwychwstanie z pełną energią i zostanie przeniesiony do ciebie.','Elitarne zaklęcie (czar). Twoje czary mnicha dodają +15...60% dodatkowych pkt. żywotności. Efekt końcowy: losowy sojusznik zostaje wskrzeszony z pełną energią i przeniesiony do ciebie.'],
269=>['Ochronny Symbol','Elitarne zaklęcie (czar). Przez 10 sek., za każdym razem, kiedy wybrany sojusznik będzie miał otrzymać obrażenia, dostanie w zamian tyle samo pkt. żywotności, ale nie więcej niż 6...60. Wszystkie twoje Modlitwy Ochronne będą niedostępne przez 5 sek.','Elitarne zaklęcie (czar). (10 sek.) Zamienia obrażenia (maksymalnie 6...60) w leczenie. Wszystkie twoje umiejętności Modlitw Ochronnych są wyłączone (5 sek.).'],
270=>['Bariera Życia','Elitarne zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, obrażenia zadawane wybranemu sojusznikowi innemu niż ty zmniejszane są o 20...50%. Jeśli w momencie, gdy ten sojusznik otrzyma obrażenia, twoja żywotność będzie poniżej 50%, to Bariera Życia przestanie działać.','Elitarne zaklęcie (czar). Obniża obrażenia o 20...50%. Na cel nie można wybrać siebie. Jeśli w momencie, gdy cel otrzyma obrażenia, twoja żywotność będzie poniżej 50%, to Bariera Życia przestanie działać.'],
271=>['Ogień Fanatyka','Zaklęcie (czar). Przez 60 sek., za każdym razem, kiedy użyjesz umiejętności, której celem będzie sojusznik, wszyscy przeciwnicy bezpośrednio przy tej osobie otrzymają 5...35 pkt. obrażeń od ognia, a ty stracisz 1 pkt. energii.','Zaklęcie (czar). (60 sek.) Za każdym razem, kiedy na sojuszniku użyjesz umiejętności, wszyscy przeciwnicy bezpośrednio przy tej osobie otrzymają po 5...35 pkt. obrażeń od ognia. Koszt obrażeń: tracisz 1 pkt. energii.'],
272=>['Aura Baltazara','Zaklęcie (czar). Przez 8 sek., przeciwnicy bezpośrednio przy wybranym sojuszniku otrzymują w każdej sekundzie 10...30 pkt. świętych obrażeń.','Zaklęcie (czar). (8 sek.) Przeciwnikom bezpośrednio przy wybranym sojuszniku w każdej sekundzie zadaje po 10...30 pkt. świętych obrażeń.'],
273=>['Łamacz Czarów','Elitarne zaklęcie (czar). Przez 5...17 sek., wybrany sojusznik nie może być celem zaklęć wrogich czarów.','Elitarne zaklęcie (czar). (5...17 sek.) Wybrany sojusznik nie może być celem wrogich czarów.'],
274=>['Uzdrawiające Ziarno','Zaklęcie (czar). Przez 10 sek., za każdym razem, kiedy wybrany sojusznik inny niż ty otrzyma obrażenia, on i wszyscy sojusznicy w kontakcie z nim otrzymają 3...30 pkt. żywotności.','Zaklęcie (czar). (10 sek.) Za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia, on i sojusznicy bezpośrednio przy nim otrzymują po 3...30 pkt. żywotności. Na cel nie można wybrać siebie.'],
275=>['Usunięcie Przypadłości','Czar. Usuwa z wybranego sojusznika jedną przypadłość (zatrucie, chorobę, oślepienie, oszołomienie, krwawienie, okulawienie, płonięcie, osłabienie, pękniętą zbroję lub głęboką ranę). Jeżeli przypadłość zostanie usunięta, sprzymierzeniec zostaje uzdrowiony za 5...70 żywotności.','Czar. Usuwa przypadłość. Efekt usunięcia: dodaje 5...70 pkt. żywotności. Na cel nie można wybrać siebie.'],
276=>['Przywrócenie Stanu','Elitarny czar. Usuwasz z wybranego sojusznika innego niż ty wszystkie przypadłości (zatrucie, chorobę, oślepienie, oszołomienie, krwawienie, okulawienie, płonięcie, osłabienie, pękniętą zbroję i głęboką ranę). Za każdą usuniętą przypadłość, sojusznik ten otrzyma 10...70 pkt. żywotności.','Elitarny czar. Usuwa wszystkie przypadłości. Efekt usunięcia: za każdą usuniętą przypadłość dodaje 10...70 pkt. żywotności. Na cel nie można wybrać siebie.'],
277=>['Usunięcie Przypadłości','Czar. Z wybranego sojusznika usuwasz jedną przypadłość (zatrucie, chorobę, oślepienie, oszołomienie, krwawienie, okulawienie, płonięcie, osłabienie, pękniętą zbroję lub głęboką ranę). Za każdą pozostałą przypadłość, osoba ta otrzyma 5...70 pkt. żywotności.','Czar. Usuwa przypadłość. Efekt usunięcia: za każdą pozostałą przypadłość dodaje 5...70 pkt. żywotności.'],
278=>['Oczyszczenie z Przypadłości','Czar. Usuwa z wybranego sojusznika wszystkie przypadłości (zatrucie, chorobę, oślepienie, oszołomienie, krwawienie, okulawienie, płonięcie, osłabienie, pękniętą zbroję i głęboką ranę).','Czar. Usuwa wszystkie przypadłości.'],
279=>['Boskie Uzdrowienie','Czar. Uzdrawiasz siebie i członków drużyny w zasięgu słuchu dodając każdemu 15...60 pkt. żywotności.','Czar. Tobie i członkom drużyny w zasięgu słuchu dodaje po 15...60 pkt. żywotności.'],
280=>['Uzdrowienie Obszarowe','Czar. Uzdrawiasz siebie i wszystkie stworzenia bezpośrednio przy tobie dodając każdemu 30...180 pkt. żywotności.','Czar. Tobie oraz sojusznikom i przeciwnikom bezpośrednio obok ciebie dodaje po 30...180 pkt. żywotności.'],
281=>['Uzdrawiająca Modlitwa','Czar. Uzdrawiasz wybranego sojusznika dodając mu 30...80 pkt. żywotności.','Czar. Dodaje 30...80 pkt. żywotności.'],
282=>['Słowo Uzdrowienia','Elitarny czar. Uzdrawiasz wybranego sojusznika dodając mu 5...100 pkt. żywotności. Jeśli jego żywotność znajduje się poniżej 50%, to uzdrawiasz go o dodatkowe 30...115 punktów.','Elitarny czar. Dodaje 5...100 pkt. żywotności. Dodatkowo dodaje 30...115 pkt. żywotności, jeśli żywotność wybranego sojusznika jest poniżej 50%.'],
283=>['Pocałunek Dwayny','Czar. Wybranemu sojusznikowi innemu niż ty dodajesz 20...65 pkt. żywotności i dodatkowe 15...40 pkt. żywotności za każde zaklęcie lub klątwę na nim.','Czar. Dodaje 20...65 pkt. żywotności. Dodaje 15...40 pkt. dodatkowej żywotności za każdą klątwę lub zaklęcie na wybranym sojuszniku. Na cel nie można wybrać siebie.'],
284=>['Boski Dar','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, za każdym razem, kiedy rzucisz czar z grupy Modlitw Ochronnych lub Łaski Bogów, którego celem jest sojusznik, osoba ta otrzymuje 15...60 pkt. żywotności, a ty tracisz 1 punkty energii.','Zaklęcie (czar). Dodaje wybranemu sojusznikowi 15...60 pkt. żywotności, za każdym razem, kiedy rzucisz na niego czar z grupy Modlitw Ochronnych lub Łaski Bogów. Koszt uzdrowienia: tracisz 1 pkt. energii.'],
285=>['Uzdrawiające Dłonie','Elitarne zaklęcie (czar). Przez 10 sek., za każdym razem, kiedy wybrany sojusznik otrzyma obrażenia, zostanie uzdrowiony otrzymując 5...35 pkt. żywotności.','Elitarne zaklęcie (czar). (10 sek.) Dodaje 5...35 pkt. żywotności, za każdym razem, kiedy cel otrzymuje obrażenia.'],
286=>['Uzdrowienie Innej Osoby','Czar. Uzdrawiasz wybranego sojusznika innego niż ty dodając mu 35...180 pkt. żywotności.','Czar. Dodaje 35...180 pkt. żywotności. Na cel nie można wybrać siebie.'],
287=>['Uzdrowienie Drużyny','Czar. Uzdrawiasz każdego członka drużyny o 30...75 pkt. żywotności.','Czar. Każdemu członkowi drużyny dodaje 30...75 pkt. żywotności.'],
288=>['Bryza Uzdrowienia','Zaklęcie (czar). Przez 15 sek., wybrany sojusznik posiada regenerację żywotności +4...9.','Zaklęcie (czar). (15 sek.) Regeneracja żywotności +4...9.'],
289=>['Życiodajne Błogosławieństwo','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, maksymalna żywotność wybranego sojusznika będzie większa o +40...200 pkt.','Zaklęcie (czar). +40...200 pkt. do maksymalnej żywotności.'],
290=>['Odnowienie','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik posiada regenerację żywotności +1...4.','Zaklęcie (czar). Regeneracja żywotności +1...4.'],
291=>['Zastępcze Życie','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, za każdym razem, kiedy wybrany sojusznik trafia przeciwnika, otrzymuje 2...17 pkt. żywotności.','Zaklęcie (czar). Otrzymujesz 2...17 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik trafi przeciwnika.'],
292=>['Podarowanie Żywotności','Czar. Tracisz połowę aktualnej liczby pkt. żywotności. Wybrany sojusznik inny niż ty otrzymuje 100...136% pkt., które ty straciłeś.','Czar. Dodaje 100...136% połowy twojej aktualnej żywotności. Tracisz połowę aktualnej żywotności. Na cel nie można wybrać siebie.'],
293=>['Sygnet Oddania','Sygnet. Uzdrawiasz wybranego sojusznika dodając mu 20...120 pkt. żywotności.','Sygnet. Dodaje 20...120 pkt. żywotności.'],
294=>['Sygnet Osądu','Sygnet elitarny. Cel zostaje powalony. Wybrany przeciwnik i wszyscy przeciwnicy przy nim otrzymują 15...75 pkt. świętych obrażeń.','Sygnet elitarny. Powala cel. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 15...75 pkt. świętych obrażeń.'],
295=>['Sygnet Oczyszczenia','Sygnet. Z wybranego sojusznika usuwasz wszystkie klątwy i zaklęcia. Za każdą usuniętą klątwę i każde usunięte zaklęcie tracisz 10 pkt. energii.','Sygnet. Usuwa wszystkie klątwy i przypadłości. Koszt usunięcia: 10 pkt. energii za każdą.'],
296=>['Sygnet Zguby','Sygnet. Wybrany przeciwnik otrzymuje 30...60 pkt. świętych obrażeń. Jeśli wybrany przeciwnik atakował, zostaje powalony.','Sygnet. Zadaje 30...60 pkt. świętych obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik atakuje.'],
297=>['Błogosławiony Sygnet','Sygnet. Za każde zaklęcie, które utrzymujesz, otrzymujesz 3 pkt. energii. W ten sposób nie możesz otrzymać więcej niż 3...24 pkt. energii.','Sygnet. Za każde zaklęcie, które utrzymujesz, otrzymujesz 3 punkty Energii. W ten sposób nie możesz otrzymać więcej niż 3...24 pkt. energii.'],
298=>['Męczennik','Elitarny czar. Przenosisz na siebie wszystkie przypadłości (wraz z ich pozostałymi czasami działania), pod których działaniem są członkowie drużyny.','Elitarny czar. Przenosi wszystkie przypadłości z wszystkich sojuszników na ciebie.'],
299=>['Ochraniające Dłonie','Zaklęcie (czar). Przez 8 sek., obrażenia oraz żywotność wykradana wybranemu sojusznikowi są zmniejszone o 3...18. Kiedy Ochraniające Dłonie przestają działać, sojusznik ten odzyskuje 5...50 żywotności.','Zaklęcie (czar). (8 sek].) Zmniejsza obrażenia oraz kradzież żywotności o 3...18. Efekt końcowy: przywraca 5...50 pkt. żywotności.'],
300=>['Kontemplacja Czystości','Umiejętność. Tracisz wszystkie zaklęcia. Za każde stracone otrzymujesz 0...80 pkt. żywotności, oczyszczasz się z jednej klątwy i jednej przypadłości (maksymalna liczba klątw i przypadłości, które zostaną zdjęte: 1...8).','Umiejętność. Za każde zaklęcie, które masz na sobie otrzymujesz 0...80 pkt. żywotności i tracisz klątwę oraz przypadłość (maksymalna liczba dla klątw i przypadłości to 1...8). Tracisz wszystkie zaklęcia.'],
301=>['Usunięcie Klątwy','Czar. Z wybranego sojusznika usuwasz jedną klątwę.','Czar. Z wybranego sojusznika usuwa jedną klątwę.'],
302=>['Pogrom Klątwy','Czar. Z wybranego sojusznika usuwasz jedną klątwę. Jeśli klątwa zostanie usunięta, to każdy przeciwnik w okolicy otrzyma 10...85 pkt. świętych obrażeń.','Czar. Z wybranego sojusznika usuwa jedną klątwę. Efekt usunięcia: przeciwnikom w okolicy wybranego sojusznika zadaje 10...85 pkt. świętych obrażeń.'],
303=>['Przemiana Klątw','Czar. Z wybranego sojusznika innego niż ty usuwasz wszystkie klątwy. Ten sojusznik otrzymuje na 8...20 sek. +10 punktów pancerza na każdą klątwę nekromanty, która została z niego zdjęta.','Czar. Usuwa wszystkie klątwy; +10 pkt. pancerza za każdą usuniętą klątwę nekromanty (8...20 sek.). Na cel nie można wybrać siebie.'],
304=>['Światło Dwayny','Czar. Wskrzeszasz wszystkich członków drużyny w okolicy. Każdy z nich wraca do życia z 25% pkt. żywotności i bez energii.','Czar. Wskrzesza wszystkich martwych członków drużyny w okolicy (25% żywotności, 0 pkt. energii).'],
305=>['Wskrzeszenie','Czar. Wskrzeszasz wybranego członka drużyny. Wraca on do życia z 25% pkt. żywotności i bez energii.','Czar. Wskrzesza wybranego członka drużyny (25% żywotności, 0 pkt. energii).'],
306=>['Odrodzenie','Czar. Wskrzeszasz wybranego członka drużyny. Wraca on do życia z 25% pkt. żywotności i bez energii, zostaje też przeniesiony do miejsca, w którym się aktualnie znajdujesz. Wszystkie umiejętności wskrzeszonego będą niedostępne przez 10...3 sek. Ten czar pochłania całą twoją pozostałą energię.','Czar. Wskrzesza wybranego członka drużyny (25% żywotności, 0 pkt. energii). Teleportuje cel do ciebie. Wyłącza umiejętności celu (10...3 sek.). Tracisz całą energię.'],
307=>['Odwrócenie Losu','Zaklęcie (czar). Przez 8 sek., kiedy następnym razem wybrany sojusznik miałaby otrzymać obrażenia lub stracić żywotność na rzecz przeciwnika, dostanie w zamian tyle samo pkt. żywotności, ale nie więcej niż 15...80.','Zaklęcie (czar). (8 sek.) Zamienia następne obrażenia lub wykradzioną żywotność (maksymalnie 15...80) w leczenie.'],
308=>['Wsparcie','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik inny niż ty posiada regenerację żywotności +1 i regenerację energii +1, ale ty tracisz 1 pkt. energii za każdym razem, gdy rzuci on czar.','Zaklęcie (czar). Regeneracja żywotności +1 i regeneracja energii +1. Na cel nie można wybrać siebie. Tracisz 1 pkt. energii, za każdym razem, kiedy wybrany sojusznik rzuca czar.'],
309=>['Święty Całun','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, rzucanie klątw na wybranego sojusznika zabiera dwa razy więcej czasu. Kiedy Święty Całun przestanie działać, z wybranego sojusznika usuwana jest jedna klątwa.','Zaklęcie (czar). Podwójny czas rzucania klątw przeciwko wybranemu sojusznikowi. Efekt końcowy: usuwa klątwę.'],
310=>['Boski Duch','Zaklęcie (czar). Przez 1...14 sek. wszystkie czary mnicha, które rzucasz kosztują o 5 pkt. energii mniej. (Koszt minimalny: 1 pkt. energii.)','Zaklęcie (czar). (1...14 sek.) Czary mnicha kosztują cię o 5 pkt. energii mniej. Minimalny koszt: 1 pkt. energii.'],
311=>['Przejęcie Przypadłości','Czar. Wszystkie przypadłości z wybranego sojusznika innego niż ty przenoszone są na ciebie. Za każdą przejętą w ten sposób przypadłość, otrzymujesz 6...26 pkt. żywotności.','Czar. Przenosi wszystkie przypadłości z wybranego sojusznika na ciebie. Efekt przeniesienia: za każdą przypadłość otrzymujesz 6...26 pkt. żywotności. Na cel nie można wybrać siebie.'],
312=>['Święte Uderzenie','Umiejętność. Dotknięty przeciwnik otrzymuje 10...55 świętych obrażeń. Jeśli był powalony, otrzymuje dodatkowe 10...55 pkt. świętych obrażeń.','Umiejętność dotykowa. Zadaje 10...55 pkt. świętych obrażeń. Zadaje 10...55 pkt. dodatkowych świętych obrażeń, jeżeli cel jest powalony.'],
313=>['Uzdrawiający Dotyk','Czar. Dotkniętemu sojusznikowi dodajesz 20...80 pkt. żywotności. Punkty żywotności otrzymywane dzięki Łasce Bogów są w przypadku tego czaru podwajane.','Czar dotykowy. Dodaje 20...80 pkt. żywotności. Punkty żywotności otrzymywane dzięki Łasce Bogów są w przypadku tego czaru podwajane.'],
314=>['Przywracanie Życia','Czar. Dotykasz ciała martwego członka drużyny. Wraca on do życia z 20...65% pkt. żywotności i 42...90% pkt. energii.','Czar dotykowy. Wskrzesza wybranego członka drużyny (20...65% żywotności, 42...90% energii).'],
315=>['Zemsta','Zaklęcie (czar). Przywraca do życia martwego członka drużyny z pełną żywotnością i energią. Po 30 sek. ten członek drużyny zadaje o 25% więcej obrażeń. Kiedy to zaklęcie przestanie działać, członek drużyny zginie. Śmierci poniesione podczas działania tego zaklęcia nie zwiększają kary za śmierć.','Zaklęcie (czar). (30 sek.) Wskrzesza wybranego członka drużyny (pełna żywotności, pełna energia). Ten sojusznik zadaje o 25% więcej obrażeń i nie otrzymuje kary za śmierć. Efekt końcowy: ten sojusznik ginie.'],
316=>['Do granic możliwości!','Okrzyk. Za każdego wroga w zasięgu słuchu (maksymalnie 1...6) otrzymujesz jedną dawkę adrenaliny. Przez 10...20 sek., twoja maksymalna żywotność zostaje zwiększona o 10...60.','Okrzyk. (10...20 sek.) Otrzymujesz +10...60 do maksymalnej żywotności. Efekt początkowy: otrzymujesz jedną dawkę adrenaliny za każdego wroga w zasięgu słuchu (maksymalnie 1...6).'],
317=>['Szał Bojowy','Postawa elitarna. Przez 5...20 sek. poruszasz się o 33% szybciej i otrzymujesz z ataków podwójne dawki adrenaliny. Szał Bojowy przestanie działać, jeśli użyjesz umiejętności nie opartej na adrenalinie.','Postawa elitarna. (5...20 sek.) Poruszasz się o 33% szybciej i za swoje ataki otrzymujesz podwójną adrenalinę. Koniec działania, jeśli użyjesz umiejętności nie opartej na adrenalinie.'],
318=>['Ignorowanie Bólu','Umiejętność elitarna. Przez 20 sek. otrzymujesz dodatkowo 90...300 pkt. żywotności, 20 pkt. pancerza oraz -1...10 pkt. obrażeń mniej.','Umiejętność elitarna. (12 sek.) Posiadasz dodatkowe 90...300 pkt. żywotności, dodatkowe 20 pkt. pancerza i otrzymujesz o 1...10 pkt. mniej obrażeń.'],
319=>['Pośpiech','Postawa. Przez 8...20 sek., poruszasz się o 25% szybciej.','Postawa. (8...20 sek.) Poruszasz się o 25% szybciej.'],
320=>['Podcięcie Ścięgien','Atak mieczem. Jeśli atak trafi, twój cel zostanie okulawiony na 3...15 sek., przez co spadnie jego szybkość ruchu.','Atak mieczem. Wywołuje przypadłość okulawienie (3...15 sek.).'],
321=>['Dziki Cios','Atak wręcz. Tracisz całą adrenalinę. Jeśli atak trafi, spowoduje trafienie krytyczne i przerwanie wszystkich postaw, pod których działaniem był twój cel. Tego ataku nie można zablokować.','Atak wręcz. Zawsze trafienie krytyczne. Przerywa postawę. Nie do zablokowania. Pochłania całą adrenalinę.'],
322=>['Potężny Atak','Atak wręcz. Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń.','Atak wręcz. Zadaje +10...40 pkt. obrażeń.'],
323=>['Desperacki Cios','Atak wręcz. Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń, a twój cel otrzyma jedną z następujących przypadłości: głęboka rana (na 20 sek.), osłabienie (na 20 sek.), krwawienie (na 25 sek.) lub okulawienie (na 15 sek.). Po wykonaniu Desperackiego Ciosu, zostajesz powalony.','Atak wręcz. Zadaje +10...40 pkt. obrażeń. Wywołuje jedną losową przypadłość spośród następujących: głęboka rana (20 sek.), osłabienie (20 sek.), krwawienie (25 sek.) lub okulawienie (15 sek.). Zostajesz powalony.'],
324=>['Dreszcz Zwycięstwa','Atak wręcz. Jeśli ten cios trafi, otrzymujesz +20...40 pkt. obrażeń. Jeśli posiadasz więcej żywotności niż wybrany przeciwnik, otrzymujesz dawki adrenaliny w liczbie 1...2.','Atak wręcz. Zadaje +20...40 pkt. obrażeń. Jeśli masz większą żywotność od przeciwnika, otrzymujesz dawki adrenaliny w liczbie 1...2.'],
325=>['Rozpraszający Cios','Atak wręcz. Wyprowadź cios, który nie zadaje obrażeń, ale przerywa aktualną czynność celu (i czynności przeciwników w kontakcie z celem).','Atak wręcz. Trafia także przeciwników bezpośrednio przy twoim celu. Przerywa czynność. Trafia nie zadając obrażeń.'],
326=>['Uderzenie Obrońcy','Atak wręcz. Jeśli atak trafi przeciwnika w ruchu, zadajesz 10...40 pkt. dodatkowych obrażeń.','Atak wręcz. Zadaje +10...40 pkt. obrażeń, jeżeli cel się porusza.'],
327=>['Zamach Gryfa','Atak wręcz. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli atak jest zablokowany, cel zostaje powalony i otrzymuje 10...34 pkt. obrażeń.','Atak wręcz. Zadaje +5...20 pkt. obrażeń. Powala i zadaje 10...34 pkt. obrażeń, jeżeli nastąpiło blokowanie.'],
328=>['Czyste Uderzenie','Atak mieczem. Jeśli Czyste Uderzenie trafi, zadajesz +1...30 pkt. obrażeń. Jeśli nie przyjąłeś żadnej postawy, to Czyste Uderzenie nie może zostać zablokowane.','Atak mieczem. Zadaje +1...30 pkt. obrażeń. Nie do zablokowania, chyba że przyjąłeś postawę.'],
329=>['Rozłupanie Czaszki','Elitarny atak wręcz. Jeżeli atak trafi, przerywasz aktualną czynność wybranego przeciwnika. Jeśli przeciwnik rzucał czar, to na 15 sek. zostaje oszołomiony.','Elitarny atak wręcz. Przerywa czynność. Wywołuje przypadłość oszołomienie (15 sek.), jeżeli cel rzuca czar.'],
330=>['Młyniec','Atak toporem. Kolisty zamach toporem zadający wszystkim przeciwnikom bezpośrednio przy tobie +4...12 pkt. obrażeń.','Atak toporem. Przeciwnikom bezpośrednio przy tobie zadaje po +4...12 pkt. obrażeń.'],
331=>['Miażdżący Młot','Atak młotem. Tracisz całą adrenalinę. Jeśli Miażdżący Młot trafi, twój cel zostaje powalony.','Atak młotem. Powoduje powalenie. Pochłania całą adrenalinę.'],
332=>['Uderzenie Byka','Atak wręcz. Jeśli atak trafi przeciwnika będącego w ruchu, zadajesz +5...30 pkt. obrażeń, a twój cel zostaje powalony.','Atak wręcz. Zadaje +5...30 pkt. obrażeń i powoduje powalenie, jeżeli wybrany przeciwnik jest w ruchu.'],
333=>['Pomszczę Cię!','Okrzyk. Za każdego martwego sojusznika, otrzymujesz 10 sek. regeneracji żywotności +3...7 i szybkość twoich ataków zwiększa się o 25%.','Okrzyk. Posiadasz regenerację żywotności +3...7 i atakujesz o 25% szybciej (10 sek. za każdego martwego sojusznika).'],
334=>['Podcięcie Toporem','Atak toporem. Jeśli atak trafi przeciwnika z głęboką raną, zadajesz +4...16 pkt. obrażeń, a ten przeciwnik na 15 sek. zostaje okulawiony.','Atak toporem. Zadaje +4...16 pkt. obrażeń i wywołuje przypadłość okulawienie (15 sek.), jeżeli wybrany przeciwnik ma głęboką ranę.'],
335=>['Rozłupanie','Elitarny atak toporem. Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń oraz zadajesz 1...2 wrogom 10...40 pkt. obrażeń ciętych.','Elitarny atak toporem. Zadaje +10...40 pkt. obrażeń oraz zadaje 1...2 wrogom w bezpośrednim sąsiedztwie 10...40 pkt. obrażeń ciętych.'],
336=>['Uderzenie Kata','Atak toporem. Jeśli atak trafi, zadajesz +15...45 pkt. obrażeń.','Atak toporem. Zadaje +15...45 pkt. obrażeń.'],
337=>['Rozczłonkowanie','Atak toporem. Jeśli ten cios toporem trafi, zadaje głęboką ranę, obniżając na 5...20 sek. maksymalną żywotność celu o 20%.','Atak toporem. Wywołuje przypadłość głęboka rana (5...20 sek.).'],
338=>['Patroszenie','Elitarny atak toporem. Jeśli Patroszenie trafi, zadajesz +10...45 pkt. obrażeń i głęboką ranę, obniżając na 5...20 sek. maksymalną żywotność celu o 20%.','Elitarny atak toporem. Zadaje +10...45 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.).'],
339=>['Przeszywające Uderzenie','Atak toporem. Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń. Ten atak toporem posiada 20% przebicia pancerza.','Atak toporem. Zadaje +10...25 pkt. obrażeń. 20% przebicie pancerza.'],
340=>['Przerywające Cięcie','Atak toporem. Jeżeli atak trafi, przerywasz aktualną czynność wybranego przeciwnika. Jeżeli tą czynnością było rzucanie czaru, to czar ten zostaje wyłączony na 20 sek.','Atak toporem. Przerywa czynność. Efekt przerwania: przerwana umiejętność jest niedostępna przez +20 sek.'],
341=>['Szybkie Cięcie','Atak toporem. Jeśli ten atak trafi swój cel, zadajesz +1...20 obrażeń. Jeśli Szybkie Cięcie zostanie zablokowane, cel otrzymuje 1...20 pkt. obrażeń i głęboką ranę przez 20 sek.','Atak toporem. Zadaje +1...20 pkt. obrażeń. Zadaje 1...20 pkt. obrażeń i wywołuje przypadłość głęboka rana (20 sek.), jeżeli nastąpiło blokowanie.'],
342=>['Osłabiający Topór','Atak toporem. Jeśli atak trafi przeciwnika z głęboką raną, zadajesz 5...25 pkt. dodatkowych obrażeń i ten przeciwnik przez 20 sek. będzie cierpiał na osłabienie.','Atak toporem. Zadaje +5...25 pkt. obrażeń i wywołuje przypadłość osłabienie (20 sek.), jeżeli wybrany przeciwnik ma głęboką ranę.'],
343=>['Za Większą Sprawiedliwość!','Okrzyk. Przez 20 sek., za każdym razem, kiedy otrzymujesz adrenalinę, otrzymujesz jej o 100% więcej.','Okrzyk. (20 sek.) Otrzymujesz o 100% więcej adrenaliny.'],
344=>['Nawałnica Ciosów','Postawa. Przez 5 sek., twoja szybkość wyprowadzania ataków zwiększa się o 33%, ale zadajesz o 25% mniej obrażeń.','Postawa. (5 sek.) Atakujesz o 33% szybciej. Zadajesz o 25% mniej obrażeń.'],
345=>['Postawa Obronna','Postawa. Przez 1...5 sek., masz 75% szans na zablokowanie ataków wręcz i pocisków. Kiedy Postawa Obronna przestaje działać, otrzymujesz jedną dawkę adrenaliny za każdą posiadaną umiejętność walki wręcz (maksymalnie 0...4).','Postawa. (1...5 sek.) Masz 75% szans na zablokowanie ataków. Efekt końcowy: otrzymujesz jedną dawkę adrenaliny za każdą posiadaną umiejętność walki wręcz (maksymalnie 0...4).'],
346=>['Furia','Postawa. Przez 8 sek. atakujesz o 33% szybciej, ale odnosisz 175...125% obrażeń.','Postawa. (8 sek.) Atakujesz o 33% szybciej. Odnosisz 175...125% obrażeń.'],
347=>['Odporność na Ból','Umiejętność. Przez 7...18 sek., otrzymujesz dodatkowe 90...300 pkt. żywotności.','Umiejętność. (7...18 sek.) Twoja maksymalna żywotność zwiększa się o +90...300 pkt.'],
348=>['Pilnujcie się!','Okrzyk. Członkowie drużyny w zasięgu słuchu na 10 sek. otrzymują +5...25 pkt. pancerza. Ten zaśpiew przestanie działać po otrzymaniu 10 ataków.','Okrzyk. (10 sek.) Członkowie drużyny w zasięgu słuchu posiadają +5...25 pkt. pancerza. Przestanie działać po otrzymaniu 10 ataków.'],
349=>['Sprint','Postawa. Przez 8...14 sek., poruszasz się o 25% szybciej.','Postawa. (8...14 sek.) Poruszasz się o 25% szybciej.'],
350=>['Uderzenie w Brzuch','Atak młotem. Jeśli ten atak trafi powalnego przeciwnika, to wzbije się chmura pyłu, która na 3...7 sek. oślepi sąsiadujących przeciwników.','Atak młotem. Wywołuje przypadłość oślepienie u sąsiadujących przeciwników (3...7 sek.), jeżeli wybrany przeciwnik zostanie powalony.'],
351=>['Potężny Cios','Atak młotem. Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń.','Atak młotem. Zadaje +10...40 pkt. obrażeń.'],
352=>['Miażdżące Uderzenie','Atak młotem. Jeśli atak trafi, zadajesz +1...20 pkt. obrażeń. Jeśli trafisz powalonego przeciwnika zadajesz głęboką ranę, obniżając na 5...20 sek. maksymalną żywotność celu o 20%.','Atak młotem. Zadaje +1...20 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
353=>['Niedbały Zamach','Atak młotem. Atakujesz wszystkich sąsiadujących przeciwników. Każdy trafiony otrzymuje +1...20 pkt. obrażeń.','Atak młotem. Atakuje wszystkich sąsiadujących przeciwników zadając im +1...20 pkt. obrażeń.'],
354=>['Wstrząsotwórca','Elitarny atak młotem. Wszyscy przeciwnicy bezpośrednio przy tobie zostają powaleni. (50% szans na niepowodzenie, jeśli Biegłość w Młotach wynosi 4 lub mniej.)','Elitarny atak młotem. Powalasz wybranego przeciwnika i przeciwników bezpośrednio przy nim. 50% szans na niepowodzenie, chyba że wartość Biegłości w Młotach wynosi 5 lub więcej.'],
355=>['Druzgoczący Młot','Elitarny atak młotem. Jeśli Druzgoczący Młot trafi, twój cel zostaje powalony i przez 5...20 sek. cierpi na osłabienie.','Elitarny atak młotem. Powoduje powalenie. Wywołuje przypadłość osłabienie (5...20 sek.).'],
356=>['Nieblokowalne Uderzenie','Atak młotem. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli Nieblokowalne Uderzenie zostanie zablokowane, twój cel zostanie powalony i otrzyma 5...20 pkt. obrażeń.','Atak młotem. Zadaje +5...20 pkt. obrażeń. Zadaje 5...20 pkt. obrażeń i powala, jeżeli nastąpiło blokowanie.'],
357=>['Kontruderzenie','Atak młotem. Jeśli atak trafi atakującego przeciwnika, ten przeciwnik zostaje powalony.','Atak młotem. Powoduje powalenie, jeżeli wybrany przeciwnik atakuje.'],
358=>['Łamacz Kręgosłupa','Elitarny atak młotem. Jeśli Łamacz Kręgosłupa trafi, zadajesz +1...20 pkt. obrażeń, a twój cel zostaje powalony. Jeśli masz siłę 8 lub większą, powalenie trwa 4 sekundy.','Elitarny atak młotem. Zadaje +1...20 pkt. obrażeń. Powoduje powalenie. Powalenie trwa 4 sek. w przypadku siły na poziomie 8 lub wyższym.'],
359=>['Ciężki Cios','Atak młotem. Tracisz całą adrenalinę. Jeśli atak trafi osłabionego przeciwnika, to zostaje on powalony i otrzymuje +1...30 pkt. obrażeń.','Atak młotem. Zadaje +1...30 pkt. obrażeń i powala, jeżeli wybrany przeciwnik jest osłabiony. Pochłania całą adrenalinę.'],
360=>['Osłabiający Cios','Atak młotem. Jeśli cios trafi, twój cel na 5...20 sek. zostanie osłabiony.','Atak młotem. Wywołuje przypadłość osłabienie (5...20 sek.).'],
361=>['Sygnet Doljaka','Sygnet. Przez 8...20 sek. posiadasz +10...40 pkt. pancerza i nie możesz zostać powalony, ale twoja prędkość ruchu jest zmniejszona o 75%.','Sygnet. (8...20 sek.) Posiadasz +10...40 pkt. pancerza i nie możesz zostać powalony. Poruszasz się o 75% wolniej.'],
362=>['Spryt Wojownika','Umiejętność. Przez 5...11 sek., twoich ataków wręcz nie można zablokować.','Umiejętność. (5...11 sek.) Twoich ataków wręcz nie można blokować.'],
363=>['Uderzenie Tarczą','Umiejętność. Przez 5...11 sek. kiedy trzymasz tarczę, następna umiejętność walki wręcz użyta przeciwko tobie zostanie zablokowana, napastnik zostaje powalony, zaś sama umiejętność staje się niedostępna przez dodatkowe 15 sek.','Umiejętność. (5...11 sek.) Blokujesz następną umiejętność walki wręcz. Powoduje powalenie i zwiększa odnowienie tej umiejętności o +15 sek. Bez efektu, jeśli nie dzierżysz tarczy.'],
364=>['Szarża!','Elitarny okrzyk. Wszyscy sojusznicy w zasięgu przestają być okulawieni. Oprócz tego, przez 5...13 sek., sojusznicy ci poruszają się o 33% szybciej.','Elitarny okrzyk. (5...13 sek.) Sojusznicy w zasięgu słuchu poruszają się o 33% szybciej. Efekt początkowy: sojusznicy przestają być okulawieni.'],
365=>['Zwycięstwo Jest Moje!','Elitarny okrzyk. Za każdą przypadłość, pod której działaniem jest wybrany przeciwnik, otrzymujesz 10...68 pkt. żywotności i 3...7 pkt. energii.','Elitarny okrzyk. Za każdą przypadłość, pod której działaniem jest wybrany przeciwnik, otrzymujesz 10...68 pkt. żywotności i 3...7 pkt. energii.'],
366=>['Poznajcie Co To Strach!','Okrzyk. Wszyscy pobliscy przeciwnicy tracą 2...6 pkt. energii. Przez 1...15 sek., twoje ataki wręcz mają +5...30% szansy na zadanie trafienia krytycznego nieruchomym wrogom.','Okrzyk. (1...15 sek.) Masz o +5...30% większą szansę na trafienie krytyczne w nieruchomych wrogów. Efekt początkowy: pobliscy wrogowie tracą 2...6 pkt. energii.'],
367=>['Tarcze w Górę!','Okrzyk. Przez 5...11 sek. ty i wszyscy członkowie drużyny w zasięgu słuchu posiadacie +60 pkt. pancerza przeciwko atakom dystansowym.','Okrzyk. (5...11 sek.) Członkowie drużyny w zasięgu słuchu otrzymują po +60 pkt. pancerza przeciwko atakom zasięgowym.'],
368=>['Przetrwam!','Okrzyk. Za każdą przypadłość, pod której działaniem jesteś, otrzymujesz regenerację punkty żywotności +3. Ta regeneracja kończy się po 5...11 sek.','Okrzyk. (5...11 sek.) Za każdą przypadłość, pod której działaniem jesteś, otrzymujesz regenerację żywotności +3.'],
370=>['Postawa Berserkera','Postawa. Przez 8...14 sek., atakujesz o 33% szybciej i otrzymujesz o 100% adrenaliny więcej. Postawa Berserkera przestanie działać, kiedy użyjesz umiejętności.','Postawa. (8...14 sek.) Atakujesz o 33% szybciej i otrzymujesz o 100% więcej adrenaliny. Przestanie działać, jeśli użyjesz umiejętności.'],
371=>['Postawa Zrównoważona','Postawa. Przez 8...20 sek., nie możesz zostać powalony i nie otrzymujesz dodatkowych obrażeń od trafień krytycznych.','Postawa. (8...20 sek.) Nie możesz zostać powalony i nie otrzymujesz dodatkowych obrażeń z trafień krytycznych.'],
372=>['Obrona Gladiatora','Postawa elitarna. Przez 5...11 sek., masz 75% szans na blokowanie skierowanych przeciwko tobie ataków. Jeśli zablokujesz w ten sposób atak w walce wręcz, atakujący otrzymuje 5...35 pkt. obrażeń.','Postawa elitarna. (5...11 sek.) Masz 75% szans na blokowanie. Atakujący otrzymuje 5...35 pkt. obrażeń, za każdym razem, kiedy zablokujesz w ten sposób atak wręcz.'],
373=>['Odbijanie Strzał','Postawa. Przez 1...6 sek., masz 75% szans na zablokowanie ataków. Jeśli zablokujesz pocisk, pobliscy wrogowie zaczyną krwawić przez 5...15 sek.','Postawa. (1...6 sek) Masz 75% szans na zablokowanie ataków. Pobliscy wrogowie zaczyną krwawić przez (5...15 sek.), jeśli uda ci się zablokować pocisk.'],
374=>['Wytrzymałość Wojownika','Umiejętność elitarna. Przez 5...35 sek., za każdym razem kiedy trafisz w walce wręcz, otrzymujesz 3 punkty Energii. Wytrzymałość Wojownika nie może zwiększyć twojej energii powyżej 10...25 pkt.','Umiejętność elitarna. (5...35 sek.) Otrzymujesz 3 punkty Energii, za każdym razem, kiedy twój atak wręcz trafi. Nie otrzymujesz energii, jeżeli masz więcej niż 10...25 pkt. energii.'],
375=>['Krasnoludzka Postawa Bojowa','Postawa elitarna. Przez 5...11 sek., jeśli walczysz młotem, atakujesz 33% szybciej, otrzymujesz +40 do pancerza, a twoja umiejętność przerywa akcję przeciwnika po trafieniu.','Postawa elitarna. (5...11 sek.) Atakujesz 33% szybciej, otrzymujesz +40 do pancerza, a twoje umiejętności ataku przerywają akcje przeciwnika. Bez efektu, jeśli nie korzystasz z młota.'],
376=>['Postawa Zdyscyplinowana','Postawa. Przez 1...4 sek. posiadasz +10 punktów pancerza i masz 75% szans na blokowanie ataków. Postawa Zdyscyplinowana przestaje działać, jeśli użyjesz umiejętności opartej na adrenalinie.','Postawa. (1...4 sek.) Posiadasz 75% szans na blokowanie i +10 pkt. pancerza. Kończy się, jeśli użyjesz umiejętności opartej na adrenalinie.'],
377=>['Czujna Postawa','Postawa. Przez 1...6 sek., blokujesz wszystkie umiejętności związane z atakiem, których jesteś celem. Za każdy udany blok otrzymujesz adrenalinę i 5 pkt. energii. Czujna Postawa przestaje działać, jeśli użyjesz umiejętności.','Postawa. (1...6 sek.) Blokujesz umiejętności związane z atakowaniem. Za każdy blok otrzymujesz adrenalinę i 5 pkt. energii. Przestanie działać, jeśli użyjesz umiejętności.'],
378=>['Postawa Tarczownika','Postawa. Przez 1...6 sek, jeśli używasz tarczy, masz 75% szans na zablokowanie ataków, a otrzymywane obrażenia są zmniejszone o 2 za każdy poziom siły (maksymalna redukcja obrażeń to 15 pkt.).','Postawa. (1...6 sek.) Masz 75% szans na zablokowanie ataków. Otrzymywane obrażenia zostają zmniejszone o 2 za każdy poziom siły (maksymalna redukcja obrażeń to 15 pkt/). Bez efektu, jeśli nie używasz tarczy.'],
379=>['Szarża Byka','Postawa elitarna. Przez 1...7 sek. poruszasz się o 50% szybciej i jeśli trafisz w walce wręcz poruszającego się przeciwnika, ten przeciwnik zostanie powalony. Szarża Byka przestaje działać, gdy użyjesz umiejętności.','Postawa elitarna. (1...7 sek.). Poruszasz się o 50% szybciej. Powala, jeśli atakiem wręcz trafisz poruszającego się przeciwnika. Przestanie działać, jeśli użyjesz umiejętności.'],
380=>['Obrona Bonetti\'ego','Postawa. Przez 5...11 sek. masz 75% szans na blokowanie ataków wręcz i ataków zasięgowych. Za każdy zablokowany atak wręcz otrzymujesz 5 pkt. energii. Obrona Bonetti\'ego przestanie działać, kiedy użyjesz umiejętności.','Postawa. (5...11 sek.) Masz 75% szans na blokowanie. Za każdy zablokowany atak wręcz otrzymujesz 5 pkt. energii. Przestanie działać, jeśli użyjesz umiejętności.'],
381=>['Sto Ostrzy','Umiejętność elitarna. Przez 15 sek., za każdym razem, kiedy zaatakujesz mieczem, wszyscy przeciwnicy bezpośrednio przy tobie otrzymają po 10...35 pkt. obrażeń ciętych.','Umiejętność elitarna. (15 sek.) Przeciwnikom bezpośrednio przy tobie zadaje po 10...35 pkt. obrażeń ciętych, jeśli atakujesz mieczem.'],
382=>['Przecięcie Tętnicy','Atak mieczem. Jeśli atak trafi, twój cel na 5...25 sek. zaczyna krwawić, tracąc wtedy żywotność.','Atak mieczem. Wywołuje przypadłość krwawienie (5...25 sek.).'],
383=>['Cięcie Galratha','Atak mieczem. Jeśli atak trafi, zadajesz +1...40 pkt. obrażeń.','Atak mieczem. Zadaje +1...40 pkt. obrażeń.'],
384=>['Głębokie Cięcie','Atak mieczem. Jeśli atak trafi krwawiącego przeciwnika, zadajesz 5...20 pkt. dodatkowych obrażeń i głęboką ranę, obniżając na 5...20 sek. maksymalną żywotność celu o 20%.','Atak mieczem. Zadaje +5...20 pkt. obrażeń i wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli twój cel krwawi.'],
385=>['Kończące Pchnięcie','Atak mieczem. Tracisz całą adrenalinę. Jeśli Kończące Pchnięcie trafi, zadajesz 5...40 pkt. dodatkowych obrażeń. Te obrażenia zostają podwojone, jeśli żywotność twojego celu była poniżej 50%.','Atak mieczem. Zadaje +5...40 pkt. obrażeń. Zadaje +5...40 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik ma poniżej 50% żywotności. Pochłania całą adrenalinę.'],
386=>['Przeszywające Ostrze','Atak mieczem. Jeśli atak trafi, zadajesz +1...20 pkt. obrażeń. Jeśli Przeszywające Ostrze zostanie zablokowane, twój cel zaczyna krwawić na 25 sek. i otrzymuje 1...20 pkt. obrażeń.','Atak mieczem. Zadaje +1...20 pkt. obrażeń. Zadaje 1...20 pkt. obrażeń i wywołuje przypadłość krwawienie (25 sek.), jeżeli nastąpiło blokowanie.'],
387=>['Riposta','Umiejętność. Przez 8 sek., kiedy trzymasz miecz, blokujesz następny atak w walce wręcz skierowany w ciebie, a napastnik otrzymuje 20...80 pkt. obrażeń.','Umiejętność. (8 sek.) Blokujesz następny atak wręcz, a atakujący otrzymuje 20...80 pkt. obrażeń. Bez efektu, jeśli nie dzierżysz miecza.'],
388=>['Zabójcza Riposta','Umiejętność. Przez 8 sek., kiedy trzymasz miecz, blokujesz następny atak w walce wręcz skierowany w ciebie, a napastnik otrzymuje 15...90 pkt. obrażeń i zaczyna krwawić przez 3...25 sek.','Umiejętność. (8 sek.) Blokujesz następny atak wręcz, a atakujący otrzymuje 15...90 pkt. obrażeń. Wywołuje przypadłość krwawienie (3...25 sek.). Bez efektu, jeśli nie dzierżysz miecza.'],
389=>['Popis bronią','Umiejętność elitarna. Wszystkie twoje umiejętności związane z atakiem się odnawiają. Za każdą umiejętność odnowioną w ten sposób otrzymujesz 2...7 pkt. energii.','Umiejętność elitarna. Odnawia twoje umiejętności związane z atakowaniem. Za każdą odnowioną umiejętność otrzymujesz 2...7 pkt. energii.'],
390=>['Brutalne Cięcie','Atak mieczem. Jeżeli atak trafi, przerywasz czynność wybranego przeciwnika. Jeśli tą czynnością było użycie czaru, to zadajesz 1...40 pkt. dodatkowych obrażeń.','Atak mieczem. Przerywa czynność. Efekt przerwania: zadaje +1...40 pkt. obrażeń, jeżeli czynnością było rzucanie czaru.'],
391=>['Strzał Myśliwego','Strzał z łuku. Jeśli Strzał Myśliwego trafi, twój cel zaczyna krwawić na 3...25 sek.','Strzał z łuku. Wywołuje przypadłość krwawienie (3...25 sek.).'],
392=>['Przygwożdżenie','Strzał z łuku. Jeśli Przygwożdżenie trafi, twój cel zostanie okulawiony na 3...15 sek.','Strzał z łuku. Wywołuje przypadłość okulawienie (3...15 sek.).'],
393=>['Okulawiający Strzał','Elitarny strzał z łuku. Jeśli Okulawiający Strzał trafi, twój cel zostanie okulawiony na 4...14 sek. Tego ataku nie można zablokować.','Elitarny strzał z łuku. Nie do zablokowania. Powoduje okulawienie (4...14 sek.).'],
394=>['Potężny Strzał','Strzał z łuku. Jeśli Potężny Strzał trafi, wybrany przeciwnik otrzymuje +25...50 pkt. obrażeń.','Strzał z łuku. Wybrany przeciwnik otrzymuje 25...50 pkt. obrażeń.'],
395=>['Grad Strzał','Elitarny strzał z łuku. Wszystkie przygotowania zostają usunięte. Wystrzeliwuje strzały w wybranego wroga i maksymalnie 5 stojących obok celów. Każda z tych strzał zadaje +5...20 pkt. obrażeń, jeśli trafi.','Elitarny strzał z łuku. Zadaje 5...20 pkt. obrażeń. Trafia 5 wrogów stojących obok celu. Wszystkie przygotowania zostają usunięte.'],
396=>['Podwójny Strzał','Strzał z łuku. Wystrzeliwujesz w wybranego przeciwnika na raz dwie strzały. Strzały zadają o 25% mniej obrażeń.','Strzał z łuku. W wybranego przeciwnika wystrzeliwujesz jednocześnie dwie strzały. Te strzały zadają o 25% mniej obrażeń.'],
397=>['Szybki Strzał','Elitarny strzał z łuku. Wystrzeliwujesz strzałę, która leci dwa razy szybciej.','Elitarny strzał z łuku. Wystrzeliwujesz strzałę, która leci dwa razy szybciej.'],
398=>['Przeszywający Atak','Strzał z łuku. Jeśli Przeszywający Atak trafi, zadajesz +5...25 pkt. obrażeń. Ten atak ma 10% przebicie pancerza.','Strzał z łuku. Zadaje +5...25 pkt. obrażeń. 10% przebicie pancerza.'],
399=>['Przerywający Strzał','Strzał z łuku. Jeśli Przerywający Strzał trafi, przerywa bieżącą czynność celu, ale zadaje jedynie 1...16 pkt. obrażeń. Jeśli tą czynnością było użycie umiejętności, to ta umiejętność będzie niedostępna przez dodatkowe 20 sek.','Strzał z łuku. Przerywa czynność. Efekt przerwania: przerwana umiejętność jest niedostępna przez +20 sek. Zadaje jedynie 1...16 pkt. obrażeń.'],
400=>['Precyzyjny Strzał','Strzał z łuku. Jeśli Precyzyjny Strzał trafi, zadajesz +3...10 pkt. obrażeń. Precyzyjnego Strzału nie można zablokować. Atak ten łatwo przerwać.','Strzał z łuku. Zadaje +3...10 pkt. obrażeń. Nie do zablokowania. Łatwo przerwać.'],
402=>['Zdecydowany Strzał','Strzał z łuku. Jeśli Zdecydowany Strzał trafi, zadajesz +5...20 pkt. obrażeń. Jeśli natomiast chybi, wszystkie twoje umiejętności związane z atakiem odnowią się.','Strzał z łuku. Zadaje +5...20 pkt. obrażeń. Odnawia twoje umiejętności związane z atakowaniem, jeżeli nie trafi.'],
403=>['Pewny Strzał','Strzał z łuku. Wystrzeliwujesz strzałę, która leci trzy razy szybciej i nie można jej zablokować.','Strzał z łuku. Wystrzeliwujesz strzałę, która leci trzy razy szybciej. Nie do zablokowania.'],
404=>['Zatruta Strzała','Elitarny strzał z łuku. Jeśli Zatruta Strzała trafi, twój cel przez 5...20 sek. będzie zatruty.','Elitarny strzał z łuku. Wywołuje przypadłość zatrucie (5...20 sek.).'],
405=>['Obiecany Strzał','Elitarny strzał z łuku. Jeśli Strzał Przysięgi trafi w cel, wszystkie pozostałe umiejętności zostaną odnowione. Jeśli nie trafi, wszystkie twoje umiejętności zostaną zablokowane na 10...4 sek. (50% szansy na spudłowanie przy Biegłości 7 lub mniej.)','Elitarny strzał z łuku. Jeśli trafi, odnawia wszystkie pozostałe umiejętności. Jeśli spudłuje, blokuje wszystkie umiejętności (10...4 sek.) 50% szansy na spudłowanie, o ile nie masz Biegłości 8 lub wyżej.'],
406=>['Wyniszczający Strzał','Strzał z łuku. Jeśli Wyniszczający Strzał trafi, twój cel traci 1...10 pkt. energii.','Strzał z łuku. Powoduje utratę 1...10 pkt. energii.'],
407=>['Strzał z Bliska','Strzał z łuku. Wystrzeliwujesz strzałę, która ma połowę normalnego zasięgu, ale zadaje +10...40 pkt. obrażeń.','Strzał z łuku o połowie zasięgu. Zadaje +10...40 pkt. obrażeń.'],
408=>['Oszałamiający Strzał','Strzał z łuku. Jeśli Oszałamiający Strzał trafi przeciwnika rzucającego czar, rzucanie czaru zostanie przerwane, a cel będzie oszołomiony przez 5...20 sek. Ten strzał zadaje jedynie 1...16 pkt. obrażeń.','Strzał z łuku. Przerywa czar. Efekt przerwania: wywołuje przypadłość oszołomienie (5...20 sek.). Zadaje jedynie 1...16 pkt. obrażeń.'],
409=>['Karzący Strzał','Elitarny strzał z łuku. Jeśli Karzący Strzał trafi, zadajesz +10...20 pkt. obrażeń, a czynność celu zostaje przerwana.','Elitarny strzał z łuku. Zadaje +10...20 pkt. obrażeń. Przerywa czynność.'],
411=>['Oswojenie Zwierzęcia','Umiejętność. Oswajasz wskazane zwierzę. Po oswojeniu, twój zwierzęcy towarzysz będzie z tobą podróżował, jeśli tylko na pasku umiejętności będziesz miał Oswojenie Zwierzęcia. Nie możesz oswoić zwierzęcia, które przewyższa cię więcej niż o 4 poziomy.','Umiejętność. Oswajasz wskazane zwierzę. Po oswojeniu, twój zwierzęcy towarzysz będzie z tobą podróżował, jeśli tylko na pasku umiejętności będziesz miał Oswojenie Zwierzęcia. Nie możesz oswoić zwierzęcia, które przewyższa cię więcej niż o 4 poziomy.'],
412=>['Zew Ochrony','Okrzyk. Przez 120 sek. twój zwierzęcy towarzysz posiada 5...20 pkt. redukcję obrażeń.','Okrzyk. (120 sek.) Twój zwierzęcy towarzysz posiada 5...20 pkt. redukcję obrażeń.'],
415=>['Zew Pośpiechu','Okrzyk. Przez 30 s twój zwierzęcy towarzysz atakuje i porusza się o 33% szybciej.','Okrzyk. (30 sekund) Twój zwierzak porusza się i atakuje o 33 % szybciej.'],
422=>['Ożywienie Zwierzęcia','Umiejętność. Wskrzeszasz wszystkich zaprzyjaźnionych zwierzęcych towarzyszy w okolicy. Każdy z nich wraca do życia z 10...94% żywotności.','Umiejętność. Wskrzeszasz wszystkie sojusznicze zwierzaki w okolicy (10...94% żywotności).'],
423=>['Symbiotyczne Więzy','Okrzyk. Przez 120...300 sek., twój zwierzęcy towarzysz otrzymuje regenerację żywotności równą 1...3 i połowa fizycznych obrażeń zadawanych twojemu zwierzęcemu towarzysz jest przenoszona na ciebie.','Okrzyk. (120...300 sek.) Twój zwierzęcy towarzysz posiadasz regenerację żywotności +1...3. Połowa obrażeń zadawanych twojemu zwierzęcemu towarzyszowi jest przekierowywana na ciebie.'],
424=>['Rzut Piachem','Umiejętność. Dotknięty cel i przeciwnicy bezpośrednio przy nim zostają oślepieni na 3...15 sek.','Umiejętność dotykowa. Wywołuje przypadłość oślepienie (3...15 sek.). Działa także na przeciwników bezpośrednio przy wybranym przeciwniku.'],
425=>['Unik','Postawa. Przez 5...11 sek., poruszasz się o 33% szybciej i masz 27...75% szans na zablokowanie nadlatujących pocisków. Unik skończy się kiedy zaatakujesz.','Postawa. (5...11 sek.) Poruszasz się o 33% szybciej i masz 27...75% szans na blokowanie pocisków. Przestanie działać, jeśli zaatakujesz.'],
426=>['Brutalny Strzał','Strzał z łuku. Jeśli Brutalny Strzał trafi, przerywa bieżącą czynność celu. Jeśli tą czynnością było użycie czaru, to zadajesz +13...28 pkt. obrażeń.','Strzał z łuku. Przerywa czynność. Efekt przerwania: zadaje +13...28 pkt. obrażeń, jeżeli czynnością było rzucanie czaru.'],
427=>['Sygnet Antidotum','Sygnet. Oczyszczasz się z zatrucia, choroby, oślepienia i jednej dodatkowej przypadłości.','Sygnet. Usuwa z ciebie zatrucie, chorobę, oślepienie i jedną dodatkową przypadłość.'],
428=>['Zapalające Strzały','Elitarny strzał z łuku. Wystrzeliwujesz strzały w wybranego przeciwnika i maksymalnie 2 przeciwników będących w pobliżu niego. Trafieni przeciwnicy zostają podpaleni na 1...3 sek.','Elitarny strzał z łuku. Trafia 2 przeciwników w pobliżu twojego celu i podpala ich (1...3 sek.).'],
429=>['Strzały Melandru','Elitarne przygotowanie. Przez 18 sek., kiedy tylko twoje strzały trafią, wywołują krwawienie na 3...25 sek. i dodatkowo, jeśli trafią w cel, który jest pod działaniem zaklęcia, zadają +8...28 pkt. obrażeń.','Elitarne przygotowanie. (18 sek.) Twoje strzały wywołują przypadłość krwawienie (3...25 sek.) i zadają +8...28 pkt. obrażeń przeciwnikom pod działaniem zaklęcia.'],
430=>['Ryzyko Strzelca','Elitarne przygotowanie. Przez 18 sek., za każdym razem kiedy twoja strzała trafi otrzymujesz 5...10 pkt. energii, ale za każdym razem kiedy chybi tracisz 10 pkt. energii.','Elitarne przygotowanie. (18 sek.) Otrzymujesz 5...10 pkt. energii, za każdym razem, kiedy twoje strzały trafiają. Tracisz 10 pkt. energii, jeśli nie trafisz.'],
431=>['Strzały Wybuchające','Przygotowanie. Przez 24 sek. twoje strzały eksplodują przy trafieniu, zadając celowi i wszystkim przeciwnikom znajdującym się bezpośrednio przy nim 3...18 pkt. obrażeń od ognia.','Przygotowanie. (24 sek.) Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim twoje strzały zadają po 3...18 pkt. obrażeń od ognia.'],
432=>['Czytanie Wiatru','Przygotowanie. Przez 24 sek., twoje strzały lecą dwa razy szybciej i zadają 3...10 pkt. dodatkowych obrażeń.','Przygotowanie. (24 sek.) +3...10 pkt. obrażeń. Twoje strzały lecą dwa razy szybciej.'],
433=>['Płonące Strzały','Przygotowanie. Przez 24 sek., twoje strzały zadają obrażenia od ognia i dodatkowe 3...24 pkt. obrażeń od ognia.','Przygotowanie. (24 sek.) +3...24 pkt. obrażeń od ognia. Twoje strzały zadają obrażenia od ognia.'],
434=>['Duszący Gaz','Przygotowanie. Przez 1...12 sek. twoje strzały zadają 1...8 pkt. dodatkowych obrażeń i roznoszą Duszący Gaz na wszystkich przeciwników bezpośrednio przy celu. Duszący Gaz przerywa próby rzucania czarów.','Przygotowanie. (1...12 sek.) +1...8 pkt. obrażeń. Roznosi Duszący Gaz na przeciwników bezpośrednio przy celu. Duszący Gaz przerywa rzucanie czarów.'],
435=>['Nakładanie Trucizny','Przygotowanie. Przez 24 sek., cele trafione przez twoje fizyczne ataki zostają zatrute na 3...15 sek.','Przygotowanie. (24 sek.) Twoje fizyczne ataki wywołują przypadłość zatrucie (3...15 sek.).'],
436=>['Uzdrowienie Zwierzęcia','Umiejętność. Leczysz swojego zwierzęcego towarzysza dodając mu 40...120 pkt. żywotności. Jeśli jest martwy, wskrzeszasz go z 10...58% punktami żywotności. Jeśli masz na wyposażeniu Uzdrowienie Zwierzęcia, twój towarzysz będzie podróżował wraz z tobą.','Umiejętność. Twój zwierzęcy towarzysz otrzymuje 40...120 pkt. żywotności. Wskrzesza twojego zwierzęcego towarzysza (10...58% żywotności). Jeśli masz na wyposażeniu Uzdrowienie Zwierzęcia, twój towarzysz będzie podróżował wraz z tobą.'],
437=>['Bestialski Skok','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Bestialski Skok, który zadaje +5...20 pkt. obrażeń. Jeśli atak trafi przeciwnika rzucającego czar, to przeciwnik ten zostanie powalony.','Atak zwierzaka. Zadaje +5...20 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik rzuca czar.'],
438=>['Okaleczające Uderzenie','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Okaleczające Uderzenie, które zadaje +5...20 pkt. obrażeń. Jeśli atak trafi przeciwnika, to przeciwnik ten zostanie okulawiony na 3...15 sek.','Atak zwierzaka. Zadaje +5...20 pkt. obrażeń. Po trafieniu powoduje okulawienie (na 3...15 sek.).'],
439=>['Dzikie Pchnięcie','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Dzikie Pchnięcie, które zadaje +5...35 pkt. obrażeń. Jeśli atak trafi atakującego przeciwnika, to przeciwnik ten przez 5...25 sek. będzie krwawił.','Atak zwierzaka. Zadaje +5...35 pkt. obrażeń. Wywołuje przypadłość krwawienie (5...25 sek.), jeżeli wybrany przeciwnik atakuje.'],
440=>['Uderzenie Padlinożercy','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Uderzenie Padlinożercy, które zadaje +10...25 pkt. obrażeń. Jeśli atak trafi przeciwnika, pod działaniem przypadłości, to otrzymujesz +3...15 pkt. energii.','Atak zwierzaka. Zadaje +10...25 pkt. obrażeń. Otrzymujesz 3...15 pkt. energii, jeżeli wybrany przeciwnik jest pod działaniem przypadłości.'],
441=>['Natarcie Melandru','Atak zwierzaka. Twój zwierzęcy towarzysz próbuje wykonać Natarcie Melandru, które zadaje +5...20 pkt. obrażeń wszystkim przeciwnikom znajdującym się w pobliżu.','Atak zwierzaka. Zadaje +5...20 pkt. obrażeń przeciwnikom znajdującym się w pobliżu.'],
442=>['Zajadłe Uderzenie','Elitarny atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Zajadłe Uderzenie, które zadaje +13...28 pkt. obrażeń. Jeśli atak trafi, to otrzymujesz adrenalinę i 3...10 pkt. energii.','Elitarny atak zwierzaka. Zadaje +13...28 pkt. obrażeń. Otrzymujesz adrenalinę i 3...10 pkt. energii.'],
443=>['Skok Drapieżnika','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Skok Drapieżnika, który zadaje +5...35 pkt. obrażeń. Jeśli atak trafi, to twój zwierzęcy towarzysz otrzymuje 5...50 pkt. żywotności.','Atak zwierzaka. Zadaje +5...35 pkt. obrażeń. Twój zwierzęcy towarzysz otrzymuje 5...50 pkt. żywotności, jeżeli ten atak trafi.'],
444=>['Brutalne Uderzenie','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Brutalne Uderzenie, które zadaje +5...35 pkt. obrażeń. Jeśli atak trafi przeciwnika, którego żywotność jest poniżej 50%, to przeciwnik ten otrzyma +5...35 pkt. dodatkowych obrażeń.','Atak zwierzaka. Zadaje +5...35 pkt. obrażeń. Zadaje +5...35 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik ma poniżej 50% żywotności.'],
445=>['Przerywające Uderzenie','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Przerywające Uderzenie, które zadaje +1...12 pkt. obrażeń. Jeśli atak trafi przeciwnika używającego umiejętności, to umiejętność ta zostanie przerwana i będzie niedostępna przez dodatkowe 20 sek.','Atak zwierzaka. Zadaje +1...12 pkt. obrażeń. Przerywa umiejętność. Efekt przerwania: przerwana umiejętność będzie niedostępna przez +20 sek.'],
446=>['Maść z Trolla','Umiejętność. Przez 13 sek. posiadasz regenerację żywotności równą +3...10.','Umiejętność. (13 sek.) Posiadasz regenerację żywotności +3...10.'],
447=>['Ryk Otyugha','Okrzyk. Przez 10...25 sek., twój zwierzęcy towarzysz posiada +24 pkt. pancerza, dodatkowo jego ataków nie można zablokować.','Okrzyk. (10...25 sek.) Twój zwierzęcy towarzysz ma +24 pkt. pancerza, a jego ataków nie można blokować.'],
448=>['Ucieczka','Postawa elitarna. Przez 1...8 sek., poruszasz się o 33% szybciej i masz 75% szansy na zablokowanie ataków.','Postawa elitarna. (1...8 sek.) Poruszasz się o 33% szybciej i masz 75% szans na blokowanie.'],
449=>['Postawa Wyćwiczona','Postawa elitarna. Przez 20...35 sek. twoje przygotowania odnawiają się o 50% szybciej i trwają o 30...300% dłużej.','Postawa elitarna. (20...35 sek.) Twoje przygotowania odnawiają się o 50% szybciej i trwają o 30...300% dłużej.'],
450=>['Wirująca Obrona','Postawa. Przez 8...20 sek., masz 75% szans na zablokowanie ataków. Jeśli zablokujesz w ten sposób atak strzelecki, przeciwnicy bezpośrednio przy tobie otrzymają 5...11 pkt. obrażeń.','Postawa. (8...20 sek.) Masz 75% szans na blokowanie. Zadaje 5...11 pkt. obrażeń przeciwnikom bezpośrednio przy tobie, za każdym razem, kiedy zablokujesz atak zasięgowy.'],
451=>['Wytrzymałość Melandru','Postawa elitarna. Przez 8...20 sek., za każdą przypadłość i klątwę, pod których jesteś działaniem, otrzymujesz regenerację żywotności równą +4 i regenerację energii równą +1.','Postawa elitarna. (8...20 sek.) Za każdą przypadłość i klątwę, pod których jesteś działaniem, otrzymujesz regenerację żywotności +4 i regenerację energii +1.'],
452=>['Obrona Drydera','Postawa. Przez 5...11 sek., masz 75% szans na zablokowanie ataków i otrzymujesz 34...60 pkt. pancerza przeciwko obrażeniom od żywiołów.','Postawa. (5...11 sek.) Masz 75% szans na blokowanie i +34...60 pkt. pancerza przeciwko obrażeniom od żywiołów.'],
453=>['Błyskawiczny Refleks','Postawa. Przez 5...11 sek., masz 75% szans na zablokowanie ataków wręcz i strzeleckich, a dodatkowo atakujesz o 33% szybciej.','Postawa. (5...11 sek.) Atakujesz o 33% szybciej i masz 75% szans na blokowanie.'],
454=>['Tygrysia Furia','Postawa. Wszystkie twoje umiejętności nie związane z atakami będą niedostępne przez 5 sek. Przez 5...11 sek., atakujesz o 33% szybciej.','Postawa. (5...11 sek.) Atakujesz o 25% szybciej. Wyłacza twoje umiejętności nie związane z atakami (5 sek.).'],
455=>['Łowca Burz','Postawa. Przez 8...20 sek., poruszasz się o 25% szybciej i za każdym razem kiedy otrzymasz obrażenia od żywiołów, dostaniesz 1...5 pkt. energii.','Postawa. (8...20 sek.) Poruszasz się o 25% szybciej i otrzymujesz 1...5 pkt. energii, za każdym razem, kiedy otrzymujesz obrażenia od żywiołów.'],
456=>['Szybkość Węża','Postawa. Przez 15...30 sek., czas odnawiania twoich umiejętności zmniejsza się o 33%. Szybkość Węża skończy się kiedy twoja żywotność spadnie poniżej 50%.','Postawa. (15...30 sek.) Twoje umiejętności odnawiają się o 33% szybciej. Przestanie działać, jeśli twoja żywotność spadnie poniżej 50%.'],
457=>['Pyłowa Pułapka','Pułapka. Kiedy Pyłowa Pułapka zostanie uaktywniona, to w każdej sekundzie (5 sek. łącznie), wszyscy przeciwnicy w pobliżu zostaną oślepieni na 3...8 sek. i otrzymają po 10...25 pkt. obrażeń od ziemi. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać. Pyłowa Pułapka przestanie działać po 90 sek.','Pułapka. (90 sek.) Działa na przeciwników w pobliżu. W każdej sekundzie zadaje 10...25 pkt. obrażeń (5 sek.). Co sekundę (5 sek.) wywołuje przypadłość oślepienie (3...8 sek.). Łatwo przerwać.'],
458=>['Kolczasta Pułapka','Pułapka. Kiedy Kolczasta Pułapka zostanie uruchomiona, to wszyscy przeciwnicy w pobliżu otrzymują 7...23 obrażeń przebijających, zostają okulawieni i na 3...25 sek. zaczynają krwawić. Kolczasta Pułapka przestaje działać po 90 sekundach. W czasie, kiedy będziesz używać tej umiejętności, łatwo ci będzie przerwać.','Pułapka. (90 sek.) Działa na przeciwników w pobliżu. Zadaje 7...23 pkt. obrażeń przebijających. Wywołuje przypadłości okulawienie oraz krwawienie (3...25 sek.). Łatwo przerwać.'],
459=>['Płomienna Pułapka','Pułapka. Kiedy Płomienna Pułapka zostanie uruchomiona, to w każdej sekundzie (z 3 łącznie) wszyscy przeciwnicy w pobliżu otrzymują 5...20 pkt. obrażeń od ognia i zaczynają płonąć przez 1...3 sek. Płomienna Pułapka przestaje działać po 90 sekundach. W czasie, kiedy będziesz używać tej umiejętności, łatwo ci będzie przerwać.','Pułapka. (90 sek.) Działa na przeciwników w pobliżu. W każdej sekundzie zadaje 5...20 pkt. obrażeń od ognia (3 sek.). Wywołuje przypadłość płonięcie (1...3 sek.). Łatwo przerwać.'],
460=>['Uzdrawiające Źródło','Pułapka. Przez 10 sek., wszyscy sojusznicy znajdujący się bezpośrednio przy źródle są uzdrawiani co 2 sekundy, otrzymując 15...60 pkt. żywotności. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','Pułapka. (10 sek.) Działa na sojuszników w bezpośredniej odległości. Co 2 sek. dodaje 15...60 pkt. żywotności. Łatwo przerwać.'],
461=>['Pułapka z Ostrzy','Pułapka elitarna. Kiedy Pułapka z Ostrzy zostanie uruchomiona, to w każdej sekundzie (przez 2 sek.) wszyscy przeciwnicy w pobliżu otrzymują po 10...40 pkt. obrażeń przebijających, zostaną okulawieni na 3...25 sek. i powaleni. Pułapka z Ostrzy przestanie działać po 90 sek. W czasie, kiedy będziesz używać tej umiejętności, łatwo ci będzie przerwać.','Pułapka elitarna. (90 sek.) Działa na przeciwników w pobliżu. Co sekundę (przez 2 sek.) zadaje 10...40 pkt. obrażeń przebijających, powala i wywołuje przypadłość okulawienie (3...25 sek.). Łatwo przerwać.'],
462=>['Zima','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Dla stworzeń w jego zasięgu wszystkie obrażenia od żywiołów stają się obrażeniami od zimna. Duch umiera po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Dla stworzeń w zasięgu zamienia obrażenia od żywiołów na obrażenie od zimna. Nie działa na duchy.'],
463=>['Odsiew','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Wszystkie stworzenia nie-duchy w jego zasięgu otrzymują 4 dodatkowe obrażenia za każdym razem, kiedy otrzymają fizyczne obrażenia. Duch umiera po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). O +4 zwiększa obrażenia fizyczne zadawane przez stworzenia w zasięgu. Nie działa na duchy.'],
464=>['Skraj Wymarcia','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Jeśli w jego zasięgu zginie jakieś stworzenie nie-duch, to Skraj Wymarcia zada 14...50 pkt. obrażeń wszystkim stworzeniom tego samego typu w swoim zasięgu, które posiadają mniej niż 90% żywotności. Duch umiera po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Zadaje 14...50 pkt. obrażeń stworzeniom w zasięgu, za każdym razem, kiedy zginie stworzenie tego samego rodzaju. Nie działa na duchy. Bez obrażeń dla stworzeń, które mają więcej niż 90% żywotności.'],
465=>['Większa Pożoga','Elitarny obrządek natury. Tworzysz 1...10 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu wszystkie obrażenia fizyczne stają się w zamian obrażeniami od ognia. Duch umiera po 30...240 sek.','Elitarny obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Dla stworzeń w zasięgu zamienia obrażenia fizyczne na obrażenia od ognia. Nie działa na duchy.'],
466=>['Pożoga','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Wszystkie strzały, które trafiają stworzenia nie-duchy w jego zasięgu zadają obrażenia od ognia. Ten duch ginie po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Wszystkie strzały stworzeń w zasięgu zadają obrażenia od ognia. Nie działa na duchy.'],
467=>['Czas Obfitości','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Wszystkim stworzeniom nie-duchom w jego zasięgu maksymalna żywotność zwiększa się o +50...150 i pancerz o +8. Duch umiera po 15...90 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 15...90 sek.). Stworzenia w zasięgu posiadają +50...150 pkt. do maksymalnej żywotności i +8 pkt. pancerza. Nie działa na duchy.'],
468=>['Symbioza','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Na każde zaklęcie, pod którego działaniem jest stworzenie nie-duch w zasięgu, maksymalna żywotność tego stworzenia zwiększa się o +27...150 pkt. Duch umiera po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Stworzenia w zasięgu otrzymują +27...150 pkt. do maksymalnej żywotności na każde zaklęcie, pod którego są działaniem. Nie działa na duchy.'],
469=>['Pierwotne Echa','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu użycie sygnetów kosztuje 10 pkt. energii. Duch umiera po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Użycie sygnetu przez stworzenia w zasięgu kosztuje 10 pkt. energii. Nie działa na duchy.'],
470=>['Sezon Łowów','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu, uleczanie jest obniżone o 20%. Za każdy swój trafiony atak otrzymujesz 5 pkt. żywotności. Duch umiera po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Stworzenia w zasięgu otrzymują o 20% mniej pkt. żywotności. Stworzenia otrzymują 5 pkt. energii, za każdym razem, kiedy ich atak wręcz trafi. Nie działa na duchy.'],
471=>['Zmarznięta Ziemia','Obrządek natury. Tworzy 1...10 poziomowego Ducha. Żadne stworzenie nie-Duch w jego zasięgu nie może używać umiejętności wskrzeszania. Duch umiera po 30...180 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Stworzenia w zasięgu nie mogą używać umiejętności wskrzeszania. Nie działa na duchy.'],
472=>['Sprzyjające Wiatry','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Strzały stworzeń nie-duchów w jego zasięgu lecą dwa razy szybciej i zadają +6 obrażeń. Duch umiera po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Strzały stworzeń w zasięgu lecą dwa razy szybciej i zadają +6 pkt. obrażeń. Nie działa na duchy.'],
474=>['Pobudzający Wiatr','Obrządek natury. Tworzysz 1...6 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu wszystkie umiejętności kosztują o 15 pkt. energii mniej (minimalny koszt to 10 pkt. energii), ale odnawiają się o 25% wolniej. Duch umiera po 1...60 sek.','Obrządek natury. Tworzy ducha na poziomie 1...6 (czas życia 1...60 sek.). Umiejętności stworzeń w zasięgu kosztują o 15 pkt. energii mniej (minimalny koszt 10 pkt. energii) i odnawiają się o 25% wolniej. Nie działa na duchy.'],
475=>['Ożywczy Zefir','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu, wszystkie umiejętności odnawiają się dwa razy szybciej, ale kosztują o 30% więcej energii. Duch umiera po 15...90 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 15...90 sek.). Umiejętności stworzeń w zasięgu kosztują o 30% pkt. energii więcej i odnawiają się dwa razy szybciej. Nie działa na duchy.'],
476=>['Odnowienie Natury','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Przez 30...240 sek. zaklęcia i klątwy używane przez stworzenia nie-duchy, potrzebują dwa razy więcej czasu na rzucenie, a energetyczny koszt utrzymania zaklęć zwiększa się dwukrotnie. Duch umiera po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Stworzenia w zasięgu dwa razy dłużej rzucają zaklęcia i klątwy, a energetyczny koszt utrzymania ich zaklęć jest dwa razy większy. Nie działa na duchy.'],
477=>['Błotnisty Teren','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Wszystkie stworzenia nie-duchy w jego zasięgu poruszają się o 10% wolniej i nie działają zwiększenia prędkości. Duch umiera po 30...180 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Stworzenia w zasięgu poruszają się o 10% wolniej; neguje także premie do szybkości. Nie działa na duchy.'],
570=>['Piętno Niepewności','Elitarna klątwa (czar). Przez 5...25 sek. wybrany przeciwnik posiada degenerację żywotności -1...5, a zaklęcia i postawy, pod których jest działaniem kończą się o 20...60% szybciej. Wszystkie twoje umiejętności spoza profesji skrytobójcy będą niedostępne przez 5 sek.','Elitarna klątwa (czar). (5...25 sek.). Powoduje degenerację żywotności -1...5. Zaklęcia i postawy wskazanego przeciwnika kończą się o 20...60% szybciej. Wyłącza umiejętności nienależące do zabójcy (5 sek.).'],
571=>['Przerywający Sztylet','Czar. Rzucasz Przerywającym Sztyletem w wybranego przeciwnika i zadajesz mu 10...35 pkt. obrażeń od ziemi. Jeśli przeciwnik aktywuje umiejętność, to zostaje ona przerwana. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Czar o połowie zasięgu. Pocisk: zadaje 10...35 pkt. obrażeń od ziemi. Przerywa umiejętność.'],
572=>['Zabójczy Paradoks','Postawa. Wszystkie twoje umiejętności związane z atakowaniem są niedostępne przez 10 sek. Przez 5...15 sek. twoje umiejętności zabójcy aktywują się i odnawiają się o 33% szybciej.','Postawa. (5...15 sek.) Twoje umiejętności zabójcy aktywują i odnawiają się o 33% szybciej. Wyłącza twoje umiejętności związane z atakami (10 sek.).'],
763=>['Zawistne Spojrzenie','Zaklęcie (czar). Usuwa zaklęcie z wybranego przeciwnika. Jeśli zaklęcie się skończy, przez kolejne 1...20 sek., twoje następne zaklęcie będzie mogło być rzucone 0...1 sek. szybciej i zużyje 1...10 pkt. energii mniej.','Zaklęcie (czar). Usuwa zaklęcie z wybranego przeciwnika.Efekt usunięcia: twoje następne zaklęcie będzie mogło być rzucone 0...1 sek. szybciej i zużyje 1...10 pkt. energii mniej. (1...20 sek.)'],
764=>['Lament Zagłady','Elitarna klątwa (czar). Przez 2...6 sek. wszystkie atrybuty wybranego przeciwnika wynoszą 0.','Elitarna klątwa (czar). (2...6 sek.) Atrybuty wybranego przeciwnika wynoszą 0.'],
766=>['Pogardliwe Spojrzenie','Czar. Jeżeli wybrany przeciwnik ma więcej niż 50% pkt. żywotności, to ten przeciwnik traci wszystkie zaklęcia.','Czar. Zdejmujesz zaklęcia wybranego przeciwnika. Bez efektu, chyba że ten przeciwnik ma więcej niż 50% żywotności.'],
769=>['Obrona Żmiji','Czar. Wszyscy przeciwnicy w bezpośredniej odległości zostają na 5...20 sek. zatruci, a ty wykonujesz krok cienia w kierunku przeciwnym do twojego celu.','Czar. U wszystkich przeciwników w bezpośredniej odległości wywołuje zatrucie (5...20 sek.), a ty wykonujesz krok cienia w kierunku przeciwnym do twojego celu.'],
770=>['Powrót','Czar. Wszyscy przeciwnicy bezpośrednio przy Tobie zostają okulawieni na 3...8 sek. Wykonujesz krok cienia do wybranego sojusznika.','Czar. Okulawia (3...8 sek.) wszystkich przeciwników bezpośrednio przy tobie. Wykonujesz krok cienia do miejsca wybranego sojusznika. Na cel nie można wybrać siebie.'],
771=>['Aura Przemieszczenia','Elitarne zaklęcie (czar). Rzucając Aurę Przemieszczenia wykonujesz krok cienia do wybranego przeciwnika. Gdy przestaniesz utrzymywać Aurę Przemieszczenia, wracasz do miejsca gdzie została rzucona.','Elitarne zaklęcie (czar). Wykonujesz krok cienia do wybranego przeciwnika. Efekt końcowy: wracasz do swojego początkowego miejsca.'],
772=>['Hojnym Był Tsungrai','Czar z przedmiotu. Trzymaj prochy Tsungraia przez maksymalnie 15...60 sek., aby otrzymać +50...140 do maksymalnych pkt. żywotności. Gdy upuścisz jego prochy, otrzymasz 100...280 pkt. żywotności.','Czar z przedmiotu. (15...60 sek.) Twoja maksymalna żywotność zwiększa się o +50...140 pkt. Efekt upuszczenia: otrzymujesz 100...280 pkt. żywotności.'],
773=>['Potężnym Był Vorizun','Czar z przedmiotu. Trzymaj prochy Vorizuna przez maksymalnie 15...60 sek. Trzymając jego prochy, zyskujesz +15 pkt. pancerza oraz zwiększasz maksimum pkt. energii o 30.','Czar z przedmiotu. (15...60 sek.) Posiadasz +15 pkt. pancerza, a twoja maksymalna energia zwiększa się o +30 pkt.'],
775=>['Zabójczy Kwiat','Atak podwójny. Musi nastąpić po ataku drugą ręką. Zabójczy Kwiat zadaje wybranemu przeciwnikowi +20...45 pkt. obrażeń, wszyscy przeciwnicy bezpośrednio przy nim otrzymują 20...45 pkt. obrażeń.','Atak podwójny. Zadaje +20...45 pkt. obrażeń. Działa także na przeciwników bezpośrednio przy wybranym przeciwniku. Musi nastąpić po ataku drugą ręką.'],
776=>['Skręcone Kły','Atak podwójny. Musi nastąpić po ataku drugą ręką. Jeżeli atak trafi, Skręcone Kły zadają +10...20 pkt. obrażeń, a uderzony przeciwnik zaczyna krwawić i otrzymuje głęboką ranę na 5...20 sek.','Atak podwójny. Zadaje +10...20 pkt. obrażeń. Wywołuje przypadłości krwawienie i głęboka rana (5...20 sek.). Musi nastąpić po ataku drugą ręką.'],
777=>['Rogi Wołu','Atak podwójny. Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, Rogi Wołu zadają +1...11 pkt. obrażeń. Jeśli zaatakowany przeciwnik nie znajduje się bezpośrednio przy żadnym sojuszniku, zostaje powalony.','Atak podwójny. Zadaje +1...11 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik nie jest bezpośrednio przy żadnym swoim sojuszniku. Musi nastąpić po ataku drugą ręką.'],
778=>['Opadający Pająk','Atak drugą ręką. Musi uderzyć powalonego przeciwnika. Jeżeli atak trafi, Opadający Pająk zadaje +15...35 pkt. obrażeń, a wybrany przeciwnik zostaje zatruty na 5...20 sek.','Atak drugą ręką. Zadaje +15...35 pkt. obrażeń. Wywołuje przypadłość zatrucie (5...20 sek.). Bez efektu, chyba że wybrany przeciwnik jest powalony.'],
779=>['Uderzenie Czarnego Lotosu','Atak poprzedzający. Jeśli atak trafi, Uderzenie Czarnego Lotosu zadaje +10...31 pkt. obrażeń. Jeżeli wybrany przeciwnik jest pod działaniem klątwy, otrzymujesz 5...13 pkt. energii.','Atak poprzedzający. Zadaje +10...31 pkt. obrażeń. Jeżeli wybrany przeciwnik jest pod działaniem klątwy, otrzymujesz 5...13 pkt. energii.'],
780=>['Lisie Kły','Atak drugą ręką. Musi nastąpić po ataku poprzedzającym. Lisie Kły nie mogą zostać zablokowane i zadają +10...35 pkt. obrażeń, jeżeli trafią.','Atak drugą ręką. Zadaje +10...35 pkt. obrażeń. Nie do zablokowania. Musi nastąpić po ataku poprzedzającym.'],
781=>['Uderzenie Moebiusa','Elitarny atak drugą ręką. Musi nastąpić po ataku podwójnym. Jeśli atak trafi, Uderzenie Moebiusa zadaje +10...35 pkt. obrażeń. Jeżeli uderzysz przeciwnika, który posiada mniej niż 50% pkt. żywotności, wszystkie twoje pozostałe umiejętności ataku zostają odnowione.','Elitarny atak drugą ręką. Zadaje +10...35 pkt. obrażeń. Odnawia twoje pozostałe umiejętności związane z atakami, jeżeli żywotność wybranego przeciwnika jest poniżej 50%. Musi nastąpić po ataku podwójnym.'],
782=>['Rozdzierające Uderzenie','Atak poprzedzający. Jeśli Rozdzierające Uderzenie trafi, twój cel zaczyna krwawić przez 5...20 sek.','Atak poprzedzający. Wywołuje przypadłość krwawienie (5...20 sek.).'],
783=>['Niespodziewane Uderzenie','Atak poprzedzający. Jeśli atak trafi, zadajesz +19...31 pkt. obrażeń. Jeżeli ten przeciwnik miał ponad 90% pkt. żywotności, zdajesz dodatkowe 15...75 pkt. obrażeń.','Atak poprzedzający. Zadaje +19...31 pkt. obrażeń. Zadaje 15...75 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik ma powyżej 90% żywotności.'],
784=>['Wijąca się Żmija','Czar. Wijąca się Żmija musi nastąpić po ataku poprzedzającym. Wybrany przeciwnik zostaje powalony oraz zatruty na 5...20 sek.','Czar. Powoduje powalenie. Wywołuje przypadłość zatrucie (5...20 sek.). Musi nastąpić po ataku poprzedzającym.'],
785=>['Piętno Śmierci','Klątwa (czar). Przez 4...10 sek., wybrany przeciwnik otrzymuje przy leczeniu 50% mniej pkt. żywotności.','Klątwa (czar). (4...10 sek.) Wybrany przeciwnik otrzymuje o 50% mniej pkt. żywotności.'],
786=>['Żelazna Dłoń','Umiejętność. Wybrany dotknięty przeciwnik otrzymuje 5...50 pkt. obrażeń oraz jeżeli cierpiał na przypadłość lub był pod wpływem klątwy, zostaje powalony. Żelazna Dłoń liczy się jako atak poprzedzający.','Umiejętność dotykowa. Zadaje 5...50 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik ma na sobie klątwę lub przypadłość. Traktuje się jako atak poprzedzający.'],
787=>['Wytrzymały Oręż','Czar z broni. Przez 3...12 sek. wybrany sojusznik posiada Wytrzymały Oręż. Pod wpływem klątwy lub przypadłości, ten sojusznik zyskuje regenerację żywotności +1...6 i otrzymuje +24 pkt. pancerza.','Czar z broni. (3...12 sek.) Regeneracja żywotności +1...6 i +24 pkt. pancerza. Bez efektu, chyba że wybrany sojusznik jest pod wpływem klątwy lub przypadłości.'],
788=>['Ślepym Był Mingson','Czar z przedmiotu. Trzymaj prochy Mingsona przez maksymalnie 15...60 sek. Gdy upuścisz jego prochy, wszyscy przeciwnicy w pobliżu zostaną oślepieni na 3...8 sek.','Czar z przedmiotu. (15...60 sek.) Efekt upuszczenia: oślepia (3...8 sek.) wszystkich przeciwników w pobliżu.'],
789=>['Zachłannym Był Kuurong','Elitarny czar z przedmiotu. Trzymaj prochy Kuuronga przez maksymalnie 15...60 sek. Gdy upuścisz jego prochy, wszyscy przeciwnicy w okolicy otrzymują 15...75 pkt. obrażeń od oraz zostają powaleni.','Elitarny czar z przedmiotu. (15...60 sek.) Efekt upuszczenia: wszystkim przeciwnikom w okolicy zadaje po 15...75 pkt. obrażeń i powala ich.'],
790=>['Mściwym Był Khanhei','Elitarny czar z przedmiotu. Trzymaj prochy Khanheia przez maksymalnie 5...11 sek. Za każdym razem, kiedy przeciwnik uderzy cię w walce, gdy trzymasz prochy Khanheia, wykradniesz mu 10...45 pkt. żywotności.','Elitarny czar z przedmiotu. (5...11 sek.) Każdemu przeciwnikowi, który cię trafi, wykradasz 10...45 pkt. żywotności.'],
791=>['Ciało z Mego Ciała','Czar. Tracisz połowę aktualnej liczby punktów żywotności. Wskrzeszasz wybranego członka drużyny z twoim aktualnym poziomem żywotności i z 5...20% pkt. energii.','Czar. Wskrzeszasz wybranego członka drużyny (połowa twojej aktualnej żywotności i 5...20% energii). Tracisz połowę żywotności.'],
792=>['Odłamkowy Oręż','Czar z broni. Przez 20 sek. wskazany sprzymierzeniec otrzymuje Odłamkowy Oręż. Kolejne ataki sojusznika (1...5 ) zadają 5...50 pkt.obrażeń maksymalnie 4 pobliskim wrogom.','Czar z broni. (20 sek.) Ataki zadają po 5...50 pkt. obrażeń 3 przeciwnikom w bezpośredniej odległości. Koniec po 1...5 atakach.'],
793=>['Ochronny Oręż','Czar z broni. Na 3...8 sek., wybrany sojusznik zyskuje Ochronny Oręż, który zapewnia mu +2...4 regeneracji żywotności oraz 50% szans na zablokowanie ciosu.','Czar z broni. (3...8 sek.) Regeneracja żywotności +2...4. 50% szans na blokowanie.'],
794=>['Zawodzący Oręż','Czar z broni. Na 3...14 sek., wybrany sojusznik zyskuje Zawodzący Oręż. Za każdym razem, kiedy Zawodzący Oręż trafi atakującego przeciwnika, czynność tego przeciwnika zostaje przerwana.','Czar z broni. (3...14 sek.) Ataki przerywają czynności atakujących przeciwników.'],
795=>['Upiorny Oręż','Czar z broni. Na 12 sek., wybrany sojusznik zyskuje Upiorny Oręż. Kolejne (3) ataki tego sojusznika zadają 10...50 pkt. obrażeń mniej i wykradają do 10...50 pkt. żywotności.','Czar z broni. (12 sek.) Ataki wybranego sojusznika wykradają 10...50 pkt. żywotności, ale zadają 10...50 pkt. obrażeń mniej. Koniec po 3 atakach.'],
799=>['Czarująca Ułuda','Elitarny czar. Wykonujesz Krok Cienia w stronę wskazanego przeciwnika, który zostaje oszołomiony na 3...9 sek.','Elitarny czar. Wykonujesz krok cienia do tego przeciwnika. Wywołuje przypadłość oszołomienie (3...9 sek.).'],
800=>['Trwała Trucizna','Klątwa (czar). Przez 5 sek., wybrany przeciwnik posiada degeneracji żywotności -1...5. Jeżeli przeciwnik ten porusza się, gdy Trwała Trucizna powinna przestać działać, zostaje ona odnowiona na kolejne 5 sek.','Klątwa (czar). (5 sek.) Powoduje degenerację żywotności -1...5. Odnowienie: jeżeli wybrany przeciwnik jest w ruchu, kiedy ta klątwa się kończy.'],
801=>['Całun Ciszy','Elitarna klątwa (czar). Wszystkie twoje czary będą niedostępne przez 15 sek. Przez 1...6 sek. wybrany dotknięty przeciwnik nie może rzucać czarów.','Elitarna klątwa dotykowa - czar. (1...6 sek.) Wybrany przeciwnik nie może rzucać czarów. Twoje czary są wyłączone (15 sek.).'],
802=>['Przełamanie Zasłony','Klątwa (czar). Przez 1...11 sek., wybrany przeciwnik nie może blokować twoich ataków.','Klątwa (czar). (1...11 sek.) Wybrany przeciwnik nie może blokować twoich ataków.'],
803=>['Spijanie Mocy','Elitarna klątwa (czar). Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a jeśli w ciągu 10 sek. ten przeciwnik rzuci zaklęcie, przejmujesz od niego do 5...15 pkt. energii.','Elitarna klątwa (czar). Przerywa użycie czaru lub pieśni. Skutek przerwania: przejmuje 5...15 pkt. energii, gdy wybrany przeciwnik rzuca czar (10 sek.).'],
804=>['Magiczna Ospałość','Elitarna klątwa (czar). Przez 1...10 sek. wszystkie czary rzucane przez wybranego przeciwnika powodują u niego 10 punktów Przemagicznienia.','Elitarna klątwa (czar). (1...10 sek.) Zaklęcia rzucane przez cel powodują 10 punktów Przemagicznienia.'],
805=>['Ożywienie Wampirycznej Poczwary','Czar. Wykorzystaj najbliższe zwłoki by ożywić Wampiryczną Poczwarę na 1...17 poziomie. Za każdym razem, kiedy Wampiryczna Poczwara zadaje obrażenia, zyskujesz taką samą liczbę pkt. żywotności.','Czar. Tworzy wampiryczną poczwarę na poziomie 1...17. Otrzymujesz liczbę punktów żywotności równą punktom obrażeń, jakie ona zadaje. Zużywa świeże ciało.'],
806=>['Żarliwość Kultysty','Elitarne zaklęcie (czar). Przez 5 sek. plus 3 sek. za każdy poziom Wydzierania Duszy, twoje czary nekromantyczne kosztują -1...6 mniej Energii, ale za każdym razem gdy rzucisz taki czar, zaczynasz krwawić przez 10 sek.','Elitarne zaklęcie (czar). (5 sek. plus 3 sek. za każdy poziom Wydzierania Duszy) Twoje czary nekromantyczne kosztują -1...6 mniej Energii. Zaczynasz krwawić (10 sek.) za każdym razem, gdy rzucisz taki czar.'],
808=>['Piętno Żniwiarza','Elitarna klątwa (czar). Przez 30 sek. wybrany przeciwnik posiada degenerację żywotności -1...5. Jeżeli ten przeciwnik umrze będąc pod działaniem Piętna Żniwiarza, otrzymujesz 5...15 pkt. energii.','Elitarna klątwa (czar). (30 sek.) Powoduje degenerację żywotności -1...5. Otrzymujesz 5...15 pkt. energii, jeżeli wybrany przeciwnik umrze, będąc pod działaniem tej klątwy.'],
809=>['Lodowa Skała','Elitarna klątwa (czar). Wybrany przeciwnik otrzymuje 25...100 pkt. obrażeń od zimna, porusza się o 66% wolniej i zostaje przeklęty Lodową Skałą na 3 sek. Gdy Lodowa Skała przestanie działać, ten przeciwnik otrzymuje 25...100 pkt. obrażeń od zimna.','Elitarna klątwa (czar). (3 sek.) Efekt początkowy: zadaje 25...100 pkt. obrażeń od zimna i spowalnia cel o 66%. Efekt końcowy: zadaje 25...100 pkt. obrażeń od zimna celowi i wszystkim pobliskim przeciwnikom.'],
810=>['Zastawa Obrońcy','Umiejętność. Przez 5...11 sek., sojusznicy bezpośrednio przy tobie mają 75% szans na blokowanie ataków. Zastawa Obrońcy skończy się, jeśli się poruszysz.','Umiejętność. (5...11 sek.) Sojusznicy w bezpośredniej odległości mają 75% szans na blokowanie. Przestanie działać, jeśli się ruszysz.'],
811=>['Jedność w Biegu','Postawa. Przez 5...15 sek., ty i twój zwierzęcy towarzysz poruszacie się o 25% szybciej.','Postawa. (5...15 sek.) Ty i twój zwierzęcy towarzysz poruszacie się o 25% szybciej.'],
812=>['Buntowniczą Była Xinrae','Elitarny czar z przedmiotu. Trzymaj prochy Xinrae przez maksymalnie 15...60 sek. Gdy trzymasz jej prochy, w pojedynczym trafieniu nie możesz stracić więcej niż 20% swojej maksymalnej żywotności. Kiedy upuścisz jej prochy, od pobliskich przeciwników wykradasz 5...50 pkt. żywotności.','Elitarny czar z przedmiotu. (15...60 sek.) Jeden atak nie może ci zabrać więcej niż 20% twojej maksymalnej żywotności. Efekt zdjęcia: wykrada 5...50 pkt. żywotności z pobliskich przeciwników.'],
813=>['Aura Lyssy','Elitarne zaklęcie (czar). Przez 10 sek. posiadasz regenerację energii +0...5. Czar zaczyna ponownie działać, za każdym razem, kiedy rzucisz czar na przeciwnika.','Elitarne zaklęcie (czar). (10 sek.) Posiadasz regenerację energii +0...5. Odnawianie: za każdym razem, kiedy rzucisz czar na przeciwnika.'],
814=>['Cieniste Schronienie','Zaklęcie (czar). Przez 6 sek., otrzymujesz regenerację żywotności równą 5...10. Gdy Cieniste Schronienie przestanie działać, otrzymujesz 40...100 pkt. żywotności jeżeli atakujesz.','Zaklęcie (czar). (6 sek.) Posiadasz regenerację żywotności +5...10. Efekt końcowy: otrzymujesz 40...100 pkt. żywotności, jeżeli atakujesz.'],
815=>['Nić Skorpiona','Klątwa (czar). Przez 8...20 sek., następnym razem, kiedy wybrany przeciwnik oddali się od ciebie na więcej niż 23 metrów, wykonujesz krok cienia do niego, a on zostaje powalony. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Klątwa o połowie zasięgu - czar. (8...20 sek.) Wykonujesz krok cienia do wybranego przeciwnika i powalasz go, kiedy znajdzie się w odległości większej niż 23 m od ciebie.'],
816=>['Lustrzana Postawa','Klątwa (czar). Przez 10...35 sek., za każdym razem, kiedy wybrany przeciwnik przyjmuje postawę, ty przyjmujesz taką samą postawę.','Klątwa (czar). (10...35 sek.) Przyjmujesz postawę, pod której działaniem jest wybrany przeciwnik.'],
817=>['Niezgoda','Elitarny czar. Jeżeli wybrany przeciwnik cierpi na przypadłość i jest pod wpływem klątwy lub zaklęcia, przeciwnik ten otrzymuje 30...110 pkt. obrażeń.','Elitarny czar. Zadaje 30...110 pkt. obrażeń. Bez efektu, chyba że wybrany przeciwnik jest pod działaniem przypadłości i ma na sobie klątwę lub zaklęcie.'],
818=>['Studnia Zmęczenia','Czar studni. Wykorzystaj wybrane zwłoki lub poświęć 66% swojej żywotności, by na 10...55 sek. utworzyć Studnię Zmęczenia. Wrogowie na obszarze Studni Zmęczenia cierpią -1 degeneracji pkt. energii.','Czar studni. (10...55 sek.). Przeciwnicy w tej studni mają degenerację energii -1. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
819=>['Wampiryczny Duch','Elitarne zaklęcie (czar). Wybranemu przeciwnikowi wykradasz 15...60 pkt. żywotności. Przez 10 sek. posiadasz regenerację żywotności +5...10.','Elitarne zaklęcie (czar). Wybranemu przeciwnikowi wykradasz 15...60 pkt. żywotności. Posiadasz regenerację żywotności +5...10 (10 sek.).'],
820=>['Deprawacja','Elitarna klątwa (czar). Przez 5...20 sek., za każdym razem, kiedy wybrany przeciwnik rzuca czar, ten przeciwnik i jeden przeciwnik w pobliżu tracą po 1...5 pkt. energii.','Elitarna klątwa (czar). (5...20 sek.) Powoduje utratę 1...5 pkt. energii, za każdym razem, kiedy wybrany przeciwnik rzuca czar. Energię traci również jeden przeciwnik w pobliżu twojego celu.'],
821=>['Lodowate Żyły','Elitarna klątwa (czar). Wybrany przeciwnik otrzymuje 10...90 pkt. obrażeń od zimna. Przez 10...35 sek., jeżeli wybrany przeciwnik umrze, wszyscy pobliscy przeciwnicy otrzymują 20...110 pkt. obrażeń od zimna.','Elitarna klątwa (czar). (10...35 sek.) Przeciwnikom w pobliżu zadaje 20...110 pkt. obrażeń od zimna, jeżeli wybrany przeciwnik umrze. Efekt początkowy: zadaje 10...90 pkt. obrażeń od zimna.'],
822=>['Osłabienie Kolan','Elitarna klątwa (czar). Przez 1...16 sek. wybrany przeciwnik posiada degenerację żywotności -1...4 oraz otrzymuje 5...20 pkt obrażeń będąc w ruchu.','Elitarna klątwa (czar). (1...16 sek.) Wybrany przeciwnik posiada degenerację żywotności -1...4 oraz otrzymuje 5...20 pkt obrażeń będąc w ruchu.'],
823=>['Płonąca Szybkość','Zaklęcie (czar). Przez 7 sek. płoniesz i poruszasz się 30...45% szybciej. Kiedy Płonąca Szybkość dobiegnie końca, wszyscy znajdujący się w bezpośrednim sąsiedztwie wrogowie zostają podpaleni na 3...9 sek.','Zaklęcie (czar). (7 sek.) Poruszasz się 30...45% szybciej. Płoniesz (przez 3...9 sek.). Efekt końcowy: podpala (3...9 sek.) przeciwników w bezpośrednim sąsiedztwie.'],
824=>['Magmowe Strzały','Czar. Magmowe Strzały lecą w kierunku maksymalnie 3 przeciwników w pobliżu twojego celu i jeżeli trafią, zadają 20...65 pkt. obrażeń od ognia.','Czar. Pocisk: zadaje 20...65 pkt. obrażeń od ognia. Efekt dodatkowy: wystrzeliwuje pociski w 2 innych przeciwników w pobliżu twojego celu.'],
825=>['Rozżarzone Węgle','Czar. Tworzy pod wybranym wrogiem Rozżarzone Węgle. Przez 5 sek. przeciwnicy bezpośrednio przy wybranym sojuszniku otrzymują co sekundę po 5...29 pkt. obrażeń od ognia. Każdy przeciwnik powalony na Rozżarzonych Węglach zostaje podpalony na 3...7 sek.','Czar. Zadaje 5...29 pkt. obrażeń na sek. (przez 5 sek.) na obszarze wokół celu. Trafia wrogów stojących obok celu. Podpala (na 3...7 sek.) powalonych przeciwników.'],
826=>['Cienisty Kształt','Elitarne zaklęcie (czar). Przez 5...21 sek., nie możesz być celem wrogich czarów, a twoje obrażenia są zmniejszone o 5 za każde nałożone na ciebie zaklęcie Zabójcy. Nie możesz zadać więcej niż 5...25 pkt. obrażeń jednym atakiem lub umiejętnością.','Elitarne zaklęcie (czar). (5...21 sek.) Nie możesz być celem wrogich czarów. Twoje obrażenia zostają zmniejszone o 5 za każde nałożone na ciebie zaklęcie zabójcy. Nie możesz zadać więcej niż 5...25 pkt. obrażeń jednym atakiem lub umiejętnością.'],
827=>['Wyssanie Siły','Elitarna klątwa (czar). Przez 5...20 sek., wybrany przeciwnik zadaje atakami -5...50 pkt. obrażeń, a wszystkie twoje ataki na tego przeciwnika maja 50% więcej szans na uzyskanie trafienia krytycznego.','Elitarna klątwa (czar). (5...20 sek.) Wybrany przeciwnik zadaje -5...50 pkt. obrażeń. Posiadasz +50% szans na wykonanie trafienia krytycznego w tego przeciwnika.'],
828=>['Ohydny Fetor','Klątwa (czar). Wybrany przeciwnik otrzymuje 10...65 pkt. obrażeń od zimna. Jeżeli wybrany przeciwnik cierpi na jakąś przypadłość, to ten przeciwnik przez 10 sek. posiada dodatkowo degenerację żywotności -1...5.','Klątwa (czar). Powoduje degenerację żywotności -1...5 (10 sek.). Efekt początkowy: zadaje 10...65 pkt. obrażeń od zimna. Klątwa zostaje nałożona tylko, jeśli wybrany przeciwnik cierpi na przypadłość.'],
830=>['Promień Osądu','Elitarny czar. Wywołujesz Promień Osądu w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy bezpośrednio przy tym miejscu otrzymują w każdej sekundzie po 10...50 pkt. świętych obrażeń i zaczynają płonąć na 1...3 sek.','Elitarny czar. W każdej sekundzie (5 sek.) zadaje 10...50 pkt. świętych obrażeń i wywołuje przypadłość płonięcie (1...3 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu.'],
831=>['Pierwotny Szał','Postawa elitarna. Przez 1...9 sek. atakujesz 33% szybciej i poruszasz się 33% szybciej, ale odnosisz 150...125% obrażeń.','Postawa elitarna. (1...9 sek.) Atakujesz 33% szybciej i poruszasz się 33% szybciej. Odnosisz 150...125% obrażeń.'],
832=>['Ożywienie Golema Tkankowego','Elitarny czar. Wykorzystaj najbliższe zwłoki, by ożywić golema tkankowego na 3...25 poziomie. Golem tkankowy pozostawia 1...4 szt. zwłok, które można wykorzystać. Możesz mieć tylko jednego golema tkankowego naraz.','Elitarny czar. Tworzy golema tkankowego na poziomie 3...25, który po śmierci zostawia 1...4 szt. świeżych ciał. Zużywa świeże ciało. W danej chwili możesz mieć tylko jednego golema tkankowego.'],
834=>['Nieostrożny Pośpiech','Klątwa (czar). Przez 6...12 sek. wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim znajdują się pod działaniem klątwy Nieostrożny Pośpiech. Pod wpływem klątwy atakują o 25% szybciej, ale mają 50% szans na nietrafiony atak.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy twoim celu (6...12 sek.). Ci przeciwnicy mają 50% szans na nietrafianie, ale atakują o 25% szybciej.'],
835=>['Krwawe Więzy','Klątwa (czar). Przez 3...12 sek., wybrany przeciwnik oraz wszyscy sąsiadujący wrogowie zostają dotknięci klątwą Krwawe Więzy. Za każdym razem, kiedy sojusznik trafi któregoś z nich podczas ataku, sojusznik ten otrzyma 5...20 pkt. żywotności. Jeśli jeden z tych przeciwników zginie podczas działania Krwawych Więzów, wszyscy sojusznicy w jego bezpośrednim sąsiedztwie odzyskają 20...100 pkt. żywotności.','Klątwa (czar). Klątwa zostaje także rzucona na wrogów w bezpośrednim sąsiedztwie celu (3...12 sek.). Sojusznicy trafiający w tych wrogów otrzymują 5...20 pkt. żywotności. Jeśli któryś z tych wrogów zginie podczas działania klątwy, sąsiadujący z nim sojusznicy odzyskają 20...100 pkt. żywotności.'],
836=>['Skok Błyskawicy','Elitarny czar. Błyskawicznie skaczesz do wybranego przeciwnika. Wybrany przeciwnik otrzymuje 10...70 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicie pancerza, ale powoduje wyczerpanie.','Elitarny czar. Zadaje 10...70 pkt. obrażeń od błyskawic. 25% przebicie pancerza. Natychmiast ruszasz do tego przeciwnika. Powoduje u ciebie wyczerpanie.'],
837=>['Dar Energii','Elitarne zaklęcie (czar). Przez 20 sek. twoja maksymalna energia zwiększa się o +1...12 pkt. oraz otrzymujesz regenrację żyworności +5. Gdy Dar Energii przestanie działać zyskujesz +1...3 pkt. energii oraz 1...3 pkt. żywotności.','Elitarne zaklęcie (czar). (20 sek.) Twoja maksymalna energia zwiększa się o +1...12 pkt. Otrzymujesz regenerację żyworności +5. Efekt końcowy: otrzymujesz 36...60 pkt. energii oraz 1...3 pkt. żywotności.'],
838=>['Smutek Dwayny','Zaklęcie (czar). Przez 30 sek. wybrany sojusznik i wszyscy sojusznicy w pobliżu będą pod działaniem Smutku Dwayny. Jeśli zginie sojusznik będący pod działaniem Smutku Dwayny, to każdy członek drużyny otrzymuje 5...50 pkt. żywotności.','Zaklęcie (czar). Zaklęcie działa także na sojuszników w pobliżu twojego celu (30 sek.). Twoja drużyna otrzymuje 5...50 pkt. żywotności, kiedy jeden z tych sojuszników zginie.'],
839=>['"Wycofać Się!"','Okrzyk. Jeśli w zasięgu słuchu znajdują się martwi sojusznicy, to przez 5...11 sek. twoja drużyna porusza się o 33% szybciej.','Okrzyk. (5...11 sek.) Członkowie drużyny w zasięgu słuchu poruszają się o 33% szybciej. Bez efektu, chyba że w zasięgu słuchu są martwi sojusznicy.'],
840=>['Zatrute Serce','Czar. Ty oraz wszyscy znajdujący się przy tobie przeciwnicy zostajecie zatruci na 5...15 sek.','Czar. Wywołuje zatrucie (5...15 sek.) u sąsiadujących z tobą przeciwników. Ty również ulegasz zatruciu.'],
841=>['Cuchnąca Ziemia','Czar. Wybrany przeciwnik otrzymuje 15...65 pkt. obrażeń od zimna. Jeśli ten przeciwnik jest powalony, zostaje on zatruty na 5...20 sek.','Czar. Zadaje 15...65 pkt. obrażeń od zimna. Wywołuje przypadłość zatrucie (5...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
842=>['Błyskawica Łukowa','Czar. Wybrany przeciwnik otrzymuje 5...40 pkt. obrażeń od elektryczności. Jeśli jesteś pod wpływem Przemagicznienia, dwóch przeciwników w pobliżu twojego celu zostanie uderzonych przez piorun za 15...85 pkt. obrażeń od elektryczności. Obrażenia od Błyskawicy Łukowej mają 25% penetracji pancerza.','Czar. Zadaje 5...40 pkt. obrażeń od elektryczności. Zadaje 5...40 pkt. obrażeń od elektryczności dwóm przeciwnikom w pobliżu celu podczas Przemagicznienia. 25% penetracji pancerza.'],
843=>['Poryw Wiatru','Elitarne zaklęcie (czar). Przez 5...11 sek. ty i wskazany sojusznik poruszacie się 33% szybciej. Gdy rzucasz to zaklęcie, wszyscy sąsiadujący z tobą i wskazanym sojusznikiem przeciwnicy odnoszą 15...70 pkt. obrażeń od zimna. Wrogowie trafieni Porywem Wiatru podczas atakowania lub poruszania się są powalani.','Elitarne zaklęcie (czar). (5...11 sek.). Ty i wskazany sojusznik poruszacie się 33% szybciej. Początkowy efekt: wrogowie sąsiadujący z tobą lub wskazanym sojusznikiem odnoszą 15...70 pkt. obrażeń od zimna. Atakujący lub poruszający się wrogowie są powalani.'],
844=>['Wzburzona Ziemia','Czar. W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Wzburzoną Ziemię. Przez następne 5 sek., co sekundę, Wzburzona Ziemia zadaje przeciwnikom w pobliżu tego miejsca po 10...40 pkt. obrażeń od ziemi. Każdy, poruszający się szybciej niż normalnie, przeciwnik na obszarze Wzburzonej Ziemi zostaje powalony.','Czar. W każdej sekundzie zadaje 10...40 pkt. obrażeń od ziemi (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca celu. Powala przeciwników, którzy się poruszają szybciej niż normalnie.'],
845=>['Płynny Płomień','Czar. Wybrany przeciwnik otrzymuje 7...112 pkt. obrażeń od ognia. Jeżeli przeciwnik ten atakuje lub rzuca czar, wszyscy przeciwnicy w pobliżu także otrzymują po 7...112 pkt. obrażeń od ognia.','Czar. Zadaje 7...112 pkt. obrażeń od ognia. Przeciwnikom w pobliżu twojego celu zadaje 7...112 pkt. obrażeń od ognia, jeżeli ten przeciwnik atakuje lub rzuca czar.'],
846=>['Para','Czar. Wybrany przeciwnik otrzymuje 20...60 pkt. obrażeń od zimna. Jeżeli wybrany przeciwnik płonie, para oślepia go na 5...10 sek. i zadaje mu dodatkowe 20...60 pkt. obrażeń od ognia.','Czar. Zadaje 20...60 pkt. obrażeń od zimna. Powoduje oślepienie (5...10 sek.) i zadaje 20...60 pkt. obrażeń od ognia, jeżeli wybrany przeciwnik płonie.'],
847=>['Sygnet Daru','Sygnet elitarny. Uzdrawiasz wybranego sojusznika dodając mu 20...80 pkt. żywotności. Twój następny czar z Modlitw Uzdrawiających lub Ochronnych, który rzucany jest na sojusznika, dodaje dodatkowe 20...100 pkt. żywotności.','Sygnet elitarny. Dodaje 20...80 pkt. żywotności. Twój następny czar z Modlitw Uzdrawiających lub Ochronnych, który rzucany jest na sojusznika, dodaje +20...100 pkt. żywotności.'],
848=>['Odwrócenie Klątwy','Zaklęcie (czar). Usuwasz z wybranego sojusznika jedną klątwę. Jeśli doszło w ten sposób do usunięcia klątwy, to kiedy przez 5...10 sek. wybrany sojusznik miałby otrzymać obrażenia, zostaną one zmniejszane o 5...50 pkt.','Zaklęcie (czar). (5...10 sek.) Z wybranego sojusznika usuwa jedną klątwę. Następne obrażenia, jakie ten sojusznik otrzyma zostaną zmniejszone o 5...50 pkt. Bez efektu, chyba że ten sojusznik jest pod wpływem klątwy.'],
849=>['Rozdzierające Cięcie','Atak toporem. Jeśli Rozdzierające Cięcie trafi, zadajesz +5...20 pkt. obrażeń. Jeśli trafi powalonego przeciwnika, twój cel zaczynie krwawić przez 5...20 sek.','Atak toporem. Zadaje +5...20 pkt. obrażeń. Wywołuje przypadłość krwawienie (5...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
850=>['Wściekły Cios','Atak młotem. Jeżeli Wściekły Atak trafi, zadajesz +5...20 pkt. obrażeń. Jeżeli cel jest pod działaniem osłabienia, to na 1...8 sek. otrzymuje także głęboką ranę.','Atak młotem. Zadaje +5...20 pkt. obrażeń. Powoduje powstanie głębokiej rany (1...8 sek.), jeżeli wybrany przeciwnik jest osłabiony.'],
851=>['Cięcie Słońca i Księżyca','Atak mieczem. Atakujesz wybranego przeciwnika dwa razy. Ataki te nie mogą zostać zablokowane.','Atak mieczem. Wybranego przeciwnika atakujesz dwa razy. Nie do zablokowania.'],
852=>['Strzał Rozpryskowy','Strzał z łuku. Jeśli Strzał Rozpryskowy trafi, zadajesz +3...15 pkt. obrażeń. Jeśli Strzał Rozpryskowy zostanie zablokowany, wszyscy przeciwnicy w pobliżu celu otrzymają 5...65 pkt. obrażeń.','Strzał z łuku. Zadaje +3...15 pkt. obrażeń. Zadaje 5...65 pkt, obrażeń przeciwnikom w pobliżu, jeśli atak zostanie zablokowany.'],
853=>['Strzał Melandru','Elitarny strzał z łuku. Jeśli Strzał Melandru trafi, przeciwnik zaczyna krwawić przez 5...25 sek. Jeśli trafiony zostanie powalony lub poruszający się przeciwnik , to otrzyma +10...25 pkt. obrażeń i będzie okulawiony przez 5...15 sek.','Elitarny strzał z łuku. Wywołuje krwawienie (5...25 sek.). Zadaje +10...25 pkt. obrażeń oraz powoduje okulawienie (5...15 sek.), jeżeli twój cel się porusza lub jest powalony.'],
854=>['Sidła','Pułapka. Kiedy Sidła zadziałają, wszyscy przeciwnicy w pobliżu zostaną okulawieni na 3...15 sek. Sidła przestają działać po 90 sekundach. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','Pułapka. (90 sek.) Działa na przeciwników w pobliżu. Wywołuje przypadłość okulawienie (3...15 sek.). Łatwo przerwać.'],
858=>['Tańczące Sztylety','Czar. Wyślij trzy Tańczące Sztylety, z których każdy, jeżeli trafi, zadaje wybranemu przeciwnikowi 5...35 pkt. obrażeń od ziemi. Tańczące Sztylety posiadają zasięg dwa razy mniejszy niż zwykły czar. Ta umiejętność liczy się jako atak poprzedzający.','Czar o połowie zasięgu. Trzy pociski: każdy zadaje 5...35 pkt. obrażeń od ziemi. Traktuje się jako atak poprzedzający.'],
859=>['Przyzwanie Nocnej Zmory','Klątwa (czar). Przez 2...16 sek., wybrany przeciwnik posiada degenerację żywotności -8.','Klątwa (czar). (2...16 sek.) Powoduje degenerację żywotności -8.'],
860=>['Sygnet Przerwania','Sygnet. Jeśli cel rzuca właśnie czar, zostaje on przerwany, a cel otrzymuje 10...51 pkt. obrażeń. Jeśli dany cel jest przeklęty, Sygnet Przerwania może przerwać wszystkie umiejętności poza czarami.','Sygnet. Przerywa rzucenie czaru. Może przerwać dowolną umiejętność, jeżeli cel jest przeklęty. Skutek przerwania: zadaje 10...51 pkt. obrażeń.'],
862=>['Chciwe Spojrzenie','Elitarny czar. Zadaje 20...40 pkt. obrażeń i wykrada 20...40 pkt. żywotności wyrbanemu wrogowi i wszystkim przeciwnikom w pobliżu.','Elitarny czar. Zadaje 20...40 pkt. obrażeń i wykrada 20...40 pkt. żywotności wybranemu wrogowi i wszystkim przeciwnikom w pobliżu.'],
863=>['Rozkaz Apostazji','Elitarne zaklęcie (czar). Przez 5 sek., za każdym razem, kiedy członek drużyny trafi przeciwnika zadając obrażenia fizyczne, ten przeciwnik traci jedno zaklęcie. Za każde zdjęte zaklęcie mnicha, tracisz 10...3% maksymalnych pkt. żywotności.','Elitarne zaklęcie (czar). Zaklina wszystkich członków drużyny (5 sek.). Ci członkowie drużyny usuwają po jednym zaklęciu, kiedy zadają fizyczne obrażenia. Koszt usunięcia: za każde zaklęcie mnicha, tracisz 10...3% maksymalnych punktów żywotności.'],
864=>['Gnębiące Spojrzenie','Czar. Wybrany przeciwnik oraz sąsiadujący z nim wrogowie otrzymują 10...30 pkt. obrażeń od cienia. Wrogowie cierpiący już na jakąś przypadłość zostają otruci oraz osłabieni na 3...12 sek.','Czar. Zadaje 10...30 pkt. obrażeń celowi i sąsiadującym przeciwnikom. Wywołuje zatrucie i osłabienie (3...12 sek.) u wrogów cierpiących na jakąś przypadłość.'],
865=>['Młot Błyskawic','Czar. Wybrany przeciwnik otrzymuje 10...100 pkt. obrażeń od elektryczności a jego zbroja pęka na 5...20 sek. Młot Błyskawic ma 25% penetrację pancerza.','Czar. Zadaje 10...100 pkt. obrażeń od elektryczności. Wywołuje przypadłość pęknięta zbroja (5...20 sek.). 25% penetracji pancerza.'],
866=>['Mgliste Ostrze','Czar. Wybrany przeciwnik otrzymuje 15...135 pkt. obrażeń od zimna. Mgliste Ostrze zadaje połowę obrażeń, jeżeli ten przeciwnik ma na sobie jakieś zaklęcia.','Czar. Zadaje 15...135 pkt. obrażeń od zimna. Połowa obrażeń, jeżeli wybrany przeciwnik ma na sobie zaklęcie.'],
867=>['Uzdrawiające Światło','Elitarny czar. Uzdrawiasz wybranego sojusznika dodając mu 40...120 pkt. żywotności. Jeśli cel ma na sobie zaklęcie, to otrzymujesz 1...3 pkt. energii.','Elitarny czar. Dodaje 40...120 pkt. żywotności. Otrzymujesz 1...3 pkt. energii, jeżeli wybrany sojusznik jest pod działaniem zaklęcia.'],
869=>['"Tchórz!"','Elitarny okrzyk. Jeśli przeciwnik się porusza, zostaje powalony.','Elitarny okrzyk. Powoduje powalenie, jeżeli wybrany przeciwnik jest w ruchu.'],
870=>['Zaraza','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Jeśli w jego zasięgu zginie jakieś stworzenie nie-duch, to przypadłości tego stworzenia przenoszą się na inne stworzenie w okolicy będące już pod działaniem przypadłości. Duch ginie po 30...180 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Jeśli w jego zasięgu zginie jakieś stworzenie, to przypadłości tego stworzenia przenoszą się na inne stworzenia w okolicy będące już pod działaniem przypadłości. Nie działa na duchy.'],
871=>['Pieśń Cienia','Rytuał spętania. Tworzy ducha o poziomie 1...10. Ataki ducha zadają 5...20 pkt. obrażeń i powodują ślepotę przez 1...6 sek. Duch umiera po 30 sekundach.','Rytuał spętania. Tworzy ducha o poziomie 1...10 (długość życia: 30 sek.). Jego ataki zadają 5...20 pkt. obrażeń i powodują ślepotę (1...6 sek.).'],
876=>['Sygnet Cienia','Sygnet. Wybrany przeciwnik otrzymuje 5...35 pkt. obrażeń. Jeżeli ten przeciwnik był oślepiony, zdajesz dodatkowe 15...60 pkt. obrażeń.','Sygnet. Zadaje 5...35 pkt. obrażeń. Zadaje 15...60 pkt. dodatkowych obrażeń, jeżeli cel jest oślepiony.'],
877=>['Równowaga Lyssy','Czar. Wybrany przeciwnik traci 1 zaklęcie. Jeżeli posiadasz więcej zaklęć niż wybrany przeciwnik, umiejętność nie daje żadnego efektu.','Czar. Z wybranego przeciwnika zdejmuje jedno zaklęcie. Bez efektu, jeżeli masz więcej zaklęć niż ten przeciwnik.'],
878=>['Wizje Żalu','Elitarna klątwa (czar). Przez 10 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu otrzymują 15...45 pkt. obrażeń za każdym razem, kiedy użyją umiejętności oraz 5...50 pkt. dodatkowych obrażeń jeśli nie znajdują się pod wpływem innej klątwy mesmera.','Elitarna klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (10 sek.) Przeciwnicy ci otrzymują 15...45 pkt. obrażeń za każdym razem, kiedy użyją umiejętności oraz 5...50 pkt. dodatkowych obrażeń jeśli nie znajdują się pod wpływem innej klątwy mesmera.'],
879=>['Iluzja Bólu','Klątwa (czar). Przez 8 sek., wybrany przeciwnik ma degenerację żywotności -3...10 oraz otrzymuje co sekundę 3...10 pkt. obrażeń. Kiedy Iluzja Bólu dobiega końca, wybrany przeciwnik odzyskuje 36...120 pkt. żywotności.','Klątwa (czar). (8 sek.) Powoduje degenerację żywotności -3...10 u wybranego przeciwnika, który dodatkowo otrzymuje co sekundę 3...10 pkt. obrażeń. Efekt końcowy: wybrany przeciwnik odzyskuje 36...120 pkt. żywotności.'],
880=>['Skradziona Szybkość','Elitarna klątwa (czar). Przez 1...10 sek., cel i wszyscy pobliscy przeciwnicy rzucają czary 100% dłużej. Twoje lub sojusznicze czary wycelowane w tych przeciwników rzucane są 50% szybciej.','Elitarna klątwa (czar). Klątwa działa także na wrogów w bezpośrednim sąsiedztwie (1...10 sek.). Podwaja czas rzucania czarów. Twoje lub sojusznicze czary wycelowane w przeciwników pod działaniem klątwy, rzucane są 50% szybciej.'],
881=>['Eteryczny Sygnet','Sygnet. Jeżeli masz mniej niż 5...10 pkt. energii, zyskujesz 10...20 pkt. energii.','Sygnet. Otrzymujesz 10...20 pkt. energii. Bez efektu, chyba że masz mniej niż 5...10 pkt. energii.'],
882=>['Sygnet Antyzaklęcia','Sygnet. Tracisz całą energię. Wybrany przeciwnik traci jedno zaklęcie.','Sygnet. Usuwa jedno zaklęcie. Tracisz całą energię.'],
883=>['Odebranie Głosu','Klątwa (czar). Przez 5...20 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu nie mogą używać okrzyków ani pieśni.','Klątwa (czar). Klątwa działa także na przeciwników w pobliżu celu (5...20 sek.). Ci przeciwnicy nie mogą używać okrzyków ani zaśpiewów.'],
884=>['Wypalające Płomienie','Elitarny czar. Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu padają ofiarą Wypalających Płomieni. Przeciwnicy płonący w momencie, kiedy zostanie użyta ta umiejętność otrzymują po 10...100 pkt. obrażeń od ognia. Pozostali zaczynają płonąć na 1...7 sek.','Elitarny czar. Trafia przeciwników w pobliżu twojego celu. Przeciwnikom, którzy płoną zadaje po 10...100 pkt. obrażeń od ognia. U przeciwników, którzy nie płoną, wywołuje przypadłość płonięcie (1...7 sek.).'],
885=>['Uzdrawiający Strażnik','Zaklęcie (czar). Przez 2...6 sek., wszyscy członkowie drużyny w zasięgu słuchu mają 75% szans na blokowanie ataków. Jeśli atak zostanie zablokowany, wszyscy sojusznicy w zasięgu słuchu odzyskują 10...40 pkt. żywotności, a Uzdrawiający Strażnik przestaje działać.','Zaklęcie (czar). (2...6 sek.) Członkowie drużyny w zasięgu słuchu mają 75% szans na zablokowanie ataków. Efekt zablokowania: Sojusznicy w zasięgu słuchu odzyskują 10...40 pkt. żywotności, a Uzdrawiający Strażnik przestaje działać.'],
886=>['Kojąca Bryza','Zaklęcie (czar). Przez 8...18 sek. wybrany sojusznik posiada regenerację żywotności +10. To zaklęcie przestanie działać, kiedy sojusznik wykona atak lub użyje umiejętności.','Zaklęcie (czar). (8...18 sek.) Regeneracja żywotności +10. Przestanie działać, jeśli wybrany sojusznik zaatakuje lub użyje umiejętności.'],
887=>['Sygnet Odmłodzenia','Sygnet. Uzdrawiasz wybranego sojusznika dodając mu 15...75 pkt. żywotności. Jeśli wybrany sojusznik rzuca czar lub atakuje, otrzymuje dodatkowe 15...75 pkt. żywotności.','Sygnet. Dodaje 15...75 pkt. żywotności. Dodaje dodatkowo 15...75 pkt. żywotności, jeżeli wybrany sojusznik atakuje lub rzuca czar.'],
888=>['Wirujący Topór','Elitarny atak toporem. Jeśli Wirujący Topór trafi, zadajesz +5...20 pkt. obrażeń i dodatkowo przestają działać wszystkie postawy, pod których działaniem był twój cel. Tego ataku nie można zablokować.','Elitarny atak toporem. Zadaje +5...20 pkt. obrażeń i wyłącza postawy. Nie do zablokowania.'],
889=>['Mocny Cios','Elitarny atak młotem. Jeśli Mocny Cios trafi, zadajesz +10...30 pkt. obrażeń, a postawa bojowa używana przez zaatakowanego przeciwnika przestaje działać. Przeciwnik zostaje osłabiony na 5...20 sek. Ten atak nie może zostać zablokowany.','Elitarny atak młotem. Zadaje +10...30 pkt. obrażeń. Usuwa postawę przeciwnika. Wywołuje osłabienie (5...20 sek.). Nie do zablokowania.'],
891=>['"Nikt Nie Przejdzie!"','Okrzyk. Wszyscy pobliscy wrogowie, którzy się poruszają, zostają powaleni. Umiejętność ta odnawia się 1...8 sek. szybciej za każdego powalonego wroga (maksymalnie 25 sek.).','Okrzyk. Powala wszystkich poruszających się wrogów, którzy znajdują się w pobliżu. Odnawia się 1...8 sek. szybciej za każdego powalonego w ten sposób wroga (maksymalnie 25 sek.).'],
892=>['Drżące Ostrze','Elitarny atak mieczem. Jeśli Drżące Ostrze trafi, zadajesz +10...40 pkt. obrażeń. Jeśli atak trafi poruszającego się przeciwka, zostanie on oszołomiony na 10 sek.','Elitarny atak mieczem. Zadaje +10...40 pkt. obrażeń. Wywołuje przypadłość oszołomienie (10 sek.), jeżeli cel się poruszał.'],
893=>['Poszukujące Strzały','Przygotowanie. Przez 3...14 sek., twoich strzał nie można zablokować. Poszukujące Strzały przestaną działać, kiedy nie trafisz.','Przygotowanie. (3...14 sek.) Twoich strzał nie można blokować. Przestanie działać, jeśli nie trafisz.'],
898=>['Przeciążenie','Klątwa (czar). Przez 5 sek., wybrany wróg otrzymuje -1...3 pkt. degeneracji żywotności. Jeśli wybrany przeciwnik używa jakiejś umiejętności, Przeciążenie zadaje mu 15...75 pkt. obrażeń, a wszystkim wrogom w jego bezpośrednim sąsiedztwie 75% tych obrażeń.','Klątwa (czar). (5 sek.). Powoduje degenerację żywotności -1...3. Jeśli wybrany przeciwnik używa umiejętności, odnosi 15...75 pkt. obrażeń, a wszyscy wrogowie w jego bezpośrednim sąsiedztwie otrzymują 75% tych obrażeń.'],
899=>['Wizje Skruchy','Klątwa (czar). Przez 5...10 sek., wybrany przeciwnik cierpi -1...3 degeneracji żywotności. Jeżeli ten przeciwnik atakował, to otrzymuje 10...52 pkt. obrażeń.','Klątwa (czar). (5...10 sek.) Powoduje degenerację żywotności -1...3. Efekt początkowy: 10...52 pkt. obrażeń, jeżeli wybrany przeciwnik atakuje.'],
900=>['Wspólne Brzemię','Elitarna klątwa (czar). Przez 5...20 sek. wybrany przeciwnik i wszyscy przeciwnicy na obszarze ataku rzucają zaklęcia i poruszają się o 50% wolniej.','Elitarna klątwa (czar). Klątwa działa także na przeciwników w pobliżu twojego celu (5...20 sek.). Ci przeciwnicy atakują, rzucają zaklęcia i poruszają się o 50% wolniej.'],
901=>['Spętanie Duszy','Elitarna klątwa (czar). Przez 30 sek. za każdym razem, kiedy wybrany przeciwnik otrzyma punkty żywotności, uzdrawiający otrzyma 20...80 pkt. obrażeń. Ta klątwa przestanie działać, kiedy na cel zostanie rzucona klątwa z Modlitw Ofensywnych.','Elitarna klątwa (czar). (30 sek.) Za każdym razem, kiedy wybrany przeciwnik otrzyma punkty żywotności, uzdrawiający otrzyma 20...80 pkt. obrażeń. Koniec, kiedy na cel zostanie rzucona klątwa z Modlitw Ofensywnych.'],
902=>['Krew Napastnika','Czar. Wykradasz do 5...45 pkt. żywotności wybranemu przeciwnikowi. Jeśli przeciwnik ten wykonywał atak, zostaje osłabiony na 3...12 sek.','Czar. Wykrada 5...45 pkt. żywotności. Powoduje osłabienie (3...12 sek.), jeśli cel atakował.'],
903=>['Lodowy Pryzmat','Czar. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń od zimna. Jeśli przeciwnik jest pod działaniem klątwy Magii Wody, Lodowy Pryzmat zadaje +15...75 obrażeń od zimna wszystkim pobliskim przeciwnikom.','Czar. Zadaje 15...75 pkt. obrażeń od zimna. zadaje +15...75 obrażeń od zimna wszystkim pobliskim przeciwnikom, jeśli cel jest pod działaniem zaklęcia Magii Wody.'],
904=>['Wściekły Topór','Atak toporem. Jeśli Wściekły Topór trafi, zadajesz +5...35 pkt. obrażeń. Jeśli przeciwnik zablokuje atak, to otrzymujesz 3 dawki adrenaliny.','Atak toporem. Zadaje +5...35 pkt. obrażeń. Dodaje ci 3 dawki adrenaliny, jeśli zostanie zablokowana.'],
905=>['Skuteczne Uderzenie','Atak młotem. Jeśli Skuteczne Uderzenie trafi, zadajesz +5...20 pkt. obrażeń i otrzymujesz 3...8 pkt. energii. Jeśli przeciwnik był osłabiony, ataku tego nie można zablokować.','Atak młotem. Zadaje +5...20 pkt. obrażeń, a ty otrzymujesz 3...8 pkt. energii. Nie do zablokowania, jeżeli wybrany przeciwnik jest osłabiony.'],
906=>['"Na Kolana!"','Okrzyk. Tracisz całą adrenalinę. Jeśli jeden z przeciwników bezpośrednio przy tobie jest powalony, wszystkie twoje postawy zostają automatycznie odnowione.','Okrzyk. Automatycznie odnawia twoje postawy, jeżeli jesteś w bezpośredniej odległości od powalonego przeciwnika. Tracisz całą adrenalinę.'],
907=>['Smocze Cięcie','Elitarny atak mieczem. Jeśli Smocze Cięcie trafi, zadajesz +10...40 pkt. obrażeń i otrzymujesz dawki adrenaliny w liczbie 1...5.','Elitarny atak mieczem. Zadaje +10...40 pkt. obrażeń. Jeżeli trafisz, otrzymujesz adrenalinę w liczbie dawek: 1...5.'],
908=>['Strzał Bandyty','Strzał z łuku. Jeśli Strzał Bandyty trafi, zadajesz +25...55 pkt. obrażeń i wszystkie twoje umiejętności nie związane z atakami będą niedostępne przez 5 sek.','Strzał z łuku. Zadaje +25...55 pkt. obrażeń. Wszystkie twoje umiejętności nie związane z atakami są wyłączone (5 sek.), jeżeli ten atak trafi.'],
909=>['Strzał w Skupieniu','Strzał z łuku. This shot moves three times faster, cannot be blocked, and strikes for +10...40 damage but all of your other attack skills are disabled for 8...4 seconds.','Strzał z łuku. Deals +10...40 damage. Unblockable. This shot moves three times faster.Your other attack skills are disabled (8...4 seconds).'],
910=>['Duchowa Rozpadlina','Czar. Otwiera duchową szczelinę w miejscu pobytu wroga. Po 3 sek., wszyscy przeciwnicy w bezpośrednim sąsiedztwie otrzymują 25...125 pkt. obrażeń od błyskawic oraz przez 1...20 sek. znajdą się pod działaniem Pękniętej Zbroi.','Czar. (3 sek.) Działa na przeciwników w bezpośrednim sąsiedztwie początkowej lokacji wybranego wroga. Zadaje 25...125 pkt. obrażeń od błyskawic i powoduje pęknięcie zbroi (1...20 sek.)'],
911=>['Przymierze','Rytuał spętania. Tworzysz 1...12 poziomowego ducha. Za każdym razem, kiedy nie będący duchem sojusznik w zasięgu otrzymuje obrażenia lub zostaje mu wykradziona żywotność, efekty zostają zmniejszone o 15 pkt., a duch otrzymuje 15 pkt. obrażeń. Duch ginie po 30...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 30...60 sek.). Za każdym razem, kiedy nie będący duchem sojusznik w zasięgu otrzymuje obrażenia lub zostaje mu wykradziona żywotność, efekty te zostają zmniejszone o 15, a duch otrzymuje 15 pkt. obrażeń.'],
913=>['Cichym Był Tanasen','Elitarny czar z przedmiotu. Trzymaj prochy Tanasena przez maksymalnie 5...20 sek. Trzymając jego prochy, zyskujesz +10...25 pkt. pancerza, a twoje czynności nie mogą zostać przerwane.','Elitarny czar z przedmiotu. (5...20 sek.) Posiadasz +10...25 pkt. pancerza. Twoje czynności nie mogą zostać przerwane.'],
914=>['Pożarcie Duszy','Elitarny czar. Wykradasz 5...70 pkt. żywotności od wybranego przeciwnika. Wszystkie wrogie przywołane stworzenia w pobliżu przeciwnika otrzymują 25...125 pkt. obrażeń.','Elitarny czar. Wykrada 5...70 pkt. żywotności. Zadaje 25...125 pkt. obrażeń wrogim przywołanym stworzeniom w pobliżu wybranego przeciwnika.'],
915=>['Duchowe Światło','Czar. Wybrany sojusznik zostaje uleczony, otrzymując 60...180 pkt. żywotności. Jeżeli w zasięgu słuchu znajdują się jakieś duchy, nie poświęcasz żywotności.','Czar. Dodaje 60...180 pkt. żywotności. Nie poświęcasz żywotności, jeżeli jesteś w zasięgu słuchu ducha.'],
916=>['Opłakiwanie','Klątwa (czar). Przez 5...20 sek., wybrany przeciwnik i wszyscy wrogowie znajdujący się w pobliżu cierpią na degenerację żywotności 0...3. Jeśli w momencie nałożenia klątwy znajdujesz się w zasięgu słuchu od zwłok lub ducha, wrogowie otrzymują dodatkowo 10...50 pkt. obrażeń.','Klątwa (czar). Nakłada klątwę także na wrogów w pobliżu celu (5...20 sek.). Powoduje degenerację żywotności na poziomie 0...3. Efekt początkowy: zadaje 10...50 pkt/ obrażeń, jeśli znajdujesz się w zasięgu słuchu od zwłok lub ducha.'],
917=>['Rozerwanie Duszy','Czar. Wybrany sojuszniczy duch zostaje zniszczony. Wszyscy przeciwnicy w pobliżu otrzymują 50...140 pkt. obrażeń od błyskawic oraz zostają oślepieni na 3...12 sek.','Czar. Niszczy wybranego sojuszniczego ducha. Przeciwnikom w pobliżu zadaje po 50...140 pkt. obrażeń od błyskawic i wywołuje u nich przypadłość oślepienie (3...12 sek.).'],
918=>['Duch Ciałem Się Staje','Czar. Wybrany dotknięty sojuszniczy duch zostaje zniszczony. Wszyscy sojusznicy w pobliżu otrzymują 30...240 pkt. żywotności.','Czar dotykowy. Niszczy wybranego dotkniętego sojuszniczego ducha. Sojusznikom w pobliżu dodaje po 30...240 pkt. żywotności.'],
919=>['Duchowy Płomień','Czar. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od błyskawic. Jeżeli w zasięgu słuchu jest jakiś duch, Duchowy Płomień podpali przeciwnika na 1...5 sek.','Czar. Zadaje 5...50 pkt. obrażeń od błyskawic. Powoduje płonięcie (1...5 sek.), jeżeli w zasięgu słuchu znajduje się duch.'],
920=>['Zniszczenie','Rytuał spętania. Tworzysz ducha na poziomie 1...14, który ginie po 30 sek. Gdy duch ten zginie, wszyscy przeciwnicy w okolicy otrzymują 5...25 pkt. obrażeń za każdą sekundę życia ducha (maksymalnie 150 pkt. obrażeń).','Rytuał spętania. Tworzysz ducha na poziomie 1...14, który ginie po 30 sek. Gdy duch ten zginie, wszyscy przeciwnicy w okolicy otrzymują 5...25 pkt. obrażeń za każdą sekundę życia ducha (maksymalnie 150 pkt. obrażeń).'],
921=>['Dysonans','Rytuał spętania. Tworzysz 1...12 poziomowego ducha. Ten duch zadaje 5...20 pkt. obrażeń, a czynność każdego kto otrzyma od niego obrażenia, zostaje przerwana. Duch ginie po 10...25 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 10...25 sek.). Jego ataki zadają 5...20 pkt. obrażeń i przerywają czynności.'],
923=>['Antyzaklęcie','Rytuał spętania. Tworzysz 1...12 poziomowego ducha. Ten duch zadaje 5...20 pkt. obrażeń, a każdy kto otrzyma od niego obrażenia, traci jedno zaklęcie. Duch ginie po 10...35 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 10...35 sek.). Jego ataki zadają 5...20 pkt. obrażeń i usuwają zaklęcie.'],
925=>['Przywołanie','Zaklęcie (czar). Tak długo jak utrzymujesz Przywołanie, nic się nie dzieje. Gdy Przywołanie przestanie działać, wykonujesz krok cienia do sojusznika, którego miałeś na celu aktywując tę umiejętność, a wszystkie twoje umiejętności będą niedostępne przez 3 sek.','Zaklęcie (czar). Efekt końcowy: wykonujesz krok cienia do wybranego sojusznika. Na cel nie można wybrać siebie i kiedy przestanie działać wyłącza wszystkie twoje umiejętności na 3 sek.'],
926=>['Ostre Sztylety','Zaklęcie (czar). Przez 5...30 sek., ataki twojego zwierzęcego towarzysza wywołują zatrucie na 5...15 sek.','Zaklęcie (czar). (5...30 sek.) Twoje ataki sztyletem wywołują krwawienie (5...15 sek.).'],
927=>['Haniebny Strach','Klątwa (czar). Przez 10 sek., wybrany przeciwnik porusza się 10% szybciej niż normalnie. Co sekundę, jeżeli ten przeciwnik się porusza, to otrzymuje on 5...20 pkt. obrażeń.','Klątwa (czar). (10 sek.) Wybrany przeciwnik porusza się o 10% szybciej, ale w każdej sekundzie otrzymuje 5...20 pkt. obrażeń, jeżeli jest w ruchu.'],
928=>['Całun Cienia','Elitarna klątwa (czar). Przez 3...9 sek. wybrany przeciwnik nie może być celem zaklęć.','Elitarna klątwa (czar). (3...9 sek.) Wybrany przeciwnik nie może być celem zaklęć.'],
929=>['Cień Pośpiechu','Postawa. Przez 10...40 sek. poruszasz się o 15% szybciej. Gdy Cień Pośpiechu przestanie działać, wykonujesz krok cienia do miejsca, gdzie umiejętność została użyta.','Postawa. (10...40 sek.) Poruszasz się o 15% szybciej. Efekt końcowy: wracasz do swojego początkowego miejsca.'],
930=>['Inkantacja Pomyślności','Zaklęcie (czar). Przez 20 sek., następny czar, który rzucisz będzie niedostępny przez dodatkowe 10...5 sek., a ty otrzymasz 110...200% energetycznego kosztu tego czaru.','Zaklęcie (czar). (20 sek.) Twój następny czar daje ci 110...200% swojego energetycznego kosztu. Ten czar odnawia się o dodatkowe 10...5 sek. dłużej.'],
931=>['Przywrócenie Mocy','Czar. Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a cel otrzymuje 10...5 pkt. energii.','Czar. Przerywa użycie czaru lub pieśni. Skutek przerwania: cel otrzymuje 10...5 pkt. energii.'],
932=>['Komplikacja','Czar. Jeśli wybrany wróg używa jakiejś umiejętności, to jej działanie zostaje przerwane, zaś sama umiejętność staje się niedostępna na dodatkowe 5...12 sek. dla tego wroga i wszystkich przeciwników w okolicy.','Czar. Przerywa umiejętność. Efekt przerwania: wyłącza przerwaną umiejętność (+25...12 sek.) u wybranego wroga i wszystkich przeciwników na danym obszarze.'],
933=>['Burza Rozproszenia','Elitarny czar. Wybrany przeciwnik traci wszystkie zaklęcia. Za każde zaklęcie zdjęte w ten sposób, Burza Rozproszenia zostaje wyłączona na dodatkowe 7 sek.','Elitarny czar. Usuwa wszystkie zaklęcia. Koszt usunięcia: Burza Rozproszenia jest niedostępna przez +7 sek. za każde zdjęte zaklęcie.'],
934=>['Nienaturalny Sygnet','Sygnet. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Jeśli jest on pod działaniem klątwy lub zaklęcia, przeciwnicy w bezpośrednim sąsiedztwie celu otrzymują 5...50 pkt. obrażeń.','Sygnet. Zadaje 15...75 pkt. obrażeń. Zadaje 5...50 pkt. obrażeń innym wrogom w sąsiedztwie, jeśli cel jest pod działaniem klątwy lub zaklęcia.'],
935=>['Wzbierająca Żółć','Klątwa (czar). Przez 20 sek. klątwa ta nic nie robi. Gdy Wzbierająca Żółć przestanie działać, wybrany przeciwnik i wszyscy przeciwnicy w okolicy otrzymają po 1...6 pkt. obrażeń za każdą sekundę działania Wzbierającej Żółci.','Klątwa (czar). (20 sek.) Efekt końcowy: zadaje 1...6 pkt. obrażeń za każdą sekundę, w której Wzbierająca Żółć była aktywna. Działa także na innych przeciwników w okolicy.'],
936=>['Zatruwające Zaklęcia','Czar. Wybrany przeciwnik traci jedno zaklęcie. Na każde pozostałe zaklęcie, wybrany przeciwnik zostaje zatruty na 3...10 sek.','Czar. Z wybranego przeciwnika usuwa jedno zaklęcie. Wywołuje przypadłość zatrucie (3...10 sek. za każde pozostałe zaklęcie na tym przeciwniku).'],
937=>['Fala Uderzeniowa','Elitarny czar. Przeciwnicy w kontakcie otrzymują 15...60 pkt. obrażeń od ziemi, przeciwnicy w pobliżu otrzymują 15...60 pkt. obrażeń od ziemi, a przeciwnicy w okolicy otrzymują 15...60 pkt. obrażeń od ziemi.','Elitarny czar. Przeciwnikom w okolicy zadaje po 15...60 pkt. obrażeń od ziemi. Przeciwnicy w pobliżu otrzymują obrażenia dwa razy, przeciwnicy w bezpośredniej odległości otrzymują obrażenia trzy razy.'],
938=>['Ochrona przed Powaleniem','Ochrona (czar). W miejscu, w którym przebywasz, tworzysz Ochronę przed Powaleniem. Przez 10...25 sek. sojusznicy nie-duchy nie mogą zostać powaleni.','Ochrona (czar). (10...25 sek.) Sojusznicy w granicach tej ochrony nie mogą zostać powaleni. Nie działa na sojusznicze duchy.'],
939=>['Lodowe Kajdany','Elitarna klątwa (czar). Przez 1...10 sek. szybkość ruchu wybranego przeciwnika jest obniżona o 66% za każde zaklęcie, pod którego działaniem się znajduje. Jeżeli przeciwnik jest pod wpływem zaklęcia, jego ruch zostaje spowolniony o 90%.','Elitarna klątwa (czar). (1...10 sek.) Wybrany przeciwnik porusza się o 66% wolniej. Ten przeciwnik porusza się o 90% wolniej, jeżeli jest pod działaniem zaklęcia.'],
941=>['Błogosławione Światło','Elitarny czar. Uzdrawiasz wybranego sojusznika dodając mu 10...120 pkt. żywotności i zdejmujesz z niego po jednej klątwie i przypadłości.','Elitarny czar. Dodaje 10...120 pkt. żywotności. Usuwa jedną przypadłość i jedną klątwę.'],
942=>['Wycofanie Klątw','Elitarny czar. Usuwa wszystkie klątwy z wybranego sojusznika i wszystkich sojuszników bezpośrednio przy nim. Za każdą usuniętą w ten sposób klątwę, czar będzie się odnawiał o 2 sek. dłużej. (50% szans na niepowodzenie, chyba że wartość Łaski Bogów wynosi 4 lub mniej).','Elitarny czar. Usuwa wszystkie klątwy. Działa także na sąsiadujących sojuszników. Koszt usunięcia: +2 sek. do czasu odnawiania za każda usuniętą klątwę. 50% szans na niepowodzenie, chyba że wartość Łaski Bogów wynosi 5 lub więcej.'],
943=>['Ugaszenie','Czar. Z każdego członka drużyny usuwasz po jednej przypadłości. Członkowie drużyny, którzy w ten sposób zostali uwolnieni od płonięcia, otrzymują po 10...100 pkt. żywotności.','Czar. Działa na wszystkich członków drużyny. Usuwa przypadłość. Członkowie drużyny uwolnieni od płonięcia otrzymują po 10...100 pkt. żywotności.'],
944=>['Sygnet Siły','Sygnet. Twoje kolejne ataki w liczbie 1...16 zadają +5 pkt. obrażeń każdy.','Sygnet. Twoje ataki zadają +5 pkt. obrażeń. Koniec po 1...16 atakach.'],
946=>['Skupienie Trapera','Elitarne przygotowanie. Przez 12...36 sek. nie będzie ci łatwo przerwać, kiedy będziesz używał umiejętności związanych z ustawianiem pułapek. Atrybut Przetrwanie w Dziczy zwiększa się o 0...4.','Elitarne przygotowanie. (12...36 sek.) Twoje umiejętności związane z pułapkami nie są już łatwe do przerwania. Otrzymujesz +0...4 do atrybutu Przetrwanie w Dziczy.'],
947=>['Ciernie','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Każde stworzenie nie-duch, które zostanie powalone w jego zasięgu otrzyma 5 pkt. obrażeń i będzie krwawić przez 5...20 sek. Ten duch ginie po 30...240 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Powalone stworzenia otrzymują po 5 pkt. obrażeń i zaczynają krwawić (5...20 sek.). Nie działa na duchy.'],
948=>['Desperackie Uderzenie','Atak poprzedzający. Jeżeli masz mniej niż 50...80% pkt. żywotności, zadajesz +15...60 pkt. obrażeń.','Atak poprzedzający. Zadaje +15...60 pkt. obrażeń, jeżeli posiadasz mniej niż 50...80% żywotności.'],
949=>['Ścieżka Lisa','Zaklęcie (czar). Przez 10...35 sek., twoich kolejnych 1...6 ataków nie można zablokować','Zaklęcie (czar). (10...35 sek.) Twoich ataków nie można blokować. Koniec po 1...6 atakach.'],
950=>['Cieniste Brzemię','Klątwa (czar). Przez 3...15 sek. wybrany przeciwnik porusza się o 25% wolniej i tak długo, jak nie ma na sobie innych klątw, posiada 20...30 pkt. pancerza mniej przeciwko twoim atakom.','Klątwa (czar). (3...15 sek.) Wybrany przeciwnik porusza się o 25% wolniej i posiada 20...30 pkt. pancerza mniej przeciwko twoim atakom. Obniżenie pancerza działa na tego przeciwnika tylko, gdy nie jest on pod działaniem innych klątw.'],
951=>['Wyssanie Szybkości','Klątwa (czar). Przez 5...15 sek. wybrany przeciwnik porusza się o 33% wolniej, a ty poruszasz się o 33% szybciej. Ten czar odnawia się o 50% szybciej, jeżeli został rzucony na poruszającego się przeciwnika.','Klątwa (czar). (5...15 sek.) Wybrany przeciwnik porusza się o 33% wolniej, a ty poruszasz się o 33% szybciej. Odnowienie szybsze o 50%, jeżeli cel się poruszał.'],
952=>['Szarża Śmierci','Czar. Wykonaj krok cienia do wybranego przeciwnika. Jeżeli wybrany przeciwnik ma więcej pkt. żywotności niż ty, otrzymujesz 65...200 pkt. żywotności.','Czar. Wykonujesz krok cienia do wybranego przeciwnika. Otrzymujesz 65...200 pkt. żywotności, jeżeli ten przeciwnik ma więcej żywotności niż ty.'],
953=>['Strumień Energii','Elitarna klątwa (czar). Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a przez 4...10 sek. cel otrzymuje -2 do degeneracji energii.','Elitarna klątwa (czar). Przerywa użycie czaru lub pieśni. Skutek przerwania: -2 do degeneracji energii (4...10 sek.).'],
954=>['Wypędzenie Klątw','Elitarny czar. Usuwasz z wybranego sojusznika do 2 klątw.','Elitarny czar. Z wybranego sojusznika usuwa dwie klątwy.'],
955=>['Rozdarcie Zaklęcia','Czar. Z wybranego przeciwnika zdejmujesz zaklęcia w liczbie 1. Jeżeli zaklęcie zostało zdjęte, przeciwnik ten przez 5...25 sek. będzie krwawił.','Czar. Usuwa zaklęcia w liczbie 1. Efekt usunięcia: wywołuje przypadłość krwawienie (5...25 sek.).'],
957=>['Tarcza Przeciw Czarom','Zaklęcie (czar). Przez 5...20 sek., w momencie kiedy rzucasz czary, nie możesz być celem wrogich czarów. Kiedy Tarcza Przeciw Czarom przestanie działać, wszystkie twoje umiejętności będą niedostępne przez 8...4 sek.','Zaklęcie (czar). (5...20 sek.) W momencie kiedy rzucasz czary, nie możesz być celem wrogich czarów. Efekt końcowy: twoje umiejętności są wyłączone (8...4 sek.).'],
958=>['Uzdrawiający Szept','Czar. Uzdrawiasz wybranego sojusznika innego niż ty dodając mu 40...100 pkt. żywotności. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Czar o połowie zasięgu. Dodaje 40...100 pkt. żywotności. Na cel nie można wybrać siebie.'],
959=>['Eteryczne Światło','Czar. Uzdrawiasz wybranego sojusznika dodając mu 25...100 pkt. żywotności. Jest to czar łatwy do przerwania.','Czar. Dodaje 25...100 pkt. żywotności. Łatwo przerwać.'],
960=>['Uwolnienie Zaklęć','Czar. Tracisz wszystkie zaklęcia. Za każde zaklęcie mnicha, które straciłeś, każdy członek drużyny otrzymuje 5...35 pkt. żywotności.','Czar. Usuwa wszystkie twoje zaklęcia. Za każde usunięte zaklęcie mnicha dodaje każdemu członkowi drużyny 5...35 pkt. żywotności.'],
961=>['Okaleczenie','Elitarny obrządek natury. Tworzysz 1...10 poziomowego ducha. Krwawiące stworzenia w jego zasięgu otrzymują degenerację żywotności -2. Kiedy duch umrze, wszystkie stworzenia nie-duchy w jego zasięgu posiadające mniej niż 90% żywotności będą krwawić przez 5...25 sek. Ten duch ginie po 30...240 sek.','Elitarny obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Krwawiące stworzenia w zasięgu posiadają degenerację żywotności -2. Efekt końcowy: u stworzeń w zasięgu, które mają mniej niż 90% żywotności, wywołuje przypadłość krwawienie (5...25 sek.). Nie działa na duchy.'],
962=>['Duchowy Transfer','Czar. Najbliższy duch traci 5...50 pkt. żywotności. Wybrany sojusznik otrzymuje 5 pkt. żywotności za każdy stracony przez ducha pkt. żywotności.','Czar. Najbliższy duch traci 5...50 pkt. żywotności. Wybranemu sojusznikowi dodaje 5 pkt. żywotności za każdy stracony pkt. żywotności.'],
963=>['Odnowa','Rytuał spętania. Tworzysz 1...14 poziomowego ducha. Gdy ten duch ginie, wszyscy członkowie drużyny w okolicy zostają wskrzeszeni z 5...50% pkt. żywotności i z zerem pkt. energii. Ten duch ginie po 30 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...14 (czas życia 30 sek.). Efekt końcowy: wskrzesza martwych członków drużyny w okolicy (5...50% żywotności, 0 pkt. energii).'],
964=>['Mściwy Oręż','Czar z broni. Przez 8 sek., następnym razem, kiedy wybrany sojusznik otrzyma cios lub zostanie mu wykradziona żywotność, to sojusznik ten wykrada przeciwnikowi do 15...60 pkt. żywotności.','Czar z broni. (8 sek.) Wykrada 15...60 pkt. żywotności następnemu przeciwnikowi, kt&oacute;ry zada obrażenia lub wykradnie żytwotność wybranemu sojusznikowi.'],
973=>['Proszek Oślepiający','Czar. Musi nastąpić po ataku drugą ręką. Wybrany przeciwnik zostaje oślepiony na 3...15 sek.','Czar. Oślepia (3...15 sek.) wybranego przeciwnika i wszystkich przeciwników bezpośrednio przy nim. Musi nastąpić po ataku drugą ręką.'],
974=>['Dotyk Modliszki','Umiejętność. Wybrany przeciwnik zostaje okulawiony na 5...20 sek. Ta umiejętność liczy się jako atak drugą ręką.','Umiejętność. Powoduje okulawienie (5...20 sek.). Ta umiejętność traktowana jest jako atak drugą ręką.'],
975=>['Wyczerpujące Natarcie','Atak podwójny. Musi nastąpić po ataku poprzedzającym. Przerywa czynność celu. Jeśli przerwaną czynnością było rzucanie zaklęcia, cel otrzymuje 10 punktów Przemagicznienia.','Atak podwójny. Przerywa czynność przeciwnika. Powoduje 10 punktów Przemagicznienia, jeśli przerwaną czynnością było rzucenie zaklęcia. Musi nastąpić po ataku poprzedzającym.'],
976=>['Powtarzające się Uderzenie','Atak drugą ręką. Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, zadajesz +10...30 pkt. obrażeń. Jeżeli atak nie trafi, będzie się odnawiał dodatkowe 15 sek.','Atak drugą ręką. Zadaje +10...30 pkt. obrażeń. Ta umiejętność odnawia się o 15 sek. dłużej, jeżeli nie trafi. Musi nastąpić po ataku drugą ręką.'],
977=>['Ścieżka Lotosu','Zaklęcie (czar). Przez 20 sek., następnym razem, gdy twoja umiejętność związana z atakiem podwójnym trafi, zyskujesz 5...20 pkt. energii.','Zaklęcie (czar). (20 sek.) Otrzymujesz 5...20 pkt. energii następnym razem, kiedy trafisz atakiem podwójnym.'],
978=>['Piętno Niestabilności','Klątwa (czar). Przez 20 sek., następnym razem, gdy zadasz wybranemu przeciwnikowi atak podwójny, przeciwnik ten zostaje powalony.','Klątwa (czar). (20 sek.) Powala, kiedy następnym razem trafisz wybranego przeciwnika atakiem podwójnym.'],
979=>['Nieufność','Klątwa (czar). Przez 6 sek. następny czar wybranego przeciwnika wymierzony przeciwko twojemu sojusznikowi zawiedzie, przeciwnik ten odniesie 10...80 pkt. obrażeń, a wszyscy przeciwnicy w jego pobliżu odniosą 75% tych obrażeń.','Klątwa (czar). (6 sek.). Następny czar wybranego przeciwnika wymierzony przeciwko twojemu sojusznikowi zawiedzie, przeciwnik ten odniesie 10...80 pkt. obrażeń, a przeciwnicy w jego pobliżu odniosą 75% tych obrażeń.'],
980=>['Uczta Dusz','Czar. Niszczysz wszystkie sojusznicze duchy w pobliżu. Za każdego zniszczonego w ten sposób ducha, każdy z członków drużyny otrzymuje 50...100 pkt. żywotności.','Czar. Każdy członek drużyny otrzymuje 50...100 pkt. żywotności na każdego sojuszniczego ducha w pobliżu. Wszystkie sojusznicze duchy w pobliżu zostają zniszczone.'],
981=>['Rekonwalescencja','Rytuał spętania. Tworzysz 1...14 poziomowego ducha. Nie będący duchami sojusznicy w jego zasięgu posiadają regenerację żywotności +1...3. Ten duch ginie po 15...45 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...14 (czas życia 15...45 sek.). Sojusznicy nie-duchy w zasięgu posiadają regenerację żywotności +1...3.'],
982=>['Schronienie','Rytuał spętania. Tworzysz 1...12 poziomowego ducha. Nie będący duchami sojusznicy w jego zasięgu od pojedynczego ataku nie mogą stracić więcej niż 10% maksymalnych pkt. żywotności. Za każdym razem, kiedy ten duch zapobiega obrażeniom, traci 75...45 pkt. żywotności. Duch ginie po 30...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 30...60 sek.). Sojusznicy nie-duchy w zasięgu, od pojedynczego ataku nie mogą stracić więcej niż 10% maksymalnych pkt. żywotności. Koszt ochrony przed obrażeniami: ten duch traci 75...45 pkt. żywotności.'],
983=>['Cienisty Oręż','Czar z broni. Na 1...7 sek., wybrany sojusznik zyskuje Cienisty Oręż. Za każdym razem, kiedy ten sojusznik otrzymuje cios, atakujący go zostaje oślepiony na 5 sek. Następne 1...3 razy, gdy ten sojusznik zostanie trafiony, atakujący go zostaje oślepiony na 5 sek.','Czar z broni. (1...7 sek.) Oślepia (na 5 sek.) każdego, kto zaatakuje wybranego sojusznika. Kolejne ataki sprzymierzeńca (1...3) powodują w przypadku trafienia ślepotę (na 5 sek.).'],
985=>['Kolczatka','Czar. Target foe and all foes adjacent to your target are Crippled and Bleeding for 5...15 seconds. Caltrops has half the normal range.','Czar o połowie zasięgu. Inflicts Crippled and Bleeding conditions (5...15 seconds) on target and adjacent foes.'],
986=>['Uderzenie Dziewiątego Ogona','Atak podwójny. Musi nastąpić po ataku drugą ręką. Uderzenie Dziewięciu Ogonów nie może zostać zablokowane i zadaje +15...40 pkt. obrażeń, jeśli trafi.','Atak podwójny. Zadaje +15...40 pkt. obrażeń. Nie do zablokowania. Musi nastąpić po ataku drugą ręką.'],
987=>['Ścieżka Pustej Dłoni','Elitarne zaklęcie (czar). Przez 5...15 sek. ataki drugą ręką oraz ataki podwójne kosztują zero punktów energii i odnawiają się 25...50% szybciej.','Elitarne zaklęcie (czar). (5...15 sek.). Twoje ataki drugą ręką oraz ataki podwójne kosztują zero punktów energii i odnawiają się 25...50% szybciej.'],
988=>['Rozbicie Skroni','Elitarny atak drugą ręką. Musi nastąpić po ataku poprzedzającym. Jeśli atak trafi, wybrany przeciwnik zostaje oszołomiony i oślepiony na 1...10 sek., a jeżeli przeciwnik ten rzucał czar, zostaje on przerwany.','Elitarny atak drugą ręką. Przerywa czar. Wywołuje przypadłości oszołomienie i oślepienie (1...10 sek.). Musi nastąpić po ataku poprzedzającym.'],
989=>['Uderzenie Złotego Feniksa','Atak drugą ręką. Jeżeli nie masz na sobie zaklęcia, ten atak nie trafia. Jeśli atak trafi, Uderzenie Złotego Feniksa zadaje +10...30 pkt. obrażeń, zaś wszyscy sąsiadujący przeciwnicy otrzymują 10...30 pkt. obrażeń.','Atak drugą ręką. Zadaje +10...30 pkt. obrażeń celowi oraz 10...30 pkt. obrażeń sąsiadującym przeciwnikom. Nie działa, jeśli nie masz na sobie zaklęcia.'],
990=>['Przegnanie Zaklęć','Umiejętność. Wybrany przeciwnik traci 1 zaklęcie. Wszystkie twoje pozostałe umiejętności, nie związane z atakowaniem, zostają wyłączone na 8...4 sek. Za każdą umiejętność wyłączoną w ten sposób, wybrany dotknięty przeciwnik traci jedno dodatkowe zaklęcie.','Umiejętność dotykowa. Zdejmuje jedno zaklęcie na każdą umiejętność nie związaną z atakami, którą posiadasz. Wszystkie twoje umiejętności nie związane z atakami są wyłączone (8...4 sek.).'],
991=>['Wyparcie Klątw','Czar. Za każdą odnawiającą się umiejętność Łaski Bogów na twoim pasku umiejętności, zdejmujesz z wybranego sojusznika jedną klątwę.','Czar. Za każdą odnawiającą się umiejętność Łaski Bogów na twoim pasku umiejętności, zdejmujesz z wybranego sojusznika jedną klątwę.'],
992=>['Potrójne Cięcie','Elitarny atak toporem. Atakujesz wybranego przeciwnika i przeciwników bezpośrednio przy nim. Każdy celny atak zadaje +10...40 pkt. obrażeń.','Elitarny atak toporem. Zadaje +10...40 pkt. obrażeń. Trafia także przeciwników w bezpośredniej odległości.'],
993=>['Gniewne Uderzenie','Elitarny atak młotem. Jeśli Gniewne Uderzenie trafi, otrzymujesz dawki adrenaliny w liczbie 1...4. Jeżeli trafisz poruszającego się przeciwnika, zadajesz +10...40 pkt. obrażeń, a twój cel zostaje powalony.','Elitarny atak młotem. Jeżeli trafisz, daje ci dawki adrenaliny w liczbie 1...4. Zadaje +10...40 pkt. obrażeń i powala, jeżeli cel porusza się.'],
994=>['Cios Odnowy','Atak młotem. Jeśli Cios Odnowy trafi, zadaje +10...40 pkt. obrażeń. Jeśli trafisz powalonego wroga, otrzymujesz 3 pkt. energii, a atak ten natychmiast się odnawia.','Atak młotem. Zadaje +10...40 pkt. obrażeń. Otrzymujesz 3 pkt. energii, zaś atak ten natychmiast się odnawia, jeśli wybrany przeciwnik był powalony.'],
995=>['Postawa Tygrysa','Postawa. Przez 4...10 sek., atakujesz o 33% szybciej. Postawa Tygrysa skończy się jeśli jakiś z twoich ataków nie trafi.','Postawa. (4...10 sek.) Atakujesz o 33% szybciej. Przestanie działać, jeśli nie trafisz.'],
996=>['Cięcie w Postawie','Atak mieczem. Jeśli Cięcie w Postawie trafi, zadaje +5...20 pkt. obrażeń oraz dodatkowo 5...20 pkt. obrażeń, jeśli jesteś pod działaniem jakiejś postawy.','Atak mieczem. Zadaje +5...20 pkt. obrażeń. Zadaje 5...20 pkt. dodatkowych obrażeń, jeżeli przyjąłeś postawę.'],
997=>['Klęska Głodu','Elitarny obrządek natury. Tworzysz 1...10 poziomowego ducha. Za każdym razem, kiedy energia stworzenia nie-ducha w jego zasięgu spadnie do 0, stworzenie to otrzymuje 20...70 pkt. obrażeń. Ten duch ginie po 30...180 sek.','Elitarny obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Stworzeniom w zasięgu, których energia spadnie do 0, zadaje 20...70 pkt. obrażeń. Nie działa na duchy.'],
1018=>['Krytyczne Oko','Umiejętność. Przez 10...35 sek., otrzymujesz dodatkowe 3...15% szans na zadanie trafienia krytycznego podczas ataku. Zyskujesz 1 pkt. energii za każdym razem, gdy wykonasz trafienie krytyczne.','Umiejętność. (10...35 sek.) Posiadasz +3...15% szans na wykonanie trafienia krytycznego. Otrzymujesz 1 pkt. energii, za każdym razem, kiedy wykonasz trafienie krytyczne.'],
1019=>['Krytyczne Uderzenie','Atak podwójny. Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, zadajesz +10...30 pkt. obrażeń, ma miejce trafienie krytyczne i zyskujesz 1...3 pkt. energii.','Atak podwójny. Zadaje +10...30 pkt. obrażeń. Automatyczne trafienie krytyczne. Otrzymujesz 1...3 pkt. energii. Musi nastąpić po ataku drugą ręką.'],
1020=>['Stalowe Ostrza','Atak podwójny. Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, zadajesz +5...16 pkt. obrażeń (maksymalnie 60) za każdy odnawiający się atak sztyletem.','Atak podwójny. Zadaje +5...16 pkt. obrażeń (maksymalnie 60) za każdy odnawiający się atak sztyletem. Musi nastąpić po ataku drugą ręką.'],
1021=>['Uderzenie Dżungli','Atak drugą ręką. Musi nastąpić po ataku poprzedzającym. Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń. Jeżeli uderzenie trafi okulawionego przeciwnika, on oraz wszyscy sąsiadujący z nim przeciwnicy otrzymują 1...31 pkt. obrażeń.','Atak drugą ręką. Zadaje +10...25 pkt. obrażeń. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 1...31 pkt. obrażeń, jeżeli ten przeciwnik jest okaleczony. Musi nastąpić po ataku poprzedzającym.'],
1022=>['Dzikie Uderzenie','Atak drugą ręką. Musi nastąpić po ataku poprzedzającym. Jeśli atak trafi, zadaje +10...35 pkt. obrażeń i dodatkowo przestają działać wszystkie postawy, pod których działaniem był wybrany przeciwnik. Tego ataku nie można zablokować.','Atak drugą ręką. Zadaje +10...35 pkt. obrażeń. Przerywa postawę wybranego przeciwnika. Nie do zablokowania. Musi nastąpić po ataku poprzedzającym.'],
1023=>['Żądło Skaczącej Modliszki','Atak poprzedzający. Jeżeli Żądło Modliszki trafi, wybrany przeciwnik otrzymuje 5...15 pkt. obrażeń. Jeśli atak trafi poruszającego się przeciwnika, zostaje on okulawiony na 3...15 sek.','Atak poprzedzający. Zadaje +5...15 pkt. obrażeń. Wywołuje przypadłość okulawienie (3...15 sek.), jeżeli wybrany przeciwnik porusza się.'],
1024=>['Pchnięcie Czarnej Modliszki','Atak poprzedzający. Jeśli atak trafi, zadajesz +8...20 pkt. obrażeń. Jeśli wybrany przeciwnik jest pod wpływem klątwy, zostaje on okulawiony na 3...15 sek.','Atak poprzedzający. Zadaje +8...20 pkt. obrażeń. Wywołuje przypadłość okulawienie (3...15 sek.), jeżeli wybrany przeciwnik jest pod działaniem klątwy.'],
1025=>['Przerywające Pchnięcie','Atak poprzedzający. Jeżeli atak trafi, przerywasz czynność wybranego przeciwnika. Jeżeli tą czynnością było rzucanie czaru, zostaje on wyłączony na 3...10 sek.','Atak poprzedzający. Przerywa czynność. Jeżeli przerwaną czynnością było rzucanie czaru, to zostaje on wyłączony (3...10 sek.).'],
1026=>['Uderzenie Złotego Lotosu','Atak poprzedzający. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeżeli masz na sobie zaklęcie, otrzymujesz 5...8 pkt. energii.','Atak poprzedzający. Zadaje +5...20 pkt. obrażeń. Otrzymujesz 5...8 pkt. energii, jeżeli jesteś pod działaniem zaklęcia.'],
1027=>['Krytyczna Obrona','Zaklęcie (czar). Przez 4...10 sekund, masz 75% szans na blokowanie ataków. Krytyczna Obrona zaczyna działać od nowa za każdym razem, gdy wykonasz trafienie krytyczne.','Zaklęcie (czar). (4...10 sek.) Masz 75% szans na blokowanie. Odnowienie: za każdym razem, gdy wykonasz trafienie krytyczne.'],
1028=>['Ścieżka ku Doskonałości','Zaklęcie (czar). Przez 60 sek., za każdym razem, gdy wykonasz trafienie krytyczne, otrzymasz 10...40 pkt. żywotności.','Zaklęcie (czar). (60 sek.) Twoje trafienia krytyczne dodają ci 10...40 pkt. żywotności.'],
1029=>['Mroczna Apostazja','Elitarne zaklęcie (czar). Przez 3...17 sek., za każdym razem, gdy wykonasz trafienie krytyczne, zdejmiesz jedno zaklęcie ze swojego celu. Jeżeli zdejmiesz zaklęcie w ten sposób, stracisz 10...3 pkt. energii albo Mroczna Apostazja przestanie działać.','Elitarne zaklęcie (czar). (3...17 sek.) Twoje trafienia krytyczne zdejmują zaklęcie. Koszt usunięcia: utrata 10...3 pkt. energii lub koniec Mrocznej Apostazji.'],
1030=>['Furia Szarańczy','Elitarne zaklęcie (czar). Przez 10...35 sek., otrzymujesz dodatkowe 50% szans na wykonanie podwójnego uderzenia sztyletami.','Elitarne zaklęcie (czar). (10...35 sek.) Masz +50% szans na podwójne uderzenie. Bez efektu, jeśli nie dzierżysz sztyletów.'],
1031=>['Całun Boleści','Zaklęcie (czar). Przez 30...60 sek., jeżeli masz mniej niż 50% żywotności, otrzymujesz +3...8 regeneracji żywotności oraz masz 75% szansy na zablokowanie ataków.','Zaklęcie (czar). (30...60 sek.) Otrzymujesz +3...8 regeneracji żywotności oraz masz 75% szans na blokowanie. Bez efektu, chyba że twoja żywotność jest poniżej 50%.'],
1032=>['Serce Cienia','Czar. Otrzymujesz 30...150 pkt. żywotności; wykonujesz krok cienia w kierunku przeciwnym do twojego celu.','Czar. Otrzymujesz 30...150 pkt. żywotności; wykonujesz krok cienia w kierunku przeciwnym do twojego celu.'],
1033=>['Przebicie','Umiejętność. Musi nastąpić po ataku podwójnym. Wybrany przeciwnik otrzymuje 25...100 pkt. obrażeń od ziemi oraz przez 5...20 sek. cierpi z powodu głębokiej rany.','Umiejętność. Zadaje 25...100 pkt. obrażeń od ziemi. Wywołuje przypadłość głęboka rana (5...20 sek.). Musi nastąpić po ataku podwójnym.'],
1034=>['Ropiejąca Rana','Elitarna klątwa (czar). For 1...7 seconds, target foe moves 33% slower. That foe takes 5...25 damage each second while suffering from a condition.','Elitarna klątwa (czar). (1...7 sek.) Wybrany przeciwnik porusza się 33% wolniej. Przeciwnik ten otrzymuje co sekundę 5...25 pkt. obrażeń, jeśli cierpi na jakąś przypadłość.'],
1035=>['Obietnica Zabójcy','Elitarna klątwa (czar). Przez 5...15 sek., jeżeli wybrany przeciwnik umrze, zyskujesz 5...20 pkt. energii oraz wszystkie twoje umiejętności zostają odnowione.','Elitarna klątwa (czar). (5...15 sek.) Otrzymujesz 5...20 pkt. energii i wszystkie twoje umiejętności odnowią się, jeżeli wybrany przeciwnik umrze.'],
1036=>['Sygnet Podłości','Sygnet. Za każdą przypadłość, na którą cierpi wybrany przeciwnik, tracisz jedną ze swych przypadłości.','Sygnet. Tracisz jedną przypadłość za każdą przypadłość, pod której działaniem jest wybrany przeciwnik.'],
1037=>['Mroczna Ucieczka','Postawa. Przez 5...15 sek., poruszasz się 25% szybciej i otrzymujesz połowę obrażeń. Mroczna Ucieczka przestanie działać z twoim kolejnym trafionym atakiem.','Postawa. (5...15 sek.) Poruszasz się o 25% szybciej i otrzymujesz połowę obrażeń. Przestanie działać, jeśli twój atak trafi.'],
1038=>['Okulawiający Sztylet','Czar. Rzuć Okulawiający Sztylet w wybranego przeciwnika. Jeżeli atak trafi, Okulawiający Sztylet zadaje 15...60 pkt. obrażeń od ziemi oraz okulawia poruszających się przeciwników na 3...15 sek. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Czar o połowie zasięgu. Pocisk: zadaje 15...60 pkt. obrażeń od ziemi. Wywołuje przypadłość okulawienie (3...15 sek.), jeżeli wybrany przeciwnik porusza się.'],
1040=>['Spacer Ducha','Czar. Wykonaj krok cienia do wybranego ducha.','Czar. Wykonujesz krok cienia do wybranego ducha.'],
1041=>['Niewidoczna Furia','Postawa. Wszyscy przeciwnicy w kontakcie zostaną oślepieni na 3...10 sek. Przez 10...30 sek., oślepieni przeciwnicy nie mogą cię blokować.','Postawa. Wywołuje oślepienie wśród sąsiednich przeciwników (3...10 s). Nie możesz zostać zablokowany przez oślepionych przeciwnikĂłw (10...30 s).'],
1042=>['Błyskające Ostrza','Postawa elitarna. Przez 5...30 sek., otrzymujesz dodatkowe 75% szans na blokowanie ataków podczas walki. Jeżeli zablokujesz atak w ten sposób, to atakujący otrzyma 5...20 pkt. obrażeń.','Postawa elitarna. (5...30 sek.) Masz 75% szans na blokowanie, kiedy atakujesz. Efekt zablokowania: 5...20 pkt. obrażeń dla atakującego przeciwnika.'],
1043=>['Pęd','Postawa. Przez 3 sek., biegniesz 50% szybciej.','Postawa. (3 sek.) Poruszasz się o 50% szybciej.'],
1044=>['Mroczne Więzienie','Klątwa (czar). Wykonaj krok cienia do wybranego przeciwnika. Przez 1...6 sek., wybrany przeciwnik porusza się 33% wolniej.','Klątwa (czar). Wykonujesz krok cienia do wybranego przeciwnika. Ten przeciwnik porusza się o 33% wolniej (1...6 sek.).'],
1045=>['Uderzenie Dłonią','Umiejętność elitarna. Wybrany dotknięty przeciwnik otrzymuje 10...65 pkt. obrażeń i zostaje okulawiony na 1...5 sek. Ta umiejętność liczy się jako atak drugą ręką.','Elitarna umiejętność dotykowa. Zadaje 10...65 pkt. obrażeń i wywołuje przypadłość okulawienie (1...5 sek.). Ta umiejętność traktowana jest jako atak drugą ręką.'],
1048=>['Ujawnienie Zaklęcia','Czar. Z wybranego przeciwnika zdejmujesz jedno zaklęcie i otrzymujesz 3...15 pkt. energii. Na 20 sekund Ujawnienie Zaklęcia zostaje zastąpione zaklęciem zdjętym z wybranego przeciwnika.','Czar. Z wybranego przeciwnika usuwa zaklęcie. Efekty usunięcia: otrzymujesz 3...15 pkt. energii; ten czar zamieniany jest na to zaklęcie (20 sek.).'],
1049=>['Ujawnienie Klątwy','Czar. Z wybranego sojusznika zdejmujesz jedną klątwę i otrzymujesz 4...10 pkt. energii. Na 20 sekund Ujawnienie Klątwy zostaje zastąpione klątwą zdjętą z wybranego sojusznika.','Czar. Z wybranego sojusznika usuwa jedną klątwę. Efekty usunięcia: otrzymujesz 4...10 pkt. energii; ten czar zamieniany jest na tę klątwę (20 sek.).'],
1052=>['Nagromadzenie Bólu','Czar. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Jeżeli wybrany przeciwnik jest pod wpływem 2 lub więcej klątw, to ten przeciwnik otrzymuje Głęboką Ranę na 5...20 sek.','Czar. Zadaje 15...75 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik jest pod działaniem 2 lub więcej klątw.'],
1053=>['Rozkojarzenie','Elitarny czar. Twoje pozostałe umiejętności są wyłączone na 8 sek. Jeśli cel używał właśnie umiejętności, zostanie ona przerwana i wyłączona na dodatkowe 5...12 sek.','Elitarny czar. Przerywa użycie umiejętności. Skutek przerwania: wyłącza przerwaną umiejętność (+5...12 sek.). Twoje pozostałe umiejętności są wyłączone (8 sek.).'],
1054=>['Oblicze Przodka','Zaklęcie (czar). Przez 4...10 sek., za każdym razem, kiedy wybrany sojusznik zostanie trafiony atakiem wręcz, wszyscy przeciwnicy bezpośrednio przy nim stracą całą adrenalinę i po 3 punkty energii.','Zaklęcie (czar). (4...10 sek.) Wszyscy przeciwnicy w kontakcie tracą adrenalinę i 3 pkt. energii, za każdym razem, kiedy atak wręcz trafi wybranego sojusznika.'],
1055=>['Powracająca Niepewność','Elitarna klątwa (czar). Przez 5 sek., cel otrzymuje -1...6 pkt. degeneracji żywotności. Jeżeli dany cel jest obłożony inną klątwą, gdy Powracająca Niepewność się skończy, zostaje ona nałożona ponownie.','Elitarna klątwa (czar). (5 sek.) Odejmuje 1...6 regeneracji żywotności. Odnowienie: jeśli dany cel jest obłożony inną klątwą, gdy Powracająca Niepewność się skończy.'],
1056=>['Brzemię Kitaha','Klątwa (czar). Przez 6...12 sek., wybrany przeciwnik porusza się 50% wolniej. Gdy Brzemię Kitaha przestanie działać, otrzymujesz 10...18 pkt. energii.','Klątwa (czar). (6...12 sek.) Wybrany przeciwnik porusza się o 50% wolniej. Efekt końcowy: otrzymujesz 10...18 pkt. energii.'],
1057=>['Psychiczna Niestabilność','Elitarny czar. Przerywa akcję wybranego przeciwnika. Jeśli tą akcją jest umiejętność, przeciwnik i wszyscy pobliscy wrogowie zostają powaleni na 2...4 sek. (50% szans na niepowodzenie, jeśli Szybkie Rzucanie Czarów jest na poziomie 4 lub mniejszym.)','Elitarny czar. Przerywa akcję. Efekt przerwania: jeśli tą akcją jest umiejętność, przeciwnik i wszyscy pobliscy wrogowie zostają powaleni na 2...4 sek. 50% szans na niepowodzenie, chyba że Szybkie Rzucanie Czarów jest na poziomie 5 lub wyższym.'],
1059=>['Sygnet Pożeracz Klątw','Sygnet. Wybrany dotknięty sojusznik i maksymalnie 2...5 sojuszników bezpośrednio przy nim tracą po jednej klątwie. Otrzymujesz 1...4 pkt. energii za każdą klątwę zdjętą w ten sposób.','Sygnet dotykowy. Usuwa po jednej klątwie z celu i 2...5 sojuszników bezpośrednio przy nim. Efekt usunięcia: otrzymujesz 1...4 pkt. energii za każdą usuniętą klątwę.'],
1061=>['Sprzężenie Zwrotne','Czar. Wybrany przeciwnik traci jedno zaklęcie. Jeśli zaklęcie zostanie zdjęte w ten sposób, to ten przeciwnik traci 4...10 pkt. energii.','Czar. Usuwa jedno zaklęcie. Efekt usunięcia: wybrany przeciwnik traci 4...10 pkt. energii.'],
1062=>['Magiczna Kradzież','Czar. Na 5...35 sek. jeden losowy czar wybranego przeciwnika zostaje wyłączony, a Magiczna Kradzież zostaje zastąpiona tym czarem.','Czar. (5...35 sek.) Wyłącza jeden losowy czar. Ta umiejętność staje się tym czarem.'],
1066=>['Łup Zwycięzcy','Elitarna klątwa (czar). Przez 3...15 sek., za każdym razem, kiedy wybrany przeciwnik atakuje lub rzuca czar na stworzenie z mniejszą liczbą punktów żywotności od siebie, traci 25...100 pkt. żywotności.','Elitarna klątwa (czar). (3...15 sek.) Powoduje utratę 25...100 pkt. żywotności, za każdym razem, kiedy wybrany przeciwnik atakuje lub rzuca czar na stworzenie z mniejszą żywotnością.'],
1067=>['Zgubne Uderzenie','Czar. Wybrany przeciwnik otrzymuje 12...48 pkt. obrażeń od cienia. Jeżeli ten przeciwnik ma ponad 50% pkt. żywotności, wykradasz mu 12...48 pkt. żywotności.','Czar. Zadaje 12...48 pkt. obrażeń. Wykrada 12...48 pkt. żywotności, jeżeli wybrany przeciwnik ma powyżej 50% żywotności.'],
1068=>['Bolesny Chłód','Czar. Wybrany przeciwnik otrzymuje 15...60 pkt. obrażeń od zimna. Jeżeli ten przeciwnik miał więcej życia niż ty, Bolesny Chłód odnawia się natychmiastowo.','Czar. Zadaje 15...60 pkt. obrażeń od zimna. Natychmiast się odnawia, jeżeli wybrany przeciwnik ma więcej żywotności niż ty.'],
1069=>['Smak Bólu','Czar. Jeżeli wybrany przeciwnik ma mniej niż 50% pkt. żywotności, otrzymujesz 30...150 pkt. żywotności.','Czar. Otrzymujesz 30...150 pkt. żywotności. Bez efektu, chyba że wybrany przeciwnik ma poniżej 50% żywotności.'],
1070=>['Splugawienie Zaklęć','Czar. Wybrany przeciwnik i przeciwnicy w pobliżu otrzymują po 6...60 pkt. obrażeń od cienia oraz po 4...20 pkt. obrażeń od cienia za każde zaklęcie, które mają na sobie.','Czar. Wybranemu przeciwnikowi i przeciwnikom w pobliżu zadaje po 6...60 pkt. obrażeń. Zadaje 4...20 pkt. dodatkowych obrażeń za każde zaklęcie, pod którego są działaniem.'],
1071=>['Dreszcze Grozy','Klątwa (czar). Przez 10...40 sek., za każdym razem, kiedy wybrany przeciwnik otrzymuje obrażenia od zimna podczas używania umiejętności, ten przeciwnik zostaje rozproszony, a ty tracisz 8...3 pkt. energii albo Dreszcze Grozy przestają działać.','Klątwa (czar). (10...40 sek.) Obrażenia od zimna przerywają umiejętności wybranego przeciwnika. Koszt przerwania: tracisz 8...3 pkt. energii lub klątwa się kończy.'],
1075=>['Wampiryczny Rój','Czar. Wampiryczny R&oacute;j wykrada do 15...60 pkt. żywotności maksymalnie trzem przeciwnikom w okolicy.','Czar. Wykrada 15...60 pkt. żywotności. Trafia dw&oacute;ch dodatkowych przeciwnik&oacute;w w okolicy.'],
1076=>['Krwiopijca','Czar. Jeżeli posiadasz ponad 90 pkt. żywotności, zaczynasz krwawić przez 6 sek. Od wybranego przeciwnika wykradasz do 20...65 pkt. żywotności.','Czar. Wykrada 20...65 pkt. żywotności. Zaczynasz krwawić (6 sek.), jeżeli twoja żywotność jest powyżej 90%.'],
1077=>['Wampiryczne Ukąszenie','Umiejętność. Dotknij wybranego przeciwnika by wykraść mu do 29...74 pkt. żywotności.','Umiejętność dotykowa. Wykrada 29...74 pkt. żywotności.'],
1078=>['Ugryzienie Błotniaka','Umiejętność. Wybrany dotknięty przeciwnik otrzymuje 20...58 pkt. obrażeń.','Umiejętność dotykowa. Zadaje 20...58 pkt. obrażeń.'],
1079=>['Osłabiające Dotknięcie','Umiejętność. Wybrany dotknięty przeciwnik traci 5...65 pkt. żywotności i cierpi na osłabienie przez 5...20 sek.','Umiejętność dotykowa. Powoduje utratę 5...65 pkt. żywotności. Wywołuje przypadłość osłabienie (5...20 sek.).'],
1081=>['Wiatr Teinai','Czar. Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 10...40 pkt. obrażeń od zimna. Płonący przeciwnicy trafieni Wiatrem Teinai otrzymują dodatkowo 40...80 pkt. obrażeń i wykonywana przez nich czynność zostaje przerwana.','Czar. Zadaje 10...40 pkt. obrażeń od zimna. Płonący przeciwnicy otrzymują +40...80 obrażeń, a ich czynność zostaje przerwana. Zadaje obrażenia znajdującym się w sąsiedztwie.'],
1082=>['Strzała Porażenia','Czar. Wyślij porażającą strzałę, która leci w kierunku wybranego przeciwnika, zadając 5...50 pkt. obrażeń od błyskawic. Jeśli Strzała Porażenia trafi przeciwnika pod wpływem Pękniętej Zbroi, otrzymujesz 5 pkt. energii oraz 1 pkt. energii za każde dwa stopnie pojemności energii. Strzała Porażenia czar posiada 25% przebicia pancerza.','Czar. Szybki pocisk: zadaje 5...50 pkt. obrażeń od elektryczności. Bonus 5 do energii oraz 1 pkt. energii za każde 2 stopnie pojemności energii, jeśli trafisz przeciwnika pod wpływem Pękniętej Zbroi. 25% penetracji pancerza.'],
1083=>['Niestabilny Grunt','Elitarny czar. Stwórz Niestabilny Grunt w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy w pobliżu otrzymują co sekundę 10...40 pkt. obrażeń od ziemi. Atakujący przeciwnicy uderzeni Niestabilnym Gruntem zostają powaleni.','Elitarny czar. W każdej sekundzie zadaje 10...40 pkt. obrażeń od ziemi (5 sek.) i powala atakujących przeciwników. Trafia przeciwników w pobliżu początkowego miejsca celu.'],
1084=>['Zbroja z Odłamków','Zaklęcie (czar). Przez 5...11 sek. masz 25...50% szans na blokowanie ataków oraz za każdym razem, kiedy jesteś celem wrogiego czaru lub ataku, jeden przeciwnik w pobliżu otrzymuje 5...35 pkt. obrażeń od ziemi.','Zaklęcie (czar). (5...11 sek.) Masz 25...50% szans na blokowanie. Jednemu przeciwnikowi w pobliżu zadaje 5...35 pkt. obrażeń od ziemi, za każdym razem, kiedy jesteś celem wrogiego czaru lub ataku.'],
1085=>['Wybuch Popiołu','Klątwa (czar). Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 35...65 pkt. obrażeń od ziemi. Płonący przeciwnicy trafieni przez Wybuch Popiołu zostają przeklęci na 5 sek. i mają 20...75% szansę na nieudane ataki.','Klątwa (czar). Zadaje 35...65 pkt. obrażeń od ziemi. Płonący przeciwnicy pozostają pod wpływem klątwy przez 5 sek. i unikają 20...75% ataków. Dotyczy również postaci w bezpośrednim sąsiedztwie.'],
1086=>['Tupnięcie Smoka','Czar. W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Tupnięcie Smoka. Wszyscy przeciwnicy na tym obszarze zostają powaleni i otrzymują 26...100 pkt. obrażeń od ziemi. Ten czar powoduje wyczerpanie.','Czar. Zadaje 26...100 pkt. obrażeń od ziemi. Powoduje powalenie. Trafia także przeciwników w pobliżu tego przeciwnika. Powoduje u ciebie wyczerpanie.'],
1088=>['Drugi Oddech','Elitarny czar. Uzyskujesz 1 punktów energii i 5 punktów żywotności za każdy punkt energii ograniczony przez limit aktywacyjny. Tracisz wszystkie zaklęcia.','Elitarny czar. Uzyskujesz 1 punktów energii i 5 punktów żywotności za każdy punkt limitu aktywacyjnego. Tracisz wszystkie zaklęcia.'],
1090=>['Rozżarzone Zgliszcze','Klątwa (czar). Wybrany przeciwnik otrzymuje 10...70 pkt. obrażeń od ognia. Jeśli jesteś pod wpływem Przemagicznienia, ten przeciwnik zostanie przeklęty Rozżarzonymi Zgliszczami na 3 sek. i co sekundę będzie otrzymywał 5...25 pkt. dodatkowych obrażeń od ognia.','Klątwa (czar). Zadaje wybranemu przeciwnikowi 10...70 pkt. obrażeń od ognia. Jeśli jesteś pod wpływem Przemagicznienia, przeciwnik zostanie przeklęty na 3 sek. i co sekundę będzie otrzymywał 5...25 pkt. obrażeń od ognia.'],
1091=>['Podwójny Smok','Elitarne zaklęcie (czar). Przeciwnicy bezpośrednio przy tobie otrzymują po 1...4 pkt. obrażeń od ognia. Przez 8 sek. twój atrybut Magia Ognia jest większy o +10...40.','Elitarne zaklęcie (czar). Wszystkim przeciwnikom w pobliżu zadaje po 1...4 pkt. obrażeń od ognia. Otrzymujesz +10...40 do Magii Ognia (8 sek.).'],
1093=>['Żar Teinai','Ochrona (czar). Stawia w twoim miejscu znak Żaru Teinai na 10...15 sek. Przeciwnicy w zasięgu działania znaku otrzymują degenerację żywotności -2...5. Osłabieni przeciwnicy atakują 33% wolniej. Ta umiejętność zostanie wyłączona na 20 sek.','Ochrona (czar). (10...15 sek.) Powoduje degenerację żywotności -2...5. Osłabieni działaniem znaku przeciwnicy atakują 33% wolniej. Nieaktywne przez 20 sek.'],
1094=>['Ogniste Tchnienie','Czar. Wywołaj Ogniste Tchnienie w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy w tym obszarze otrzymują w każdej sekundzie 10...40 pkt. obrażeń od ognia.','Czar. W każdej sekundzie zadaje 10...40 pkt. obrażeń od ognia (5 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu.'],
1095=>['Gwiezdny Wybuch','Elitarny czar. Wybrany dotknięty przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 7...112 pkt. obrażeń od ognia. Jeżeli obrażenia otrzymał więcej niż jeden przeciwnik, tracisz 5 pkt. energii.','Elitarny czar dotykowy. Zadaje 7...112 pkt. obrażeń od ognia. Trafia także przeciwników w pobliżu. Tracisz 5 punktów energii, jeżeli został trafiony więcej niż jeden przeciwnik.'],
1096=>['Glif Esencji','Glif. Przez 15 sek. twój następny czar zostanie rzucony natychmiastowo, ale stracisz wszystkie punkty energii.','Glif. (15 sek.) Twój następny czar zostaje rzucony natychmiastowo. Tracisz całą energię.'],
1097=>['Więzienie Teinai','Klątwa (czar). Przez 1...8 sek., nogi wybranego przeciwnika zostają skute lodem, co powoduje, że porusza się on 66% wolniej. Jeśli przeciwnik jest pod wpływem Pękniętego Pancerza, chłód wnika głębiej, powodując degenerację żywotności 5...9.','Klątwa (czar). (1...8 sek.) Cel porusza się 66% wolniej. U przeciwników z Pękniętym Pancerzem powoduje degenerację żywotności 5...9.'],
1098=>['Lodowe Lustro','Elitarna klątwa (czar). Przez 2...6 sek., zadajesz dodatkowe 15...70 pkt. obrażeń od zimna, za każdym razem gdy rzucisz klątwę Magii Wody.','Elitarna klątwa (czar). (2...6 sek.) Zadajesz dodatkowe 15...70 pkt. obrażeń od zimna, za każdym razem gdy rzucisz klątwę Magii Wody.'],
1099=>['Kryształy Teinai','Czar. Wybrany przeciwnik otrzymuje 20...40 pkt. obrażeń. Jeśli cel jest przeklęty Magią Wody, to zaklęcie trafia cel i pobliskich przeciwników za dodatkowe 20...40 pkt. obrażeń, a pobliscy przeciwnicy cierpią przez 5...15 sek. z powodu Pękniętego Pancerza.','Czar. Zadaje wybranemu przeciwnikowi 20...40 pkt. obrażeń. Zadaje przeciwnikowi +20...40 więcej obrażeń i powoduje Pęknięty Pancerz (przez 5...15 sek.) u pobliskich przeciwników, jeśli cel był pod wpływem klątwy Magii Wody.'],
1113=>['Gniew Kirina','Czar. Przez 5 sek., przeciwnicy bezpośrednio przy miejscu, w którym ten czar został rzucony, otrzymują w każdej sekundzie po 8...32 pkt. świętych obrażeń.','Czar. W każdej sekundzie zadaje 8...32 pkt. świętych obrażeń (5 sek.). Trafia przeciwników bezpośrednio przy twoim początkowym miejscu.'],
1114=>['Duchowa Więź','Zaklęcie (czar). Przez 8 sek., za każdym razem, kiedy wybrany sojusznik z kolejnych 10 ataków lub czarów otrzyma więcej niż 50 pkt. obrażeń, dostanie 30...90 pkt. żywotności.','Zaklęcie (czar). (8 sek.) Dodaje 30...90 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik otrzymuje więcej niż 50 pkt. obrażeń. Przestanie działać, jeśli ten sojusznik otrzyma obrażenia z 10 ataków lub czarów.'],
1115=>['Zaklęte Powietrze','Elitarne zaklęcie (czar). Przez 4...10 sek. zaklęcia rzucane na wybranego sojusznika innego niż ty kosztują o 10 pkt. energii mniej (minimalnie 1 pkt. energii).','Elitarne zaklęcie (czar). (4...10 sek.) Zaklęcia rzucane na wybranego sojusznika kosztują o 10 pkt. energii mniej (minimalnie 1 pkt. energii). Na cel nie można wybrać siebie.'],
1117=>['Niebiańska Rozkosz','Czar. Uzdrawia ciebie i członków drużyny w zasięgu słuchu dodając każdemu 15...60 pkt. żywotności.','Czar. Tobie i członkom drużyny w zasięgu słuchu dodaje po 15...60 pkt. żywotności.'],
1118=>['Uzdrawiający Wybuch','Elitarny czar. Wybrany sojusznik odzyskuje 20...120 pkt. żywotności. Wszyscy członkowie drużyny w zasięgu słuchu od celu odzyskują żywotność równą premii z Łaski Bogów. Twoje modlitwy ofensywne zostają zablokowane na 20 sekund.','Elitarny czar. Leczy 20...120 pkt. żywotności. Członkowie drużyny w zasięgu słuchu celu otrzymują żywotność równą premii z Łaski Bogów. <c x="SkillDull">Blokuje twoje modlitwy ofensywne (20 sekund).'],
1119=>['Uzdrawiający Krąg Karei','Czar. Uzdrawiasz siebie i wszystkie stworzenia bezpośrednio przy tobie dodając każdemu 30...180 pkt. żywotności.','Czar. Otrzymujesz 30...180 pkt. żywotności. Dodaje żywotność także stworzeniom w bezpośredniej odległości.'],
1120=>['Spojrzenie Jamei','Czar. Uzdrawiasz wybranego sojusznika innego niż ty dodając mu 35...180 pkt. żywotności.','Czar. Dodaje 35...180 pkt. żywotności. Na cel nie można wybrać siebie.'],
1121=>['Dar Życia','Czar. Wszystkie twoje umiejętności oparte na Modlitwach Uzdrawiających będą niedostępne przez 10...5 sek. Wybrany sojusznik inny niż ty otrzymuje 15...150 pkt. żywotności.','Czar. Dodaje 15...150 pkt. żywotności. Wyłącza twoje pozostałe umiejętności Modlitw Uzdrawiających (10...5 sek.). Na cel nie można wybrać siebie.'],
1123=>['Osłona Życia','Elitarne zaklęcie (czar). Z wybranego sojusznika usuwasz 0...2 przypadłości. Przez 8 sek., kiedy następnym razem wybrany sojusznik miałaby otrzymać obrażenia lub stracić żywotność na rzecz przeciwnika, dostanie w zamian tyle samo pkt. żywotności (maksymalnie 20...100).','Elitarne zaklęcie (czar). (8 sek.) Zamienia następne obrażenia lub wykradzioną żywotność (maksymalnie 20...100) w leczenie. Efekt początkowy: Usuwa przypadłości (0...2).'],
1126=>['Empatyczne Usunięcie','Elitarny czar. Ty i inny wybrany sojusznik tracicie po jednej przypadłości i klątwie. Otrzymujecie też po 50 pkt. żywotności.','Elitarny czar. Z wybranego sojusznika i ciebie usuwa jedną klątwę oraz przypadłość. Dodaje wam też po 50 pkt. żywotności. Na cel nie można wybrać siebie.'],
1128=>['Wskrzeszający Chorał','Czar. Wskrzeszasz wybranego członka drużyny, który wraca do życia z tyloma pkt. żywotności ile aktualnie posiadasz i 5...35% energii. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Czar o połowie zasięgu. Wskrzesza wybranego członka drużyny z twoim aktualnym poziomem żywotności i z 5...35% energii.'],
1129=>['Słowo Potępienia','Elitarny czar. Wybrany przeciwnik otrzymuje 30...130 pkt. świętych obrażeń. Jeśli twój cel miał mniej niż 50% żywotności, Słowo Potępienia będzie się odnawiało o 20 sek. dłużej.','Elitarny czar. Zadaje 30...130 pkt. świętych obrażeń. +20 sek. do czasu odnawiania, jeżeli wybrany przeciwnik ma poniżej 50% żywotności.'],
1130=>['Włócznia Światła','Czar. Jeśli Włócznia Światła trafi w wybranego przeciwnika, zadaje 26...56 pkt. świętych obrażeń. Jeśli trafi w atakującego przeciwnika zadaje +15...60 pkt. obrażeń.','Czar. Pocisk: zadaje 26...56 pkt. świętych obrażeń. Zadaje 15...60 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik atakuje.'],
1131=>['Uderzenie Kamiennej Duszy','Umiejętność. Dotknięty przeciwnik otrzymuje 10...55 świętych obrażeń. Jeśli był powalony, otrzymuje dodatkowe 10...55 pkt. świętych obrażeń.','Umiejętność dotykowa. Zadaje 10...55 pkt. świętych obrażeń. Zadaje 10...55 pkt. dodatkowych świętych obrażeń, jeżeli wybrany przeciwnik jest powalony.'],
1133=>['Cios Pijaka','Atak wręcz. Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń, a twój cel otrzyma jedną z następujących przypadłości: głęboka rana (na 20 sek.), osłabienie (na 20 sek.), krwawienie (na 25 sek.) lub okulawienie (na 15 sek.). Po wykonaniu Ciosu Pijaka, zostaniesz powalony.','Atak wręcz. Zadaje +10...40 pkt. obrażeń. Wywołuje jedną losową przypadłość spośród następujących: głęboka rana (20 sek.), osłabienie (20 sek.), krwawienie (25 sek.) lub okulawienie (15 sek.). Zostajesz powalony.'],
1134=>['Zamach Lewiatana','Atak wręcz. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli przeciwnik zablokuje ten atak, to zostaje powalony i otrzymuje 10...34 pkt. obrażeń.','Atak wręcz. Zadaje +5...20 pkt. obrażeń. Powala i zadaje 10...34 pkt. obrażeń, jeżeli nastąpiło blokowanie.'],
1135=>['Uderzenie Jaizhenju','Atak mieczem. Jeśli Uderzenie Jaizhenju trafi, zadajesz +1...30 pkt. obrażeń. Jeśli nie przyjąłeś żadnej postawy, to Uderzenie Jaizhenju nie może zostać zablokowane.','Atak mieczem. Zadaje +1...30 pkt. obrażeń. Nie do zablokowania, chyba że przyjąłeś postawę.'],
1136=>['Przebijające Cięcie','Atak toporem. Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń. Ten atak toporem posiada 20% przebicie pancerza.','Atak toporem. Zadaje +10...25 pkt. obrażeń. 20% przebicie pancerza.'],
1137=>['Uderzenie Yeti','Atak młotem. Tracisz całą adrenalinę. Atakujesz wszystkich wrogów w bezpośrednim sąsiedztwie. Jeśli atak trafi wroga cierpiącego na jakąś przypadłość, zostanie on powalony. (50% szans na niepowodzenie jeśli biegłość w używaniu młotów wynosi 4 lub mniej.)','Atak młotem. Atakuje wszystkich wrogów w bezpośrednim sąsiedztwie. Powala wrogów cierpiących na jakąś przypadłość. Tracisz całą adrenalinę. 50% szans na niepowodzenie, chyba że biegłość w używaniu młotów wynosi 5 lub więcej.'],
1141=>['"Umrzesz!"','Okrzyk. Jeśli żywotność przeciwnika wynosi mniej niż 90%, otrzymujesz dawki adrenaliny w liczbie 1...3.','Okrzyk. Otrzymujesz adrenalinę w następującej liczbie dawek: 1...3. Nie ma efektu, chyba że wybrany przeciwnik ma poniżej 90% żywotności.'],
1142=>['Pomyślne Parowanie','Postawa elitarna. Przez 8 sek., następny atak skierowany w ciebie zostanie zablokowany. Otrzymasz dawki adrenaliny w liczbie 1...4 po zakończeniu działania tej postawy.','Postawa elitarna. (8 sek.) Blokuje jeden atak. Efekt końcowy: otrzymujesz dawki adrenaliny (1...4).'],
1144=>['Cięcie Srebrnoskrzydłego','Atak mieczem. Jeśli atak trafi, zadajesz +1...40 pkt. obrażeń.','Atak mieczem. Zadaje +1...40 pkt. obrażeń.'],
1146=>['Popchnięcie','Umiejętność elitarna. Dotknięty wrogi cel odnosi 15...75 pkt. obrażeń, jego postawa dobiega końca i zostaje powalony.','Elitarna umiejętność dotykowa. Dotknięty wrogi cel odnosi 15...75 pkt. obrażeń, jego postawa dobiega końca i zostaje powalony.'],
1191=>['Rozdzielający Atak','Strzał z łuku. Jeśli Rozdzielający Atak trafi, zadajesz +5...25 pkt. obrażeń. Ten atak ma 10% przebicie pancerza.','Strzał z łuku. Zadaje +5...25 pkt. obrażeń. 10% przebicie pancerza.'],
1192=>['Strzał Zojuna','Strzał z łuku. Wystrzeliwujesz strzałę, która ma połowę normalnego zasięgu, ale zadaje +10...40 pkt. obrażeń.','Strzał z łuku o połowie zasięgu. Zadaje +10...40 pkt. obrażeń.'],
1194=>['Drapieżcza Więź','Okrzyk. Przez 5...20 s ataki twojego zwierzęcego towarzysza są o 25% szybsze i dodają Ci 1...31 pkt. żywotnośći przy każdym udanym ataku.','Okrzyk. (5...20 s) Twój zwierzak atakuje 25% szybciej i zyskujesz 1...31 pkt. żywotności za każdym razem, gdy wykona on udany atak.'],
1195=>['Jedność w Uzdrowieniu','Umiejętność elitarna. Przez 15 sek., twój zwierzęcy towarzysz wykrada 1...20 pkt. żywotności, za każdym razem gdy jego atak dojdzie celu. Zarówno ty, jak i twój zwierzęcy towarzysz odzyskujecie 20...104 pkt. żywotności. Jeśli twój towarzysz nie żyje, zostaje wskrzeszony z 50% żywotności. Jeśli posiadasz tę umiejętność na wyposażeniu, twój towarzysz będzie podróżował wraz z tobą.','Umiejętność elitarna. (15 sek.) Z każdym atakiem twój zwierzęcy towarzysz wykrada 1...20 pkt. żywotności. Efekt początkowy: przywraca 20...104 pkt. żywotności tobie i twojemu zwierzęciu; wskrzesza twojego zwierzęcego towarzysza (50% żywotności), jeśli ten nie żyje. Jeśli posiadasz tę umiejętność na wyposażeniu, twój towarzysz będzie podróżował wraz z tobą.'],
1196=>['Pośpiech Zojuna','Postawa. Przez 5...11 sek., poruszasz się o 33% szybciej i masz 27...75% szans na zablokowanie nadlatujących pocisków. Pośpiech Zojuna skończy się, jeśli zaatakujesz.','Postawa. (5...11 sek.) Poruszasz się o 33% szybciej i masz 27...75% szans na blokowanie pocisków. Przestanie działać, jeśli zaatakujesz.'],
1197=>['Strzał Dobijający','Strzał z łuku. Strzał Dobijający zadaje jedynie 10...30 pkt. obrażeń, ale porusza się szybciej niż normalny. Jeśli Strzał Dobijający trafi w przeciwnika, kt&oacute;ry będzie miał mniej niż 50% żywotności, to ta umiejętność odnowi się automatycznie. Twoje pozostałe umiejętności ofensywme nie działają przez 2 sek.','Strzał z łuku. Szybko lecąca strzała. Zadaje 10...30 pkt. obrażeń. Natychmiast się odnawia, jeżeli wybrany przeciwnik ma poniżej 50% żywotności. Twoje pozostałe umiejętności ofensywne nie działają (2 sek).'],
1198=>['Strzała z Szerokim Grotem','Elitarny strzał z łuku. Wystrzeliwujesz strzałę o szerokim grocie, która leci wolniej niż normalnie. Jeśli atak trafi, wybrany przeciwnik zostanie oszołomiony na 5...20 sek., a jeśli rzucał czar, to czar zostanie przerwany.','Elitarny strzał z łuku. Wolno lecąca strzała. Przerywa czar. Wywołuje przypadłość oszołomienie (5...20 sek.).'],
1199=>['Szklane Strzały','Elitarne przygotowanie. Przez 10...35 sek., twoje strzały po trafieniu zadają +6...20 pkt. obrażeń, a jeśli zostaną "zablokowane", to powodują, że na 10...20 sek. cel zaczyna krwawić.','Elitarne przygotowanie. (10...35 sek.) Twoje strzały zadają +6...20 pkt. obrażeń. Wywołuje przypadłość krwawienie (10...20 sek.), jeżeli zostanie zablokowana.'],
1200=>['Sygnet Łucznika','Sygnet elitarny. Przez 1...24 sek. wszystkie przypadłości, które nakładasz przy pomocy łuku trwają o 150% dłużej.','Sygnet elitarny. (1...24 sek.) Przypadłości, które nakładasz przy pomocy łuku trwają o 150% dłużej.'],
1201=>['Wściekły Skok','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Wściekły Skok, który zadaje +5...20 pkt. obrażeń. Jeśli atak trafi przeciwnika rzucającego czar, to ten przeciwnik zostaje powalony.','Atak zwierzaka. Zadaje +5...20 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik rzuca czar.'],
1202=>['Rozszalałe Uderzenie','Elitarny atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Rozszalałe Uderzenie, które powoduje u przeciwnika głęboką ranę na 5...20 sek. oraz zadaje +10...50 pkt. obrażeń..','Elitarny atak zwierzaka. Powoduje głęboką ranę (5...20 sek.) i zadaje +10...50 pkt. obrażeń.'],
1203=>['Bestialskie Zmiażdżenie','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Bestialskie Zmiażdżenie, które zadaje +5...20 pkt. obrażeń. Jeśli atak trafi powalonego przeciwnika, to będzie on oszołomiony przez 4...10 sek.','Atak zwierzaka. Zadaje +5...20 pkt. obrażeń. Wywołuje przypadłość oszołomienie (4...10 sek.), jeżeli wybrany przeciwnik jest powalony.'],
1205=>['Trujące Ugryzienie','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Trujące Ugryzienie, które zatruwa cel na 5...20 s.','Atak zwierzaka. Wywołuje przypadłość zatrucie (5...20 s).'],
1206=>['Skok','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Skok, który zadaje +5...20 pkt. obrażeń. Jeśli atak trafi poruszającego się przeciwnika, ten przeciwnik zostaje powalony.','Atak zwierzaka. Zadaje +5...20 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik jest w ruchu.'],
1209=>['Furia Bestii','Postawa. Wszystkie twoje umiejętności nie związane z atakami będą niedostępne przez 5 sek. Przez 5...11 sek., atakujesz o 33% szybciej.','Postawa. (5...11 sek.) Atakujesz o 25% szybciej. Twoje umiejętności nie związane z atakami są wyłączone (5 sek.).'],
1211=>['Gniazdo Żmij','Pułapka. Tworzysz Gniazdo Żmij. Kiedy się ono uaktywni, każdy przeciwnik w pobliżu otrzyma 5...35 pkt. obrażeń przebijających i przez 5...20 sek. będzie zatruty. Gniazdo Żmij dezaktywuje się po 90 sek. Jest to pułapka łatwa do przerwania.','Pułapka. (90 sek.) Działa na przeciwników w pobliżu. Zadaje 5...35 pkt. obrażeń przebijających. Wywołuje przypadłość zatrucie (5...20 sek.). Łatwo przerwać.'],
1212=>['Równonoc','Elitarny obrządek natury. Tworzy ducha o poziomie 1...10. Zaklęcia powodujące Przemagicznienie rzucone w jego pobliżu powodują dodatkowe 10 punktów Przemagicznienia. Duch umiera po 30...240 sek.','Elitarny obrządek natury. Tworzy ducha o poziomie 1...10 (długość życia: 30...240 sek.). Zaklęcia powodujące Przemagicznienie rzucone w zasięgu przeciwnika powodują dodatkowe 10 punktów Przemagicznienia.'],
1213=>['Spokój','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Zaklęcia rzucane przez stworzenia nie-duchy w jego zasięgu kończą się o 20...50% szybciej. Ten duch ginie po 15...120 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 15...120 sek.). Zaklęcia na stworzeniach w zasięgu przestają działać o 20...50% szybciej. Nie działa na duchy.'],
1215=>['Krzyk Dusz','Elitarny czar. Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu otrzymują po 10...65 pkt. obrażeń od błyskawic. Jeżeli w zasięgu słuchu znajdują się jakieś duchy lub trzymasz przedmiot, to otrzymujesz 10 pkt. energii.','Elitarny czar. Wybranemu przeciwnikowi i wszystkim przeciwnikom w pobliżu zadaje po 10...65 pkt. obrażeń od błyskawic. Jeżeli w zasięgu słuchu znajdują się jakieś duchy lub trzymasz przedmiot, to otrzymujesz 10 pkt. energii.'],
1217=>['Władca Rytuałów','Umiejętność elitarna. Przez 5...35 sek., twoje atrybuty Rytualisty zostaną zwiększone o 2...4 na potrzeby kolejnej umiejętności. Jeśli ta umiejętności jest rytuałem spętania, odnawia się 10...60% szybciej, zaś Władca Rytuałów odnawia się natychmiast.','Umiejętność elitarna. Przez 5...35 sek., twoje atrybuty Rytualisty zostaną zwiększone o +2...4 na potrzeby kolejnej umiejętności. Jeśli ta umiejętności jest rytuałem spętania, odnawia się 10...60% szybciej, zaś Władca Rytuałów odnawia się natychmiast.'],
1218=>['Okrutnym Był Daoshen','Czar z przedmiotu. Trzymaj prochy Daoshena przez maksymalnie 15...60 sek. Kiedy je trzymasz, wszystkie umiejętności Rytualisty otrzymują 10% do penetracji pancerza. Gdy upuścisz jego prochy, wszyscy przeciwnicy w pobliżu otrzymają 15...85 pkt. obrażeń od błyskawic.','Czar z przedmiotu. (15...60 sek.) Twoje umiejętności Rytualisty otrzymują 10% do penetracji pancerza. Efekt upuszczenia: wszyscy przeciwnicy w pobliżu otrzymują po 15...85 pkt. obrażeń od błyskawic.'],
1219=>['Opiekuńczym Był Kaolai','Czar z przedmiotu. Trzymaj prochy Kaolaia przez maksymalnie 15...60 sek. Trzymając jego prochy, otrzymujesz 20 do pancerza. Kiedy upuścisz prochy, wszyscy członkowie drużyny odzyskują 20...95 pkt. żywotności.','Czar z przedmiotu. (15...60 sek.) Posiadasz +20 pkt. pancerza. Efekt upuszczenia: wszyscy członkowie drużyny otrzymują po 20...95 pkt. żywotności.'],
1220=>['Zestrojoną Była Songkai','Elitarny czar z przedmiotu. Trzymaj prochy Songkai przez maksymalnie 45 sek. Kiedy trzymasz jej prochy, twoje czary i rytuały spętania kosztują o -5...50% podstawowego kosztu energetycznego mniej.','Elitarny czar z przedmiotu. (45 sek.) Twoje czary i rytuały spętania kosztują -5...50% bazowej energii.'],
1221=>['Odporną Była Xiko','Czar z przedmiotu. Unieś prochy Xiko na maks. 5...20 s. Za każdą klątwę lub przypadłość, na kt&oacute;rą cierpisz unosząc jej prochy, otrzymujesz +3 do regeneracji żywotności. W momencie wyrzucenia jej proch&oacute;w tracisz 1...4 przypadłość.','Czar z przedmiotu. (5...20 sek.) Za każdą przypadłość lub klątwę, pod której jesteś działaniem, otrzymujesz regenerację żywotności +3. Efekt upuszczenia: tracisz przypadłości w liczbie 1...4.'],
1222=>['Żywotną Była Naomei','Czar z przedmiotu. Trzymaj prochy Naomei przez maksymalnie 45 sek. Gdy upuścisz jej prochy, wszyscy członkowie drużyny w okolicy zostają wskrzeszeni z 15...75% pkt. żywotności i z zerem pkt. energii.','Czar z przedmiotu. (45 sek.) Efekt upuszczenia: wskrzesza martwych członków drużyny w okolicy (15...75% żywotności, 0 pkt. energii).'],
1223=>['Udręczoną Była Lingwah','Czar z przedmiotu. Trzymaj prochy Lingwah przez maksymalnie 10...60 sek. Kiedy je trzymasz, wszystkie klątwy Rytualisty kosztują o 1...5 mniej energii i trwają 50% dłużej. Gdy upuścisz jej prochy, wszystkie twoje klątwy Rytualisty zostaną odnowione.','Czar z przedmiotu. (10...60 sek.) Twoje klątwy Rytualisty kosztują o 1...5 mniej energii i trwają 50%. Efekt upuszczenia: wszystkie twoje klątwy Rytualisty zostaną odnowione.'],
1224=>['Przemieszczenie Ducha','Czar. Przenosisz wybranego sojuszniczego ducha do miejsca, w którym się znajdujesz.','Czar. Przenosisz wybranego sojuszniczego ducha do miejsca, w którym się znajdujesz.'],
1225=>['Połączone Uderzenie','Czar. Wybrany przeciwnik otrzymuje 5...95 pkt. obrażeń od błyskawic. Ten przeciwnik otrzymuje dodatkowe 5...35 pkt. obrażeń od błyskawic, jeżeli trzymasz przedmiot.','Czar. Zadaje 5...95 pkt. obrażeń od błyskawic. Zadaje 5...35 pkt. dodatkowych obrażeń od błyskawic, jeżeli trzymasz przedmiot.'],
1226=>['Uderzenie Duchowego Daru','Czar. Wybrany przeciwnik otrzymuje 20...65 obrażeń od błyskawic, a wszystkie duchy pod twoją kontrolą w zasięgu słuchu zyskują 20...65 pkt. żywotności.','Czar. Zadaje 20...65 pkt. obrażeń od błyskawic. Kontrolowane przez ciebie duchy w zasięgu słuchu otrzymują po 20...65 pkt. żywotności.'],
1227=>['Uderzenie Esencji','Czar. Wybrany przeciwnik otrzymuje 15...60 pkt. obrażeń od błyskawic. Jeżeli w zasięgu słuchu znajdują się jakieś duchy, zyskujesz 1...9 pkt. energii.','Czar. Zadaje 15...60 pkt. obrażeń od błyskawic. Otrzymujesz 1...9 pkt. energii, jeżeli w zasięgu słuchu jest jakiś duch.'],
1228=>['Duchowe Wysysanie','Czar. Duch znajdujący się najbliżej ciebie traci całą energię. Otrzymujesz 30...60% tej energii.','Czar. Duch znajdujący się najbliżej ciebie traci całą energię. Otrzymujesz 30...60% tej energii.'],
1229=>['Wybuchowy Byt','Zaklęcie (czar). Przez 15...60 sek., za każdym razem, kiedy tworzysz kreaturę, maksymalnie 5 przeciwników w pobliżu tej kreatury otrzymuje 20...65 pkt. obrażeń od błyskawicy.','Zaklęcie (czar). (15...60 sek.) Za każdym razem, kiedy stworzysz stworzenie, umiejętność zadaje po 20...65 pkt. obrażeń od błyskawic 5 przeciwnikom w pobliżu tego stworzenia.'],
1230=>['Dar Tworzenia','Zaklęcie (czar). Przez 15...60 sek., za każdym razem, kiedy tworzysz kreaturę, zyskujesz +5...50 pkt. żywotności oraz 1...6 pkt. energii.','Zaklęcie (czar). (15...60 sek.) Otrzymujesz 5...50 pkt. żywotności i 1...6 pkt. energii, za każdym razem, kiedy stworzysz stworzenie.'],
1231=>['Duchowe Połączenie','Elitarne zaklęcie (czar). Przez 12 sek., otrzymujesz +1...6 do regeneracji energii. Jeśli podczas rzucania tego czaru w zasięgu słuchu znajduje się duch, otrzymujesz 3...12 pkt. energii.','Elitarne zaklęcie (czar). (12 sek.) Otrzymujesz +1...6 do regeneracji energii. Efekt początkowy: jeśli w zasięgu słuchu znajduje się duch, otrzymujesz 3...12 pkt. energii.'],
1232=>['Zbroja Nieczułości','Umiejętność. Przez 10...35 sek., twoje duchy w zasięgu słuchu otrzymują 50% mniej obrażeń i są odporne na trafienia krytyczne.','Umiejętność. (10...35 sek.) Twoje duchy w zasięgu słuchu otrzymują 50% mniej obrażeń i są odporne na trafienia krytyczne.'],
1233=>['Kojące Wspomnienia','Czar. Uzdrawiasz wybranego sojusznika dodając 10...100 pkt. żywotności. Jeżeli trzymasz przedmiot, otrzymujesz 3 pkt. energii.','Czar. Dodaje 10...100 pkt. żywotności. Otrzymujesz 3 pkt. energii, jeżeli trzymasz przedmiot.'],
1234=>['Odnowa Ciała i Duszy','Czar. Wybrany sojusznik otrzymuje 20...115 pkt. żywotności. Sojusznik ten traci jedną przypadłość za każdego ducha w zasięgu słuchu.','Czar. Dodaje 20...115 pkt. żywotności. Usuwa jedną przypadłość na każdego ducha w zasięgu słuchu.'],
1235=>['Stępiony Oręż','Klątwa (czar). Przez 5...20 sek., wybrany przeciwnik i wszyscy sąsiadujący wrogowie nie mogą wykonać krytycznego trafiania i zadają 3...20 pkt. obrażeń mniej.','Klątwa (czar). Klątwa działa także na przeciwników w bezpośrednim sąsiedztwie celu (5...20 sek.). Neguje zdolność wykonywania trafień krytycznych. Zmniejsza obrażnia o 3...20.'],
1236=>['Unieruchamiające Łańcuchy','Klątwa (czar). Przez 3 sek., wybrany przeciwnik i wszyscy wrogowie w pobliżu poruszają się 90% wolniej, a podczas ruchu otrzymują co sekundę 1...30 pkt. obrażeń.','Klątwa (czar). Klątwa działa także na przeciwników w pobliżu twojego celu (3 sek.). Przeciwnicy ci poruszają się o 90% wolniej , a podczas ruchu otrzymują co sekundę 1...30 pkt. obrażeń.'],
1237=>['Bolesne Więzy','Klątwa (czar). Przez 10...20 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu zostają przeklęci Bolesnymi Więzami i otrzymują 8...20 pkt. obrażeń za każdym razem, kiedy otrzymają uderzenie od ducha.','Klątwa (czar). Klątwa działa także na przeciwników w pobliżu twojego celu (10...20 sek.). Duchy zadają tym przeciwnikom 8...20 pkt. dodatkowych obrażeń.'],
1238=>['Sygnet Tworzenia','Sygnet. Otrzymujesz 4 pkt. energii za każde przywołane i kontrolowane przez ciebie stworzenie w zasięgu słuchu (maksymalnie 3...12 pkt. energii).','Sygnet. Otrzymujesz 4 pkt. energii (maksymalnie 3...12) za każde przywołane i kontrolowane przez ciebie stworzenie w zasięgu słuchu.'],
1239=>['Sygnet Duchów','Sygnet elitarny. Tworzysz trzy duchy na poziomie 1...12. Ataki tych duchów zadają po 5...20 pkt. obrażeń. Duchy giną po 60 sek.','Sygnet elitarny. Tworzy trzy duchy na poziomie 1...12 (czas życia 60 sek.). Ich ataki zadają 5...20 pkt. obrażeń.'],
1240=>['Skręcenie Duszy','Umiejętność elitarna. Przez 5...45 sek., twoje rytuały spętania kosztują 15 pkt. energii mniej (minimalnie 5) i odnawiają się natychmiast. Skręcenie Duszy kończy się po przeprowadzeniu rytuałów spętania (w liczbie 1...3).','Umiejętność elitarna. (5...45 sek.) Twoje rytuały spętania kosztują 15 pkt. energii mniej (minimalnie 5) i odnawiają się natychmiast. Kończy się po przeprowadzeniu rytuałów spętania (w liczbie 1...3).'],
1244=>['Duchowy Pośpiech','Zaklęcie (czar). Przez 5...30 sek. rzucane czary odnawiają się o 25% szybciej, jeżeli znajdujesz się w okolicy ducha.','Zaklęcie (czar). (5...30 sek.) Czary, które rzucasz odnawiają się o 25% szybciej. Bez efektu, jeśli nie jesteś w zasięgu słuchu ducha.'],
1245=>['Spojrzenie z Zaświatów','Czar. Wybrany przeciwnik otrzymuje 20...65 pkt. obrażeń od błyskawic. Jeśli w zasięgu słuchu znajduje się duch, przeciwnik zostaje dodatkowo oślepiony na 2...6 sek.','Czar. Zadaje 20...65 pkt. obrażeń od błyskawic. Wywołuje ślepotę (2...6 sek.), jeżeli w zasięgu słuchu znajduje się duch.'],
1246=>['Gniew Przodków','Umiejętność. Przez 1 sek. nic się nie dzieje. Kiedy umiejętność przestanie działać, wszyscy przeciwnicy bezpośrednio przy wybranym sojuszniku otrzymują po 5...110 pkt. obrażeń od błyskawic.','Umiejętność. (1 sek.) Efekt końcowy: Przeciwnikom bezpośrednio przy wybranym sojuszniku zadaje po 5...110 pkt. obrażeń od błyskawic.'],
1247=>['Ból','Rytuał spętania. Tworzysz 1...12 poziomowego ducha. Ataki tego ducha zadają 5...30 pkt. obrażeń. Ten duch ginie po 30...150 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 30...150 sek.). Jego ataki zadają 5...30 pkt. obrażeń.'],
1249=>['Przemieszczenie','Rytuał spętania. Tworzysz 1...14 poziomowego ducha. Wszyscy sojusznicy nie-duchy w jego zasięgu mają 75% szans na blokowanie ataków. Za każdym razem, gdy atak zostanie w ten sposób zablokowany, duch otrzyma 60 pkt. obrażeń. Duch ginie po 30...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...14 (czas życia 30...60 sek.). Sojusznicy nie-duchy w zasięgu mają 75% szans na blokowanie. Efekt zablokowania: ten duch otrzymuje 60 pkt. obrażeń.'],
1250=>['Zabezpieczenie','Elitarny rytuał spętania. Tworzysz 1...14 poziomowego ducha. Co 4 sek. ten duch leczy jednego nie będącego duchem sojusznika w okolicy dodając mu 10...115 pkt. żywotności. Ten duch ginie po 90 sek.','Elitarny rytuał spętania. Tworzy ducha na poziomie 1...14 (czas życia 90 sek.). Co 4 sek. ten duch leczy jednego sojusznika nie-ducha, dodając mu 10...115 pkt. żywotności.'],
1251=>['Życie','Rytuał spętania. Tworzysz 1...14 poziomowego ducha. Gdy ten duch ginie, wszyscy nie będący duchami sojusznicy w jego zasięgu otrzymują 1...7 pkt. żywotności za każdą sekundę życia tego ducha. Ten duch ginie po 20 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...14 (czas życia 20 sek.). Działa na sojuszników nie-duchy w zasięgu. Efekt końcowy: dodaje 1...7 pkt. żywotności na każdą sekundę życia tego ducha.'],
1252=>['Uziemienie','Rytuał spętania. Tworzysz 1...14 poziomowego ducha. Wszyscy nie będący duchami przeciwnicy powaleni w zasięgu tego ducha, zostają powaleni na przynajmniej 3 sek. Za każdym razem, kiedy tak się dzieje, ten duch traci 50...25 pkt. żywotności. Ten duch ginie po 15...45 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...14 (czas życia 15...45 sek.). Za każdym razem, kiedy przeciwnik nie-duch w zasięgu zostanie powalony, będzie powalony przez przynajmniej 3 sek. Koszt powalenia: ten duch traci 50...25 pkt. żywotności.'],
1253=>['Pieśń Krwi','Rytuał spętania. Tworzysz ducha na poziomie 1...12, który ginie po 30...150 sek. Ataki tego ducha wykradają do 5...25 pkt. żywotności.','Rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 30...150 sek.). Jego ataki wykradają 5...25 pkt. żywotności.'],
1255=>['Żądza Wędrowania','Elitarny rytuał spętania. Tworzysz 1...12 poziomowego ducha. Za każdym razem, kiedy ten duch trafia stojącego w miejscu przeciwnika, ten przeciwnik zostaje powalony, a duch traci 70...50 pkt. żywotności. Duch ginie po 30...60 sek.','Elitarny rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 30...60 sek.). Jego ataki powalają przeciwników stojących w miejscu. Koszt powalenia: ten duch traci 70...50 pkt. żywotności.'],
1257=>['Oręż Duchowego Światła','Elitarny czar z broni. Przez 10 sek. wybrany sojusznik otrzymuje co sekundę 5...25 pkt. żywotności oraz dodatkowo 5...25 pkt. żywotności co sekundę, jeśli sojusznik ten znajduje się w pobliżu ducha.','Elitarny czar z broni. (10 s). Cel otrzymuje 5...25 pkt. żywotności na sekundę. Dodatkowo leczy 5...25 pkt. na sekundę w zasięgu słuchu ducha.'],
1258=>['Brutalny Oręż','Czar z broni. Na 10...40 sek. wybrany sojusznik otrzymuje Brutalny Oręż. Dzierżący ten oręż zadaje +5...15 pkt. obrażeń tak długo, jak nie ma na sobie żadnego zaklęcia.','Czar z broni. (10...40 sek.) Ataki zadają +5...15 pkt. obrażeń. Bez efektu, kiedy wybrany sojusznik jest pod wpływem zaklęcia.'],
1259=>['Prowadzony Oręż','Czar z broni. Przez 4...10 sek., ciosy tego sojusznika nie mogą być blokowane.','Czar z broni. (4...10 sek.) Ataków nie można blokować.'],
1260=>['Potulność','Klątwa (czar). Przez 5...30 sek. wybrany przeciwnik i wszyscy przeciwnicy w okolicy atakują o 50% wolniej.','Klątwa (czar). Klątwa działa także na przeciwników w okolicy celu (5...30 sek.). Ci przeciwnicy atakują o 50% wolniej.'],
1261=>['Lodowata Zbroja','Zaklęcie (czar). Na 10...25 sek., otrzymujesz +10...40 punktów pancerza przeciwko obrażeniom fizycznym i nie możesz w tym czasie zostać podpalony.','Zaklęcie (czar). (10...25 sek.) Otrzymujesz +10...40 pkt. pancerza przeciwko obrażeniom fizycznym i niewrażliwość na płonięcie.'],
1262=>['Uzdrawiający Krąg','Czar. Stworzenia w bezpośredniej odległości otrzymują po 30...180 pkt. żywotności. Rzucający czar nie otrzymuje pkt. żywotności.','Czar. Sojusznikom i przeciwnikom w bezpośredniej odległości dodaje 30...180 pkt. żywotności. Rzucający czar nie otrzymuje pkt. żywotności.'],
1263=>['Odnowienie Życia','Czar. Wskrzeszasz wybranego dotkniętego martwego członka drużyny z 50% pkt. żywotności i 5...20% pkt. energii. On i wszyscy sojusznicy w zasięgu słuchu otrzymują 55...130 pkt. żywotności.','Czar dotykowy. Wskrzesza wybranego członka drużyny (50% żywotności, 5...20% pkt. energii). Sojusznikom w zasięgu słuchu dodaje 55...130 pkt. żywotności.'],
1264=>['Zagłada','Czar. Zadaj wybranemu przeciwnikowi 10...60 pkt. obrażeń od błyskawic (maksymalnie 135) za każdy odnawiający się rytuał spętania, który posiadasz.','Czar. Zadaje 10...60 pkt. obrażeń od błyskawic (maksymalnie 135) za każdy odnawiający się rytuał spętania.'],
1265=>['Dar Posiadacza','Czar. Uzdrawiasz wybranego sojusznika dodając mu 15...60 pkt. żywotności. Jeżeli ten sojusznik posiada zaczarowaną broń, Dar Posiadacza dodaje dodatkowe 15...75 pkt. żywotności.','Czar. Dodaje 15...60 pkt. żywotności. Dodaje dodatkowo 15...75 pkt. żywotności, jeżeli ten sojusznik ma zaczarowaną broń.'],
1266=>['Ukojenie','Rytuał spętania. Tworzysz 1...12 poziomowego ducha. Wszyscy przeciwnicy w jego zasięgu otrzymują adrenalinę dwa razy wolniej. Ten duch ginie po 15...45 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 15...45 sek.). Przeciwnicy w zasięgu dwa razy dłużej gromadzą adrenalinę.'],
1267=>['Życiodajny Oręż','Czar z broni. Na 5...30 sek., wybrany sojusznik zyskuje Życiodajny Oręż, który zwiększa maksymalne pkt. żywotności o +40...175.','Czar z broni. (5...30 sek.) +40...175 pkt. do maksymalnej żywotności.'],
1268=>['Oręż Przyspieszenia','Elitarny czar z broni. Na 5...25 sek. wybrany sojusznik otrzymuje Oręż Przyspieszenia, który zwiększa o 33% szybkość odnawiania czarów i rytuałów spętania.','Elitarny czar z broni. (5...25 sek.) Czary i rytuały spętania odnawiają się o 33% szybciej.'],
1269=>['Sygnet Szału','Sygnet. Wybrany przeciwnik otrzymuje 5...50 pkt. świętych obrażeń i 5...10 pkt. świętych obrażeń za każdą umiejętność opartą na adrenalinie, którą posiada.','Sygnet. Zadaje 5...50 pkt. świętych obrażeń. Zadaje 5...10 pkt. dodatkowych świętych obrażeń, za każdą umiejętność wybranego przeciwnika opartą na adrenalinie.'],
1333=>['Przedłużenie Przypadłości','Elitarny czar. Z wybranego przeciwnika przenosi wszystkie przypadłości na wszystkich przeciwników w pobliżu twojego celu. Czasy trwania tych przypadłości wydłużają się o 5...100% (maksymalnie 30 sek.).','Elitarny czar. Z wybranego przeciwnika przenosi wszystkie przypadłości na wszystkich przeciwników w pobliżu twojego celu. Czasy trwania tych przypadłości wydłużają się o 5...100% (maksymalnie 30 sek.).'],
1334=>['Hipochondria','Czar. Przenosi na cel wszystkie przypadłości ze wszystkich wrogów w okolicy.','Czar. Przenosi wszystkie przypadłości od wrogów w okolicy na wybranego przeciwnika.'],
1335=>['Upadek Marnotrawcy','Klątwa (czar). Przez 5 sek., wybrany wróg zostaje dotknięty klątwą Upadku Marnotrawcy. Kiedy pozostaje pod działaniem klątwy, zarówno on jak i wszyscy wrogowie w jego bezpośrednim sąsiedztwie, otrzymują co sekundę 1...10 pkt. obrażeń oraz dodatkowe 1...10 pkt. za każdą sekundę działania tego czaru. Klątwa dobiega końca wcześniej, jeśli wybrany wróg użyje jakiejś umiejętności.','Klątwa (czar). (5 sek.) Kiedy wybrany przeciwnik pozostaje pod działaniem klątwy, zarówno on jak i wszyscy wrogowie w jego bezpośrednim sąsiedztwie otrzymują co sekundę 1...10 pkt. obrażeń. Wrogowie otrzymują +1...10 pkt. obrażeń za każdą sekundę działania tej klątwy. Kończy się wcześniej, jeśli wybrany wróg użyje jakiejś umiejętności.'],
1336=>['Duchowy Ból','Czar. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Wszystkie wrogie przywołane stworzenia na obszarze w pobliżu wroga otrzymują 25...125 pkt. obrażeń.','Czar. Zadaje 15...75 pkt. obrażeń. Zadaje 25...125 pkt. obrażeń wrogim przywołanym stworzeniom w rejonie wybranego przeciwnika.'],
1337=>['Wyssanie Urojeń','Czar. Zdejmujesz jedną klątwę mesmera z wybranego przeciwnika. Jeśli klątwa została usunięta w ten sposób, to przeciwnik traci 1...5 pkt. energii, z kolei ty otrzymujesz 4 pkt. energii za każdy punkt stracony przez niego.','Czar. Z wybranego przeciwnika usuwa jedną klątwę mesmera. Powoduje utratę 1...5 pkt. energii. Otrzymujesz 4 pkt. energii za każdy punkt straconej energii. Bez efektu, chyba że została usunięta klątwa.'],
1338=>['Wytrwała Pamięć','Zaklęcie (czar). Przez 5...20 sek., za każdym razem, kiedy czar, który rzucasz zostanie przerwany, czar natychmiast się odnowi.','Zaklęcie (czar). (5...20 sek.) Twoje przerwane czary natychmiast się odnawiają.'],
1339=>['Symbole Inspiracji','Umiejętność elitarna. Przez 6...40 sek. ta umiejętność staje się elitarną umiejętnością wybranego przeciwnika. Używane przez ciebie umiejętności elitarne wykorzystują atrybut Szybkie Rzucanie Czarów zamiast normalnego atrybutu.','Umiejętność elitarna. (6...40 sek.) Ta umiejętność staje się elitarną umiejętnością wybranego przeciwnika. Używane przez ciebie umiejętności elitarne wykorzystują atrybut Szybkie Rzucanie Czarów zamiast normalnego atrybutu.'],
1340=>['Przyspieszenie Sygnetów','Zaklęcie (czar). Przez 36...60 sek., wszystkie twoje sygnety używają wartości współczynnika Szybkiego Rzucania Czarów zamiast zwykłych atrybutów.','Zaklęcie (czar). (36...60 sek.) Twoje sygnety używają współczynnika Szybkiego Rzucania Czarów.'],
1341=>['Frustracja','Klątwa (czar). Przez 5...20 sek., wybrany przeciwnik rzuca czary o 50% wolniej i otrzymuje 5...50 pkt. obrażeń za każdym razem, kiedy jego akcja zostanie przerwana. Jeśli działanie umiejętności zostało przerwane, Frustracja zadaje podwójne obrażenia.','Klątwa (czar). (5...20 sek.) Powoduje, że rzucanie czarów jest wolniejsze o 50%. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń, za każdym razem, kiedy jego czary zostaną przerwane. Zadaje podwójne obrażenia w momencie przerwania umiejętności.'],
1342=>['Dokuczliwość','Elitarny czar. Jeżeli wybrany przeciwnik używa umiejętności, aktualnie wykonywana czynność tego przeciwnika i czynność każdego przeciwnika w okolicy zostają przerwane. Dodatkowo wykradasz 0...5 energii od wszystkich wrogów w okolicy.','Elitarny czar. Przerywa umiejętność. Efekt przerwania: przerywasz także czynności innych wrogów w okolicy i wykradasz 0...5 energii od wszystkich wrogów w okolicy.'],
1343=>['Eteryczny Fantom','Klątwa (czar). Przez 10 sek. wybrany przeciwnik posiada degenerację energii -1. Jeśli klątwa zostanie zdjęta przed tym czasem, to przeciwnik straci 1...5 pkt. energii.','Klątwa (czar). (10 sek.) Powoduje degenerację energii -1. Powoduje utratę 1...5 pkt. energii, jeżeli klątwa przestanie przedwcześnie działać.'],
1344=>['Sieć Rozproszenia','Klątwa (czar). Przerywasz czynność wybranego przeciwnika. Przez 10 sek., wybrany przeciwnik znajduje się pod działaniem klątwy Sieć Rozproszenia. Kiedy przestanie ona działać, czynność celu zostanie ponownie przerwana.','Klątwa (czar). (10 sek.) Efekt początkowy: przerywa umiejętność. Efekt końcowy: przerywa umiejętność.'],
1345=>['Zagadka Zaklinacza','Elitarna klątwa (czar). Przez 10 sek. wybrany przeciwnik rzuca zaklęcia 100...200% wolniej. Jeśli w momencie nałożenia klątwy wybrany przeciwnik nie znajduje się pod działaniem żadnego zaklęcia, przeciwnik ten odnosi 10...100 pkt. obrażeń, a wszyscy wrogowie w jego bezpośrednim sąsiedztwie odnoszą 75% tych obrażeń.','Elitarna klątwa (czar). Spowalnia o 100...200% rzucanie zaklęć (10 sek.). Początkowy efekt: jeśli wybrany przeciwnik nie jest pod wpływem zaklęcia, zadaje mu 10...100 pkt. obrażeń, a sąsiadującym z nim przeciwnikom zadaje 75% tych obrażeń.'],
1346=>['Sygnet Iluzji','Sygnet elitarny. Twoje następne nieiluzyjne czary (1...3) używają atrybutu Magia Iluzji, zamiast swojego normalnego atrybutu.','Sygnet elitarny. Twoje następne nieiluzyjne czary (1...3) używają atrybutu Magia Iluzji, zamiast swojego normalnego atrybutu.'],
1347=>['Rozładowanie Zaklęcia','Czar. Z wybranego przeciwnika zdejmujesz jedno zaklęcie. Jeśli przeciwnik jest pod działaniem klątwy, to umiejętność ta odnowi się o 20...50% szybciej.','Czar. Z wybranego przeciwnika usuwa jedno zaklęcie. Odnowa szybsza o 20...50%, jeżeli ten przeciwnik był pod działaniem klątwy.'],
1348=>['Wir Pożeracz Klątw','Elitarny czar. Z wybranego sojusznika usuwasz jedną klątwę. Jeśli klątwa zostanie usunięta w ten sposób, to każdy przeciwnik w pobliżu sojusznika otrzyma 30...90 pkt. obrażeń i straci jedno zaklęcie.','Elitarny czar. Usuwa z wybranego sojusznika jedną klątwę. Efekt usunięcia: Zadaje 30...90 pkt. obrażeń wrogom w pobliżu wybranego sojusznika i pozbawia ich po jednym zaklęciu.'],
1349=>['Zwierciadło Antyzaklęcia','Czar. Z wybranego przeciwnika zdejmujesz jedno zaklęcie. To samo zaklęcie tracą wszyscy członkowie drużyny tego przeciwnika.','Czar. Z wybranego przeciwnika usuwa jedno zaklęcie. To samo zaklęcie tracą członkowie drużyny wybranego przeciwnika.'],
1350=>['Łatwa Kradzież','Elitarny czar. Przerywa czynność przeciwnika. Jeżeli tą czynnością była umiejętność, to umiejętność ta będzie niedostępna przez 5...20 sek., a Łatwa Kradzież zostanie zastąpiona tą umiejętnością.','Elitarny czar. Przerywa czynność. Efekt przerwania: jeżeli tą czynnością była umiejętność, to umiejętność ta będzie niedostępna, a Łatwa Kradzież zostanie zastąpiona tą umiejętnością (5...20 sek.).'],
1351=>['Ożywienie Ociężałej Poczwary','Czar. Wykorzystujesz najbliższe zwłoki, by ożywić Ociężałą Poczwarę na 1...17 poz. Kiedy Ocieżała Poczwara zginie, zastępowany jest przez Strzępiastą Poczwarę na 0...15 poz., której ataki wywołują krwawienie.','Czar. Tworzy ociężałą poczwarę na poziomie 1...17. Kiedy ociężała poczwara zginie, zastępowana jest przez strzępiastą poczwarę na 0...15 poz., której ataki wywołują krwawienie. Zużywa świeże ciało.'],
1352=>['Rozkaz Ożywieńców','Elitarny czar. Przez 5 sek. twoje sługi zadają +3...16 pkt. obrażeń, ale za każdym razem, kiedy jeden z nich trafi, ty tracisz 2% swojej maksymalnej żywotności.','Elitarny czar. (5 sek.) Twoi nieumarli słudzy zadają +3...16 pkt. obrażeń. Efekt po trafieniu sługi: tracisz 2% twojej maksymalnej żywotności.'],
1353=>['Zgniłe Ciało','Czar. Niszczysz wybranego swojego nieumarłego sługę. Wszyscy przeciwnicy w pobliżu tego stworzenia na 5...15 sek. będą pod działaniem choroby.','Czar. Niszczy jednego z twoich nieumarłych sług. U przeciwników w pobliżu tego sługi wywołuje przypadłość choroba (5...15 sek.).'],
1354=>['Uczta Nieumarłych','Czar. Niszczysz wybranego, sojuszniczego nieumarłego sługę. Wszyscy twoi pozostali nieumarli sojusznicy otrzymują 10...100 punktów żywotności.','Czar. Niszczy jednego z twoich nieumarłych sług. Dodaje po 10...100 pkt. żywotności twoim sługom.'],
1355=>['Rozdzierające Kości','Elitarne zaklęcie (czar). Przez 60 sek., kiedy zginie wybrany nieumarły sługa, zastąpi go Strzępiasta Poczwara na 0...15 poz., której ataki wywołują krwawienie.','Elitarne zaklęcie (czar). (60 sek.) Kiedy wybrany nieumarły sługa zginie, zastępowany jest przez strzępiastą poczwarę na 0...15 poz., której ataki wywołują krwawienie.'],
1356=>['Zakażanie','Elitarne zaklęcie (czar). Przez 60 sek., za każdym razem, kiedy zaczniesz cierpieć na nową przypadłość, wszyscy przeciwnicy w okolicy zaczną cierpieć na tą samą przypadłość, a ty poświęcisz 10...5% swojej maksymalnej żywotności.','Elitarne zaklęcie (czar). (60 sek.) Za każdym razem, kiedy otrzymujesz przypadłość, wszyscy przeciwnicy w okolicy otrzymują tą samą przypadłość. Za każdym razem, kiedy się to stanie, poświęcasz 10...5% maksymalnej żywotności.'],
1358=>['Wrzody Płuc','Klątwa (czar). Przez 10...30 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu posiadają degenerację żywotności -4 podczas krwawienia i zaczną krwawić na 5...20 sek., kiedy tylko użyją okrzyku lub pieśni.','Klątwa (czar). Klątwa działa także na przeciwników w pobliżu twojego celu (10...30 sek.). Powoduje degenerację żywotności -4 u przeciwników, którzy krwawią. Wywołuje przypadłość krwawienie (5...20 sek.), za każdym razem, kiedy ci przeciwnicy użyją okrzyku lub zaśpiewu.'],
1359=>['Ból Antyzaklęcia','Elitarny czar. Wybrany przeciwnik traci zaklęcia w liczbie 1...3. Jeżeli przeciwnik straci w ten sposób zaklęcie, to on i wszyscy przeciwnicy w bezpośredniej odległości tracą 10...100 pkt. żywotności.','Elitarny czar. Wybrany przeciwnik traci zaklęcia w liczbie 1...3. Efekt usunięcia: ten przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim tracą po 10...100 pkt. żywotności.'],
1360=>['Piętno Furii','Klątwa (czar). Przez 5 sek., sojusznicy trafiający we wroga otrzymują dawki adrenaliny (0...2). Kiedy klątwa dobiegnie końca, trafiony przeciwnik znajdzie się na 1...15 sek. pod działaniem Pękniętej Zbroi.','Klątwa (czar). (5 sek.) Sojusznicy trafiający wybranego przeciwnika otrzymują dawki adrenaliny w liczbie 0...2. Efekt końcowy: wywołuje pęknięcie zbroi (1...15 sek.)'],
1362=>['Skażenie Zaklęcia','Elitarna klątwa (czar). Z wybranego przeciwnika zdejmujesz jedno zaklęcie. Jeżeli zaklęcie zostało zdjęte w ten sposób, to przez 10 sek. przeciwnik będzie posiadał degenerację żywotności -1...8.','Elitarna klątwa (czar). Z wybranego przeciwnika usuwa jedno zaklęcie. Efekt usunięcia: degeneracja żywotności -1...8 (10 sek.).'],
1363=>['Sygnet Smutku','Sygnet. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Jeżeli wybrany przeciwnik znajduje się w pobliżu ciała lub jego zwierzak jest martwy, to umiejętność natychmiast się odnowi.','Sygnet. Zadaje 15...75 pkt. obrażeń. Natychmiast się odnawia, jeżeli wybrany przeciwnik znajduje się w pobliżu ciała lub jego zwierzęcy towarzysz jest martwy.'],
1364=>['Sygnet Cierpienia','Sygnet elitarny. Krwawisz przez 6 sek. Następna umiejętność nekromanty, która trafi we wrogi cel, spowoduje krwawienie przez 2...16 sek.','Sygnet elitarny. Krwawisz przez 6 sek. Powoduje krwawienie przeciwnika, który jest celem twojej następnej umiejętności nekromanckiej (2...16 sek.).'],
1365=>['Sygnet Zagubionych Dusz','Sygnet. Jeżeli wybrany przeciwnik ma mniej niż 50% pkt. żywotności, to otrzymujesz 10...100 pkt. żywotności i 1...10 pkt. energii.','Sygnet. Otrzymujesz 10...100 pkt. żywotności i 1...10 pkt. energii, jeżeli wybrany przeciwnik ma poniżej 50% żywotności.'],
1366=>['Studnia Ciemności','Czar studni. Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by na 5...50 sek. utworzyć Studnię Ciemności. Przeciwnicy pod działaniem klątwy w zasięgu działania Studni Ciemności nie trafiają w 50% przypadków.','Czar studni. (5...50 sek.). Obłożeni klątwą przeciwnicy w tej studni mają 50% szans na chybienie. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
1367=>['Oślepiające Porażenie','Elitarny czar. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od błyskawic, a także on i wszyscy przeciwnicy bezpośrednio przy nim zostają oślepieni na 3...8 sek. Ten czar posiada 25% przebicie pancerza.','Elitarny czar. Zadaje 5...50 pkt. obrażeń od błyskawic. U celu i u przeciwników bezpośrednio przy nim wywołuje przypadłość oślepienie (3...8 sek.). 25% przebicie pancerza.'],
1368=>['Lodowate Wiatry','Klątwa (czar). Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 30...60 pkt. obrażeń od zimna. Przez 10 sek. następna klątwa Magii Wody trafiająca przeklętego przeciwnika będzie trwać 25...100% dłużej.','Klątwa (czar). (10 sek.) Następna klątwa wodna trafiająca przeklętego przeciwnika będzie trwać 25...100% dłużej. Efekt początkowy: 30...60 pkt. obrażeń od zimna. Zadaje obrażenia znajdującym się w sąsiedztwie.'],
1369=>['Błyskawica','Czar. Wystrzeliwujesz Błyskawicę, która po trafieniu zadaje 5...50 pkt. obrażeń od błyskawic. Jeżeli Błyskawicą zostanie trafiony poruszający się przeciwnik, to otrzyma on dodatkowe 5...50 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicie pancerza.','Czar. Pocisk: zadaje 5...50 pkt. obrażeń od błyskawic. Zadaje 5...50 pkt. dodatkowych obrażeń od błyskawic, jeżeli wybrany przeciwnik jest w ruchu. 25% przebicie pancerza.'],
1370=>['Pośpiech Burzowego Dżinna','Zaklęcie (czar). Przez 10...25 sek., poruszasz się o 25% szybciej. W każdej sekundzie, kiedy się poruszasz, tracisz 1 pkt. energii.','Zaklęcie (czar). (10...25 sek.) Poruszasz się o 25% szybciej. Tracisz 1 pkt. energii w każdej sekundzie ruchu.'],
1371=>['Kamienny Napastnik','Zaklęcie (czar). Przez 5...30 sek., za każdym razem, kiedy otrzymujesz lub zadajesz obrażenia od żywiołów lub fizyczne, obrażenia te zamieniane są na obrażenia od ziemi.','Zaklęcie (czar). (5...30 sek.) Zamienia obrażenia fizyczne i obrażenia od żywiołów, jakie otrzymujesz, na obrażenia od ziemi.'],
1372=>['Burza Piaskowa','Elitarny czar. W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Burzę Piaskową. Przez 10 sek., przeciwnicy w pobliżu co sekundę otrzymują 20...40 pkt. obrażeń od ziemi, co więcej przeciwnicy atakujący co sekundę otrzymują dodatkowe 10...30 obrażeń od ziemi.','Elitarny czar. W każdej sekundzie zadaje 20...40 pkt. obrażeń od ziemi (10 sek.). Trafia przeciwników w pobliżu początkowego miejsca wybranego przeciwnika. Co sekundę trafia atakujących przeciwników, zadając 10...30 pkt. dodatkowych obrażeń od ziemi.'],
1373=>['Kamienna Osłona','Elitarne zaklęcie (czar). Przez 5...20 sek., ataki wykonywane przez wybranego przeciwnika i wszystkich przeciwników w pobliżu zadają obrażenia od ziemi i nie mogą powodować trafień krytycznych.','Elitarne zaklęcie (czar). Klątwa działa także na przeciwników w pobliżu celu (5...20 sek.). Zamienia ataki na takie, które zadają obrażenia od ziemi i usuwa zdolność zadawania trafień krytycznych.'],
1374=>['Hebanowy Jastrząb','Czar. Wystrzeliwujesz pocisk, który po trafieniu zadaje wybranemu przeciwnikowi 10...85 pkt. obrażeń od ziemi i na 5...15 sek. powoduje u niego osłabienie.','Czar. Pocisk: zadaje 10...85 pkt. obrażeń i wywołuje osłabienie (5...15 sek.).'],
1375=>['Aura Kamiennego Ciała','Zaklęcie (czar). Przez 5...15 sek., obrażenia, które otrzymujesz obniżane są o 1...31 pkt., a ty jesteś odporny na trafienia krytyczne.','Zaklęcie (czar). (5...15 sek.) Obniża obrażenia, jakie otrzymujesz o 1...31 i stajesz się niewrażliwy na trafienia krytyczne.'],
1376=>['Glif Odnowy','Glif. Przez 15 sek. twoje następne 2 czary uzdrawiają cię dodając po 30...105 pkt. żywotności, dodatkowo jesteś uzdrawiany o 150...400% pkt. energii zużytych na te czary.','Glif. (15 sek.) Twoje następne 2 czary dodają ci 30...105 pkt. żywotności, dodatkowo jesteś uzdrawiany o 150...400% pkt. energii zużytych na te czary.'],
1377=>['Eteryczny Pryzmat','Umiejętność elitarna. Przez 3 sek. wszystkie obrażenia jakie otrzymujesz są obniżane o 75%. Kiedy Eteryczny Pryzmat przestanie działać, otrzymujesz 5...20 pkt. energii.','Umiejętność elitarna. (3 sek.) Wszystkie obrażenia jakie otrzymujesz są obniżane o 75%. Efekt końcowy: otrzymujesz 5...20 pkt. energii.'],
1378=>['Mistrz Magii','Elitarne zaklęcie (czar). Przez 1...61 sek. wszystkie twoje atrybuty związane z żywiołami wynoszą 8...14 i twoje zaklęcia związane z żywiołami zwracają ci 1 pkt. energii oraz 30% ich kosztu.','Elitarne zaklęcie (czar). (1...61 sek.) Wszystkie twoje atrybuty związane z żywiołami wynoszą 8...14 i twoje zaklęcia związane z żywiołami zwracają ci 1 pkt. energii oraz 30% ich kosztu.'],
1379=>['Rozżarzone Spojrzenie','Czar. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od ognia. Jeżeli przeciwnik płonie, otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii.','Czar. Zadaje 5...50 pkt. obrażeń od ognia. Otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii, jeżeli wybrany przeciwnik płonie.'],
1380=>['Żar Sawanny','Elitarny czar. W miejscu, gdzie znajduje się wybrany przeciwnik tworzysz Żar Sawanny. Przez 5 sek. wszyscy przeciwnicy w pobliżu otrzymują co sekundę 5...20 pkt. obrażeń od ognia za każdą sekundę działania tego czaru.','Elitarny czar. W każdej sekundzie od rzucenia czaru zadaje 5...20 pkt. obrażeń od ognia (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca znajdowania się celu.'],
1381=>['Pośpiech Ognistego Dżinna','Zaklęcie (czar). Przeciwnicy w bezpośredniej odległości otrzymują po 15...120 pkt. obrażeń od ognia. Przez 8...14 sek. poruszasz się o 25% szybciej. Pośpiech Ognistego Dżinna odnawia się o 50% szybciej, jeżeli efekty czaru dosięgły przeciwnika.','Zaklęcie (czar). (8...14 sek.) Poruszasz się o 25% szybciej. Efekt początkowy: przeciwnikom bezpośrednio przy tobie zadaje po 15...120 pkt. obrażeń od ognia. Jeżeli czar zadał obrażenia przeciwnikowi, to odnawia się o 50% szybciej.'],
1382=>['Zamrażający Podmuch','Klątwa (czar). Zadaje wybranemu przeciwnikowi 20...80 pkt. obrażeń od zimna. Jeśli przeciwnik ten jest po wpływem klątwy Magii Wody, otrzymuje dodatkowe 66 pkt. obrażeń od zimna.','Klątwa (czar). Zadaje 20...80 pkt. obrażeń od zimna. Zadaje +66 pkt. obrażeń od zimna, jeśli przeciwnik znajduje się pod wpływem klątwy Magii Wody.'],
1390=>['Interwencja Sędziego','Zaklęcie (czar). Przez 10 sek., kiedy następnym razem wybrany sojusznik ma otrzymać śmiertelne obrażenia, to są one negowane, a jeden przeciwnik w pobliżu otrzymuje 30...180 pkt. świętych obrażeń.','Zaklęcie (czar). (10 sek.) Neguje następne śmiertelne obrażenia. Efekt zanegowania: przeciwnikowi w pobliżu wybranego sojusznika zadaje 30...180 pkt. świętych obrażeń.'],
1391=>['Wspierający Duch','Zaklęcie (czar). Przez 5...23 sek., za każdym razem, kiedy wybrany sojusznik otrzyma obrażenia będąc powalonym, otrzyma 5...50 pkt. żywotności.','Zaklęcie (czar). (5...23 sek.) Dodaje 5...50 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia będąc powalonym.'],
1392=>['Czujne Uzdrawianie','Zaklęcie (czar). Przez 10 sek. wybrany sojusznik posiada regenerację żywotności równą +1...4. Jeżeli umiejętność przestanie działać przed tym czasem, to sojusznik otrzymuje 30...120 pkt. żywotności.','Zaklęcie (czar). (10 sek.) Wybrany sojusznik posiada regenerację żywotności +1...4 i otrzymuje 30...120 pkt. żywotności, jeżeli to zaklęcie przedwcześnie przestanie działać.'],
1393=>['Dar Uzdrowiciela','Elitarne zaklęcie (czar). Przez 10...55 sek. czary oparte na Modlitwach Uzdrawiających rzucasz o 50% szybciej i dodają one o 50% pkt. żywotności więcej.','Elitarne zaklęcie (czar). (10...55 sek.) Czary z Modlitw Uzdrawiających rzucasz o 50% szybciej i dodają one o 50% więcej żywotności.'],
1394=>['Przymierze Uzdrowiciela','Elitarne zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, twoje czary Modlitw Uzdrawiających uzdrawiają o 20% pkt. żywotności mniej, ale kosztują o -1...4 pkt. energii mniej.','Elitarne zaklęcie (czar). Twoje czary z Modlitw Uzdrawiających kosztują o 1...4 pkt. energii mniej. Te czary dodają o 20% mniej żywotności.'],
1395=>['Wahadło Baltazara','Elitarne zaklęcie (czar). Przez 5...25 sek., następnym razem, gdy wybrany sojusznik ma zostać powalony przez przeciwnika, to przeciwnik zostaje powalony za niego.','Elitarne zaklęcie (czar). (5...25 sek.) Powali następnego przeciwnika, który spróbuje powalić wybranego sojusznika.'],
1396=>['Słowa Otuchy','Czar. Uzdrawiasz wybranego sojusznika dodając mu 20...65 pkt. żywotności i dodatkowe 20...50 pkt. żywotności, jeśli cierpi na przypadłość.','Czar. Dodaje 20...65 pkt. żywotności. Dodatkowo dodaje 20...50 pkt. żywotności, jeśli wybrany sojusznik jest pod wpływem przypadłości.'],
1397=>['Światło Wybawienia','Elitarny czar. Uzdrawiasz wszystkich członków drużyny dodając każdemu 5...70 pkt. żywotności..','Elitarny czar. Każdemu członkowi drużyny dodaje 5...70 pkt. żywotności.'],
1398=>['Zgubne Zaklęcia','Klątwa (czar). Przez 30 sek., za każdym razem, kiedy wybrany przeciwnik będzie celem zaklęcia, rzucający to zaklęcie otrzyma 15...75 pkt. obrażeń.','Klątwa (czar). (30 sek.) Każdemu kto rzuca zaklęcie na wybranego przeciwnika zadaje 15...75 pkt. obrażeń.'],
1399=>['Pochłaniająca Tarcza','Zaklęcie (czar). Przez 3...7 sek., za każdym razem, kiedy wybrany sojusznik zostanie trafiony będąc pod działaniem tego zaklęcia, obrażenia przez niego otrzymywane są obniżane o 5.','Zaklęcie (czar). (3...7 sek.) Obniża otrzymywane obrażenia o 5, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia.'],
1400=>['Odwrócenie Obrażeń','Zaklęcie (czar). Przez 8 sek., kiedy wybrany sojusznik będzie miał następnym razem otrzymać obrażenia, to w zamian otrzyma je przeciwnik, który je zadał (maksymalnie 5...75).','Zaklęcie (czar). (8 sek.) Neguje następne obrażenia i zadaje źródłu tą samą liczbę pkt. obrażeń (maksymalnie 5...75).'],
1401=>['Odnawiający Dotyk','Czar. Dotknięty sojusznik traci dwie przypadłości i za każdą przypadłość usuniętą w ten sposób otrzymuje 15...60 pkt. żywotności.','Czar dotykowy. Usuwa dwie przypadłości. Za każdą usuniętą przypadłość dodaje 15...60 pkt. żywotności.'],
1402=>['Krytyczne Cięcie','Atak toporem. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeżeli atak spowodował trafienie krytyczne, przerywasz czynność wybranego przeciwnika.','Atak toporem. Zadaje +5...20 pkt. obrażeń. Przerywa czynność, kiedy wykonasz trafienie krytyczne.'],
1403=>['Bolesne Cięcie','Atak toporem. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli wybrany przeciwnik ma głęboką ranę, to przerywasz jego czynność.','Atak toporem. Zadaje +5...20 pkt. obrażeń. Przerywa czynność, jeżeli wybrany przeciwnik ma głęboką ranę.'],
1404=>['Atak na Oślep','Postawa. Przez 1...15 sek., atakujesz o 33% szybciej, ale poruszasz się o 33% wolniej.','Postawa. (1...15 sek.) Atakujesz o 33% szybciej. Poruszasz się o 33% wolniej.'],
1405=>['Uderzenie w Szarży','Postawa elitarna. Przez 1...10 sek. biegasz o 33% szybciej. Twoje kolejne trafienie wręcz zadaje +10...90 pkt. obrażeń, a ta postawa przestaje działać. Postawa przestanie działać, kiedy użyjesz umiejętności.','Postawa elitarna. (1...10 sek.) Poruszasz się o 33% szybciej i w następnym celnym ataku wręcz zadajesz +10...90 pkt. obrażeń. Przestanie działać, kiedy trafisz lub jeśli użyjesz umiejętności.'],
1406=>['Uderzenie Głową','Umiejętność elitarna. Wybrany dotknięty przeciwnik otrzymuje 40...100 pkt. obrażeń. Przez 10 sek. będziesz oszołomiony.','Elitarna umiejętność dotykowa. Zadaje 40...100 pkt. obrażeń. Jesteś oszołomiony (10 sek.).'],
1407=>['Lwie Uzdrowienie','Umiejętność. Wszystkie twoje sygnety będą niedostępne przez 12 sek. Otrzymujesz 50...110 pkt. żywotności i dawki adrenaliny w liczbie 0...3.','Umiejętność. Otrzymujesz 50...110 pkt. żywotności i dawki adrenaliny w liczbie 0...3. Wyłącza twoje sygnety (12 sek.).'],
1408=>['Szał Ntouki','Umiejętność elitarna. Otrzymujesz adrenalinę w liczbie dawek: 1...7. Przez 8 sek., za każdym razem, kiedy użyjesz umiejętności opartej na adrenalinie, umiejętność ta odnowi się po 3 sek.','Umiejętność elitarna. Otrzymujesz dawki adrenaliny w liczbie 1...7. Przez 8 sek. umiejętność oparte na adrenalinie posiadają 3 sek. czas odnowienia.'],
1409=>['Uderzenie Mokele','Atak młotem. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń i otrzymujesz dawki adrenaliny w liczbie: 2.','Atak młotem. Zadaje +5...20 pkt. obrażeń, a ty otrzymujesz dawki adrenaliny w liczbie 2.'],
1410=>['Harde Uderzenie','Atak młotem. Jeśli ten atak trafi swój cel, zadajesz +1...20 pkt. obrażeń. Jeśli cel jest powalony na ziemię, zostaje oszołomiony na 1...8 sek.','Atak młotem. Zadaje +1...20 pkt. obrażeń. Jeśli wróg jest powalony na ziemię, zostaje oszołomiony (1...8 sek.).'],
1411=>['Sygnet Wytrzymałości','Sygnet. Twoja maksymalna żywotność zwiększa się o +50...300 pkt. Ten sygnet przestanie działać z twoim kolejnym trafionym atakiem.','Sygnet. Twoja maksymalna żywotność zwiększa się o +50...300 pkt. Przestanie działać, jeśli twój atak trafi.'],
1412=>['"Jesteś Sam!"','Elitarny okrzyk. Jeśli wybrany przeciwnik nie jest w pobliżu sojusznika, to na 8 sek. zostaje okulawiony i osłabiony.','Elitarny okrzyk. Wywołuje przypadłości okulawienie oraz osłabienie (8 sek.). Bez efektu, jeżeli wybrany przeciwnik jest w pobliżu jednego ze swoich sojuszników.'],
1413=>['Wybuch Agresji','Postawa. Przez 2...10 sek. atakujesz o 33% szybciej. Kiedy ta postawa przestanie działać, tracisz całą adrenalinę.','Postawa. (2...10 sek.) Atakujesz o 33% szybciej. Efekt końcowy: tracisz całą adrenalinę.'],
1414=>['Wściekła Szarża','Postawa. Twoja szybkość poruszania się rośnie o 25% na najbliższe 5...15 sek. Wściekła Szarża dobiega końca, gdy uda ci się trafić jakiś cel. Jeśli trafisz go atakiem wręcz, zyskujesz wtedy również impulsy adrenaliny (0...3).','Postawa. (5...15 sek.) Poruszasz się 25% szybciej. Zyskujesz +0...3 adrealiny przy następnym ataku wręcz. <c x="SkillDull">Kończy się, gdy trafisz wroga.'],
1415=>['Okulawiające Cięcie','Elitarny atak mieczem. Jeśli atak trafi, twój cel zostanie okulawiony na 5...15 sek. i zaczyna krwawić przez 10...25 sek.','Elitarny atak mieczem. Wywołuje przypadłości okulawienie (5...15 sek.) i przypadłość krwawienie (10...25 sek.).'],
1416=>['Barbarzyńskie Podcięcie','Atak mieczem. Jeśli atak trafi, zadaje +5...30 pkt. obrażeń. Jeżeli nie przyjąłeś żadnej postawy, to twój cel przez 5...15 sek. będzie krwawił.','Atak mieczem. Zadaje +5...30 pkt. obrażeń. Wywołuje przypadłość krwawienie (5...15 sek.), jeżeli nie przyjąłeś postawy.'],
1465=>['Przygotowany Strzał','Elitarny strzał z łuku. Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń. Jeżeli jesteś pod działaniem przygotowania, otrzymujesz 1...9 pkt. energii.','Elitarny strzał z łuku. Zadaje +10...25 pkt. obrażeń. Otrzymujesz 1...9 pkt. energii, jeżeli jesteś pod działaniem przygotowania.'],
1466=>['Płonąca Strzała','Elitarny strzał z łuku. Jeżeli atak trafi, zadaje +10...30 pkt. obrażeń, a cel będzie płonął przez 2...8 sek.','Elitarny strzał z łuku. Zadaje +10...30 pkt. obrażeń. Wywołuje przypadłość płonięcie (2...8 sek.).'],
1467=>['Wysoki Strzał','Strzał z łuku. Jeśli strzała trafi, zadaje +10...35 pkt. obrażeń. Nie można jej zablokować, ale leci o 50% wolniej.','Strzał z łuku. Zadaje +10...35 pkt. obrażeń. Nie do zablokowania. Ta strzała leci o 50% wolniej.'],
1468=>['Jedność w Ataku','Elitarny okrzyk. Twój zwierzęcy towarzysz natychmiast rusza do wybranego celu i kiedy trafi swoim następnym atakiem, wywoła u niego krwawienie na 5...15 sek. Kiedy twój następny atak trafi, wybrany cel zostanie okulawiony na 5...15 sek.','Elitarny okrzyk. Twój zwierzęcy towarzysz natychmiast rusza do wybranego celu i kiedy trafi swoim następnym atakiem, wywoła u niego przypadłość krwawienie (5...15 sek.). Wywołuje przypadłość okulawienie (5...15 sek.), kiedy twój następny atak trafi.'],
1469=>['Ogień Krzyżowy','Strzał z łuku. Jeżeli atak trafi, wybrany przeciwnik otrzymuje +5...20 pkt. obrażeń. Jeżeli przeciwnik jest w pobliżu twojego sojusznika, to atak nie może zostać zablokowany.','Strzał z łuku. Zadaje +5...20 pkt. obrażeń. Nie do zablokowania, jeżeli wybrany przeciwnik jest w pobliżu jednego z twoich sojuszników.'],
1470=>['Kolczaste Strzały','Przygotowanie. Przez 24 sek. twoje strzały wywołują krwawienie, które trwa 3...15 sek. W czasie aktywacji tej umiejętności posiadasz -40 pkt. pancerza.','Przygotowanie. (24 sek.) Twoje strzały wywołują przypadłość krwawienie (3...15 sek.). W czasie aktywacji tej umiejętności posiadasz -40 pkt. pancerza.'],
1471=>['Skupienie Padlinożercy','Umiejętność elitarna. Przez 10 sek., jeżeli trafisz przeciwnika pod działaniem przypadłości, otrzymasz 3...12 pkt. energii.','Umiejętność elitarna. (10 sek.) Jeżeli trafisz przeciwnika pod działaniem przypadłości, otrzymujesz 3...12 pkt. energii.'],
1472=>['Toksyczność','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Zatrute lub chore stworzenia w jego zasięgu otrzymują degenerację żywotności -2. Duch ginie po 30...180 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Zatrute lub chore stworzenia w zasięgu otrzymują degenerację żywotności -2.'],
1473=>['Ruchome Piaski','Elitarny obrządek natury. Tworzysz 1...10 poziomowego ducha. Wszystkie stworzenia nie-duchy w jego zasięgu tracą po jednym pkt. energii za każdym razem, kiedy zaatakują lub użyją umiejętności. Duch ginie po 30...180 sek.','Elitarny obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Stworzenia tracą 1 pkt. energii, za każdym razem, kiedy atakują lub używają umiejętności. Nie działa na duchy.'],
1474=>['Objęcia Burzy','Postawa. Przez 10 sek. poruszasz się o 25% szybciej. Postawa odnawia się za każdym razem, kiedy otrzymasz obrażenia od żywiołów.','Postawa. (10 sek.) Poruszasz się o 25% szybciej. Odnowienie: za każdym razem, kiedy otrzymujesz obrażenia od żywiołów.'],
1475=>['Szybkość Trapera','Postawa. Przez 5...30 sek. twoje pułapki odnawiają się o 25% szybciej i aktywują o 25% szybciej. Ta postawa przestanie działać z twoim kolejnym trafionym atakiem.','Postawa. (5...30 sek.) Twoje pułapki odnawiają się o 25% szybciej i aktywują o 25% szybciej. Przestanie działać, jeśli twój atak trafi.'],
1476=>['Potykacz','Pułapka. Kiedy Potykacz zostanie uaktywniony, wszyscy przeciwnicy w pobliżu otrzymują 5...20 obrażeń przebijających. Okulawieni przeciwnicy zostają powaleni. Potykacz przestaje działać po 90 sekundach. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','Pułapka. (90 sek.) Przeciwnikom w pobliżu zadaje po 5...20 pkt. obrażeń przebijających. Powala okulawionych przeciwników. Łatwo przerwać.'],
1478=>['Odnawialny Udar','Klątwa (czar). Przez 8 sek., wybrany przeciwnik otrzymuje co sekundę 2...12 pkt. obrażeń. Kiedy klątwa dobiegnie końca, otrzymujesz 1...8 pkt. energii.','Klątwa (czar). (8 sek.) Co sekundę zadaje 2...12 pkt. obrażeń. Efekt końcowy: otrzymujesz 1...8 pkt. energii.'],
1479=>['Duchowa Ofiara','Elitarny czar. Otrzymujesz 8...17 pkt. energii. Jeżeli w zasięgu słuchu znajdują się jakieś duchy, nie poświęcasz punktów żywotności.','Elitarny czar. Otrzymujesz 8...17 pkt. energii. Nie poświęcasz żywotności, jeżeli w zasięgu słuchu jest jakiś duch.'],
1480=>['Duchowy Dar','Zaklęcie (czar). Przez 60 sek., za każdym razem, kiedy stworzysz stworzenie, wszyscy sojusznicy w jego pobliżu otrzymują 5...50 pkt. żywotności i tracą jedną przypadłość.','Zaklęcie (czar). (60 sek.) Za każdym razem, kiedy stworzysz stworzenie, wszyscy sojusznicy w pobliżu otrzymują 5...50 pkt. żywotności i tracą jedną przypadłość.'],
1481=>['Sygnet Śmiertelnego Paktu','Sygnet. Wskrzeszasz wybranego członka drużyny, który powraca do życia z tyloma punktami żywotności ile masz ich ty i 15...100% maksymalnej energii. Kiedy następnym razem ten sojusznik zginie w ciągu 120 sek., zginiesz i ty.','Sygnet. Wskrzesza wybranego członka drużyny z twoim aktualnym poziomem żywotności i 15...100% maksymalnej energii. W ciągu 120 sek. umrzesz, kiedy następnym razem zginie ten członek drużyny.'],
1482=>['Odzyskanie Esencji','Elitarny czar. Wszystkie twoje duchy giną. Otrzymujesz 5...20 pkt. energii, a wszystkie twoje rytuały spętania natychmiast się odnawiają, jeżeli w ten sposób zginie jakiś duch.','Elitarny czar. Giną wszystkie twoje duchy. Jeżeli w ten sposób zginie duch, otrzymujesz 5...20 pkt. energii, a wszystkie twoje Rytuały Spętania natychmiast się odnawiają.'],
1483=>['Wypędzające Uderzenie','Atak wręcz. Jeśli ten atak trafi, zadajesz +10...60 pkt. świętych obrażeń. Zadaje podwójne obrażenia przywołanym stworzeniom.','Atak wręcz. Zadaje 10...60 pkt. świętych obrażeń. Zadaje podwójne obrażenia przywołanym stworzeniom.'],
1484=>['Mistyczny Zamach','Atak wręcz. Jeśli ten atak dojdzie celu, zadajesz +3...12 pkt. obrażeń. Jeśli znajdujesz się pod wpływem zaklęcia, atak ten zadaje dodatkowe +3...12 pkt. obrażeń.','Atak wręcz. Zadaje +3...12 pkt. obrażeń. Zadaje +3...12 pkt. obrażeń, jeżeli jesteś pod wpływem zaklęcia.'],
1485=>['Atak Eremity','Atak kosą. Jeśli atak trafi, zadaje +1...10 pkt. obrażeń i usuwa zaklęcie derwisza. Jeśli zostanie usunięte jakieś zaklęcie, zadajesz dodatkowe +1...10 pkt. obrażeń i uderzasz we wszystkich wrogów w bezpośrednim sąsiedztwie.','Atak kosą. Zadaje +1...10 pkt. obrażeń i usuwa zaklęcie derwisza. Efekt usunięcia: Zadaje +1...10 pkt. obrażeń i uderza we wszystkich wrogów w bezpośrednim sąsiedztwie.'],
1486=>['Żniwo Przypadłości','Atak wręcz. Jeśli ten atak dojdzie celu, zadajesz +3...15 pkt. obrażeń. Każdy trafiony wróg traci 1 przypadłość. W przypadku każdego wroga, który straci przypadłość, wszyscy przeciwnicy w jego sąsiedztwie otrzymują 10...40 pkt. świętych obrażeń.','Atak wręcz. Zadaje +3...15 pkt. obrażeń. Trafieni wrogowie tracą 1 przypadłość. Efekt usunięcia: Wszyscy wrogowie w sąsiedztwie trafionego otrzymują 10...40 pkt. świętych obrażeń.'],
1487=>['Zamach Podwójnego Księżyca','Atak wręcz. Tracisz 1 zaklęcie derwisza i zyskujesz 10...50 pkt. żywotności. Jeśli stracisz w ten sposób jakieś zaklęcie, nie można zablokować twojego ataku, uderzasz dwukrotnie i otrzymujesz dodatkowe 10...70 pkt. żywotności.','Atak wręcz. Usuwa jedno z twoich zaklęć derwisza. Zyskujesz 10...50 pkt. żywotności. Efekt usunięcia: Dwukrotny atak, który nie może być zablokowany, oraz dodatkowe 10...70 żywotności.'],
1488=>['Zwycięski Zamach','Atak wręcz. Jeśli atak trafi, zadaje +5...25 pkt. obrażeń. Jeśli wybrany przeciwnik ma mniej żywotności niż ty, otrzymujesz 30...80 pkt. żywotności.','Atak wręcz. Zadaje +5...25 pkt. obrażeń. Otrzymujesz 30...80 pkt. żywotności za każdego trafionego przeciwnika, który ma mniej żywotności niż ty.'],
1489=>['Niepowstrzymywalny Zamach','Atak kosą. Zadaje +3...15 pkt. obrażeń i tracisz 1 zaklęcie derwisza. Jeśli stracisz w ten sposób jakieś zaklęcie, Niepowstrzymany Zamach nie może zostać zablokowany, usuwa postawę i zadaje dodatkowo +3...15 pkt. obrażeń.','Atak kosą. Zadaje +3...15 pkt. obrażeń. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Nie do zablokowania, usuwa postawę, zadaje dodatkowo +3...15 pkt. obrażeń.'],
1490=>['Nabożny Szturm','Atak wręcz. Jeśli atak trafi, zadaje +10...20 pkt. obrażeń i usuwa 1 zaklęcie derwisza. Jeśli zaklęcie derwisza zostało usunięte, umiejętność ta odnawia się 75% szybciej, zaś wrogowie w bezpośrednim sąsiedztwie otrzymują 15...40 pkt. obrażeń.','Atak wręcz. Zadaje +10...20 pkt. obrażeń. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Umiejętność ta odnawia się 75% szybciej, a wrogowie w bezpośrednim sąsiedztwie otrzymują 15...40 pkt. obrażeń.'],
1491=>['Mistyczny Wir','Czar. Wszystkim przeciwnikom w pobliżu zadaje po 10...60 pkt. obrażeń od zimna. Jeśli znajdujesz się pod wpływem zaklęcia, czar ten zadaje dodatkowe 10...60 pkt. obrażeń od zimna.','Czar. Wszystkim przeciwnikom w pobliżu zadaje po 10...60 pkt. obrażeń od zimna. Zadaje 10...60 obrażeń od zimna więcej, jeśli jesteś pod wpływem zaklęcia.'],
1493=>['Palce Grentha','Zaklęcie błysku (czar). Wszyscy przeciwnicy w pobliżu otrzymują 10...40 pkt. obrażeń od zimna. Przez 30 sek., twoje ataki zadają obrażenia od zimna. Kiedy zaklęcie to dobiegnie końca, przekazujesz swoje przypadłości (1...2) wszystkim wrogom w pobliżu.','Zaklęcie błysku (czar). (30 sek.) Twoje ataki zadają obrażenia od zimna. Efekt początkowy: Zadaje 10...40 pkt. obrażeń od zimna pobliskim wrogom. Efekt końcowy: Przekazuje przypadłości (1...2) wszystkim wrogom w pobliżu.'],
1495=>['Ciernista Aura','Zaklęcie błysku (czar). Wszyscy wybrani przeciwnicy zaczynają krwawić przez 5...15 sek. Następnie, przez 30 sek. zaklęcie to nic nie robi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostaną okulawieni na 3...8 sek.','Zaklęcie błysku (czar). (30 sek.) Efekt początkowy: Powoduje krwawienie (5...15 sek.) u pobliskich wrogów. Efekt końcowy: Powoduje okulawienie (3...8 sek.) u pobliskich wrogów.'],
1496=>['Szał Baltazara','Zaklęcie błysku (czar). Wszyscy pobliscy przeciwnicy zostają podpaleni na 1...3 sek. Następnie, przez 20 sek. zaklęcie to nic nie robi. Kiedy zaklęcie dobiegnie końca, otrzymujesz dawki (1...2) adrenaliny, jeśli w zasięgu słuchu są jeszcze jacyś wrogowie.','Zaklęcie błysku (czar). (20 sek.) Efekt początkowy: Podpala (1...3 sek.) przeciwników w pobliżu. Efekt końcowy: Zyskujesz dawki adrenaliny (1...2), jeśli w zasięgu słuchu są jacyś wrogowie.'],
1497=>['Okrycie Pyłem','Zaklęcie błysku (czar). Wszyscy przeciwnicy w pobliżu otrzymują 10...40 pkt. obrażeń od ziemi. Przez 30 sek., twoje ataki zadają obrażenia od ziemi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostaną oślepieni na 1...4 sek.','Zaklęcie błysku (czar). (30 sek.) Twoje ataki zadają obrażenia od ziemi. Efekt początkowy: Zadaje 10...40 obrażeń od ziemi pobliskim wrogom. Efekt końcowy: Wywołuje oślepienie (1...4 sek.) u pobliskich wrogów.'],
1498=>['Nadzwyczajna Moc','Zaklęcie błysku (czar). Wszyscy przeciwnicy w pobliżu otrzymują 10...40 pkt. obrażeń od ziemi. Przez 30 sek., twoje ataki zadają obrażenia od ziemi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie mają pękniętą zbroję przez 1...10 sek.','Zaklęcie błysku (czar). (30 sek.) Twoje ataki zadają obrażenia od ziemi. Efekt początkowy: Zadaje 10...40 obrażeń od ziemi pobliskim wrogom. Efekt końcowy: Powoduje pęknięcie zbroi (1...10 sek.) pobliskich przeciwników.'],
1499=>['Nabożna Odnowa','Elitarne zaklęcie błysku (czar). Przez 8 sek. nic się nie dzieje. Kiedy zaklęcie to dobiegnie końca, Nabożna Odnowa zostaje doładowana i zyskujesz 0...5 pkt. energii oraz 0...30 żywotności.','Elitarne zaklęcie błysku (czar). (8 sek.) Efekt końcowy: Odnawia się, zaś ty zyskujesz 0...5 pkt. energii oraz 0...30 żywotności.'],
1500=>['Okrycie Mirażem','Zaklęcie błysku (czar). Przez 20 sek. masz 40% szans na wykonanie bloku i dodatkowe 4...10% za każde dodatkowe zaklęcie (maks. 80%). Wszyscy pobliscy przeciwnicy otrzymują 10...40 pkt. obrażeń od ziemi za każdym razem, gdy jest z ciebie usuwane zaklęcie derwisza.','Zaklęcie błysku (czar). (20 sek.) 40% nas na wykonanie bloku i dodatkowe 4...10% za każde kolejne zaklęcie. 10...40 pkt. obrażeń od ziemi zadawanych pobliskim wrogom, gdy tracisz zaklęcie derwisza.'],
1502=>['Tajemna Gorliwość','Elitarne zaklęcie (czar). Przez 10 sek., za każdym razem, kiedy rzucasz czar, zyskujesz 2 pkt. energii za każde zaklęcie, które masz na sobie (maksymalnie 2...7 pkt. energii).','Elitarne zaklęcie (czar). (10 sek.) Za każdym razem, kiedy rzucasz czar, otrzymujesz 2 pkt. energii (maksymalnie 2...7) za każde zaklęcie na tobie.'],
1503=>['Mistyczny Wigor','Zaklęcie (czar). Przez 20 sek., za każdym razem, kiedy twój atak trafi, otrzymujesz 3...15 pkt. żywotności za każde zaklęcie, które masz na sobie (maksymalnie 25 pkt. żywotności).','Zaklęcie (czar). (20 sek.) Za każdym razem, kiedy twój atak trafi, otrzymujesz 3...15 pkt. żywotności (maksymalnie 25) za każde zaklęcie na tobie.'],
1504=>['Czujna Interwencja','Zaklęcie (czar). Przez 60 sek., kiedy obrażenia sprowadzą żywotność wybranego sojusznika poniżej 25%, otrzymuje on 50...200 pkt. żywotności.','Zaklęcie (czar). (60 sek.) Dodaje 50...200 pkt. żywotności, kiedy następnym razem obrażenia sprowadzą żywotność wybranego sojusznika poniżej 25%.'],
1505=>['Ślub Pobożności','Zaklęcie (czar). Przez 20 sek. otrzymujesz +24 do pancerza i +1...4 do regeneracji żywotności. Ślub Pobożności odnawia się za każdym razem gdy kończy się rzucone na ciebie zaklęcie.','Zaklęcie (czar). (20 sek.) +24 do pancerza oraz +1...4 do regeneracji żywotności. Odnowienie: za każdym razem gdy kończy się rzucone na ciebie zaklęcie.'],
1506=>['Życiodajny Dar','Zaklęcie (czar). Na 20 sek. twoja maksymalna żywotność wzrasta o +40...100 pkt. Kiedy zaklęcie przestanie działać, otrzymujesz 75...200 pkt. żywotności.','Zaklęcie (czar). (20 sek.) Twoja maksymalna żywotność zwiększa się o +40...100 pkt. Efekt końcowy: otrzymujesz 75...200 pkt. żywotności.'],
1507=>['Serce Świętego Płomienia','Zaklęcie błysku (czar). Wszyscy przeciwnicy w pobliżu otrzymują po 5...30 pkt. świętych obrażeń. Następnie, przez 30 sek. twoje ataki zadają święte obrażenia. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostają podpaleni na 2...5 sek.','Zaklęcie błysku (czar). (30 sek.) Twoje ataki zadają święte obrażenia. Efekt początkowy: Przeciwnicy w pobliżu otrzymują po 5...30 pkt. świętych obrażeń. Efekt końcowy: Podpala (2...5 sek.) przeciwników w pobliżu.'],
1508=>['Przedłużenie Zaklęć','Umiejętność. Przez 10 sek., twoje kolejne zaklęcie derwisza trwa 10...150% dłużej.','Umiejętność. (10 sek.) Twoje kolejne zaklęcie derwisza trwa 10...150% dłużej.'],
1509=>['Interwencja Wiary','Zaklęcie (czar). Interwencja Wiary przestanie działać, kiedy obrażenia sprowadzą twoją żywotność poniżej 50%. Kiedy zaklęcie przestanie działać, otrzymasz 30...150 pkt. żywotności.','Zaklęcie (czar). Otrzymujesz 30...150 pkt. żywotności następnym razem, kiedy twoja żywotność spadnie poniżej 50%.'],
1510=>['Piaskowe Odłamki','Zaklęcie błysku (czar). Przez 30 sek. twoje kolejne (1...5) trafienia kosą zadają 10...60 pkt. obrażeń od ziemi wszystkim wrogom w bezpośrednim sąsiedztwie.','Zaklęcie błysku (czar). (30 sek.) Zadaje 10...60 pkt. obrażeń od ziemi wszystkim sąsiadującym wrogom za każdym razem, gdy atakujesz kosą. Kończy się po określonej liczbie ataków (1...5).'],
1512=>['Pośpiech Lyssy','Zaklęcie błysku (czar). Przez 3...15 sek., twoje zaklęcia derwisza odnawiają się o 33% szybciej. Kiedy uaktywnisz to zaklęcie, przerwane zostają akcje wykonywane przez wszystkich przeciwników w bezpośrednim sąsiedztwie. Kiedy to zaklęcie dobiegnie końca, przerwane zostają akcje wykonywane przez wszystkich przeciwników w bezpośrednim sąsiedztwie. 50% szansy na porażkę, chyba że Modlitwy Wiatru są na co najmniej 5 poziomie.','Zaklęcie błysku (czar). (3...15 sek.) Twoje zaklęcia derwisza odnawiają się 33% szybciej. Efekt początkowy: Przerywa akcje wszystkich wrogów w bezpośrednim sąsiedztwie. Efekt końcowy: Przerywa akcje wszystkich wrogów w bezpośrednim sąsiedztwie. (50% szansy na porażkę, chyba że Modlitwy Wiatru są na co najmniej 5 poziomie.)'],
1513=>['Wiodące Dłonie','Zaklęcie (czar). Przez 20 sek., twoich kolejnych 0...3 ataków nie można zablokować Kiedy ta umiejętność zostaje uaktywniona, usuwa ślepotę.','Zaklęcie (czar). (20 sek.) Twoje kolejne ataki (0...3) nie mogą zostać zablokowane. Efekt początkowy: Usuwa ślepotę.'],
1514=>['Ulotna Stabilność','Zaklęcie błysku (czar). Przez 4...10 sek., nie możesz zostać powalony i poruszasz się 25% szybciej. Zaklęcie to kończy się przed czasem, jeśli zapobiegnie powaleniu.','Zaklęcie błysku (czar). (4...10 sek.) Nie możesz zostać powalony i poruszasz się 25% szybciej. Kończy się, jeśli zapobiegnie powaleniu.'],
1515=>['Zbroja Świętości','Zaklęcie (czar). Przez 5...15 sek., wszyscy sąsiadujący z tobą przeciwnicy zaczynają cierpieć na osłabienie. Przez 15 sek. przeciwnicy cierpiący na przypadłości zadają ci 5...20 pkt. obrażeń mniej.','Zaklęcie (czar). Wywołuje osłabienie u wszystkich sąsiadujących z tobą wrogów (5...15). Przeciwnicy cierpiący na przypadłości zadają ci 5...20 pkt. mniej obrażeń (15).'],
1516=>['Mistyczna Regeneracja','Zaklęcie (czar). Na 5...20 sek., otrzymujesz regenerację żywotności +1...4 na każde zaklęcie (maksymalnie 8), pod którego jesteś działaniem.','Zaklęcie (czar). (5...20 sek.) Otrzymujesz regenerację żywotności +1...4 na każde zaklęcie (maksymalnie 8), pod którego jesteś działaniem.'],
1517=>['Ślub Milczenia','Elitarne zaklęcie (czar). Przez 5...10 sek., nie możesz być celem czarów, ale i sam nie możesz ich rzucać.','Elitarne zaklęcie (czar). (5...10 sek.) Nie możesz być celem czarów. Nie możesz rzucać czarów.'],
1518=>['Awatar Baltazara','Elitarna forma. Przez 10...90 sek., otrzymujesz +20 do pancerza przeciwko obrażeniom fizycznym, zyskujesz adrenalinę 25% szybciej, twoje ataki zadają święte obrażenia, a za każdym razem gdy stracisz zaklęcie derwisza, pobliscy wrogowie zostają podpaleni na 1...3 sek. Umiejętność zostaje zablokowana na 45 sekund.','Elitarna forma. (10...90 sek.) Otrzymujesz +20 do pancerza przeciwko obrażeniom fizycznym, zyskujesz adrenalinę 25% szybciej, twoje ataki zadają święte obrażenia oraz powodujesz płonięcie (1...3 sek.) pobliskich wrogów, za każdym razem gdy stracisz zaklęcia derwisza. Umiejętność zostaje zablokowana na 45 sekund.'],
1519=>['Awatar Dwayny','Elitarna forma. Przez 10...90 sek. twoje ataki zadają święte obrażenia. Za każdym razem, gdy używasz umiejętności ofensywnej derwisza, tracisz 1 klątwę. Gdy stracisz zaklęcie derwisza, wszyscy sprzymierzeńcy w zasięgu słuchu odzyskają 5...50 pkt. żywotności. Ta umiejętność zostanie wyłączona na 45 sek.','Elitarna forma. (10...90 sek.) Zadajesz święte obrażenia. Za każdym razem, gdy używasz umiejętności ataku derwisza, tracisz 1 klątwę. Sprzymierzeńcy w zasięgu słuchu odzyskują 5...50 pkt. żywotności za każdym razem, gdy tracisz zaklęcie derwisza. Ta umiejętność zostanie wyłączona na 45 sek.'],
1520=>['Awatar Grentha','Elitarna forma. Przez 10...90 sek. twoje ataki kosą zadają obrażenia od ciemności i wykradają 0...12 żywotności. Zyskujesz niewrażliwość na choroby i przez 3 sek. wywołujesz choroby u wszystkich wrogów w bezpośrednim sąsiedztwie za każdym razem, gdy stracisz zaklęcie derwisza. Umiejętność zostaje zablokowana na 45 sekund.','Elitarna forma. (10...90 sek.) Twoje ataki kosą zadają obrażenia od ciemności i wykradają 0...12 żywotności. Jesteś niewrażliwy na działanie chorób. Wywołujesz chorobę u wszystkich wrogów w bezpośrednim sąsiedztwie (3 sek.) kiedy stracisz zaklęcie derwisza. Umiejętność zostaje zablokowana na 45 sekund.'],
1521=>['Awatar Lyssy','Elitarna forma. Przez 10...90 sek., twoje zaklęcia derwisza odnawiają się o 50% szybciej, a twoje ataki zadają obrażenia od chaosu. Za każdym razem gdy stracisz zaklęcie derwisza, wykradasz 1 energii u wszystkich wrogów w bezpośrednim sąsiedztwie. Umiejętność zostaje zablokowana na 45 sekund.','Elitarna forma. (10...90 sek.) Twoje zaklęcia derwisza odnawiają się 50% szybciej, zaś ataki zadają obrażenia od chaosu. Kiedy stracisz zaklęcie derwisza, wykradasz 1 pkt. energii wszystkim pobliskim wrogom. Umiejętność zostaje zablokowana na 45 sekund.'],
1522=>['Awatar Melandru','Elitarna forma. Przez 10...90 sek., masz +150 do żywotności, +30 do pancerza przeciwko żywiołom, a twoje ataki zadają obrażenia od ziemi. Za każdym razem gdy stracisz zaklęcie derwisza, wszyscy członkowie drużyny w zasięgu słuchu tracą 1 przypadłość. Umiejętność zostaje zablokowana na 45 sekund.','Elitarna forma. (10...90 sek.) Otrzymujesz +150 do maksymalnej żywotności, +30 do pancerza przeciwko żywiołom, a twoje ataki zadają obrażenia od ziemi. Leczysz 1 przypadłość u wszystkich członków drużyny w zasięgu słuchu za każdym razem, gdy stracisz zaklęcie derwisza. Umiejętność zostaje zablokowana na 45 sekund.'],
1523=>['Medytacja','Zaklęcie (czar). Tracisz całą adrenalinę. Przez 20 sek., za każdym razem, gdy skończy się działające na tobie zaklęcie, otrzymasz 1...4 pkt. energii.','Zaklęcie (czar). (20 sek.) Tracisz całą adrenalinę. Otrzymujesz 1...4 za każdym razem, gdy skończy się rzucone na ciebie zaklęcie.'],
1524=>['Gorliwość Eremity','Zaklęcie (czar). Za każdego wroga w zasięgu słuchu otrzymujesz 1...3 pkt. energii (maksymalnie 8). Następnie, przez 10 sek. zaklęcie to nic nie robi. Kiedy zaklęcie dobiegnie końca, za każdego wroga w zasięgu słuchu otrzymujesz 1...3 pkt. energii (maksymalnie 8).','Zaklęcie (czar). (10 sek.) Efekt początkowy: Za każdego wroga w zasięgu słuchu otrzymujesz 1...3 pkt. energii (maksymalnie 8). Efekt końcowy: Za każdego wroga w zasięgu słuchu otrzymujesz 1...3 pkt. energii (maksymalnie 8).'],
1525=>['Naturalne Uzdrawianie','Czar. Odzyskujesz 50...170 pkt. żywotności! Jeśli jesteś pod wpływem zaklęcia, czar ten uaktywnia się 50% szybciej.','Czar. Odzyskujesz 50...170 pkt. żywotności. Umiejętność ta uaktywnia się 50% szybciej, jeśli nie jesteś pod wpływem zaklęcia.'],
1526=>['Nasycenie Życiem','Czar. Wybrany sojusznik inny niż ty otrzymuje 5...50% twojej aktualnej żywotności (maksymalnie 300 pkt. żywotności).','Czar. Dodaje 5...50% twojej aktualnej żywotności (maksymalnie 300). Na cel nie można wybrać siebie.'],
1527=>['Mistyczne Uzdrowienie','Czar. Odzyskujesz 5...65 pkt. żywotności! Przywracasz także 5...65 żywotności wszystkim członkom drużyny będącym pod wpływem zaklęcia.','Czar. Odzyskujesz 5...65 pkt. żywotności. Przywraca także 5...65 żywotności wszystkim członkom drużyny będącym pod wpływem zaklęcia.'],
1528=>['Dotyk Dwayny','Czar. Dotknięty wybrany sojusznik otrzymuje 60 pkt. żywotności na każde zaklęcie, pod którego jesteś działaniem (maksymalnie 60...240).','Czar dotykowy. Dodaje 60 pkt. żywotności (maksymalnie 60...240) za każde zaklęcie, pod którego jesteś działaniem.'],
1529=>['Nabożne Przywrócenie','Czar. Otrzymujesz 80...150 żywotności i usuwasz 1 zaklęcie derwisza. Jeśli usunięto w ten sposób zaklęcie, tracisz także klątwy w liczbie 1...3.','Czar. Otrzymujesz 80...150 żywotności i usuwasz 1 zaklęcie derwisza. Efekt usunięcia: Tracisz klątwy w liczbie 1...3.'],
1530=>['Sygnet Nabożnego Światła','Sygnet. Usuwa jedno zaklęcie derwisza. Wybrany sojusznik odzyskuje 30...150 pkt. żywotności. Jeśli w ten sposób zostanie usunięte zaklęcie, sygnet ten odnowi się 75% szybciej.','Sygnet. Przywraca 30...150 pkt. żywotności. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Odnawia się 75% szybciej.'],
1531=>['Aura Zastraszenia','Zaklęcie (czar). Przez 60 sek., masz zwiększoną maksymalną żywotność o +40...100 i otrzymujesz 1...10 pkt. obrażeń mniej od przeciwników z mniejszą żywotnością od ciebie.','Zaklęcie (czar). (60 sek.) Masz zwiększoną maksymalną żywotność o +40...100 i otrzymujesz -1...10 pkt. obrażeń od przeciwników z mniejszą żywotnością od ciebie.'],
1532=>['Mistyczna Burza Piaskowa','Czar. W miejscu swojego pobytu tworzysz piaskową burzę, która trwa 3 sek. Co sekundę wrogowie w pobliżu tego miejsca otrzymują 10...40 pkt. obrażeń od ziemi. Atakujący wrogowie otrzymują dodatkowe 10...20 pkt. obrażeń. Jeśli w momencie rzucenia czaru znajdujesz się pod wpływem zaklęcia, działa on dwa razy dłużej.','Czar. (3 sek.) Zadaje co sekundę 10...40 pkt. obrażeń od ziemi. Zadaje dodatkowe 10...20 pkt. obrażeń atakującym wrogom. Trafia przeciwników w pobliżu twojego początkowego miejsca pobytu. Trwa dwa razy dłużej, jeśli znajdujesz się pod wpływem zaklęcia.'],
1533=>['Wiatr Antyzaklęcia','Czar. Usuwa jedno z twoich zaklęć derwisza. Jeśli zostało usunięte jakieś zaklęcie, wszyscy pobliscy wrogowie tracą 1 zaklęcie i otrzymują 20...80 pkt. obrażeń od zimna.','Czar. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Wszyscy pobliscy wrogowie tracą 1 zaklęcie i otrzymują 20...80 pkt. obrażeń od zimna.'],
1534=>['Rozrywający Dotyk','Czar. Zadaje wybranemu przeciwnikowi 15...65 pkt. obrażeń od zimna. Tracisz 1 zaklęcie derwisza. Jeśli zostało usunięte jakieś zaklęcie, wybrany przeciwnik traci 1 zaklęcie, a ty otrzymujesz dawki (2) adrenaliny.','Czar dotykowy. Zadaje 15...65 pkt. obrażeń od zimna. Utrata 1 zaklęcie derwisza. Efekt usunięcia: wybrany przeciwnik traci 1 zaklęcie, a ty otrzymujesz dawki (2) adrenaliny.'],
1535=>['Okulawiający Zamach','Atak kosą. Jeżeli ten atak trafi przeciwnika, to zostaje on okulawiony na 3...12 sek. Umiejętność ta zadaje +3...15 pkt. obrażeń, jeśli przeciwnik się porusza.','Atak kosą. (3...12 sek.) Powoduje okulawienie. Zadaje +3...15 pkt. obrażeń poruszającym się wrogom.'],
1536=>['Raniące Uderzenie','Elitarny atak kosą. Jeśli ten atak dojdzie celu, zadajesz +5...20 pkt. obrażeń, docelowy wróg zaczyna krwawić przez 5...20 sek. i tracisz 1 zaklęcie derwisza. Jeśli doszło do usunięcia zaklęcia, docelowy wróg otrzymuje także głęboką ranę na 5...20 sek.','Elitarny atak kosą. Zadaje +5...20 pkt. obrażeń i powoduje krwawienie (5...20 sek.). Usuwa jedno zaklęcie derwisza. Efekt usunięcia: Powoduje głęboką ranę (5...20 sek.).'],
1537=>['Nużące Uderzenie','Atak kosą. Usuwasz 1 zaklęcie derwisza. Jeśli doszło do usunięcia zaklęcia, wybrany wróg otrzymuje głęboką ranę na 3...10 sek. Jeśli nie doszło do usunięcia zaklęcia, zostajesz osłabiony na 10 sekund.','Atak kosą. Usuwa jedno zaklęcie derwisza. Efekt usunięcia: Wywołuje głęboką ranę (3...10 sek.). Jeśli nie doszło do usunięcia zaklęcia, zostajesz osłabiony (10 sek.).'],
1538=>['Natarcie Lyssy','Atak kosą. Jeśli ten atak trafi, powoduje przerwanie akcji. Jeśli znajdujesz się pod wpływem zaklęcia, każda umiejętność, którą przerwiesz, zostanie wyłączona na kolejne 1...10 sek. Ten atak zadaje 50% pkt. normalnych obrażeń.','Atak kosą. Przerywa czynność przeciwnika. Jeśli znajdujesz się pod wpływem zaklęcia, przerwana umiejętność zostanie wyłączona na kolejne 1...10 sek. Ten atak zadaje 50% pkt. normalnych obrażeń.'],
1539=>['Lodowate Zwycięstwo','Atak kosą. Jeśli atak dojdzie celu, zadaje +3...15 pkt. obrażeń. Za każdego trafionego wroga, który miał mniej żywotności od ciebie, dany wróg oraz wszyscy przeciwnicy w jego sąsiedztwie otrzymują 10...30 pkt. obrażeń od zimna.','Atak kosą. Zadaje +3...15 pkt. obrażeń. Zadaje 10...30 pkt. obrażeń od zimna każdemu wrogowi, który ma mniej żywotności od ciebie, oraz wszystkim przeciwnikom w jego sąsiedztwie.'],
1540=>['Pewność Siebie','Zaklęcie błysku (czar). Przez 10 sek., otrzymujesz +10 do pancerza, jeśli masz jakąś przypadłość, oraz otrzymujesz 1...3 pkt. do regeneracji żywotności za każdą przypadłość, pod której wpływem jesteś. Kiedy to zaklęcie dobiega końca, zostajesz wyleczony z 1...2 przypadłości.','Zaklęcie błysku (czar). (10 sek.) Otrzymujesz +10 do pancerza będąc pod wpływem jakieś przypadłości. Otrzymujesz 1...3 pkt. żywotności za każdą przypadłość, pod której jesteś wpływem. Efekt końcowy: Usuwa 1...2 przypadłości.'],
1541=>['Zaklęty Pośpiech','Zaklęcie błysku (czar). Przez 7 sek., poruszasz się o 25% szybciej. Jeśli zaklęcie to zakończy się przedwcześnie, tracisz przypadłości (1).','Zaklęcie błysku (czar). (7 sek.) Poruszasz się 25% szybciej. Tracisz przypadłości (1), jeśli to zaklęcie zakończy się przedwcześnie.'],
1542=>['Nabożna Koncentracja','Postawa. Przez 5...20 sek., twoje czynności nie mogą być przerywane, ale za każdym razem, gdy miałyby być przerwane, tracisz 1 zaklęcie derwisza albo Nabożna Koncentracja przestanie działać.','Postawa. (5...20 sek.) Zapobiega przerwaniom. Koszt zapobieżenia: Tracisz jedno zaklęcie derwisza lub Nabożna Koncentracja dobiega końca.'],
1543=>['Nabożny Pośpiech','Postawa. Usuwasz 1 zaklęcie derwisza i przez 1...7 sek. poruszasz się 25% szybciej. Jeśli zostało usunięte zaklęcie, możesz biec 50% szybciej.','Postawa. (1...7 sek.) Tracisz 1 zaklęcie derwisza i poruszasz się 25% szybciej. Efekt usunięcia: Biegasz 50% szybciej.'],
1544=>['Wirująca Szarża','Zaklęcie błysku (czar). Przez 1...6 sek., poruszasz się o 33% szybciej niż normalnie. Kiedy następnym razem trafisz wroga, wszyscy pozostali przeciwnicy w pobliżu otrzymują 10...60 pkt. obrażeń od zimna, a zaklęcie dobiega końca.','Zaklęcie błysku (czar). (1...6 sek.) Poruszasz się 33% szybciej. Zadaje 10...60 obrażeń od zimna wszystkim wrogom w pobliżu, kiedy następnym razem trafisz jakiegoś przeciwnika, a to zaklęcie się skończy.'],
1545=>['Próba Wiary','Czar. Zadaje 15...75 pkt. obrażeń i zdejmuje 1 zaklęcie z wybranego przeciwnika. Jeśli przeciwnik ten nie znajdował się pod wpływem zaklęcia, zostaje oszołomiony na 2...6 sek.','Czar dotykowy. Zadaje +15...75 pkt. obrażeń od zimna i usuwa 1 zaklęcie. Wybrany wróg zostaje oszołomiony na 2...6 sek., jeśli nie znajdował się pod wpływem zaklęcia.'],
1546=>['Płomienna Włócznia','Atak włócznią. Jeżeli atak trafi, zadaje +5...25 pkt. obrażeń, a wybrany przeciwnik zostaje podpalony na 1...3 sek.','Atak włócznią. Zadaje +5...25 pkt. obrażeń. Wywołuje przypadłość płonięcie (1...3 sek.).'],
1547=>['Potężny Rzut','Atak włócznią. Twoja włócznia leci trzy razy szybciej. Jeśli trafi, zadajesz +10...40 pkt. obrażeń.','Atak włócznią. Zadaje +10...40 pkt. obrażeń. Ta włócznia leci trzy razy szybciej.'],
1548=>['Okrutna Włócznia','Elitarny atak włócznią. Jeśli atak trafi, zadaje +10...50 pkt. obrażeń. Jeśli trafi nieruchomego przeciwnika, na 5...20 sek. zadaje mu głęboką ranę.','Elitarny atak włócznią. Zadaje +10...50 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik nie porusza się.'],
1549=>['Rzut Grabieżcy','Atak włócznią. Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli trafi poruszającego się przeciwnika, zadaje 5...40 pkt. dodatkowych obrażeń.','Atak włócznią. Zadaje +5...20 pkt. obrażeń. Zadaje 5...40 pkt. dodatkowych obrażeń, jeżeli cel porusza się.'],
1550=>['Nieblokowalny Rzut','Atak włócznią. Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń. Tego ataku nie można zablokować.','Atak włócznią. Zadaje +10...40 pkt. obrażeń. Nie do zablokowania.'],
1551=>['Włócznia Błyskawicy','Atak włócznią. Atakuje wszystkich przeciwników znajdujących się między tobą a celem. Jeśli atak trafi, zadaje +10...20 pkt. obrażeń od piorunów. Atak ma 25% penetracji pancerza.','Atak włócznią. Zadaje +10...20 pkt. obrażeń od piorunów. 25% penetracji pancerza. Atakuje wszystkich wrogów między tobą a twoim celem.'],
1552=>['Włócznia Zmęczenia','Atak włócznią. Jeśli atak trafi, zadaje +10...40 pkt. obrażeń. Przez 5 sek. będziesz osłabiony.','Atak włócznią. Zadaje +10...40 pkt. obrażeń. Jesteś osłabiony (5 sek.).'],
1553=>['Hymn Furii','Elitarny zaśpiew. Przez 10 sek., kiedy następnym razem każdy członek drużyny w zasięgu słuchu użyje umiejętności związanej z atakami, otrzyma dawki adrenaliny w liczbie 2...5.','Elitarny zaśpiew. (10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoją następną umiejętnością otrzymują dawki adrenaliny w liczbie 2...5'],
1554=>['Okulawiający Hymn','Elitarny zaśpiew. Przez 10 sek. następna umiejętność związana z atakiem, użyta przez każdego sojusznika w zasięgu słuchu okulawi przeciwnika na 5...15 sek.','Elitarny zaśpiew. (10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem wywołują przypadłość okulawienie (5...15 sek.).'],
1555=>['Obronny Hymn','Elitarny zaśpiew. Przez 4...10 sek. każdy członek drużyny w zasięgu słuchu ma 50% szans na blokowanie ataków. Zaśpiew przestanie działać, kiedy członek drużyny trafi używając umiejętności związanej z atakami.','Elitarny zaśpiew. (4...10 sek.) Członkowie drużyny w zasięgu słuchu mają 50% szans na blokowanie. Przestanie działać, kiedy trafi umiejętność związana z atakiem.'],
1556=>['Boska Prędkość','Okrzyk. Przez 5...20 sek. wszyscy sojusznicy w zasięgu słuchu i pod działaniem zaklęcia poruszają się o 25% szybciej.','Okrzyk. (5...20 sek.) Sojusznicy w zasięgu słuchu poruszają się o 25% szybciej, kiedy są pod działaniem zaklęcia.'],
1557=>['Hymn Płomienia','Zaśpiew. Przez 10 sek. następna umiejętność związana z atakiem, użyta przez każdego członka drużyny w zasięgu słuchu podpali przeciwnika na 1...5 sek.','Zaśpiew. (10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem wywołują przypadłość płonięcie (1...5 sek.).'],
1558=>['"Po Oczach!"','Okrzyk. Przez 10 sek., następny atak wykonany przez każdego sojusznika w zasięgu słuchu ma dodatkowe 30...100% szans na trafienie krytyczne.','Okrzyk. (10 sek.) Sojusznicy w zasięgu słuchu mają +30...100% szans na wykonanie trafienia krytycznego w czasie swojego następnego ataku.'],
1559=>['Hymn Zazdrości','Zaśpiew. Przez 10 sek. następna umiejętność związana z atakiem, użyta przez każdego sojusznika w zasięgu słuchu zadaje +10...25 pkt. obrażeń przeciwnikom posiadającym więcej niż 50% pkt. żywotności.','Zaśpiew. (10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem zadają +10...25 pkt. obrażeń. Dodatkowe obrażenia zadawane są tylko przeciwnikom, którzy mają więcej niż 50% żywotności.'],
1560=>['Pieśń Potęgi','Zaśpiew. Przez 5...20 sek. każdy sojusznik w zasięgu słuchu, do czasu, gdy użyje umiejętności, posiada regenerację energii 4.','Zaśpiew. (5...20 sek.) Sojusznicy w zasięgu słuchu posiadają regenerację energii +4. Przestanie działać, kiedy zostanie użyta umiejętność.'],
1561=>['Hymn Gorliwości','Zaśpiew. Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem umiejętności związanej z atakami, otrzyma 1...8 pkt. energii.','Zaśpiew. (10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem otrzymują 1...8 pkt. energii.'],
1562=>['Aria Gorliwości','Zaśpiew. Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem czaru, otrzyma 1...6 pkt. energii.','Zaśpiew. (10 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym czarem otrzymują 1...6 pkt. energii.'],
1563=>['Liryk Gorliwości','Zaśpiew. Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem sygnetu, otrzyma 1...8 pkt. energii.','Zaśpiew. (10 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym sygnetem otrzymują 1...8 pkt. energii.'],
1564=>['Ballada Odnowy','Zaśpiew. Przez 10 sek., każdy sojusznik w zasięgu słuchu z następnym otrzymaniem obrażeń, dostanie 15...75 pkt. żywotności.','Zaśpiew. (10 sek.) Członkowie drużyny w zasięgu słuchu otrzymują 15...75 pkt. żywotności, kiedy następnym razem otrzymają obrażenia.'],
1565=>['Chorał Odnowy','Zaśpiew. Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem okrzyku lub zaśpiewu, otrzyma 30...90 pkt. żywotności.','Zaśpiew. (10 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym okrzykiem lub zaśpiewem otrzymują 30...90 pkt. żywotności.'],
1566=>['Aria Odnowy','Zaśpiew. Przez 10 sek. każdy członek drużyny w zasięgu słuchu z następnym rzuceniem czaru, otrzyma 30...90 pkt. żywotności.','Zaśpiew. (10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoim następnym czarem otrzymują 30...90 pkt. żywotności.'],
1567=>['Pieśń Koncentracji','Zaśpiew. Przez 10 sek. następna umiejętność używana przez każdego sojusznika w zasięgu słuchu nie może być przerwana.','Zaśpiew. (10 sek.) Następna umiejętność sojuszników w zasięgu słuchu nie może zostać przerwana.'],
1568=>['Hymn Naprowadzenia','Elitarny zaśpiew. Przez 10 sek. następna umiejętność związana z atakiem, używana przez każdego członka drużyny w zasięgu słuchu, nie może być zablokowana.','Elitarny zaśpiew. (10 sek.) Członkowie drużyny w zasięgu słuchu nie mogą zostać zablokowani ze swoją następną umiejętnością związaną z atakiem.'],
1569=>['Energetyzujący Chorał','Zaśpiew. Przez 10 sek. następny okrzyk lub zaśpiew każdego sojusznika w zasięgu słuchu kosztują o 3...7 pkt. energii mniej.','Zaśpiew. (10 sek.) Następny okrzyk lub zaśpiew sojuszników w zasięgu słuchu kosztuje o 3...7 pkt. energii mniej.'],
1570=>['Pieśń Oczyszczenia','Elitarny zaśpiew. Przez 20 sek. następne umiejętności w liczbie 1...6 używane przez każdego sojusznika w zasięgu słuchu usuwają z niego 1 przypadłość.','Elitarny zaśpiew. (20 sek.) Sojusznicy w zasięgu słuchu, ze swoimi następnymi umiejętnościami w liczbie 1...6 tracą jedną przypadłość.'],
1571=>['Aria Łamiąca Klątwy','Zaśpiew. Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym rzuceniem czaru, traci 1 klątwę.','Zaśpiew. (10 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym czarem tracą jedną klątwę.'],
1572=>['"Ustój!"','Okrzyk. Przez 5...15 sek., następnym razem, gdy wybrany sojusznik inny niż ty ma zostać powalony, Wszyscy przeciwnicy w pobliżu otrzymują w zamian 15...75 pkt. obrażeń.','Okrzyk. (5...15 sek.) Ochroni przed następnym powaleniem i zadaje 15...75 pkt. obrażeń wszystkim przeciwnikom w pobliżu wybranego sojusznika. Na cel nie można wybrać siebie.'],
1573=>['Bojaźń','Umiejętność. Jeśli ta umiejętność trafi powalonego wroga, wróg ten zostaje oszołomiony na 5...15 sek.','Umiejętność. Wywołuje przypadłość oszołomienie (5...15 sek.). Bez efektu, chyba że cel jest powalony.'],
1574=>['Trwała Harmonia','Echo. Przez 10...35 sek. zaśpiewy i okrzyki na wybranym sojuszniku nie-duchu trwają o 50% dłużej.','Echo. (10...35 sek.) Zaśpiewy i okrzyki na wybranym sojuszniku trwają o 50% dłużej. Na cel nie można wybrać ducha.'],
1575=>['Ognisty Finał','Echo. Przez 10...35 sek., za każdym razem, kiedy zaśpiew lub okrzyk przestaną działać na wybranym sojuszniku nie-duchu, wszyscy przeciwnicy bezpośrednio przy tym sojuszniku zaczną płonąć przez 1...7 sek.','Echo. (10...35 sek.) U przeciwników w bezpośredniej odległości wywołuje przypadłość płonięcie (1...7 sek.), za każdym razem, kiedy zaśpiew lub okrzyk przestanie działać na wybranym sojuszniku. Na cel nie można wybrać ducha.'],
1576=>['Płonący Zaśpiew','Echo. Przez 20 sek., jeśli wybrany sojusznik nie-duch trafi przeciwnika, który posiada więcej żywotności niż on, to przeciwnik ten zaczyna płonąć przez 1...3 sek. To echo jest ponownie nakładane za każdym razem, kiedy przestanie na tym sojuszniku działać zaśpiew lub okrzyk.','Echo. (20 sek.) Wywołuje przypadłość płonięcie (1...3 sek.), jeżeli wybrany sojusznik trafi przeciwnika z większą żywotnością. Odnowienie: za każdym razem, kiedy przestaje na tym sojuszniku działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1577=>['Finał Odnowy','Echo. Przez 10...35 sek., za każdym razem, kiedy okrzyk lub zaśpiew przestaną działać na wybranym sojuszniku nie-duchu, otrzymuje on 15...75 pkt. żywotności.','Echo. (10...35 sek.) Wybrany sojusznik otrzymuje 15...75 pkt. żywotności za każdym razem, kiedy przestaje na nim działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1578=>['Zaśpiew Ozdrowienia','Echo. Przez 15 sek. wybrany sojusznik nie-duch posiada regenerację żywotności +2...3. To echo jest ponownie nakładane za każdym razem, kiedy przestanie na tym sojuszniku działać zaśpiew lub okrzyk.','Echo. (15 sek.) Wybrany sojusznik posiada regenerację żywotności +2...3. Odnowienie: za każdym razem, kiedy przestaje na tym sojuszniku działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1579=>['Oczyszczający Finał','Echo. Przez 10...35 sek., za każdym razem, kiedy okrzyk lub zaśpiew przestaną działać na wybranym sojuszniku nie-duchu, traci on 1 przypadłość.','Echo. (10...35 sek.) Wybrany sojusznik traci jedną przypadłość, za każdym razem, kiedy przestaje na nim działać okrzyk lub zaśpiew. Na cel nie można wybrać ducha.'],
1580=>['Zaśpiew Odpędzenia Ostrzy','Echo. Przez 20 sek. wybrany sojusznik, który nie jest duchem, ma 5...20% szans na zablokowanie ataków. To echo jest ponownie nakładane za każdym razem, kiedy na danym sojuszniku przestanie działać zaśpiew lub okrzyk.','Echo. (20 sek.) Wybrany sojusznik ma 5...20% szans na zablokowanie ataków. Odnowienie: za każdym razem, kiedy na tym sojuszniku przestaje działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1581=>['Rozżarzony Sygnet','Sygnet. Jeżeli wybrany przeciwnik płonie, otrzymujesz 5...15 pkt. energii.','Sygnet. Otrzymujesz 5...15 pkt. energii, jeżeli wybrany przeciwnik płonie.'],
1583=>['Gorliwość Dowódcy','Umiejętność. Na każdego przeciwnika w pobliżu otrzymujesz 2...4 pkt. energii (maksymalnie 8...12 pkt. energii).','Umiejętność. Na każdego sojusznika w pobliżu otrzymujesz 2...4 pkt. energii (maksymalnie 8...12).'],
1584=>['Pocieszenie Dowódcy','Umiejętność. Otrzymujesz 30...75 pkt. żywotności. Na każdego sojusznika w zasięgu słuchu otrzymujesz także +10...20 pkt. żywotności (maksymalnie 140 pkt.).','Umiejętność. Otrzymujesz 30...75 pkt. żywotności. Na każdego sojusznika w zasięgu słuchu otrzymujesz także 10...20 pkt. żywotności (maksymalnie 140).'],
1585=>['Sygnet Synergii','Sygnet. Wybrany sojusznik inny niż ty otrzymuje 40...100 pkt. żywotności. Jeżeli nie jesteś pod działaniem zaklęcia, to także ty otrzymujesz 40...100 pkt. żywotności.','Sygnet. Wybranemu sojusznikowi dodajesz 40...100 pkt. żywotności. Ty także otrzymujesz 40...100 pkt. żywotności, jeżeli nie jesteś pod wpływem zaklęcia. Na cel nie można wybrać siebie.'],
1586=>['Anielska Ochrona','Umiejętność. Przez 10 sek., za każdym razem, kiedy wybrany sojusznik otrzymuje więcej niż 250...80 pkt. obrażeń na sekundę, uzdrawiany jest o liczbę punktów ponad tę wartość.','Umiejętność. (10 sek.) W każdej sekundzie, w której wybrany sojusznik otrzymuje obrażenia powyżej 250...80 pkt., otrzymuje jednocześnie punkty żywotności w liczbie równej obrażeniom powyżej tej liczby. Na cel nie można wybrać siebie.'],
1587=>['Anielska Więź','Umiejętność elitarna. Przez 10 sek., kiedy następnym razem sojusznik w zasięgu słuchu ma otrzymać śmiertelne obrażenia, to są one negowane i w zamian otrzyma on 20...200 pkt. żywotności. Anielska Więź przestaje działać na wszystkich pozostałych sojusznikach.','Umiejętność elitarna. (10 sek.) Kiedy następnym razem sojusznik w zasięgu słuchu ma otrzymać śmiertelne obrażenia, to są one negowane i w zamian otrzyma on 20...200 pkt. żywotności. Przestaje działać na wszystkich pozostałych sojusznikach.'],
1588=>['Sygnet Wypalenia','Sygnet elitarny. Wszyscy członkowie drużyny tracą wszystkie przypadłości. Zaczynasz płonąć przez 1 sekundę na każdą przypadłość usuniętą w ten sposób.','Sygnet elitarny. Wszyscy członkowie drużyny tracą wszystkie przypadłości. Krwawisz (1 sek. na każdą usuniętą przypadłość).'],
1589=>['"Utrzymać pozycje!"','Okrzyk. Przez 5...20 sek., wszyscy nieruchomi członkowie drużyny w zasięgu słuchu otrzymują +24 pkt. pancerza.','Okrzyk. (5...20 sek.) Członkowie drużyny w zasięgu słuchu otrzymują +24 pkt. pancerza, jeżeli się nie poruszają.'],
1590=>['"Prowadź!"','Okrzyk. Przez 1...5 sek. na każdego sojusznika w zasięgu słuchu, wybrany sojusznik porusza się o 25% szybciej (maksymalnie 30 sek.).','Okrzyk. Wybrany sojusznik porusza się o 25% szybciej przez 1...5 sek. (maksymalnie 30 sek.) na każdego sojusznika w zasięgu słuchu.'],
1591=>['"Pospieszcie się!"','Okrzyk. Przez 5...20 sek. wybrany sojusznik inny niż ty porusza się o 33% szybciej. Umiejętność przestanie działać z kolejnym trafionym atakiem tego sojusznika.','Okrzyk. (5...20 sek.) Wybrany sojusznik porusza się o 33% szybciej. Przestanie działać, jeśli wybrany sojusznik trafi. Na cel nie można wybrać siebie.'],
1592=>['"Jeszcze Tu Wrócimy!"','Okrzyk. Wszyscy członkowie drużyny w zasięgu słuchu zostają wskrzeszeni i posiadają 25...50% żywotności oraz 5...20% energii.','Okrzyk. Wszyscy członkowie drużyny w zasięgu słuchu zostają wskrzeszeni (25...50% żywotności oraz 5...20% energii).'],
1593=>['"Trzymać Się!"','Okrzyk. Wszyscy sojusznicy w zasięgu słuchu i posiadający mniej niż 75% pkt. żywotności otrzymują 1...10 pkt. energii.','Okrzyk. Sojusznicy w zasięgu słuchu otrzymują 1...10 pkt. energii. Działa tylko na sojuszników posiadających mniej niż 75% żywotności.'],
1594=>['"Pomocy!"','Okrzyk. Wskazany sojusznik niebędący duchem zyskuje 15...90 pkt. zdrowia. Przez 1...10 sek. zaklęcia innych sojuszników, których celem jest ten sojusznik, są rzucane o 50% szybciej.','Okrzyk. (1...10 sek.) Wskazany sojusznik niebędący duchem zyskuje 15...90 pkt. zdrowia, zaklęcia sojuszników rzucane na niego są rzucane o 50% szybciej.'],
1595=>['"Wycofać Się!"','Okrzyk. Przez 4...10 sek. wszyscy poruszający się sojusznicy w zasięgu słuchu otrzymują 5...15 pkt. żywotności na sek., a ich szybkość zwiększa się o 33%. "Wycofać Się!" przestanie działać na sojuszniku z jego kolejnym trafionym atakiem.','Okrzyk. (4...10 sek.) Wszyscy poruszający się sojusznicy w zasięgu słuchu otrzymują 5...15 pkt. żywotności na sek., a ich szybkość ruchu zwiększa się o 33%. Przestanie działać na sojusznika, jeśli jego atak trafi.'],
1596=>['"Nadchodzą!"','Elitarny okrzyk. Przez 4...10 sek., wszyscy sojusznicy w zasięgu słuchu poruszają się o 33% szybciej i zyskują 5...15 pkt. żywotności na sekundę podczas ruchu.','Elitarny okrzyk. (4...10 sek.) Wszyscy sojusznicy w zasięgu słuchu poruszają się o 33% szybciej i zyskują 5...15 pkt. żywotności na sekundę podczas ruchu.'],
1597=>['"Płoną!"','Okrzyk. Przez 10 sek., sojusznicy w zasięgu słuchu otrzymują o 5...35% mniej obrażeń od płonących przeciwników.','Okrzyk. (10 sek.) Członkowie drużyny w zasięgu słuchu otrzymują od płonących przeciwników o 5...35% obrażeń mniej.'],
1598=>['"Nie Poddawajcie Się!','Okrzyk. Przez 15 sek., wszyscy członkowie drużyny w zasięgu słuchu i mający mniej niż 75% pkt. żywotności, posiadają regenerację żywotności +1...5.','Okrzyk. (15 sek.) Członkowie drużyny w zasięgu słuchu posiadają regenerację żywotności +1...5. Działa tylko na członków drużyny posiadających mniej niż 75% żywotności.'],
1599=>['To Tylko Draśnięcie!','Elitarny okrzyk. Wybrany sojusznik inny niż ty traci wszystkie przypadłości. Jeżeli przypadłość została zdjęta w ten sposób, to przez 1...10 sek. sojusznik porusza się o 25% szybciej.','Elitarny okrzyk. Z wybranego sojusznika usuwa wszystkie klątwy. Jeżeli przypadłość została usunięta, to ten sojusznik porusza się o 25% szybciej (1...10 sek.). Na cel nie można wybrać siebie.'],
1600=>['Kolczasta Włócznia','Atak włócznią. Jeśli atak trafi, twój cel zaczyna krwawić na 5...20 sek.','Atak włócznią. Wywołuje przypadłość krwawienie (5...20 sek.).'],
1601=>['Zajadły Atak','Atak włócznią. Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli spowoduje trafienie krytyczne, na 5...15 sek. zadaje celowi głęboką ranę.','Atak włócznią. Zadaje +5...20 pkt. obrażeń. Z trafieniem krytycznym wywołuje przypadłość głęboka rana (5...15 sek.).'],
1602=>['Ogłuszające Uderzenie','Elitarny atak włócznią. Jeśli atak trafi, zadaje +10...50 pkt. obrażeń. Jeśli cel cierpi na przypadłość, zostaje dodatkowo oszołomiony na 4...10 sek.','Elitarny atak włócznią. Zadaje +10...50 pkt. obrażeń. Wywołuje przypadłość oszołomienie (4...10 sek.), jeżeli cel jest pod działaniem przypadłości.'],
1603=>['Bezlitosna Włócznia','Atak włócznią. Jeżeli atak trafi przeciwnika, który ma mniej niż 50% pkt. żywotności, to przeciwnik ten na 5...20 sek. otrzymuje głęboką ranę.','Atak włócznią. Wywołuje przypadłość głęboka rana (5...20 sek.). Bez efektu, chyba że cel ma mniej niż 50% żywotności.'],
1604=>['Rozpraszający Rzut','Atak włócznią. Jeżeli atak trafi przeciwnika cierpiącego na przypadłość, to czynność tego przeciwnika zostanie przerywana.','Atak włócznią. Przerywa czynności. Bez efektu, chyba że cel jest pod działaniem przypadłości.'],
1605=>['Dziki Rzut','Atak włócznią. Jeśli ten atak trafi, zadaje +5...20 pkt. obrażeń i przerywa postawę używaną przez wroga. Tego ataku nie można zablokować. Umiejętności nie dotyczące ataków włócznią są zablokowane na 3 sek.','Atak włócznią. Zadaje +5...20 pkt. obrażeń. Nieblokowalny. Przerywa postawę celu.Wyłącza umiejętności nie dotyczące ataków włócznią na 3 sek.'],
1633=>['Podłe Uderzenie','Atak wręcz. Jeśli atak trafi przeciwnika cierpiącego na przypadłość, zadajesz +10...30 pkt. obrażeń oraz wykonujesz trafienie krytyczne.','Atak wręcz. Jeżeli wybrany przeciwnik jest pod działaniem przypadłości, atak zadaje +10...30 pkt. obrażeń i jest trafieniem krytycznym.'],
1634=>['Wstrząsające Natarcie','Elitarny atak podwójny. Musi nastąpić po ataku drugą ręką. Jeśli trafi, zadajesz 5...50 pkt. obrażeń, a przeciwnik traci jedno zaklęcie. Atak nie może zostać zablokowany.','Elitarny atak podwójny. Zadaje 5...50 pkt. obrażeń. Usuwa jedno zaklęcie. Nie do zablokowania. Musi nastąpić po ataku drugą ręką.'],
1635=>['Uderzenie Złotej Czaszki','Elitarny atak drugą ręką. Jeśli jesteś pod działaniem zaklęcia i ten atak trafi, wybrany przeciwnik zostaje oszołomiony na 1...12 sek.','Elitarny atak drugą ręką. Wywołuje przypadłość oszołomienie (1...12 sek.). Bez efektu, jeśli nie jesteś pod działaniem zaklęcia.'],
1636=>['Uderzenie Czarnego Pająka','Atak drugą ręką. Musi trafić przeciwnika pod działaniem klątwy. Jeżeli atak trafi, zadaje +5...20 pkt. obrażeń, a wybrany przeciwnik zostaje zatruty na 5...20 sek.','Atak drugą ręką. Zadaje +5...20 pkt. obrażeń. Wywołuje przypadłość zatrucie (5...20 sek.). Musi trafić przeciwnika pod działaniem klątwy.'],
1637=>['Uderzenie Złotego Lisa','Atak poprzedzający. Jeżeli atak trafi, wybrany przeciwnik otrzymuje +10...30 pkt. obrażeń. Jeśli jesteś pod działaniem zaklęcia, to atak nie może zostać zablokowany.','Atak poprzedzający. Zadaje +10...30 pkt. obrażeń. Nie do zablokowania, jeżeli jesteś pod działaniem zaklęcia.'],
1638=>['Śmiercionośny Pośpiech','Zaklęcie (czar). Przez 10...35 sek., czary o połowie zasięgu rzucane są w czasie o 5...50% krótszym i odnawiają się o 5...60% szybciej.','Zaklęcie (czar). (10...35 sek.) Twoje czary o połowie zasięgu rzucane są w czasie o 5...50% krótszym i odnawiają się o 5...60% szybciej.'],
1639=>['Remedium Zabójcy','Zaklęcie (czar). Przez 30 sek. kolejne użyte przez ciebie umiejętności związane z atakiem (w liczbie 1...10) usuwają po jednej przypadłości.','Zaklęcie (czar). (30 sek.) Twoje następne umiejętności związane z atakami w liczbie 1...10 usuwają po jednej przypadłości.'],
1640=>['Obietnica Lisa','Elitarne zaklęcie (czar). Przez 5...20 sek. twoich ataków nie można zablokować. Zaklęcie przestanie działać, jeśli nie trafisz przeciwnika.','Elitarne zaklęcie (czar). (5...20 sek.) Twoich ataków nie można blokować. Przestanie działać, kiedy nie trafisz.'],
1641=>['Udawana Neutralność','Zaklęcie (czar). Na 4...10 sek. otrzymujesz regenerację żywotności +7 i +80 pkt. pancerza. To zaklęcie przestanie działać z twoim kolejnym trafionym atakiem lub użytą umiejętnością.','Zaklęcie (czar). (4...10 sek.) Posiadasz regenerację żywotności +7 i +80 pkt. pancerza. Przestanie działać, jeśli twój atak trafi lub użyjesz umiejętności.'],
1642=>['Ukryta Kolczatka','Elitarna klątwa (czar). Twoje umiejętności spoza profesji zabójcy są wyłączone na 3 sekundy. Przez 1...10 sek. cel porusza się 50% wolniej. Gdy klątwa dobiega końca, cel zostaje okulawiony na 1...15 sek.','Elitarna klątwa (czar). (1...10 s). Zmniejsza szybkość ruchu o 50%. Efekt kończący: nakłada przypadłość Okaleczenie (1...15 s). Twoje umiejętności spoza profesji zab&oacute;jcy są wyłączone (10 sekund).'],
1643=>['Atak na Zaklęcia','Umiejętność elitarna. Musi nastąpić po ataku podwójnym. Wybrany przeciwnik traci wszystkie zaklęcia.','Umiejętność elitarna. Usuwa wszystkie zaklęcia. Musi nastąpić po ataku podwójnym.'],
1644=>['Powalenie Marnotrawcy','Umiejętność elitarna. Wykonujesz krok cienia do wybranego przeciwnika. Jeżeli wybrany przeciwnik nie używa umiejętności, to zostaje powalony. Wszystkie twoje ataki nie związane ze sztyletami zostają wyłączone na 10 sek.','Umiejętność elitarna. Wykonujesz krok cienia do wybranego przeciwnika. Jeżeli wybrany przeciwnik nie używa umiejętności, to zostaje powalony. Wyłącza twoje ataki nie związane ze sztyletami (10 sek.).'],
1645=>['Kradzież Zaklęcia','Umiejętność. Jeżeli dotknięty wybrany przeciwnik jest powalony, to traci jedno zaklęcie.','Umiejętność dotykowa. Usuwa jedno zaklęcie. Bez efektu, chyba że wybrany przeciwnik jest powalony.'],
1646=>['Wróżba Śmierci','Klątwa (czar). Przez 5...35 sek., następnym razem, kiedy obrażenia zmniejszą żywotność wybranego przeciwnika poniżej 50%, zadasz mu głęboką ranę na 5...20 sek. i wykonasz do niego krok cienia. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Klątwa o połowie zasięgu - czar. (5...35 sek.) Wywołuje przypadłość głęboka rana (5...20 sek.), a następnym razem, kiedy obrażenia zmniejszą żywotność przeciwnika poniżej 50%, wykonujesz krok cienia do tego przeciwnika.'],
1647=>['Sygnet Toksycznego Szoku','Sygnet. Jeżeli wybrany przeciwnik jest zatruty, to otrzymuje 10...100 pkt. obrażeń.','Sygnet. Zadaje 10...100 pkt. obrażeń. Bez efektu, jeśli wybrany przeciwnik nie jest zatruty.'],
1648=>['Sygnet Zmroku','Sygnet. Wybrany przeciwnik traci jedno zaklęcie na każdą klątwę, pod której jest działaniem.','Sygnet. Usuwa jedno zaklęcie na każdą klątwę działającą na wybranego przeciwnika.'],
1649=>['Ścieżka Zabójcy','Postawa elitarna. Przez następne 20 sek., kiedy dzierżysz sztylety, atakujesz o 5...20% szybciej i posiadasz +5...35% szans na wykonanie trafienia krytycznego.','Postawa elitarna. (20 sek.) Kiedy dzierżysz sztylety, atakujesz o 5...20% szybciej i posiadasz +5...35% szans na wykonanie trafienia krytycznego.'],
1650=>['Spacer w Cieniu','Postawa. Krok przez cienie do wybranego wroga. Przez 15 sek. nic się nie dzieje. Twoje umiejętności ataku zostają zablokowane na 1 sekundę, a postawy i zaklęcia na 10 sek. Kiedy działanie tej postawy zakończy się, wrócisz na początkową pozycję.','Postawa. (15 sek.) Krok przez cienie do wybranego wroga. Efekt końcowy: powrót na początkową pozycję. Wyłącza twoje umiejętności ataku na 1 sekundę. Wyłącza zaklęcia i postawy na 10 sek.'],
1651=>['Ucieczka Śmierci','Czar. Wykonaj krok cienia do wybranego sojusznika. Jeżeli masz mniej pkt. żywotności niż on, to otrzymujesz 40...130 pkt. żywotności.','Czar. Otrzymujesz 40...130 pkt. żywotności, jeżeli posiadasz mniej żywotności niż wybrany sojusznik. Efekt początkowy: wykonujesz krok cienia do tego sojusznika. Na cel nie można wybrać siebie.'],
1652=>['Więzienie Cienia','Elitarna klątwa (czar). Wykonujesz krok cienia do wybranego przeciwnika. Przez 1...7 sek., wybrany przeciwnik porusza się o 66% wolniej.','Elitarna klątwa (czar). Wykonujesz krok cienia do wybranego przeciwnika. Ten przeciwnik porusza się o 66% wolniej (1...7 sek.).'],
1653=>['Zamiana','Czar. Wybrane, przyzwane stworzenie i ty zamieniacie się miejscami, wykonując krok cienia.','Czar. Wybrane, przyzwane stworzenie i ty zamieniacie się miejscami, wykonując krok cienia.'],
1654=>['Cieniste Połączenie','Elitarne zaklęcie (czar). Wykonujesz krok cienia do wybranego sojusznika innego niż ty. Gdy przestaniesz utrzymywać to zaklęcie, wracasz do miejsca, gdzie zostało rzucone.','Elitarne zaklęcie (czar). Wykonujesz krok cienia do wybranego sojusznika. Efekt końcowy: wracasz do swojego początkowego miejsca. Na cel nie można wybrać siebie.'],
1655=>['Cena Dumy','Klątwa (czar). Przez 5 sek., kiedy wybrany przeciwnik użyje następnym razem umiejętności elitarnej, straci 3...15 pkt. energii.','Klątwa (czar). (5 sek.) Powoduje utratę 3...15 pkt. energii, następnym razem, kiedy wybrany przeciwnik użyje umiejętności elitarnej.'],
1656=>['Powietrze Antyzaklęć','Elitarna klątwa (czar). Z wybranego przeciwnika i wszystkich przeciwników w pobliżu zdejmujesz po jednym zaklęciu. Przez 5...20 sek. zaklęcia rzucane na tych przeciwników kończą się o 150...300% szybciej.','Elitarna klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (5...20 sek.). Z wybranego przeciwnika i przeciwników w pobliżu usuwa po jednym zaklęciu. Zaklęcia na tych przeciwnikach kończą się o 150...300% szybciej.'],
1657=>['Sygnet Niezgrabności','Sygnet. Jeśli wybrany przeciwnik atakuje, zarówno on, jak i wrogowie w jego sąsiedztwie przerywają wykonywanie akcji i otrzymują 15...60 pkt. obrażeń. Wszyscy przeciwnicy korzystający z umiejętności ataku zostają powaleni.','Sygnet. Przerywa atak wybranego przeciwnika i sąsiadujących z nim wrogów. Efekt przerwania: zadaje 15...60 pkt. obrażeń. Powala wrogów używających umiejętności ataku.'],
1658=>['Symboliczna Poza','Postawa. Przez 5...20 sek. następny sygnet, który aktywujesz będzie się odnawiał o 20...80% szybciej.','Postawa. (5...20 sek.) Twój następny sygnet odnawia się o 20...80% szybciej.'],
1659=>['Toksyczny Chłód','Elitarny czar. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń od zimna. Jeżeli wybrany przeciwnik jest pod wpływem klątwy lub zaklęcia, to zostaje zatruty na 10...25 sek.','Elitarny czar. Zadaje 15...75 pkt. obrażeń od zimna. Wywołuje przypadłość zatrucie (10...25 sek.), jeżeli wybrany przeciwnik jest pod działaniem klątwy lub przypadłości.'],
1660=>['Studnia Milczenia','Czar studni. Wykorzystaj wybrane zwłoki lub poświęć 66% swojej żywotności, by na 10...30 sek. utworzyć Studnię Milczenia. Przeciwnicy w zasięgu działania studni nie mogą używać okrzyków ani pieśni i otrzymują -1...4 degeneracji żywotności.','Czar studni. (10...30 sek.). Przeciwnicy w tej studni nie mogą korzystać z okrzyków i pieśni oraz mają degenerację żywotności -1...4. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
1661=>['Błyszczący Kamień','Czar. Wystrzeliwujesz pocisk, który po trafieniu zadaje 5...50 pkt. obrażeń od ziemi. Jeżeli czar trafi osłabionego przeciwnika, otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii.','Czar. Pocisk: zadaje 5...50 pkt. obrażeń od ziemi. Otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii, jeżeli wybrany przeciwnik jest osłabiony.'],
1662=>['Wybuch Umysłu','Elitarny czar. Wybrany przeciwnik otrzymuje 15...60 pkt. obrażeń od ognia. Jeżeli masz więcej energii niż wybrany przeciwnik, zyskujesz 1...8 pkt. energii.','Elitarny czar. Zadaje 15...60 pkt. obrażeń od ognia. Otrzymujesz 1...8 pkt. energii, jeżeli masz więcej energii niż wybrany przeciwnik.'],
1663=>['Żywiołowy Płomień','Zaklęcie (czar). Przez 10...35 sek., za każdym razem, kiedy nałożysz klątwę żywiołu na wybranego przeciwnika, zacznie on płonąć przez 1...5 sek.','Zaklęcie (czar). (10...35 sek.) Powoduje podpalenie (przez 1...5 sek.) za każdym razem, kiedy rzucisz klątwę żywiołu na cel.'],
1664=>['Wywołanie Błyskawicy','Elitarny czar. Wybrany przeciwnik i maksymalnie dwóch innych przeciwników w jego pobliżu otrzymują po 10...90 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicie pancerza. Jeżeli nie jesteś pod działaniem zaklęcia, ten czar powoduje wyczerpanie.','Elitarny czar. Zadaje 10...90 pkt. obrażeń od błyskawic. Trafia dwóch przeciwników w pobliżu celu. 25% przebicie pancerza. Powoduje wyczerpanie, jeśli nie masz na sobie zaklęcia.'],
1683=>['Zadumany Strażnik','Zaklęcie (czar). Przez 5...11 sek. wybrany sojusznik ma 50% szans na blokowanie ataków przeciwników będących pod działaniem zaklęć.','Zaklęcie (czar). (5...11 sek.) 50% szans na blokowanie przeciwników znajdujących się pod działaniem zaklęcia.'],
1684=>['Intuicja Skryby','Elitarne zaklęcie (czar). Przez 10...35 sek., za każdym razem, kiedy użyjesz sygnetu, otrzymasz 3 pkt. energii.','Elitarne zaklęcie (czar). (10...35 sek.) Otrzymujesz 3 pkt. energii, za każdym razem, kiedy użyjesz sygnetu.'],
1685=>['Święty Pośpiech','Zaklęcie (czar). Przez 1...60 sek. czary oparte na Modlitwach Uzdrawiających rzucasz o 50% szybciej. To zaklęcie przestanie działać, kiedy rzucisz inne zaklęcie.','Zaklęcie (czar). (1...60 sek.) Czary z Modlitw Uzdrawiających rzucasz o 50% szybciej. Przestanie działać, jeśli rzucisz zaklęcie.'],
1686=>['Przebłysk Światła','Elitarny czar. Uzdrawiasz wybranego sojusznika dodając mu 10...115 pkt. żywotności.','Elitarny czar. Dodaje 10...115 pkt. żywotności.'],
1687=>['Błogosławieństwo Gorliwości','Elitarny czar. Uzdrawiasz wybranego sojusznika dodając mu 30...180 pkt. żywotności. Jeżeli miał on mniej niż 50% punktów żywotności, otrzymujesz 7 pkt. energii.','Elitarny czar. Dodaje 30...180 pkt. żywotności. Otrzymujesz 7 pkt. energii, jeśli żywotność wybranego sojusznika była poniżej 50%.'],
1688=>['Zapał Obrońcy','Elitarna klątwa (czar). Przez 10...30 sek., za każdym razem, kiedy wybrany przeciwnik trafi wykonując atak, otrzymujesz 2 pkt. energii.','Elitarna klątwa (czar). (10...30 sek.) Otrzymujesz 2 pkt. energii, za każdym razem, kiedy wybrany przeciwnik trafi wykonując atak.'],
1689=>['Sygnet Mistycznego Gniewu','Sygnet. Za każde zaklęcie, które masz na sobie, wybrany przeciwnik otrzymuje 25 pkt. świętych obrażeń (maksymalnie 30...120 pkt. świętych obrażeń).','Sygnet. Zadaje 25 pkt. świętych obrażeń za każde zaklęcie, które masz na sobie (maksymalnie 30...120 pkt. świętych obrażeń).'],
1690=>['Sygnet Usunięcia','Sygnet elitarny. Jeżeli wybrany sojusznik jest pod działaniem zaklęcia, to traci jedną klątwę i jedną przypadłość.','Sygnet elitarny. Usuwa jedną przypadłość i jedną klątwę. Bez efektu, chyba że wybrany sojusznik jest pod wpływem zaklęcia.'],
1691=>['Przegnanie Przypadłości','Czar. Z wybranego sojusznika usuwasz jedną przypadłość. Jeżeli wybrany sojusznik jest pod działaniem zaklęcia, to otrzymuje 15...75 pkt. żywotności.','Czar. Usuwa przypadłość. Dodaje 15...75 pkt. żywotności, jeżeli wybrany sojusznik jest pod wpływem zaklęcia.'],
1692=>['Przeobrażanie Klątw','Elitarny czar. Z wybranego sojusznika usuwasz do 1...3 klątw. Za każdą klątwę usuniętą w ten sposób, sojusznik traci jedną przypadłość i otrzymuje 15...75 pkt. żywotności.','Elitarny czar. Usuwa klątwy w liczbie 1...3. Za każdą usuniętą klątwę, wybrany sojusznik traci jedną przypadłość i otrzymuje 15...75 pkt. żywotności.'],
1693=>['Kontratak','Atak wręcz. Jeśli atak trafi, zadajesz +5...35 pkt. obrażeń. Jeśli trafisz atakującego przeciwnika, otrzymujesz 2...6 pkt. energii.','Atak wręcz. Zadaje +5...35 pkt. obrażeń. Otrzymujesz 2...6 pkt. energii, jeżeli wybrany przeciwnik atakuje.'],
1694=>['Cios Łowcy Magów','Elitarny atak wręcz. Jeśli atak trafi, zadajesz +7...25 pkt. obrażeń. Jeśli twój cel jest pod działaniem zaklęcia, to atak ten nie może zostać zablokowany.','Elitarny atak wręcz. Zadaje +7...25 pkt. obrażeń. Nie do zablokowania, jeżeli wybrany przeciwnik ma na sobie zaklęcie.'],
1695=>['Żołnierskie Uderzenie','Atak wręcz. Jeśli atak trafi, zadajesz +10...40 pkt. dodatkowych obrażeń. Jeśli jesteś pod działaniem zaśpiewu lub okrzyku, to atak nie może zostać zablokowany.','Atak wręcz. Zadaje +10...40 pkt. obrażeń. Nie do zablokowania, jeżeli jesteś pod działaniem zaśpiewu lub okrzyku.'],
1696=>['Ścięcie Głowy','Elitarny atak toporem. You lose all adrenaline and all Energy. This attack is unblockable, you deal +5...80 damage, and cause a Deep Wound for 5...20 seconds. This attack is always critical and if foe is killed, nearby foes are Weakened for 8 seconds.','Elitarny atak toporem. Deals +5...80 damage. Inflicts Deep Wound condition (5...20 seconds). Automatic critical hit. If foe is killed, nearby foes are Weakened (8 seconds). You lose all adrenaline and Energy.'],
1697=>['Uderzenie Łowcy Magów','Elitarny atak młotem. Jeśli atak trafi, wybrany przeciwnik zostaje powalony. Jeśli twój cel jest pod działaniem zaklęcia, to atak ten nie może zostać zablokowany.','Elitarny atak młotem. Powoduje powalenie. Nie do zablokowania, jeżeli wybrany przeciwnik jest pod wpływem zaklęcia.'],
1698=>['Postawa Żołnierza','Postawa elitarna. Przez 5...15 sek., masz 75% szans na blokowanie ataków. Atakujesz 33% szybciej, jeśli jesteś pod działaniem okrzyku lub pieśni.','Postawa elitarna. (5...15 sek.) Masz 75% szans na blokowanie ataków. Atakujesz 33% szybciej, jeśli jesteś pod działaniem okrzyku lub pieśni.'],
1699=>['Żołnierska Obrona','Postawa. Przez 1...6 sek., kiedy będziesz pod działaniem okrzyku lub pieśni, masz 75% szans na blokowanie ataków. Otrzymujesz 1 dawkę adrenaliny za każdy zablokowany atak.','Postawa. (1...6 sek.) Masz 75% szans na blokowanie, jeżeli jesteś pod działaniem pieśni lub okrzyku. Efekt bloku: otrzymujesz 1 dawkę adrenaliny.'],
1700=>['Szalona Obrona','Postawa. Przez 8 sek., masz 75% szans na blokowanie ataków, ale otrzymujesz podwójne obrażenia.','Postawa. (8 sek.) Masz 75% szans na blokowanie. Otrzymujesz podwójne obrażenia.'],
1701=>['Stabilna Postawa','Postawa elitarna. Przez 10 sek., kiedy następnym razem będziesz miał zostać powalony, otrzymasz w zamian 1...7 pkt. energii i dawki adrenaliny w liczbie 1...4.','Postawa elitarna. (10 sek.) Kiedy następnym razem będziesz miał zostać powalony, otrzymasz w zamian 1...7 pkt. energii i dawki adrenaliny w liczbie 1...4.'],
1702=>['Cięcie Stalowego Kła','Atak mieczem. Jeśli atak trafi, zadaje +1...31 pkt. obrażeń. Jeśli trafisz powalonego przeciwnika, otrzymujesz dawki adrenaliny w liczbie: 1...5.','Atak mieczem. Zadaje +1...31 pkt. obrażeń. Otrzymujesz dawki adrenaliny w liczbie 1...5, jeżeli wybrany przeciwnik jest powalony.'],
1719=>['Wrzeszczący Strzał','Strzał z łuku. Jeśli atak trafi, zadaje +10...25 pkt. obrażeń. Jeżeli twój cel jest w zasięgu słuchu, będzie krwawił przez 5...20 sek.','Strzał z łuku. Zadaje +10...25 pkt. obrażeń. Wywołuje przypadłość krwawienie (5...20 sek.), jeżeli wybrany przeciwnik jest w zasięgu słuchu.'],
1720=>['Ostra Strzała','Strzał z łuku. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli jest to trafienie krytyczne, zdajesz dodatkowe +5...25 pkt. obrażeń.','Strzał z łuku. Zadaje +5...20 pkt. obrażeń. Zadaje +5...25 pkt. dodatkowych obrażeń, jeżeli wykonasz trafienie krytyczne.'],
1721=>['Jedność w Szale','Umiejętność elitarna. Przez 3...15 sek., ty i twój zwierzęcy towarzysz atakujecie o 33% szybciej i poruszacie się o 25% szybciej.','Umiejętność elitarna. (3...15 sek.) Ty i twój zwierzęcy towarzysz atakujecie o 33% szybciej i poruszacie się o 25% szybciej. Bez efektu, chyba że twój zwierzęcy towarzysz żyje.'],
1722=>['Rozwidlona Strzała','Strzał z łuku. Jednocześnie wystrzeliwujesz w przeciwnika dwie strzały. Jeżeli masz na sobie zaklęcie lub klątwę, to wystrzeliwujesz tylko jedna strzałę.','Strzał z łuku. Wystrzeliwujesz jednocześnie dwie strzały. Wystrzeliwuje tylko jedną strzałę, jeśli jesteś pod działaniem klątwy lub zaklęcia.'],
1723=>['Rozpraszająca Celność','Przygotowanie. Przez 36 sek., za każdym razem, kiedy zadajesz trafienie krytyczne, czynność twojego celu zostaje przerwana.','Przygotowanie. (36 sek.) Przerywa czynność, za każdym razem, kiedy twoje strzały powodują trafienie krytyczne.'],
1724=>['Mistrzowska Sprawność','Postawa elitarna. Przez 1...20 sek. atakujesz o 33% szybciej, a twoje Umiejętności Strzeleckie zwiększają się o 2.','Postawa elitarna. (1...20 sek.) Atakujesz o 33% szybciej i posiadasz +2 do Umiejętności Strzeleckich.'],
1725=>['Ryczące Wiatry','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Pieśni i okrzyki kosztują o 1...5 pkt. energii więcej. Ten duch ginie po 30...180 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Zaśpiewy i okrzyki stworzeń w zasięgu kosztują o 1...5 pkt. energii więcej.'],
1726=>['Strzał Zguby Magów','Elitarny strzał z łuku. Jeżeli atak trafi, przerywasz czynność wybranego przeciwnika. Jeżeli tą czynnością było rzucanie czaru, zostaje on wyłączony na dodatkowe 10 sek. Tego ataku nie można zablokować.','Elitarny strzał z łuku. Przerywa czynność. Efekt przerwania: przerwany czar jest niedostępny przez +10 sek. Nie do zablokowania.'],
1727=>['Naturalny Krok','Postawa. Przez 1...8 sek. biegasz o 33% szybciej i masz 50% szans na blokowanie ataków. Naturalny Krok przestanie działać, jeśli znajdziesz się pod działaniem klątwy lub zaklęcia.','Postawa. (1...8 sek.) Poruszasz się o 33% szybciej i masz 50% szans na blokowanie. Przestanie działać, jeśli otrzymasz klątwę lub zaklęcie.'],
1728=>['Szał Heketa','Postawa. Przez 5...11 sek. atakujesz o 33% szybciej. Postawa przestanie działać, kiedy użyjesz umiejętności związanej z atakami.','Postawa. (5...11 sek.) Atakujesz o 33% szybciej. Przestanie działać, jeśli użyjesz umiejętności związanej z atakami.'],
1729=>['Pułapka Dymna','Pułapka elitarna. Kiedy Pułapka Dymna zostanie uaktywniona, przeciwnicy w okolicy zostają oślepieni i oszołomieni na 5...10 sek. Pułapka Dymna przestaje działać po 90 sekundach. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','Pułapka elitarna. (90 sek.). Wywołuje przypadłość oślepienie i oszołomienie (na 5...10 sek.) u wrogów na obszarze działania. Łatwo przerwać.'],
1730=>['Rozwścieczający Żar','Elitarny obrządek natury. Tworzysz 1...10 poziomowego ducha. Stworzenia nie-duchy w jego zasięgu otrzymują podwójne dawki adrenaliny. Duch ginie po 30...120 sek.','Elitarny obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 30...120 sek.). Podwaja adrenalinę otrzymywaną przez stworzenia w zasięgu.'],
1731=>['Hałaśliwym Był Sogolon','Czar z przedmiotu. Przez 60 sek. wszystkie okrzyki i pieśni, których używasz trwają o 20...50% dłużej.','Czar z przedmiotu. (60 sek.) Okrzyki i zaśpiewy, których używasz trwają o 20...50% dłużej.'],
1732=>['Niszczycielską Była Glewia','Elitarny czar z przedmiotu. Trzymaj prochy Glewii przez maksymalnie 30...60 sek. Kiedy je trzymasz, wszystkie umiejętności Rytualisty otrzymują 20% do penetracji pancerza. Gdy upuścisz jej prochy, wszyscy przeciwnicy w okolicy otrzymają 15...85 pkt. obrażeń od błyskawic.','Elitarny czar z przedmiotu. (30...60 sek.) Twoje umiejętności Rytualisty otrzymują 20% do penetracji pancerza. Efekt upuszczenia: wszyscy przeciwnicy w okolicy otrzymują po 15...85 pkt. obrażeń od błyskawic.'],
1733=>['Uderzenie Posiadacza','Czar. Wybrany przeciwnik otrzymuje 10...60 pkt. obrażeń od błyskawic. Jeśli posiadasz zaczarowaną broń, zadajesz dodatkowe 10...50 pkt. obrażeń od błyskawic.','Czar. Zadaje 10...60 pkt. obrażeń od błyskawic. Zadaje 10...50 pkt. dodatkowych obrażeń od błyskawic, jeżeli jesteś pod działaniem zaczarowanej broni.'],
1734=>['Spojrzenie Furii','Rytuał spętania. Niszczysz wybranego ducha i tworzysz 1...14 poziomowego Ducha Furii. Ataki tego ducha zadają 5...20 pkt. obrażeń. Duch ginie po 30...60 sek.','Rytuał spętania. Niszczy ducha. Tworzy ducha na poziomie 1...14 (czas życia 30...60 sek.). Jego ataki zadają 5...20 pkt. obrażeń.'],
1736=>['Duchowa Siła','Elitarne zaklęcie (czar). Przez 15...60 sek., kiedy posiadasz zaczarowaną broń twoje ataki zadają 5...35 pkt. dodatkowych obrażeń.','Elitarne zaklęcie (czar). (15...60 sek.) Twoje ataki zadają +5...35 pkt. obrażeń, jeżeli jesteś pod działaniem zaczarowanej broni.'],
1737=>['Gorliwość Posiadacza','Elitarne zaklęcie (czar). Przez 10...40 sek., za każdym razem, kiedy rzucasz czar na broń sojusznika, otrzymujesz 1...5 pkt. energii.','Elitarne zaklęcie (czar). (10...40 sek.) Otrzymujesz 1...5 pkt. energii, za każdym razem, kiedy zaczarujesz broń.'],
1738=>['Wewnętrzny Wzrok','Zaklęcie (czar). Przez 8...20 sek., nie możesz zostać oślepiony.','Zaklęcie (czar). (8...20 sek.) Jesteś odporny na oślepienie.'],
1739=>['Odnowienie Wspomnień','Zaklęcie (czar). Przez 5...20 sek., kiedy trzymasz przedmiot, wszystkie twoje czary rzucane na broń lub wykorzystujące przedmiot kosztują o 5...35% energii mniej.','Zaklęcie (czar). (5...20 sek.) Twoje czary na broń i tworzące przedmioty kosztują o 5...35% energii mniej. Bez efektu, chyba że trzymasz przedmiot.'],
1740=>['Remedium Posiadacza','Zaklęcie (czar). Przez 10...30 sek. za każdym razem, kiedy rzucasz czar na broń sojusznika, to zdejmujesz z niego 2 przypadłości.','Zaklęcie (czar). (10...30 sek.) Za każdym razem, kiedy rzucasz czar na broń, zdejmujesz z sojusznika będącego jego celem 2 przypadłości.'],
1741=>['Światło Lustrzanego Ducha','Czar. Wybrany sojusznik inny od ciebie otrzymuje 15...90 pkt. żywotności. Jeżeli znajdujesz się w pobliżu ducha, także i ty otrzymujesz 15...90 pkt. żywotności.','Czar. Dodaje 15...90 pkt. żywotności. Otrzymujesz 15...90 pkt. żywotności, jeżeli jesteś w zasięgu słuchu ducha. Na cel nie można wybrać siebie.'],
1742=>['Sygnet Niematerialnej Potęgi','Sygnet elitarny. Przez 5...20 sek. wszystkie duchy, które kontrolujesz w zasięgu słuchu atakują o 33% szybciej i zadają +5...10 pkt. obrażeń.','Sygnet elitarny. (5...20 sek.) Wszystkie duchy, które kontrolujesz w zasięgu słuchu atakują o 33% szybciej i zadają +5...10 pkt. obrażeń.'],
1743=>['Sygnet Spętania','Sygnet. Tracisz 200...50 pkt. żywotności, by przejąć kontrolę nad wybranym duchem nalezącym do wroga. (Szansa porażki wynosi 50%, jeśli twoja Moc Przywoływania ma wartość 4 lub mniejszą.)','Sygnet. Tracisz 200...50 pkt. żywotności. Zyskujesz kontrolę nad wybranym duchem wroga. <c x="SkillDull">Jeśli twoja Moc Przywoływania jest niższa niż 5, szansa porażki wynosi 50%.'],
1744=>['Szarża Opiekuna','Elitarny czar. Wybrany przeciwnik otrzymuje 20...85 pkt. obrażeń od błyskawic. Jeżeli trzymasz przedmiot, otrzymujesz 7 pkt. energii i 5...50 pkt. żywotności.','Elitarny czar. Zadaje 20...85 pkt. obrażeń od błyskawic. Otrzymujesz 7 pkt. energii i 5...50 pkt. żywotności, jeżeli trzymasz przedmiot.'],
1745=>['Katusze','Rytuał spętania. Tworzysz 1...11 poziomowego ducha. Ataki tego ducha zadają 5...20 pkt. obrażeń, a przeciwnikom pod działaniem klątw zadają podwójne obrażenia. Duch ginie po 15...45 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...11 (czas życia 15...45 sek.). Jego ataki zadają 5...20 pkt. obrażeń. Podwójne obrażenia dla przeciwników pod działaniem klątwy.'],
1747=>['Wzmocnienie','Rytuał spętania. Tworzysz 1...14 poziomowego ducha. Wszyscy sojusznicy w jego zasięgu, którzy trzymają przedmiot otrzymują 15...45 pkt. do maksymalnej żywotności i 10 pkt. do maksymalnej energii. Duch ginie po 15...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...14 (czas życia 15...60 sek.). Sojusznicy w zasięgu, którzy trzymają przedmiot, otrzymują 15...45 pkt. do maksymalnej żywotności i 10 pkt. do maksymalnej energii.'],
1748=>['Ozdrowienie','Rytuał spętania. Tworzysz 1...14 poziomowego ducha. Przypadłości, na które cierpią sojusznicy w jego zasięgu kończą się o 20...50% szybciej. Duch ginie po 30...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...14 (czas życia 30...60 sek.). Przypadłości, na które cierpią sojusznicy w zasięgu, kończą się o 20...50% szybciej.'],
1749=>['Wściekły Oręż','Elitarny czar z broni. Przez 5...20 sek., z każdym atakiem zakończonym trafieniem wybrany sojusznik otrzymuje o 100% więcej adrenaliny i 1 pkt. energii.','Elitarny czar z broni. (5...20 sek.) 100% więcej adrenaliny i +1 pkt. energii, za każdym razem, kiedy trafi atak wybranego sojusznika.'],
1750=>['Oręż Xinrae','Elitarny czar z broni. Przez 8 sek., następnym razem, kiedy wybrany sojusznik otrzyma obrażenia od przeciwnika, te obrażenia zostają zmniejszone o 5% maksymalnej żywotności tego sojusznika i sojusznik ten wykrada do 20...80 pkt. żywotności od przeciwnika.','Elitarny czar z broni. (8 sek.) Kiedy następnym razem wybrany sojusznik otrzyma obrażenia od przeciwnika, obrażenia te zostają ograniczone do 5% maksymalnej żywotności tego sojusznika, sojusznik wykrada też przeciwnikowi 20...80 pkt. żywotności.'],
1751=>['Oręż Podżegacza','Czar z broni. Przez 3...13 sek., jeżeli wybrany sojusznik atakuje przeciwnika, który nie atakuje, to czynność tego przeciwnika zostaje przerwana.','Czar z broni. (3...13 sek.) Ataki przerywają czynności. Nie przerywa ataków przeciwników.'],
1752=>['Oręż Remedium','Elitarny czar z broni. Przez 8 sek. następnym razem, kiedy wybrany sojusznik otrzyma obrażenia lub zostanie mu wykradziona żywotność, sojusznik ten wykrada przeciwnikowi do 20...80 pkt. żywotności i traci 2 przypadłości.','Elitarny czar z broni. (8 sek.) Następnym razem, kiedy wybrany sojusznik otrzyma obrażenia lub zostanie mu wykradziona żywotność, ten sojusznik wykrada przeciwnikowi do 20...80 pkt. żywotności i traci 2 przypadłości.'],
1753=>['Rozrywający Zamach','Atak kosą. Zadajesz +5...20 pkt. obrażeń i tracisz 1 zaklęcie derwisza. Jeśli stracono zaklęcie, usuwasz zaklęcie z każdego trafionego wroga.','Atak kosą. Zadaje +5...20 pkt. obrażeń. Tracisz 1 zaklęcie derwisza. Efekt usunięcia: Trafieni wrogowie tracą zaklęcie.'],
1754=>['Napaść','Elitarne zaklęcie błysku (czar). Przez 3...15 sek., atakujesz, poruszasz się oraz zyskujesz adrenalinę o 25% szybciej.','Elitarne zaklęcie błysku (czar). (3...15 sek.) Atakujesz, poruszasz się i zyskujesz adrenalinę 25% szybciej.'],
1755=>['Mistyczne Zepsucie','Zaklęcie błysku (czar). Wszyscy wrogowie w bezpośrednim sąsiedztwie cierpią przez 1...10 sek. z powodu choroby. Przez 20 sek. nic się nie dzieje. Czas trwania choroby zostaje podwojony, jeśli w momencie aktywacji tej umiejętności znajdujesz się pod wpływem zaklęcia. Kiedy zaklęcie to dobiegnie końca, wszyscy członkowie drużyny w zasięgu słuchu zostają wyleczeni z chorób.','Zaklęcie błysku (czar). (20 sek.) Efekt początkowy: Wszyscy wrogowie w bezpośrednim sąsiedztwie zaczynają chorować (1...10 sek). Podwojony czas trwania, jeśli już znajdujesz się pod wpływem zaklęcia. Efekt końcowy: Członkowie drużyny w zasięgu słuchu przestają chorować.'],
1756=>['Uścisk Grentha','Elitarne zaklęcie błysku (czar). For 20 seconds, your attack skills also Cripple that foe for 1...11 seconds and you transfer 1...3 conditions from yourself to that foe.','Elitarne zaklęcie błysku (czar). (20 seconds.) Inflict Cripple (1...11 seconds) with your attack skills and transfer 1...3 conditions.'],
1757=>['Ciernista Zasłona','Zaklęcie błysku (czar). Kiedy rzucisz to zaklęcie, wszyscy wrogowie w pobliżu otrzymują 5...50 pkt. kłutych obrażeń. Przez 5...25 sek., otrzymujesz 5...35% mniej obrażeń od czarów.','Zaklęcie błysku (czar). (5...25 sek.) Obrażenia zadawane czarami są zmniejszone o 5...35%. Efekt początkowy: Wszyscy przeciwnicy w pobliżu otrzymują 5...50 pkt. kłutych obrażeń.'],
1758=>['Uścisk Grabieżcy','Zaklęcie błysku (czar). Przez 5...20 sek., ataki przeciwko poruszającym się wrogom dodatkowo okulawiają ich na 2...9 sek. Kiedy rzucisz to zaklęcie, przestaje działać na ciebie okulawienie i 1 inna przypadłość. Zaklęcie to kończy się kiedy okulawisz przeciwnika 1...3 razy.','Zaklęcie błysku (czar). (5...20 sek.) Ataki na poruszających się wrogów powodują ich okulawienie. Efekt początkowy: Przestaje na ciebie działać okulawienie i 1 inna przypadłość. Kończy się 1...3-krotnym okulawieniu wrogów.'],
1759=>['Ślub Siły','Elitarne zaklęcie (czar). Przez 15 sek., za każdym razem gdy zaatakujesz wroga kosą, zadajesz 10...25 pkt. siecznych obrażeń wszystkim wrogom w bezpośrednim sąsiedztwie.','Elitarne zaklęcie (czar). (15 sek.) Przy ataku kosą zadajesz 10...25 pkt. siecznych obrażeń wszystkim wrogom w bezpośrednim sąsiedztwie.'],
1760=>['Aura Hebanowego Pyłu','Elitarne zaklęcie błysku (czar). Kiedy rzucisz to zaklęcie, wszyscy pobliscy wrogowie zostaną oślepieni na 1...7 sek. Przez 30 sek., jeśli dzierżysz broń zadającą obrażenia od ziemi, twoje ataki wręcz zadają +3...30 pkt. obrażeń od ziemi. Kiedy to zaklęcie dobiega końca, zostajesz wyleczony ze ślepoty.','Elitarne zaklęcie błysku (czar). (30 sek.) Zadajesz +3...30 pkt. obrażeń od ziemi swoimi atakami w walce wręcz. Efekt początkowy: Pobliscy przeciwnicy zostają oślepieni na 1...7 sek. Efekt końcowy: Usuwa ślepotę. Działa tylko wtedy, gdy używasz broni zadającej obrażenia od ziemi.'],
1761=>['Ślub Gorliwości','Elitarne zaklęcie (czar). Przez 20 sek., posiadasz regenerację energii -2, ale za każdym razem kiedy twój atak trafi, otrzymujesz 1...6 pkt. energii.','Elitarne zaklęcie (czar). (20 sek.) Otrzymujesz 1...6 pkt. energii, za każdym razem, kiedy twój atak trafi. Posiadasz degenerację energii -2.'],
1762=>['Serce Furii','Postawa. Przez 2...10 sek. atakujesz o 25% szybciej.','Postawa. (2...10 sek.) Atakujesz 25% szybciej.'],
1763=>['Gorliwa Odnowa','Zaklęcie błysku (czar). Wszyscy przeciwnicy w pobliżu otrzymują po 5...30 pkt. świętych obrażeń. Przez 5...25 sek. masz -1 do regeneracji energii i otrzymujesz 1 pkt. energii za każdym razem, gdy trafisz przeciwnika. Jeśli zaklęcie to zakończy się przedwcześnie, zyskujesz 1...5 pkt. energii.','Zaklęcie błysku (czar). (5...25 sek.) Efekt początkowy: Przeciwnicy w pobliżu otrzymują po 5...30 pkt. świętych obrażeń. Masz -1 do regeneracji energii i otrzymujesz 1 pkt. energii za każdym trafieniem. Otrzymujesz 1...5 pkt. energii, jeśli to zaklęcie zakończy się przedwcześnie.'],
1764=>['Intuicja Napastnika','Zaklęcie błysku (czar). Przez 3...10 sek., otrzymujesz dodatkowe 50% szans na blok podczas atakowania. Kiedy to zaklęcie dobiega końca, wywołujesz osłabienie trwające 3...15 sek. u wszystkich wrogów w bezpośrednim sąsiedztwie.','Zaklęcie błysku (czar). (3...10 sek.) Daje 50% szans na blok podczas atakowania. Efekt końcowy: Przez 3...15 sek. powoduje osłabienie u wrogów w bezpośrednim sąsiedztwie.'],
1765=>['Rozrywająca Aura','Zaklęcie błysku (czar). Kiedy rzucisz to zaklęcie, wszyscy wrogowie w pobliżu otrzymują 10...40 pkt. obrażeń od zimna. Przez 30 sek., twoje umiejętności związane z atakiem usuwają zaklęcia z powalonych przeciwników. Kiedy to zaklęcie dobiegnie końca, pobliscy wrogowie mają pękniętą zbroję przez 1...10 sek.','Zaklęcie błysku (czar). (30 sek.) Twoje umiejętności związane z atakiem usuwają zaklęcia z powalonych wrogów. Efekt początkowy: Wszystkim przeciwnikom w pobliżu zadaje po 10...40 pkt. obrażeń od zimna. Efekt końcowy: Pobliscy przeciwnicy przez 1...10 sek. posiadają pękniętą zbroję.'],
1766=>['Łaska Chyżych Stóp','Zaklęcie (czar). Przez 5...20 sek. poruszasz się o 25% szybciej, a przypadłości, pod których jesteś działaniem trwają o 50% krócej.','Zaklęcie (czar). (5...20 sek.) Poruszasz się o 25% szybciej, a przypadłości, pod których jesteś działaniem trwają o 50% krócej.'],
1767=>['Zamach Żniwiarza','Elitarny atak kosą. Jeśli atak trafi, powoduje okulawienie celu na 3...15 sek. Tracisz 1 zaklęcie derwisza. Jeśli dojdzie do usunięcia zaklęcia, atak ten powala przeciwników na 2...3 sek.','Elitarny atak kosą. (3...15 sek.) Powoduje okulawienie. Tracisz jedno zaklęcie derwisza. Efekt usunięcia: Powoduje powalenie na 2...3 sek.'],
1768=>['Pośpiech Grabieżcy','Zaklęcie błysku (czar). Przez 2...8 sek., poruszasz się o 25% szybciej, a poruszającym się przeciwnikom twoje ataki zadają +3...12 pkt. dodatkowych obrażeń.','Zaklęcie błysku (czar). (2...8 sek.) Poruszasz się o 25% szybciej i poruszającym się przeciwnikom zadajesz +3...12 pkt. obrażeń.'],
1769=>['Skupiona Złość','Umiejętność elitarna. Przez 45 sek., otrzymujesz o 0...150% adrenaliny więcej.','Umiejętność elitarna. (45 sek.) Otrzymujesz o 0...150% więcej adrenaliny.'],
1770=>['Naturalny Gniew','Umiejętność. Przez 4...15 sek., kiedy nie będziesz pod działaniem zaklęcia, otrzymujesz o 33% adrenaliny więcej.','Umiejętność. (4...15 sek.) Otrzymujesz o 33% więcej adrenaliny. Bez efektu, jeśli jesteś pod działaniem zaklęcia.'],
1771=>['Pieśń Odnowy','Elitarny zaśpiew. Przez 10 sek. każdy członek drużyny w zasięgu słuchu z następnym użyciem umiejętności, otrzyma 45...110 pkt. żywotności.','Elitarny zaśpiew. (10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoją następną umiejętnością otrzymują 45...110 pkt. żywotności.'],
1772=>['Liryk Oczyszczenia','Zaśpiew. Przez 5...20 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem sygnetu, traci 1 przypadłość.','Zaśpiew. (5...20 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym sygnetem tracą jedną przypadłość.'],
1773=>['Żołnierska Furia','Elitarne echo. Przez 10...35 sek., jeśli znajdujesz się pod działaniem okrzyku lub pieśni, atakujesz 33% szybciej i otrzymujesz 33% więcej adrenaliny, ale posiadasz -20 pkt. pancerza.','Elitarne echo. (10...35 sek.) Atakujesz o 33% szybciej oraz otrzymujesz 33% więcej adrenaliny, jeżeli jesteś pod działaniem okrzyku lub pieśni. Posiadasz -20 pkt. pancerza'],
1774=>['Agresywny Zaśpiew','Echo. Przez 5...25 sek., atakujesz 25% szybciej ale masz -20 pkt. pancerza. To echo jest ponownie nakładane za każdym razem, kiedy przestaje na tobie działać pieśń lub okrzyk.','Echo. (5...25 sek.) Atakujesz o 25% szybciej. Odnowienie: za każdym razem, kiedy przestaje na tobie działać pieśń lub okrzyk. Posiadasz -20 pkt. pancerza.'],
1775=>['Energetyzujący Finał','Echo. Przez 10...35 sek., za każdym razem, kiedy okrzyk lub zaśpiew przestaną działać na wybranym sojuszniku nie-duchu, otrzymuje on 1...2 pkt. energii.','Echo. (10...35 sek.) Wybrany sojusznik otrzymuje 1...2 pkt. energii za każdym razem, kiedy przestaje na nim działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1776=>['Sygnet Agresji','Sygnet. Jeżeli jesteś pod działaniem okrzyku lub zaśpiewu, otrzymujesz dawki adrenaliny w liczbie 2.','Sygnet. Otrzymujesz dawki adrenaliny w liczbie 2, jeżeli jesteś pod działaniem zaśpiewu lub okrzyku.'],
1777=>['Sygnet Remedium','Sygnet. Tracisz jedną przypadłość.','Sygnet. Tracisz jedną przypadłość.'],
1778=>['Sygnet Powrotu','Sygnet. Wskrzeszasz wybranego członka drużyny, który zmartwychwstaje z 5...20% pkt. żywotności i 1...4% pkt. energii na każdego członka drużyny w zasięgu słuchu.','Sygnet. Wskrzesza wybranego członka drużyny (5...20% pkt. żywotności i 1...4% pkt. energii na każdego członka drużyny w zasięgu słuchu).'],
1779=>['"Przygotować Się!"','Okrzyk. Zyskujesz 2 dawki adrenaliny na każdego członka drużyny w zasięgu słuchu (maks. liczba dawek adrenaliny: 1...8).','Okrzyk. Zyskujesz 2 dawki adrenaliny (maks. 1...8) na każdego członka drużyny w zasięgu słuchu.'],
1780=>['"Łapy Precz!"','Okrzyk. Przez 20 sek. następne 1...5 umiejętności oparte na dotyku, użyte przeciwko sojusznikom w zasięgu słuchu nie zadziałają.','Okrzyk. (20 sek.) Następne 1...5 umiejętności oparte na dotyku, użyte przeciwko sojusznikom w zasięgu słuchu nie zadziałają.'],
1781=>['"Odnajdźcie Ich Słabości!"','Okrzyk. Przez 5...20 sek., kiedy następnym razem wybrany sojusznik wykona atak, zada +5...50 pkt. obrażeń oraz spowoduje powstanie głębokiej rany na 5...20 sek.','Okrzyk. (5...20 sek.) Przy następnym ataku wybrany sojusznik zadaje +5...50 pkt. obrażeń oraz powoduje powstanie głębokiej rany (5...20 sek.).'],
1782=>['"Potęga Jest Wasza!"','Elitarny okrzyk. Przez 2...4 sek. wszyscy sojusznicy w zasięgu słuchu posiadają regenerację energii 1...2.','Elitarny okrzyk. (2...4 sek.) Wszyscy sojusznicy w zasięgu słuchu posiadają regenerację energii 1...2.'],
1783=>['Włócznia Pogromcy','Atak włócznią. Jeśli atak trafi, zadaje +5...25 pkt. obrażeń. Jeżeli cel ma więcej punktów żywotności niż ty, to na 5...20 sek. otrzymuje głęboką ranę.','Atak włócznią. Zadaje +5...25 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli cel ma więcej żywotności niż ty.'],
1784=>['Szybki Oszczep','Atak włócznią. Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli jesteś pod działaniem zaklęcia, to twoja włócznia leci dwa razy szybciej, a przeciwnik nie może jej zablokować.','Atak włócznią. Zadaje +5...20 pkt. obrażeń. Ta włócznia leci dwa razy szybciej i jest nie do zablokowania, jeżeli jesteś pod działaniem zaklęcia.'],
1814=>['Spojrzenie Niosącego Światłość','Umiejętność. Wybrany demoniczny sługa Abaddona otrzymuje 100 pkt. świętych obrażeń, a jego czynność zostaje przerwana. Na każdy poziom Niosącego Światłość, który osiągnąłeś, umiejętność działa na dodatkowego przeciwnika. Po użyciu umiejętność będzie niedostępna przez 15 sek.','Umiejętność. Wybrany demoniczny sługa Abaddona otrzymuje 100 pkt. świętych obrażeń, a jego czynność zostaje przerwana. Umiejętność działa na dodatkowego przeciwnika na każdy poziom Niosącego Światłość, który osiągnąłeś. Wyłącza umiejętność (15 sek.).'],
1815=>['Sygnet Niosącego Światłość','Sygnet. Jeśli jesteś w zasięgu demonicznego sługi Abaddona, otrzymujesz dawki adrenaliny w liczbie 3...5 oraz 16...24 pkt. energii.','Sygnet. Jeśli jesteś w zasięgu demonicznego sługi Abaddona, otrzymujesz dawki adrenaliny w liczbie 3...5 oraz 16...24 pkt. energii.'],
1816=>['Sygnet Odrodzenia Słonecznych Włóczni','Sygnet. Wskrzesza przy tobie wskazanego martwego członka drużyny, który będzie posiadać pełną żywotność i 10% energii za każdy zdobyty przez ciebie poziom Słonecznej Włóczni. Sygnet może być użyty tylko raz na misję, chyba że zostanie odnowiony za pomocą przypływu morale.','Sygnet. Wskrzesza przy tobie wskazanego martwego członka drużyny (pełna żywotność i 10% energii za każdy zdobyty poziom Słonecznej Włóczni). Sygnet odnawia się jedynie kiedy zwiększa się twoje morale.'],
1948=>['Cieniste Sanktuarium','Zaklęcie (czar). Zostajesz oślepiony na 5 sek. Przez 10 sek. posiadasz regenerację żywotności +7...10 i +40 pkt. pancerza.','Zaklęcie (czar). (10 sek.) Posiadasz regenerację żywotności +7...10 i +40 pkt. pancerza. Zostajesz oślepiony (5 sek.).'],
1949=>['Eteryczny Koszmar','Klątwa (czar). Wybrany przeciwnik traci 5...8 pkt. energii. Za każdy stracony w ten sposób punkt energii, ten przeciwnik i wszyscy przeciwnicy w okolicy na 10 sek. posiadają degenerację żywotności -1.','Klątwa (czar). Powoduje utratę 5...8 pkt. energii. Za każdy punkt utraconej energii, cel i przeciwnicy w okolicy posiadają degenerację żywotności -1 (10 sek.).'],
1950=>['Sygnet Zepsucia','Sygnet. Wybrany przeciwnik oraz wszyscy przeciwnicy w pobliżu otrzymują po 20...30 pkt. obrażeń. Za każdego z tych przeciwników będącego pod wpływem przypadłości lub klątwy, otrzymujesz 2 pkt. energii (maksymalnie 12...20 pkt.).','Sygnet. Wybranemu przeciwnikowi i przeciwnikom w pobliżu zadaje po 20...30 pkt. obrażeń. Otrzymujesz 2 pkt. energii (maksymalnie 12...20) za każdego z tych przeciwników, który jest pod działaniem klątwy lub przypadłości.'],
1951=>['Władca Żywiołów','Zaklęcie (czar). Przez 40...60 sek., twoje atrybuty związane z żywiołami są zwiększone o 1. Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 punkt energii za każde 10 poziomów Zapasu Energii oraz jesteś uzdrawiany o 100...300% pkt. energii zużytych na ten czar.','Zaklęcie (czar). (40...60 sek.) Twoje atrybuty związane z żywiołami są zwiększone o 1. Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 punkt energii za każde 10 poziomów Zapasu Energii oraz jesteś uzdrawiany o 100...300% pkt. energii zużytych na ten czar.'],
1952=>['Bezinteresowny Duch','Zaklęcie (czar). Przez 15...20 s czary, które rzucasz na sojuszników kosztują o 3 pkt. energii mniej.','Zaklęcie (czar). (15...20 s) Czary, które rzucasz na sojuszników kosztują o 3 pkt. energii mniej.'],
1953=>['Potrójny Strzał','Strzał z łuku. W wybranego przeciwnika wystrzeliwujesz na raz 3 strzały, które zadają o 40...25% mniej obrażeń.','Strzał z łuku. Jednocześnie wystrzeliwuje w wybranego przeciwnika 3 strzały. Te strzały zadają o 40...25% mniej obrażeń.'],
1954=>['Ratujcie się!','Okrzyk. Przez 4...6 sek., wszyscy członkowie drużyny poza tobą posiadają +100 pkt. pancerza.','Okrzyk. (4...6 sek.) Wszyscy inni członkowie drużyny otrzymują po +100 pkt. pancerza.'],
1955=>['Aura Świętej Mocy','Zaklęcie (czar). Przez 45 sek. zadajesz 20...25 pkt. świętych obrażeń wszystkim wrogom w bezpośrednim sąsiedztwie, jeśli stracisz zaklęcie derwisza.','Zaklęcie (czar). (45 sek.) Za każdym razem, gdy stracisz zaklęcie derwisza, wrogowie w bezpośrednim sąsiedztwie otrzymują 20...25 pkt. świętych obrażeń.'],
1957=>['Włócznia Furii','Atak włócznią. Atak zadaje +30...40 pkt. obrażeń. Jeżeli trafi przeciwnika pod wpływem przypadłości, otrzymujesz dawki adrenaliny w liczbie 3...6.','Atak włócznią. Zadaje +30...40 pkt. obrażeń. Otrzymujesz adrenalinę w liczbie dawek: 3...6, jeżeli trafisz przeciwnika z przypadłością.'],
1986=>['Wampiryczne Natarcie','Atak podwójny. Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, wykradasz 10...40 pkt. żywotności.','Atak podwójny. Wykrada 10...40 pkt. żywotności, jeżeli ten atak trafi. Musi nastąpić po ataku drugą ręką.'],
1987=>['Uderzenie Lotosu','Atak drugą ręką. Musi nastąpić po ataku poprzedzającym. Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń i otrzymujesz 5...20 pkt. energii.','Atak drugą ręką. Zadaje +10...25 pkt. obrażeń; otrzymujesz 5...20 pkt. energii. Musi nastąpić po ataku poprzedzającym.'],
1988=>['Cios Złotego Kła','Atak drugą ręką. Musi nastąpić po ataku poprzedzającym. Jeśli jesteś pod działaniem zaklęcia i ten atak trafi, wybrany przeciwnik na 5...20 sek. otrzyma głęboką ranę.','Atak drugą ręką. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli jesteś pod działaniem zaklęcia. Musi nastąpić po ataku poprzedzającym.'],
1990=>['Uderzenie Spadającego Lotosu','Atak drugą ręką. Musi uderzyć powalonego przeciwnika. Jeśli atak trafi, zadajesz +15...35 pkt. obrażeń i otrzymujesz 1...12 pkt. energii.','Atak drugą ręką. Zadaje +15...35 pkt. obrażeń; otrzymujesz 1...12 pkt. energii. Bez efektu, chyba że wybrany przeciwnik jest powalony.'],
1991=>['Sygnet Sadysty','Sygnet. Za każdą przypadłość, pod której działaniem jest wybrany przeciwnik, otrzymujesz 10...45 pkt. żywotności.','Sygnet. Za każdą przypadłość, pod której działaniem jest wybrany przeciwnik, otrzymujesz 10...45 pkt. żywotności.'],
1992=>['Sygnet Rozproszenia','Sygnet. Jeżeli cel rzuca czar, zostaje on przerwany i zablokowany na 1...5 sek. za każdy założony sygnet.','Sygnet. Przerywa działanie czaru. Efekt przerwania: czar przeciwnika zostaje zablokowany na 1...5 sek. za każdy założony sygnet.'],
1993=>['Sygnet Przypomnienia','Sygnet. Przez 6 sek., posiadasz regenerację energii -4. Kiedy efekt przestanie działać, otrzymujesz 13...20 pkt. energii.','Sygnet. (6 sek.) Posiadasz degenerację energii -4. Efekt końcowy: otrzymujesz 13...20 pkt. energii.'],
1994=>['Zamknięcie Mocy','Czar. Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a cel traci 5...13 pkt. energii.','Czar. Przerywa użycie czaru lub pieśni. Skutek przerwania: przerwany czar lub pieśń zostają zablokowane na +5...13 sek.'],
1995=>['Nie Marnujesz, Nie Potrzebujesz','Czar. Jeżeli wybrany przeciwnik nie rzuca czaru ani nie atakuje otrzymujesz 8...13 pkt. energii.','Czar. Otrzymujesz 8...13 pkt. energii, jeżeli wybrany przeciwnik nie atakuje ani nie rzuca czaru.'],
1996=>['Suma Wszystkich Strachów','Klątwa (czar). Przez 4...12 sek. wybrany przeciwnik porusza się, atakuje i rzuca czary o 33% wolniej.','Klątwa (czar). (4...12 sek.) Wybrany przeciwnik porusza się, atakuje i rzuca czary o 33% wolniej.'],
1997=>['Osłabiająca Aura','Zaklęcie (czar). Przez 5...20 sek., ataki wręcz sojusznika wywołują osłabienie trwające 5...20 sek.','Zaklęcie (czar). (5...20 sek.) Ataki wręcz wybranego sojusznika wywołują przypadłość osłabienie (5...20 sek.).'],
1998=>['Kakofonia','Klątwa (czar). Przez 15 sek., za każdym razem, kiedy wybrany przeciwnik użyje okrzyku lub zaśpiewu, otrzyma 30...105 pkt. obrażeń.','Klątwa (czar). (15 sek.) Zadaje 30...105 pkt. obrażeń, za każdym razem, kiedy wybrany przeciwnik użyje okrzyku lub zaśpiewu.'],
1999=>['Objęcia Zimy','Klątwa (czar). Przez 2...6 sek., wybrany przeciwnik porusza się o 66% wolniej i otrzymuje 5...15 pkt. obrażeń podczas ruchu.','Klątwa (czar). (2...6 sek.) Wybrany przeciwnik porusza się o 66% wolniej i otrzymuje 5...15 pkt. obrażeń podczas ruchu.'],
2000=>['Gliniane Kajdany','Klątwa (czar). Przez 3 sek., wybrany przeciwnik i wszyscy przeciwnicy w pobliżu poruszają się 90% wolniej. Kiedy Gliniane Kajdany się skończą, przeciwnik na 5...20 sek. zostaje osłabiony.','Klątwa (czar). (3 sek.) Cel i pobliscy przeciwnicy poruszają się 90 wolniej. Osłabia przeciwnika na 5...20 sek. po zakończeniu.'],
2001=>['Osłabiająca Ochrona','Ochrona (czar). W miejscu, w którym przebywasz tworzysz Osłabiającą Ochronę. Przez 5...20 sek., za każdym razem, kiedy przeciwnicy w zasięgu jej działania otrzymają obrażenia od żywiołów na 5...20 sek. zostaną osłabieni.','Ochrona (czar). (5...20 sek.) U przeciwników będących w granicach tej ochrony, którzy otrzymają obrażenia od żywiołów, wywołuje przypadłość osłabienie (5...20 sek.).'],
2002=>['Glif Szybkości','Glif. Przez 15 sek. twoje następne czary w liczbie 1...5 odnawiają się o 25% szybciej, a pociski z nich poruszają się o 200% szybciej.','Glif. (15 sek.) Twoje następne czary w liczbie 1...5 odnawiają się o 25% szybciej, a pociski z nich poruszają się o 200% szybciej.'],
2003=>['Wyleczenie Klątwy','Czar. Usuwasz z wybranego sojusznika jedną klątwę. Jeśli klątwa zostanie usunięta, to sojusznik ten otrzyma 30...100 pkt. żywotności.','Czar. Usuwa klątwę. Efekt usunięcia: dodaje 30...100 pkt. żywotności.'],
2004=>['Pogrom Przypadłości','Czar. Z wybranego sojusznika usuwasz jedną przypadłość. Jeśli przypadłość zostanie usunięta, to każdy przeciwnik w okolicy otrzyma 10...60 pkt. świętych obrażeń.','Czar. Usuwa przypadłość. Efekt usunięcia: przeciwnikom w okolicy wybranego sojusznika zadaje 10...60 pkt. świętych obrażeń.'],
2005=>['Dar Pogromcy','Zaklęcie (czar). Przez 30 sek., twoje czary oparte na Modlitwach Ofensywnych zapewniają podwójną premię pochodzącą od Łaski Bogów.','Zaklęcie (czar). (30 sek.) Dla umiejętności z Modlitw Ofensywnych punkty żywotności otrzymywane dzięki Łasce Bogów są podwajane.'],
2006=>['Sygnet Skarcenia','Sygnet. Wybrany przeciwnik otrzymuje 26...56 świętych obrażeń. Jeżeli w tym czasie atakował, otrzymujesz 4...14 punktów energii.','Sygnet. Zadaje 26...56 pkt. świętych obrażeń. Otrzymujesz 4...14 pkt. energii, jeżeli wybrany przeciwnik atakuje.'],
2007=>['Oczyszczający Całun','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, przypadłości, pod których działaniem znajdzie się wybrany sojusznik będą trwały o 5...50% krócej. Kiedy to zaklęcie przestanie działać, z sojusznika zostanie usunięta jedna przypadłość.','Zaklęcie (czar). Przypadłości na wybranym sojuszniku kończą się o 5...50% szybciej. Efekt końcowy: usuwa przypadłość.'],
2008=>['Druzgocące Uderzenie','Atak młotem. Jeżeli trafisz powalonego przeciwnika, to na 5...20 sek. otrzyma on głęboką ranę i zostanie osłabiony.','Atak młotem. Wywołuje przypadłości osłabienie i głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
2009=>['Ostre Cięcie','Atak toporem. Jeśli ten atak trafi, to zawsze skutkuje trafieniem krytycznym.','Atak toporem. Zawsze trafienie krytyczne.'],
2010=>['Podcięcie Kolan','Atak mieczem. Jeśli atak trafi okulawionego przeciwnika, otrzymujesz 2...7 pkt. energii i dawki adrenaliny w liczbie 1...3.','Atak mieczem. Otrzymujesz 2...7 pkt. energii i dawki adrenaliny w liczbie 1...3, jeżeli wybrany przeciwnik jest okulawiony.'],
2011=>['Chwyt','Umiejętność. Ty i dotknięty przeciwnik zostajecie powaleni. Tracisz aktualną postawę.','Umiejętność dotykowa. Powoduje powalenie. Ty również zostajesz powalony[f:"powalona"]. Twoja aktualna postawa zostaje zakończona.'],
2012=>['Promieniejąca Kosa','Atak kosą. Za każdy punkt energii, który aktualnie posiadasz, atak ten zadaje +1 pkt. obrażeń (maksymalnie 5...30 pkt. obrażeń). Jeśli ten atak trafi, otrzymujesz 1...7 energii.','Atak kosą. Zadaje +1 pkt. obrażeń (maksymalnie 5...30) za każdy punkt energii, który posiadasz. Zyskujesz 1...7 pkt. energii.'],
2013=>['Aura Grentha','Zaklęcie błysku (czar). Przez 20 sek., zadajesz 5...25 pkt. obrażeń mniej i wykradasz 5...25 żywotności przy każdym trafieniu kosą. Kiedy rzucasz to zaklęcie, wykradasz 5...25 żywotności wszystkim wrogom w bezpośrednim sąsiedztwie.','Zaklęcie błysku (czar). (20 sek.) Zadajesz 5...25 pkt. obrażeń mniej i wykradasz 5...25 żywotności przy każdym trafieniu kosą. Efekt początkowy: Wykradasz 5...25 żywotności wszystkim wrogom w bezpośrednim sąsiedztwie.'],
2014=>['Sygnet Nabożnej Powściągliwości','Sygnet. Usuwa jedno zaklęcie derwisza. Wybrany przeciwnik zostaje okulawiony na 5...15 sek. Jeśli zostało usunięte jakieś zaklęcie, wszyscy wrogowie w pobliżu twojego celu także zostają okulawieni, zaś sygnet odnawia się 75% szybciej.','Sygnet. Wywołuje okulawienie (5...15 sek.). Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Powoduje także okulawienie wrogów w pobliżu twojego celu i odnawia się 75% szybciej.'],
2015=>['Kosa Farmera','Atak kosą. Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeżeli trafisz więcej niż jednego przeciwnika, atak natychmiast się odnawia.','Atak kosą. Zadaje +5...20 pkt. obrażeń. Natychmiast się odnawia, jeżeli trafisz więcej niż jednego przeciwnika.'],
2016=>['Energiczną Była Lee Sa','Czar z przedmiotu. Trzymaj prochy Lee Sa\'y przez 5...15 sek. Kiedy trzymasz jej prochy, posiadasz regenerację energii +2. Gdy upuścisz jej prochy, otrzymujesz +1...10 pkt. energii.','Czar z przedmiotu. (5...15 sek.) Posiadasz regenerację energii +2. Efekt upuszczenia: otrzymujesz +1...10 pkt. energii.'],
2017=>['Hymn Znużenia','Zaśpiew. Przez 8 sek. następna umiejętność związana z atakiem, użyta przez każdego sojusznika w zasięgu słuchu, dodatkowo osłabi przeciwnika na 1...16 sek.','Zaśpiew. (8 sek.) Sojusznicy w zasięgu słuchu swoją następną umiejętnością związaną z atakiem wywołują osłabienie (1...16 sek.).'],
2018=>['Hymn Rozproszenia','Zaśpiew. Przez 1...10 sek. następna umiejętność związana z atakami, używana przez każdego sojusznika w zasięgu słuchu, przerywa także czynność przeciwnika.','Zaśpiew. (1...10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem przerywają czynność przeciwnika.'],
2051=>['Przyzwanie Duchów','Czar. Wszystkie duchy, które kontrolujesz wykonują krok cienia w miejsce, w którym się znajdujesz i otrzymują po 60...100 pkt. żywotności.','Czar. Duchy, które kontrolujesz wykonują krok cienia w miejsce, w którym się znajdujesz i otrzymują po 60...100 pkt. żywotności.'],
2052=>['Kieł Cienia','Klątwa (czar). Wykonujesz krok cienia do wybranego przeciwnika. Przez 10 sek. klątwa nie daje żadnego efektu. Kiedy klątwa przestanie działać, powracasz do początkowego miejsca, a przeciwnik ten na 5...20 sek. otrzymuje głęboką ranę.','Klątwa (czar). Wykonujesz krok cienia do wybranego przeciwnika. Efekt końcowy po 10 sek.: wywołuje przypadłość głęboka rana (5...20 sek.); wracasz do swojego początkowego miejsca.'],
2053=>['Przewidziane Ryzyko','Klątwa (czar). Przez 3...24 sek., ataki wybranego przeciwnika zadają +10 obrażeń, ale istnieje 50% szansy, że obrażenia z każdego ataku otrzyma właśnie ten wróg. (Maksymalnie 15...100.)','Klątwa (czar). (3...24 sek.) Ataki wybranego przeciwnika zadają +10 obrażeń. Przy każdym ataku istnieje 50% szansy, że obrażenia (maksymalnie 15...100) przejdą właśnie na tego przeciwnika.'],
2054=>['Skurczenie Zbroi','Klątwa (czar). Przez 10 sek. wybrany przeciwnik posiada degenerację żywotności -1...4. Kiedy klątwa przestanie działać, przeciwnik na 5...20 sek. znajdzie się pod działaniem pękniętej zbroi.','Klątwa (czar). (10 sek.) Powoduje degenerację żywotności -1...4. Efekt końcowy: wywołuje przypadłość pęknięta zbroja (5...20 sek.).'],
2055=>['Tętniak','Czar. Wybrany przeciwnik odzyskuje całą swoją energię. Za każdy zyskany w ten sposób punkt energii, otrzymuje 1...3 pkt. obrażeń, a wszyscy przeciwnicy w jego sąsiedztwie tracą 1 pkt. energii (maksymalna strata energii to 1...30).','Czar. Wybrany przeciwnik odzyskuje całą swoją energię. Za każdy zyskany w ten sposób punkt energii, otrzymuje 1...3 pkt. obrażeń, a wszyscy przeciwnicy w jego sąsiedztwie tracą 1 pkt. energii (maksymalnie 1...30).'],
2056=>['Błędne Oko','Klątwa (czar). Przez 4 sek., następnym razem, gdy wybrany przeciwnik wykona atak, zostanie on przerwany, a wszyscy przeciwnicy w pobliżu otrzymają po 30...110 pkt. obrażeń.','Klątwa (czar). (4 sek.) Przerywa następny atak wybranego przeciwnika. Efekt przerwania: 30...110 pkt. obrażeń dla przeciwników w pobliżu.'],
2057=>['Plugawa Uczta','Czar. Wszystkie przypadłości ze wskasanego sojusznika zostanją przekazane na ciebie. Za każdą przypadłość uzyskaną w ten sposób, otrzymujesz 0...45 pkt. żywotności i 2...4 pkt. energii. Umiejętność odnawia się dwa razy szybciej, jeżeli usuniesz chorobę z celu.','Czar. Przenosi wszystkie przypadłości z wybranego sojusznika na ciebie. Za każdą przekazaną przypadłość otrzymujesz 0...45 pkt. żywotności i 2...4 pkt. energii. Połowa odnowienia, jeżeli usuniesz chorobę. Nie można użyć na sobie.'],
2058=>['Splugawiona Żółć','Klątwa (czar). Przez 5...25 sek. wybrany przeciwnik posiada degenerację żywotności -1...3. Jeśli umrze będąc pod działaniem tej klątwy, to wszyscy przeciwnicy w pobliżu otrzymają po 25...85 pkt. obrażeń.','Klątwa (czar). (5...25 sek.) Powoduje degenerację żywotności -1...3. Przeciwnikom w pobliżu zadaje 25...85 pkt. obrażeń, jeżeli wybrany przeciwnik umrze.'],
2059=>['Wstrząs Pancerza','Czar. Wybrany przeciwnik otrzymuje 10...30 pkt. obrażeń od elektryczności a jego zbroja pęka na 5...20 sek. To zaklęcie ma 25% penetrację pancerza. Jeśli jesteś pod wpływem Przemagicznienia, to zaklęcie trafia również pobliskich wrogów.','Czar. Zadaje 10...30 pkt. obrażeń od elektryczności. Wywołuje przypadłość pęknięta zbroja (5...20 sek.). 25% penetracji pancerza. Podczas Przemagicznienia trafia pobliskich.'],
2060=>['Glif Podpalenia','Glif. Przez 15 sek. twoje następne czary w liczbie 1...4, których celem jest przeciwnik, na 1...4 sek. wywołują dodatkowo płonięcie.','Glif. (15 sek.) Twoje następne czary w liczbie 1...4, których celem jest przeciwnik, wywołują dodatkowo płonięcie (1...4 sek.).'],
2061=>['Cierpliwy Duch','Zaklęcie (czar). Na 2 sek. wskazany sprzymierzeniec znajduje się pod wpływem Cierpliwego Ducha. Jeżeli zaklęcie zakończy się przedwcześnie, sprzymierzeniec zostanie uleczony za 30...120 pkt. zdrowia.','Zaklęcie (czar). (2 sek.) Efekt końcowy: przywraca 30...120 pkt. żywotności. Bez efektu, jeżeli zakończy się przedwcześnie.'],
2062=>['Lecząca Wstęga','Czar. Wybrany sojusznik inny niż ty otrzymuje 20...110 pkt. żywotności. Nie więcej niż 2 dodatkowi sojusznicy w jego pobliżu otrzymują po 10...100 pkt. żywotności.','Czar. Dodaje 20...110 pkt. żywotności. Ulecza dwóch dodatkowych sojuszników w pobliżu wybranego sojusznika dodając im po 10...100 pkt. żywotności. Na cel nie można wybrać siebie.'],
2063=>['Pewna Dusza','Zaklęcie (czar). Przez 3...8 sek., wybrany sojusznik inny niż ty nie może zostać powalony.','Zaklęcie (czar). (3...8 sek.) Wybrany sojusznik nie może zostać powalony. Na cel nie można wybrać siebie.'],
2064=>['Nieskazitelny Umysł','Zaklęcie (czar). Przez 1...15 sek. wybrany sojusznik inny niż ty co 5 sek. traci jedną klątwę.','Zaklęcie (czar). (1...15 sek.) Co 5 sek. usuwa klątwę. Na cel nie można wybrać siebie.'],
2065=>['Nieskazitelna Dusza','Zaklęcie (czar). Przez 1...15 sek. wybrany sojusznik inny niż ty co 3 sek. traci jedną przypadłość.','Zaklęcie (czar). (1...15 sek.) Co 3 sek. usuwa przypadłość. Na cel nie można wybrać siebie.'],
2066=>['Rozbrojenie','Atak mieczem. Przerywasz czynność wybranego przeciwnika. Jeśli tą czynnością był atak, to wszystkie umiejętności związane z atakowaniem tego przeciwnika będą niedostępne przez 0...3 sek.','Atak mieczem. Przerywasz czynność wybranego przeciwnika. Efekt przerwania: wyłącza umiejętności związane z atakami tego przeciwnika (0...3 sek.), jeśli tą czynnością był atak.'],
2067=>['"Zrobiłem to Umyślnie!"','Okrzyk. Jeżeli jesteś powalony, otrzymujesz dawki adrenaliny w liczbie 1...6.','Okrzyk. Otrzymujesz dawki adrenaliny w liczbie 1...6, jeżeli jesteś powalony.'],
2068=>['Szybkostrzelność','Przygotowanie. Przez 5...25 sek. dzierżąc łuk atakujesz o 33% szybciej.','Przygotowanie. (5...25 sek.) Dzierżąc łuk atakujesz o 33% szybciej.'],
2069=>['Strzał Łowcy Ospałych','Strzał z łuku. Jeżeli atak trafi, wybrany przeciwnik otrzymuje +10...25 pkt. obrażeń. Jeżeli przeciwnik ten nie używa umiejętności, to Strzał Łowcy Ospałych zadaje dodatkowe +10...35 pkt. obrażeń.','Strzał z łuku. Zadaje +10...25 pkt. obrażeń. Zadaje +10...35 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik nie używa umiejętności.'],
2070=>['Rozcinacz Aur','Atak wręcz. Jeśli atak trafi, powoduje krwawienie przez 5...15 sek. Jeśli znajdujesz się pod wpływem zaklęcia, atak powoduje także pęknięcie zbroi przez 1...10 sek.','Atak wręcz. (5...15 sek.) Wywołuje krwawienie. Powoduje także pęknięcie zbroi (1...10 sek.), jeśli znajdujesz się pod wpływem zaklęcia.'],
2071=>['Gorliwy Zamach','Atak kosą. Jeśli ten atak dojdzie celu, zadajesz +5...20 pkt. obrażeń. Za każdego trafionego wroga otrzymujesz 3 pkt. energii oraz 1 dawkę adrenaliny.','Atak kosą. Zadaje +5...20 pkt. obrażeń. Za każdego trafionego wroga otrzymujesz 3 pkt. energii oraz 1 dawkę adrenaliny.'],
2072=>['Nieskalaną Była Li Ming','Czar z przedmiotu. Trzymaj prochy Li Ming przez 5...20 sek. Kiedy trzymasz jej prochy, przypadłości, pod których jesteś działaniem trwają o 10...50% krócej. Gdy upuścisz jej prochy, wszyscy sojusznicy w zasięgu słuchu tracą przypadłości w liczbie 1...4.','Czar z przedmiotu. (5...20 sek.) Przypadłości, pod których jesteś działaniem kończą się o 10...50% szybciej. Efekt upuszczenia: z sojuszników w zasięgu słuchu usuwa 1...4 przypadłości.'],
2073=>['Agresywny Oręż','Czar z broni. Przez 5...15 sek. atakujesz o 25% szybciej.','Czar z broni. (5...15 sek.) Atakujesz o 25% szybciej.'],
2074=>['Łamacz Żeber','Atak włócznią. Jeżeli atak trafi przeciwnika, który jest pod działaniem Pękniętej Zbroi, to przeciwnik ten na 5...20 sek. otrzymuje głęboką ranę.','Atak włócznią. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik ma pękniętą zbroję.'],
2075=>['Zaśpiew Pośpiechu','Echo. Przez 8...20 sek. wybrany sojusznik porusza się o 25% szybciej. To echo jest ponownie nakładane za każdym razem, kiedy przestanie na tym sojuszniku działać zaśpiew lub okrzyk.','Echo. (8...20 sek.) Wybrany sojusznik porusza się o 25% szybciej. Odnowienie: za każdym razem, kiedy przestaje na tym sojuszniku działać zaśpiew lub okrzyk.'],
2091=>['Cieniste Sanktuarium','Zaklęcie (czar). Zostajesz oślepiony na 5 sek. Przez 10 sek. posiadasz regenerację żywotności +7...10 i +40 pkt. pancerza.','Zaklęcie (czar). (10 sek.) Posiadasz regenerację żywotności +7...10 i +40 pkt. pancerza. Zostajesz oślepiony (5 sek.).'],
2092=>['Eteryczny Koszmar','Klątwa (czar). Wybrany przeciwnik traci 5...8 pkt. energii. Za każdy stracony w ten sposób punkt energii, ten przeciwnik i wszyscy przeciwnicy w okolicy na 10 sek. posiadają degenerację żywotności -1.','Klątwa (czar). Powoduje utratę 5...8 pkt. energii. Za każdy punkt utraconej energii, cel i przeciwnicy w okolicy posiadają degenerację żywotności -1 (10 sek.).'],
2093=>['Sygnet Zepsucia','Sygnet. Wybrany przeciwnik oraz wszyscy przeciwnicy w pobliżu otrzymują po 20...30 pkt. obrażeń. Za każdego z tych przeciwników będącego pod wpływem przypadłości lub klątwy, otrzymujesz 2 pkt. energii (maksymalnie 12...20 pkt.).','Sygnet. Wybranemu przeciwnikowi i przeciwnikom w pobliżu zadaje po 20...30 pkt. obrażeń. Otrzymujesz 2 pkt. energii (maksymalnie 12...20) za każdego z tych przeciwników, który jest pod działaniem klątwy lub przypadłości.'],
2094=>['Władca Żywiołów','Zaklęcie (czar). Przez 40...60 sek., twoje atrybuty związane z żywiołami są zwiększone o 1. Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 punkt energii za każde 10 poziomów Zapasu Energii oraz jesteś uzdrawiany o 100...300% pkt. energii zużytych na ten czar.','Zaklęcie (czar). (40...60 sek.) Twoje atrybuty związane z żywiołami są zwiększone o 1. Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 punkt energii za każde 10 poziomów Zapasu Energii oraz jesteś uzdrawiany o 100...300% pkt. energii zużytych na ten czar.'],
2095=>['Bezinteresowny Duch','Zaklęcie (czar). Przez 15...20 s czary, które rzucasz na sojuszników kosztują o 3 pkt. energii mniej.','Zaklęcie (czar). (15...20 s) Czary, które rzucasz na sojuszników kosztują o 3 pkt. energii mniej.'],
2096=>['Potrójny Strzał','Strzał z łuku. W wybranego przeciwnika wystrzeliwujesz na raz 3 strzały, które zadają o 40...25% mniej obrażeń.','Strzał z łuku. Jednocześnie wystrzeliwuje w wybranego przeciwnika 3 strzały. Te strzały zadają o 40...25% mniej obrażeń.'],
2097=>['Ratujcie się!','Okrzyk. Przez 4...6 sek., wszyscy członkowie drużyny poza tobą otrzymują po +100 pkt. pancerza.','Okrzyk. (4...6 sek.) Wszyscy inni członkowie drużyny otrzymują po +100 pkt. pancerza.'],
2098=>['Aura Świętej Mocy','Zaklęcie (czar). Przez 45 sek. zadajesz 20...25 pkt. świętych obrażeń wszystkim wrogom w bezpośrednim sąsiedztwie, jeśli stracisz zaklęcie derwisza.','Zaklęcie (czar). (45 sek.) Za każdym razem, gdy stracisz zaklęcie derwisza, wrogowie w bezpośrednim sąsiedztwie otrzymują 20...25 pkt. świętych obrażeń.'],
2099=>['Włócznia Furii','Atak włócznią. Atak zadaje +30...40 pkt. obrażeń. Jeżeli trafi przeciwnika pod wpływem przypadłości, otrzymujesz dawki adrenaliny w liczbie 3...6.','Atak włócznią. Zadaje +30...40 pkt. obrażeń. Otrzymujesz adrenalinę w liczbie dawek: 3...6, jeżeli trafisz przeciwnika z przypadłością.'],
2100=>['Przyzwanie Duchów','Czar. Wszystkie duchy, które kontrolujesz wykonują krok cienia w miejsce, w którym się znajdujesz i otrzymują po 60...100 pkt. żywotności.','Czar. Duchy, które kontrolujesz wykonują krok cienia w miejsce, w którym się znajdujesz i otrzymują po 60...100 pkt. żywotności.'],
2101=>['Krytyczna Zwinność','Zaklęcie (czar). Przez 4 sek. i 1 sekundę na każdy poziom Trafień Krytycznych atakujesz o 33% szybciej i posiadasz +15...25 pkt. pancerza. Ta umiejętność zadziała ponownie za każdym razem, kiedy wykonasz trafienie krytyczne.','Zaklęcie (czar). (4 sek. plus 1 sek. za każdy poziom Trafień Krytycznych.) Atakujesz o 33% szybciej i posiadasz +15...25 pkt. pancerza. Odnowienie: za każdym razem, gdy wykonasz trafienie krytyczne.'],
2102=>['Okrzyk Bólu','Czar. Przerywa umiejętność wybranego przeciwnika. Jeżeli ten przeciwnik był pod działaniem klątwy mesmera, to zarówno on, jak i wszyscy przeciwnicy w okolicy otrzymują po 25...50 pkt. obrażeń, zaś ich żywotność spada o 3...5 na 10 sekund.','Czar. Przerywa umiejętność. Zadaje 25...50 pkt. obrażeń wybranemu przeciwnikowi i przeciwnikom w okolicy, jeżeli wybrany przeciwnik jest pod działaniem klątwy mesmera, a także powoduje spadek żywotości o 3...5 (10 sekund).'],
2103=>['Nekroza','Umiejętność. Jeżeli wybrany przeciwnik jest pod działaniem przypadłości lub klątwy, otrzymuje 60...90 pkt. obrażeń.','Umiejętność. Zadaje 60...90 pkt. obrażeń, jeżeli wybrany przeciwnik jest pod działaniem przypadłości lub klątwy.'],
2104=>['Spotęgowanie','Umiejętność. Przez 10 sek., kiedy następnym razem zadasz celowi obrażenia od żywiołów za pomocą czaru, zadajesz także 60...70% tych obrażeń wszystkim wrogom w okolicy.','Umiejętność. (10 sek.) Kiedy następnym razem zadajesz celowi obrażenia od żywiołów za pomocą czaru, wszyscy wrogowie w okolicy otrzymują 60...70% tych obrażeń.'],
2105=>['Ziarno Życia','Zaklęcie (czar). Przez 2...5 sek., za każdym razem, kiedy wybrany sojusznik inny niż ty otrzyma obrażenia, wszyscy członkowie drużyny odzyskują po 2 pkt. żywotności na każdy twój poziom Łaski Bogów.','Zaklęcie (czar). (2...5 sek.) Członkowie drużyny odzyskują po 2 pkt. żywotności za każdy poziom Łaski Bogów, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia. Na cel nie można wybrać siebie.'],
2107=>['Wirujący Atak','Atak wręcz. Atakujesz cel i przeciwników bezpośrednio przy nim. Każdy celny atak zadaje +13...20 pkt. obrażeń.','Atak wręcz. Atakuje wybranego przeciwnika i przeciwników w bezpośredniej odległości, zadając każdemu +13...20 pkt. obrażeń.'],
2108=>['Nie Siej Zniszczenia Sam','Umiejętność. Przez 18...25 sek., ty i twój zwierzęcy towarzysz atakujecie o 25% szybciej i posiadacie regenerację żywotności +1...3.','Umiejętność. (18...25 sek.) Ty i twój zwierzęcy towarzysz atakujecie o 25% szybciej i posiadacie regenerację żywotności +1...3.'],
2109=>['Odwieczna Aura','Zaklęcie (czar). Otrzymujesz +100 do maksymalnej żywotności. Kiedy to zaklęcie dobiegnie końca, wszyscy członkowie drużyny na danym obszarze zostaną wskrzeszeni, otrzymując 40...50% żywotności oraz 20...30% energii.','Zaklęcie (czar). Otrzymujesz +100 do maksymalnej żywotności. Efekt końcowy: Wszyscy członkowie drużyny na danym obszarze zostaną wskrzeszeni, otrzymując 40...50% żywotności oraz 20...30% energii.'],
2110=>['Wampiryzm','Rytuał spętania. Tworzysz ducha na poziomie 4...14, który ginie po 75...150 sek. Ataki tego ducha wykradają do 10...20 pkt. żywotności, a ty otrzymujesz 10...20 pkt. żywotności.','Rytuał spętania. Tworzy ducha na poziomie 4...14 (czas życia 75...150 sek.). Jego ataki wykradają 10...20 pkt. żywotności, a ty otrzymujesz 10...20 pkt. żywotności.'],
2112=>['"Nie Ma się Czego Obawiać!"','Okrzyk. Przez 4 sek. i 1 sekundę na każde 2 poziomy Przywództwa wszyscy sojusznicy w zasięgu słuchu otrzymują o 20...35% mniej obrażeń. Kiedy okrzyk się skończy, ci sojusznicy otrzymają po 35...60 pkt. żywotności.','Okrzyk. (4 sek. plus 1 sek. za każde 2 poziomy Przywództwa.) Obniża obrażenia o 20...35% na każdego członka drużyny w zasięgu słuchu. Efekt końcowy: dodaje 35...60 pkt. żywotności.'],
2116=>['Atak z Zaskoczenia','Atak wręcz. Jeśli atak trafi, wybrany przeciwnik zostanie oślepiony na 5...8 sek. Ten atak liczy się jako atak poprzedzający.','Atak wręcz. Powoduje oślepienie (5...8 sek.). Traktuje się jako atak poprzedzający.'],
2135=>['Tratujący Wół','Atak podwójny. Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli atak trafi okulawionego przeciwnika, ten przeciwnik zostaje powalony.','Atak podwójny. Zadaje +5...20 pkt. obrażeń; powala, jeżeli wybrany przeciwnik jest okulawiony. Musi nastąpić po ataku drugą ręką.'],
2136=>['Zasłona Dymna','Postawa. Przez 8 sek., następnym razem, kiedy zostaniesz trafiony[f:"trafiona"], otrzymasz połowę obrażeń, a wszyscy przeciwnicy bezpośrednio przy tobie zostaną oślepieni na 2...6 sek.','Postawa. (8 sek.) Następnym razem, kiedy zostaniesz trafiony[f:"trafiona"], otrzymasz połowę obrażeń, a wszyscy przeciwnicy bezpośrednio przy tobie zostaną oślepieni (2...6 sek.).'],
2137=>['Mylące Obrazy','Klątwa (czar). Przez 2...10 sek., wybrany przeciwnik potrzebuje dwa razy więcej czasu na używanie umiejętności nie związanych z atakiem.','Klątwa (czar). (2...10 sek.) Wybrany przeciwnik potrzebuje dwa razy więcej czasu na używanie umiejętności nie związanych z atakiem.'],
2138=>['Zdrowie Przeklinającego','Zaklęcie (czar). Przez 10 sek. posiadasz regenerację żywotności +1...8. Zdrowie Przeklinającego przestanie działać, jeżeli użyjesz umiejętności nie będącej klątwą.','Zaklęcie (czar). (10 sek.) Posiadasz regenerację żywotności +1...8. Przestanie działać, jeśli użyjesz umiejętności niebędącej klątwą.'],
2139=>['Masochizm','Zaklęcie (czar). Przez 10...40 sek., otrzymujesz +2 do Magii Śmierci oraz Wydzierania Duszy, a także poświęcasz 5...3% swojej maksymalnej żywotności, za każdym razem kiedy rzucasz czar.','Zaklęcie (czar). (10...40 sek.) Otrzymujesz +2 do Magii Śmierci oraz Wydzierania Duszy.Poświęcasz 5...3% swojej maksymalnej żywotności, jeśli rzucasz czar.'],
2140=>['Przebijająca Pułapka','Pułapka. Kiedy Przebijająca Pułapka zostanie uaktywniona, wszyscy przeciwnicy w pobliżu otrzymują 5...50 pkt. obrażeń przebijających. Każdy przeciwnik znajdujący się pod działaniem Pękniętej Zbroi otrzymuje dodatkowe 15...60 pkt. obrażeń. Przebijająca Pułapka przestaje działać po 90 sekundach. Podczas aktywacji tej umiejętności, można ci łatwo przeszkodzić.','Pułapka. (90 sek.) Działa na przeciwników w pobliżu. Zadaje 5...50 pkt. obrażeń przebijających. Przeciwnikom z pękniętą zbroją zadaje po 15...60 pkt. dodatkowych obrażeń. Łatwo przerwać.'],
2141=>['Współpraca','Umiejętność. Jeżeli masz mniej pkt. żywotności niż twój zwierzęcy towarzysz, to otrzymujesz 30...120 pkt. żywotności. Jeżeli twój zwierzęcy towarzysz ma mniej pkt. żywotności niż ty, to otrzymuje 30...120 pkt. żywotności.','Umiejętność. Otrzymujesz 30...120 pkt. żywotności, jeżeli posiadasz mniej żywotności niż twój zwierzęcy towarzysz. Twój zwierzęcy towarzysz otrzymuje 30...120 pkt. żywotności, jeżeli posiada mniej żywotności niż ty.'],
2142=>['Zwierzęca Agresja','Umiejętność. Przez 5...20 sek., twój zwierzęcy towarzysz atakuje o 33% szybciej i zadaje 3...10 pkt. dodatkowych obrażeń.','Umiejętność. (5...20 sek.) Twój zwierzęcy towarzysz atakuje o 33% szybciej i zadaje +3...10 pkt. obrażeń.'],
2143=>['Rozpraszający Strzał','Strzał z łuku. Jeżeli atak trafi, przerywasz czynność wybranego przeciwnika. Jeżeli tą czynnością było użycie umiejętności, zadajesz +10...40 pkt. obrażeń.','Strzał z łuku. Przerywa czynność. Efekt przerwania: +10...40 pkt. obrażeń, jeżeli przerwałeś umiejętność.'],
2144=>['Salwa','Strzał z łuku. Wszystkie twoje przygotowania zostają przerwane. Wystrzeliwujesz strzały w wybranego przeciwnika i maksymalnie 3 przeciwników będących bezpośrednio przy nim. Te strzały trafiając, zadają +1...10 pkt. obrażeń.','Strzał z łuku. Zadaje +1...10 pkt. obrażeń. Trafia 3 przeciwników bezpośrednio przy twoim celu. Usuwane są twoje wszystkie przygotowania.'],
2145=>['Skupienie Specialisty','Przygotowanie. Przez 24 sek., twoje umiejętności ataku za pomocą łuku kosztują o 1...2 pkt. energii mniej i zadają 1...10 pkt. dodatkowych obrażeń.','Przygotowanie. (24 sek.) Twoje umiejętności ataku za pomocą łuku kosztują o 1...2 pkt. energii mniej i zadają +1...10 pkt. obrażeń.'],
2146=>['Nabożna Furia','Postawa. Usuwa jedno zaklęcie derwisza. Przez 1...7 sek. atakujesz o 25% szybciej. Jeśli zostało usunięte jakieś zaklęcie, postawa ta trwa dwa razy dłużej.','Postawa. (1...7 sek.) Atakujesz 25% szybciej i usuwasz 1 ze swoich zaklęć derwisza. Efekt usunięcia: Postawa ta trwa dwa razy dłużej.'],
2147=>['Okulawiające Zwycięstwo','Atak kosą. Jeśli ten atak trafi przeciwnika, zostaje on okaleczony na 3...8 sek. Jeśli masz więcej żywotności niż cel, wszyscy pobliscy wrogowie otrzymują 10...30 pkt. obrażeń od ziemi.','Atak kosą. (3...8 sek.) Okalecza cel. Jeśli masz więcej żywotności niż cel, wszyscy pobliscy wrogowie otrzymują 10...30 pkt. obrażeń od ziemi.'],
2148=>['Penetrująca Broń','Czar z broni. Przez 4...10 sek., następne 3 ataki wybranego sojusznika posiadają 10% przebicie pancerza i na 5...20 sek. wywołują pękniętą zbroję.','Czar z broni. (4...10 sek.) Następne 3 ataki wybranego sojusznika wywołują przypadłość pęknięta zbroja (5...20 sek.) i posiadają 10% przebicie pancerza.'],
2149=>['Oręż Odnowienia','Czar z broni. Przez 5...20 sek., kiedy następnym razem wybrany sojusznik trafi używając umiejętności związanej z atakowaniem, otrzyma 1...7 pkt. energii.','Czar z broni. (5...20 sek.) Wybrany sojusznik otrzymuje 1...7 pkt. energii następnym razem, kiedy trafi jego umiejętność związana z atakami.'],
2150=>['Włócznia Obłędu','Atak włócznią. Jeżeli twój atak trafi krwawiącego przeciwnika, to przeciwnik ten zostaje okulawiony na 5...20 sek.','Atak włócznią. Wywołuje przypadłość okulawienie (5...20 sek.), jeżeli wybrany przeciwnik krwawi.'],
2186=>['Sygnet Śmiertelnego Zepsucia','Sygnet. Zaatakowany wróg otrzymuje 5...35 pkt. obrażeń za każdą posiadaną przypadłość (maksymalnie 130 pkt. obrażeń).','Sygnet. Zadaje 5...35 pkt. obrażeń (maksymalnie 130) za każdą przypadłość na wybranym przeciwniku.'],
2187=>['Ścieżka Wojownika','Zaklęcie (czar). Przez 60 sek., trzymając broń nie będącą sztyletami posiadasz 3...33% dodatkowych szans na wykonanie trafienia krytycznego.','Zaklęcie (czar). (60 sek.) Trzymając broń nie będącą sztyletem posiadasz +3...33% szans na trafienia krytyczne.'],
2188=>['Splugawienie Obrony','Klątwa (czar). Przez 5...20 sek., kiedy następnym razem wybrany przeciwnik zablokuje trafienie, otrzyma 30...120 pkt. obrażeń.','Klątwa (czar). (5...20 sek.) Zadaje 30...120 pkt. obrażeń następnym razem, kiedy wybrany przeciwnik wykona blok.'],
2189=>['Spojrzenie Angorodona','Czar. Wybranemu przeciwnikowi wykradasz 10...50 pkt. żywotności. Jeżeli jesteś pod działaniem przypadłości, otrzymujesz 3...12 pkt. energii.','Czar. Wykrada 10...50 pkt. żywotności. Otrzymujesz 3...12 pkt. energii, jeżeli jesteś pod działaniem przypadłości.'],
2190=>['Fala Magnetyczna','Zaklęcie (czar). Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Podczas Przemagicznienia, Fala Magnetyczna wzmacnia wszystkich sojuszników w zasięgu słuchu na 1...5 sek. w blokowaniu nadchodzących ataków.','Zaklęcie (czar). Zadaje 15...75 pkt. obrażeń. Podczas Przemagicznienia, sojusznicy w zasięgu słuchu zostają wzmocnieni na 1...5 i blokują następny atak.'],
2191=>['Śliskie Podłoże','Czar. Jeśli cel lub sąsiadujący przeciwnicy są oślepieni lub w ruchu, to ci przeciwnicy zostają powaleni. istnieje 50% szansy na niepowodzenie Magii Wody poniżej 5.','Czar. Powoduje powalenie, jeżeli przeciwnik jest w ruchu lub jest oślepiony. Dotyczy wrogów stojących obok celu. 50% szansy na porażkę chyba, że Magia Wody jest na poziomie 4 lub wyższym.'],
2192=>['Błyszczący Lód','Czar. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od zimna. Jeżeli jest on pod działaniem klątwy z Magii Wody, otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii.','Czar. Zadaje 5...50 pkt. obrażeń od zimna. Otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii, jeżeli wybrany przeciwnik jest pod działaniem klątwy z Magii Wody.'],
2193=>['Wybuch Energii','Czar. Za każdy punkt energii, który posiadasz, wybrany przeciwnik otrzymuje 1...2 pkt. obrażeń (maksymalnie 130 pkt. obrażeń).','Czar. Zadaje 1...2 pkt. obrażeń (maksymalnie 130) za każdy punkt energii, który posiadasz.'],
2194=>['Rozpraszające Uderzenie','Atak wręcz. Jeżeli Rozpraszające Uderzenie trafi, nie zadaje obrażeń, ale przerywa czynność wybranego przeciwnika. Jeżeli cel jest pod działaniem Pękniętej Zbroi, to ta umiejętność będzie niedostępna przez 30 sek.','Atak wręcz. Przerywa czynność. Efekt przerwania: Wyłącza przerwaną umiejętność (30 sek.), jeżeli wybrany przeciwnik ma pękniętą zbroję. Nie zadaje obrażeń.'],
2195=>['Symboliczne Uderzenie','Atak wręcz. Jeżeli atak trafi, zadajesz +12 pkt. obrażeń na każdy sygnet, który masz na pasku umiejętności (maksymalnie 70 pkt. obrażeń).','Atak wręcz. Zadaje +12 pkt. obrażeń (maksymalnie 70) za każdy sygnet, który masz na pasku umiejętności.'],
2196=>['Szybkość Żołnierza','Postawa. Przez 3...18 sek., poruszasz się o 15% szybciej. Oprócz tego, poruszasz się jeszcze o 15% szybciej, jeśli znajdujesz się pod działaniem okrzyku lub pieśni.','Postawa. (3...18 sek.) Poruszasz się o 15% szybciej oraz dodatkowo o 15% szybciej, jeśli jesteś pod działaniem okrzyku lub pieśni.'],
2197=>['Uderzenie w Korpus','Atak wręcz. Jeżeli atak trafi, wybrany przeciwnik otrzymuje +10...40 pkt. obrażeń. Jeżeli cel jest pod działaniem Pękniętej Zbroi, to na 0...15 sek. otrzymuje głęboką ranę.','Atak wręcz. Zadaje +10...40 pkt. obrażeń. Wywołuje przypadłość głęboka rana (0...15 sek.), jeżeli wybrany przeciwnik ma pękniętą zbroję.'],
2198=>['Strzał w Korpus','Strzał z łuku. Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeżeli trafi przeciwnika będącego pod działaniem Pękniętej Zbroi, to otrzymujesz 5...10 punktów energii.','Strzał z łuku. Zadaje +5...20 pkt. obrażeń. Otrzymujesz 5...10 pkt. energii, jeżeli wybrany przeciwnik ma pękniętą zbroję.'],
2199=>['Sygnet Zatrutego Oręża','Sygnet. Przez 60 sek., twój następny atak zatruwa także cel na 8...15 sek.','Sygnet. (60 sek.) Twój następny atak wywołuje przypadłość zatrucie (8...15 sek.).'],
2200=>['Sygnet Mistycznej Prędkości','Sygnet. Przez 30 sek., twoje kolejne (1...3) skierowane na ciebie zaklęcia są rzucane natychmiastowo. Zaklęcia błysku nie zużywają tej umiejętności.','Sygnet. (30 sek.) Twoje kolejne (1...3) skierowane na ciebie zaklęcia są rzucane natychmiast. Zaklęcia błysku nie zużywają tej umiejętności.'],
2201=>['Tarcza Mocy','Zaklęcie błysku (czar). Przez 1...16 sek., blokuje kolejne ataki (1) przeciwko tobie. Jeśli dojdzie do zablokowania ataku, wszyscy właśnie atakujący wrogowie w bezpośrednim sąsiedztwie zostają powaleni i cierpią na osłabienie przez 5...20 sek.','Zaklęcie błysku (czar). (1...16 sek.) Blokuje kolejne ataki (1) wymierzone w ciebie. Powala i powoduje osłabienie (na 5...20 sek.) wszystkich atakujących właśnie wrogów w bezpośrednim sąsiedztwie.'],
2202=>['Odnawiający Uchwyt','Czar. Uzdrawiasz wybranego sojusznika dodając mu 30...90 pkt. żywotności. Jeżeli wybrany sojusznik jest pod działaniem zaczarowanej broni, to traci jedną przypadłość.','Czar. Dodaje 30...90 pkt. żywotności. Usuwa jedną przypadłość, jeżeli wybrany sojusznik ma zaczarowaną broń.'],
2203=>['Aura Duchowej Pijawki','Umiejętność. Przez 5...20 sek., wszystkie twoje duchy w zasięgu słuchu zadają o 5...20 mniej obrażeń i przy każdym ataku wykradają 5...20 pkt. żywotności.','Umiejętność. (5...20 sek.) Wszystkie twoje duchy w zasięgu słuchu zadają o 5...20 mniej obrażeń i przy każdym ataku'],
2204=>['Odmłodzenie','Rytuał spętania. Tworzysz 1...20 poziomowego ducha. Duch uzdrawia każdego członka drużyny w zasięgu słuchu, w każdej sekundzie dodając mu 3...10 pkt. żywotności. Duch traci 3...10 pkt. żywotności, na każdego członka drużyny uzdrowionego w ten sposób. Duch ginie po 30...90 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...20 (czas życia 30...90 sek.). Członkowie drużyny w zasięgu słuchu otrzymują co sekundę po 3...10 pkt. żywotności. Koszt uleczenia: ten duch traci 3...10 pkt. żywotności.'],
2205=>['Agonia','Rytuał spętania. Tworzysz 1...12 poziomowego ducha. Obecność ducha powoduje, że każdy przeciwnik w jego zasięgu słuchu co sekundę traci 3...10 pkt. żywotności. Duch traci 3...10 pkt. żywotności, na każdego przeciwnika, który w ten sposób ucierpi. Duch ginie po 30...90 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...12 (czas życia 30...90 sek.). Przeciwnicy w zasięgu słuchu co sekundę tracą 3...10 pkt. żywotności. Ten duch traci 3...10 pkt. żywotności na każdego przeciwnika, który traci żywotność.'],
2206=>['Widmowy Oręż','Czar z broni. Przez 5...20 sek., następny atak wybranego sojusznika innego niż ty nie może zostać zablokowany.','Czar z broni. (5...20 sek.) Następny atak wybranego sojusznika jest nie do zablokowania. Na cel nie można wybrać siebie.'],
2207=>['Inspirująca Przemowa','Umiejętność. Tracisz całą adrenalinę, a wybrany sojusznik inny niż ty otrzymuje dawki adrenaliny w liczbie 1...8.','Umiejętność. Wybrany sojusznik otrzymuje dawki adrenaliny w liczbie 1...8. Na cel nie można wybrać siebie. Tracisz całą adrenalinę.'],
2208=>['Płonąca Tarcza','Umiejętność. Przez 3...9 sek., kiedy trzymasz tarczę, następna umiejętność związana z atakiem użyta przeciwko tobie zostanie zablokowana. Jeżeli był to atak wręcz, to atakujący zostaje podpalony na 1...6 sek.','Umiejętność. (3...9 sek.) Blokuje następną umiejętność związaną z atakiem, której jesteś celem. Wywołuje przypadłość płonięcie (1...6 sek.), jeżeli był to atak wręcz. Bez efektu, jeśli nie dzierżysz tarczy.'],
2209=>['Święta Włócznia','Atak włócznią. Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli trafi przyzwane stworzenie, to wszyscy przeciwnicy w pobliżu otrzymują po 15...90 pkt. świętych obrażeń i na 3 sek. zostają podpaleni.','Atak włócznią. Zadaje +5...20 pkt. obrażeń. Przeciwnikom w pobliżu zadaje 15...90 pkt. świętych obrażeń i wywołuje przypadłość płonięcie (3 sek.), jeżeli trafisz przyzwanie stworzenie.'],
2210=>['Zamach Włócznią','Atak włócznią. Jeżeli atak trafi, zadaje +5...20 pkt. obrażeń, a wybrany przeciwnik zostaje oszołomiony na 4...10 sek. Ten atak działa w zasięgu walki wręcz.','Atak włócznią w walce wręcz. Zadaje +5...20 pkt. obrażeń i wywołuje przypadłość oszołomienie (4...10 sek.). Ten atak działa w zasięgu walki wręcz.'],
2211=>['Alchemiczny Kwas Alkara','Czar. Rzucasz Alchemicznym Kwasem Alkara w wybranego przeciwnika. Cel i przeciwnicy bezpośrednio przy nim otrzymują po 40...50 pkt. obrażeń. Niszczyciele otrzymują dodatkowe 45...70 pkt. obrażeń i na 14...20 sek. znajdą się pod działaniem kruchej zbroi.','Czar. Pocisk: wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 40...50 pkt. obrażeń. Niszczycielom zadaje 45...70 pkt. dodatkowych obrażeń i wywołuje u nich przypadłość pęknięta zbroja (14...20 sek.).'],
2212=>['Światło Deldrimoru','Czar. Wszyscy przeciwnicy w okolicy otrzymują po 55...80 pkt. świętych obrażeń. Położenie ukrytych obiektów będzie przez chwilę pokazane na twoim kompasie. Pokazane zostaną wszystkie ukryte obiekty w okolicy.','Czar. Przeciwnikom w okolicy zadaje po 55...80 pkt. świętych obrażeń. Pokazuje na kompasie wszystkie ukryte obiekty w okolicy.'],
2213=>['Ugryzienie w Ucho','Umiejętność. Dotknięty wybrany przeciwnik otrzymuje 50...70 pkt. obrażeń przebijających i zaczyna krwawić na 15...25 sek.','Umiejętność dotykowa. Zadaje 50...70 pkt. obrażeń przebijających i wywołuje przypadłość krwawienie (15...25 sek.).'],
2214=>['Cios Poniżej Pasa','Umiejętność. Wybranemu przeciwnikowi zadajesz +45...70 pkt. obrażeń. Jeżeli zostanie powalony, otrzymuje dodatkowe 30...50 pkt. obrażeń i cierpi z powodu pęknięcia zbroi przez 14...20 sek.','Umiejętność dotykowa. Zadaje 45...70 pkt. obrażeń. Zadaje dodatkowe 30...50 obrażeń i powoduje pęknięcie zbroi (14...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
2215=>['Awanturnicze Uderzenie Głową','Umiejętność. Uderzasz głową dotkniętego wybranego przeciwnika i jeśli trafisz, zadajesz mu 45...70 pkt. obrażeń i powalasz go.','Umiejętność dotykowa. Zadaje 45...70 pkt. obrażeń; powala.'],
2216=>['"Nie Potykaj Się!"','Okrzyk. Przez 3...5 sek., członkowie drużyny w zasięgu słuchu nie mogą zostać powaleni.','Okrzyk. (3...5 sek.) Chroni przed powaleniem; działa na członków drużyny w zasięgu słuchu.'],
2217=>['"Na Młot Urala!"','Okrzyk. Przez 30 sek., wszyscy martwi członkowie drużyny w zasięgu słuchu zostają wskrzeszeni z pełną żywotnością i energią. Wskrzeszeni członkowie drużyny zadają 25...33% więcej obrażeń. Kiedy ten efekt dobiegnie końca, członkowie drużyny będący pod jego wpływem umierają. Umiejętność ta nie powoduje kary za śmierć.','Okrzyk. (30 sek.) Wskrzesza wszystkich martwych członków drużyny w zasięgu słuchu z pełną żywotnością i energią. Wskrzeszeni członkowie drużyny zadają 25...33% więcej obrażeń. Członkowie drużyny umierają, kiedy skończy się działanie tego efektu, ale nie otrzymują kary za śmierć.'],
2218=>['Pijacki Mistrz','Postawa. Przez 72...90 sek. poruszasz się i atakujesz o 10...15% szybciej. Z kolei jeżeli jesteś pijany aktywując tą umiejętność, to poruszasz się i atakujesz o 25...33% szybciej.','Postawa. (72...90 sek.) Poruszasz się i atakujesz o 10...15% szybciej, jeżeli nie jesteś pijany. Poruszasz się i atakujesz o 25...33% szybciej, jeżeli jesteś pijany.'],
2219=>['Oręż Wielkiego Krasnoluda','Czar z broni. Przez 20 sek., broń wybranego sojusznika innego niż ty zadaje +15...20 pkt. obrażeń i posiada 28...40% szans na powalenie.','Czar z broni. (20 sek.) +15...20 pkt. obrażeń od broni i 28...40% szans na powalenie w czasie ataków. Na cel nie można wybrać siebie.'],
2220=>['Wspaniała Krasnoludzka Zbroja','Zaklęcie (czar). Przez 22...40 sek., wybrany sojusznik posiada +24 pkt. pancerza, +60 pkt. maksymalnej żywotności oraz dodatkowe +24 pkt. pancerza przeciwko niszczycielom.','Zaklęcie (czar). (22...40 sek.) +24 pkt. pancerza i +60 pkt. do maksymalnej żywotności. Dodatkowo +24 pkt. pancerza przeciwko niszczycielom.'],
2221=>['Tchnienie Wielkiego Krasnoluda','Czar. Wszyscy członkowie drużyny przestają płonąć i otrzymują po 50...60 pkt. żywotności.','Czar. Usuwa płonięcie i dodaje 50...60 pkt. żywotności; działa na członków drużyny.'],
2222=>['Śnieżna Burza','Czar. Wywołujesz Śnieżną Burzę w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy bezpośrednio przy tym miejscem otrzymują w każdej sekundzie po 30...40 pkt. obrażeń od zimna.','Czar. W każdej sekundzie zadaje 30...40 pkt. obrażeń od zimna (5 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu wybranego przeciwnika.'],
2223=>['Prochowa Mina','Pułapka. Kiedy Prochowa Mina zostanie uaktywniona, wszyscy przeciwnicy w pobliżu otrzymują po 20...30 pkt. obrażeń i przez 7...10 sek. będą oślepieni i będą krwawili. Prochowa Mina przestanie działać po 90 sek. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','Pułapka. (90 sek.) Działa na przeciwników w pobliżu. Zadaje 20...30 pkt. obrażeń. Wywołuje przypadłości oślepienie oraz krwawienie (7...10 sek.). Łatwo przerwać.'],
2224=>['Przywołanie Mursaata','Czar. Przywołujesz mursaata na poziomie 14...20, który żyje przez 40...60 sek. i posiada Osłabiający Ładunek. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.','Czar. Przywołuje mursaata na poziomie 14...20 (czas życia 40...60 sek.), który posiada Osłabiający Ładunek. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.'],
2225=>['Przywołanie Rubinowego Dżinna','Czar. Przywołujesz rubinowego dżinna na poziomie 14...20, który żyje przez 40...60 sek. i posiada Samospalenie. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.','Czar. Przywołuje rubinowego dżinna na poziomie 14...20 (czas życia 40...60 sek.), który posiada Samospalenie. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.'],
2226=>['Przywołanie Lodowego Impa','Czar. Przywołujesz lodowego impa na poziomie 14...20, który żyje przez 40...60 sek. i posiada Lodowe Kolce. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.','Czar. Przywołuje lodowego impa na poziomie 14...20 (czas życia 40...60 sek.), który posiada Lodowe Kolce. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.'],
2227=>['Przywołanie Szamana Nag','Czar. Przywołujesz szamana nag na poziomie 14...20, który żyje przez 40...60 sek. i posiada Ukamienowanie. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.','Czar. Przywołuje szamana nag na poziomie 14...20 (czas życia 40...60 sek.), który posiada Ukamienowanie. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.'],
2228=>['Wprawny Cios','Atak z dystansu. Jeżeli atak trafi, wybrany przeciwnik otrzymuje 18...30 pkt. obrażeń. Jeżeli cel jest pod działaniem kruchej zbroi, będzie krwawił przez 18...30 sek.','Atak z dystansu. Zadaje 18...30 pkt. obrażeń. Wywołuje przypadłość krwawienie (18...30 sek.), jeżeli wybrany przeciwnik ma pękniętą zbroję.'],
2229=>['Sygnet Infekcji','Sygnet. Jeżeli wybrany przeciwnik krwawi, to przez 13...20 sek. będzie pod działaniem choroby.','Sygnet. Wywołuje przypadłość choroba (13...20 sek.), jeżeli wybrany przeciwnik krwawi.'],
2230=>['Sygnet Tryptofanu','Sygnet. Przez 14...20 sek., wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim poruszają się i atakują o 23...40% wolniej.','Sygnet. (14...20 sek.) Wybrany przeciwnik i przeciwnicy bezpośrednio przy nim poruszają się i atakują o 23...40% wolniej.'],
2231=>['Sztandar Odwagi Hebanowej Awangardy','Ochrona (czar). W miejscu, w którym stoisz wbijasz Sztandar Odwagi Hebanowej Awangardy. Przez 14...20 sek., nie będący duchami sojusznicy na tym obszarze otrzymują +24 pkt. pancerza i dodatkowo +24 pkt. pancerza przeciwko popielcom.','Ochrona (czar). (14...20 sek.) Sojusznicy w granicach tej ochrony posiadają +24 pkt. pancerza i dodatkowo +24 pkt. pancerza przeciwko popielcom. Nie działa na duchy.'],
2232=>['Sztandar Mądrości Hebanowej Awangardy','Ochrona (czar). W miejscu, w którym stoisz wbijasz Sztandar Mądrości Hebanowej Awangardy. Przez 14...20 sek., nie będący duchami sojusznicy na tym obszarze mają 44...60% szans na skrócenie o połowę czasu odnawiania czarów.','Ochrona (czar). (14...20 sek.) Czary rzucane przez sojuszników w granicach tej ochrony mają 44...60% szans na odnawianie się o 50% szybciej. Nie działa na duchy.'],
2233=>['Sztandar Honoru Hebanowej Awangardy','Ochrona (czar). W miejscu, w którym stoisz wbijasz Sztandar Honoru Hebanowej Awangardy. Przez 14...20 sek., nie będący duchami sojusznicy na tym obszarze zadają +8...15 pkt. obrażeń i dodatkowo +7...10 pkt. obrażeń przeciwko popielcom.','Ochrona (czar). (14...20 sek.) Sojusznicy w granicach tej ochrony zadają +8...15 pkt. obrażeń i dodatkowo +7...10 pkt. obrażeń przeciwko popielcom. Nie działa na duchy.'],
2234=>['Wsparcie Strzelca Hebanowej Awangardy','Czar. Wybrany przeciwnik otrzymuje 54...90 pkt. obrażeń przebijających i zaczyna krwawić na 5...25 sek.Ten atak posiada 10% szans na zadanie dodatkowych 540...900 pkt. obrażeń przebijających. Jeżeli trafi popielca ma 25% szans na zadanie dodatkowych 540...900 pkt. obrażeń przebijających.','Czar. Zadaje 54...90 pkt. obrażeń przebijających i wywołuje przypadłość krwawienie (5...25 sek.). 10% szans na +540...900 pkt. obrażeń przebijających. 25% szans na +540...900 pkt. obrażeń przebijających, jeżeli celem jest popielec.'],
2235=>['Wsparcie Zabójcy Hebanowej Awangardy','Czar. Przywołujesz Zabójcę Hebanowej Awangardy na poziomie 14...20, który posiada Żelazną Dłoń, Lisie Kły oraz Uderzenie Dziewięciu Ogonów. Ten przywołany zabójca wykonuje krok cienia do wybranego przeciwnika. Jeżeli wybranym przeciwnikiem jest popielec, to zabójca żyje przez 24...30 sek. Jeżeli wybranym przeciwnikiem nie jest popielec, to zabójca żyje przez 12...15 sek.','Czar. Przywołuje zabójcę na poziomie 14...20, który posiada Żelazną Dłoń, Lisie Kły oraz Uderzenie Dziewięciu Ogonów; wykonuje on krok cienia do tego przeciwnika. Jeżeli tym przeciwnikiem jest popielec, to zabójca żyje przez 24...30 sek. Jeżeli tym przeciwnikiem nie jest popielec, to zabójca żyje przez 12...15 sek.'],
2236=>['Studnia Zniszczenia','Czar studni. Wykorzystujesz najbliższe zwłoki lub poświęcasz 66% zdrowia, by utworzyć we wskazanym miejscu Studnię Zniszczenia. Przez 5...30 sek., gdy wybrany przeciwnik otrzyma obrażenia, będąc w studni, na 5...20 sek. ma pękniętą zbroję.','Czar studni. (5...30 sek.). U przeciwników będących w studni, którzy otrzymają obrażenia fizyczne, wywołuje przypadłość pękniętej zbroi (5...20 sek.). Zużywa świeże ciało lub poświęca 66% zdrowia.'],
2237=>['Zwyrodnienie','Klątwa (czar). Przez 3...7 sek. atrybut podstawowy wybranego przeciwnika jest równy 0.','Klątwa (czar). (3...7 sek.) Obniża atrybut podstawowy tego przeciwnika do 0.'],
2238=>['Włócznia Odkupienia','Atak włócznią. Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli nie trafi, to tracisz jedną przypadłość.','Atak włócznią. Zadaje +5...20 pkt. obrażeń. Jeśli nie trafi, to tracisz jedną przypadłość.'],
2353=>['"Skończ z Nim!"','Okrzyk. Jeżeli wybrany przeciwnik posiada mniej niż 50% żywotności, to otrzymuje 44...80 pkt. obrażeń i na 12...20 sek. znajdzie się pod działaniem Pękniętej Zbroi oraz głębokiej rany.','Okrzyk. Zadaje 44...80 pkt. obrażeń i wywołuje przypadłości pęknięta zbroja oraz głęboka rana (12...20 sek.). Bez efektu, chyba że wybrany przeciwnik ma mniej niż 50% żywotności.'],
2354=>['"Uniknij Tego!"','Okrzyk. Przez 16...20 sek. twój następny atak nie może zostać zablokowany i zadaje +14...20 pkt. obrażeń.','Okrzyk. (16...20 sek.) Twój następny atak jest nie do zablokowania i zadaje +14...20 pkt. obrażeń.'],
2355=>['Jestem najpotężniejszy!','Okrzyk. Twoje kolejne ataki w liczbie 5...8 zadają +14...20 pkt. obrażeń każdy.','Okrzyk. Twoje kolejne ataki w liczbie 5...8 zadają +14...20 pkt. obrażeń.'],
2356=>['"Nikt Mnie Nie Zatrzyma!"','Okrzyk. Przez 16...20 sek., posiadasz +24 pkt. pancerza i nie możesz zostać powalony ani okulawiony.','Okrzyk. (16...20 sek.) Posiadasz +24 pkt. pancerza i nie możesz zostać powalony ani okulawiony.'],
2357=>['Podstępny Dotyk','Klątwa (czar). Dotknięty wybrany przeciwnik otrzymuje 44...80 pkt. obrażeń. Jeśli ten przeciwnik jest powalony, to nie może atakować przez 5...8 sek.','Klątwa dotykowa - czar. Zadaje 44...80 pkt. obrażeń. Wybrany przeciwnik nie może atakować (5...8 sek.), jeżeli był powalony.'],
2358=>['"Ruszasz Się Jak Krasnolud!"','Okrzyk. Cel zostaje powalony na ziemię i otrzymuje 44...80 pkt. obrażeń. Wróg ten zostaje też okulawiony na 8...15 sek.','Okrzyk. Zadaje 44...80 obrażeń, powala na ziemię i powoduje okulawienie (8...15 sek).'],
2359=>['"Wszyscy Jesteście Słabeuszami!"','Okrzyk. Wybrany przeciwnik i przeciwnicy bezpośrednio przy nim zostają osłabieni na 8...12 sek.','Okrzyk. Wywołuje przypadłość osłabienie (8...12 sek.). Działa także na przeciwników w bezpośredniej odległości.'],
2360=>['Nie Czuję Bólu','Umiejętność. Przez 30 sek. posiadasz regenerację żywotności +2...3. Jeżeli jesteś pijany aktywując tą umiejętność, to dodatkowo twoja maksymalna żywotność zwiększa się o +200...300 pkt.','Umiejętność. (30 sek.) Posiadasz regenerację żywotności +2...3. Twoja maksymalna żywotność zwiększa się o +200...300 pkt., jeżeli jesteś pijany aktywując tą umiejętność.'],
2361=>['Maczuga Tysiąca Niedźwiedzi','Atak wręcz. Jeżeli atak trafi, zadajesz +6...9 pkt. obrażeń na każdego przeciwnika bezpośrednio przy tobie (maksymalnie 60 pkt. obrażeń). Jeśli przeciwnik nie jest człowiekiem, to zostaje powalony.','Atak wręcz. Zadaje +6...9 pkt. obrażeń za każdego przeciwnika w bezpośredniej odległości (maksymalnie 60). Powoduje powalenie, jeżeli wybrany przeciwnik nie jest człowiekiem.'],
2374=>['Błogosławieństwo Niedźwiedzicy','Elitarna forma. Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu niedźwiedzicy. Przez 60 sek. posiadasz 100 pkt. pancerza i 750...800 pkt. żywotności. Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki niedźwiedzicy.','Elitarna forma. Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu niedźwiedzicy (60 sek.). Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki niedźwiedzicy. Posiadasz 100 pkt. pancerza i 750...800 pkt. żywotności.'],
2379=>['Błogosławieństwo Wilka','Elitarna forma. Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu wilka. Przez 60 sek. posiadasz 80 pkt. pancerza, 660...700 pkt. żywotności oraz regenerację żywotności 2...4. Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki wilka.','Elitarna forma. Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu wilka (60 sek.). Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki wilka. Posiadasz 80 pkt. pancerza, 660...700 pkt. żywotności oraz regenerację żywotności 2...4.'],
2384=>['Błogosławieństwo Kruka','Elitarna forma. Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu kruka. Przez 60 sek. posiadasz 80 pkt. pancerza, 660...700 pkt. żywotności i 20...30% szans na blokowanie. Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki kruka.','Elitarna forma. Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu kruka (60 sek.). Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki kruka. Posiadasz 80 pkt. pancerza, 660...700 pkt. żywotności i 20...30% szans na blokowanie.'],
2411=>['Umysłowe Upojenie','Zaklęcie (czar). Przez 10...16 sek., poruszasz się o 20...33% szybciej, a rzucanie twoich czarów trwa 20% krócej.','Zaklęcie (czar). (10...16 sek.) Poruszasz się o 20...33% szybciej, a czary rzucasz o 20% szybciej.'],
2412=>['Wykroczenie','Czar. Na 10...20 sek. jeden losowy czar wybranego przeciwnika zostaje wyłączony, a Wykroczenie zostaje zastąpione tym czarem. Otrzymujesz 5...10 pkt. energii.','Czar. (10...20 sek.) Wyłącza jeden czar. Ta umiejętność staje się tym czarem. Otrzymujesz 5...10 pkt. energii.'],
2413=>['Technobełkot','Czar. Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 30...40 pkt. obrażeń. Jeżeli wybrany przeciwnik nie jest bossem, to on i wszyscy przeciwnicy bezpośrednio przy nim zostają oszołomieni na 3...5 sek.','Czar. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 30...40 pkt. obrażeń. U tych przeciwników wywołuje przypadłość oszołomienie (3...5 sek.), jeżeli cel nie był bossem.'],
2414=>['Napromieniowany Obszar','Ochrona (czar). Przez 5 sek., przeciwnicy w okolicy posiadają degenerację żywotności -4...6. Kiedy portal przestanie działać, przeciwnicy w okolicy znajdą się na 12...20 sek. pod działaniem choroby.','Ochrona (czar). (5 sek.) Przeciwnicy w okolicy posiadają degenerację żywotności -4...6. Efekt końcowy: u przeciwników w okolicy wywołuje przypadłość choroba (12...20 sek.).'],
2415=>['Asuriańskie Rozpoznanie','Klątwa (czar). Przez 9...12 sek., twoje ataki nie mogą chybić wybranego przeciwnika. Zabicie wroga, który znajdował się pod wpływem Asuriańskiego Rozpoznania, usuwa 5% kary za śmierć.','Klątwa (czar). (9...12 sek.) Nie możesz chybić przeciwnika. Jeśli zabijesz tego przeciwnika, tracisz 5% kary za śmierć.'],
2416=>['Powietrze Doskonałości','Umiejętność. Przez 20...30 sek., za każdym razem, kiedy zdobędziesz punkty doświadczenia za zabicie przeciwnika, otrzymasz losowy asuriański dar.','Umiejętność. (20...30 sek.) Za każdym razem, kiedy zdobędziesz punkty doświadczenia za zabicie przeciwnika, otrzymasz losowy asuriański dar.'],
2417=>['Mentalny Blok','Zaklęcie (czar). Przez 5...11 sek. masz 50% szans na blokowanie ataków. Zaklęcie zostaje ponownie nałożone za każdym razem, kiedy przeciwnik cię trafi.','Zaklęcie (czar). (5...11 sek.) Masz 50% szans na blokowanie. Odnowienie: za każdym razem, kiedy przeciwnik cię trafi.'],
2418=>['Odwrócenie Bólu','Klątwa (czar). Przez 6...10 sek., za każdym razem, kiedy wybrany przeciwnik zadaje obrażenia, otrzymuje 100...140% obrażeń, które zadaje (maksymalnie 80 pkt. obrażeń).','Klątwa (czar). (6...10 sek.) Za każdym razem, kiedy wybrany przeciwnik zadaje obrażenia umiejętność zadaje mu 100...140% tych obrażeń (maksymalnie 80).'],
2420=>['Ucieczka Hebanowej Awangardy','Czar. Wykonujesz krok cienia do wybranego sojusznika innego niż ty. Ty i ten sojusznik otrzymujecie po 70...110 pkt. żywotności.','Czar. Tobie i wybranemu sojusznikowi dodaje po 70...110 pkt. żywotności. Efekt początkowy: wykonujesz krok cienia do tego sojusznika. Na cel nie można wybrać siebie.'],
2421=>['Osłabiająca Pułapka','Pułapka. Kiedy Osłabiająca Pułapka zostanie uaktywniona, wszyscy przeciwnicy w pobliżu zostają osłabieni na 10...20 sek. Wszyscy popielcy zostają powaleni. Osłabiająca Pułapka przestaje działać po 90 sekundach. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','Pułapka. (90 sek.) Działa na przeciwników w pobliżu. Zadaje 24...50 pkt. obrażeń od błyskawic. Wywołuje przypadłość osłabienie (10...20 sek.). Powala popielca. Łatwo przerwać.'],
2422=>['Wichry','Rytuał Hebanowej Awangardy. Tworzysz ducha na 4...10 poziomie. Wszyscy przeciwnicy w jego zasięgu mają 15% szans na nietrafianie atakami zasięgowymi. Duch ginie po 54...90 sek.','Rytuał Hebanowej Awangardy. Tworzy ducha na poziomie 4...10 (czas życia 54...90 sek.). Działa na przeciwników w zasięgu. 15% szans na nietrafianie ataków zasięgowych.'],
2423=>['Krasnoludzka Stabilność','Zaklęcie (czar). Przez 24...30 sek. twoje postawy trwają o 55...100% dłużej. Jeśli aktywujesz tą umiejętność będąc pijanym, nie możesz zostać powalony.','Zaklęcie (czar). (24...30 sek.) Twoje postawy trwają o 55...100% dłużej. Nie możesz zostać powalony, jeśli aktywowałeś tą umiejętność będąc pijanym.'],
2657=>['Zew Pośpiechu (PvP)','Okrzyk. Przez 30 s twój zwierzęcy towarzysz atakuje i porusza się o 25% szybciej.','Okrzyk. (30 sekund) Twój zwierzak porusza się i atakuje o 25% szybciej.'],
2734=>['Spustoszenie Umysłu (PvP)','Klątwa (czar). Przez 5...40 sek., za każdym razem gdy dany przeciwnik będzie celem jednej z twoich klątw nie należących do mesmera, straci 1 energii. Jeśli energia wroga spadnie do 0, Spustoszenie Umysłu przestaje działać, a przeciwnik otrzymuje 15...100 pkt. obrażeń.','Klątwa (czar). (5...40 sek.) Powoduje utratę 1 energii za każdym razem, gdy dany przeciwnik staje się celem twojej klątwy spoza domeny mesmera. Jeśli energia wroga spadnie do 0, Spustoszenie Umysłu przestaje działać, a przeciwnik otrzymuje 15...100 pkt. obrażeń.'],
2803=>['Zamrożenie Umysłu','Elitarna klątwa (czar). Wybrany przeciwnik otrzymuje 10...60 pkt. obrażeń od zimna. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 10...60 pkt. obrażeń od zimna oraz porusza się o 90% wolniej przez 1...5 sek. Ten czar powoduje wyczerpanie.','Elitarna klątwa (czar). Zadaje 10...60 pkt. obrażeń od zimna. Jeżeli masz więcej pkt. energii niż wybrany przeciwnik, to umiejętność zadaje 10...60 pkt. dodatkowych obrażeń od zimna i o 90% spowalnia ruch (1...5 sek.). Powoduje u ciebie wyczerpanie.'],
2804=>['Wstrząs Mózgu','Elitarny czar. Wybrany przeciwnik otrzymuje 10...50 pkt. obrażeń od błyskawic. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 10...50 pkt. obrażeń od błyskawic oraz zostaje powalony. Ten czar posiada 25% przebicia pancerza, ale powoduje wyczerpanie.','Elitarny czar. Zadaje 10...50 pkt. obrażeń od błyskawic. Zadaje 10...50 pkt. dodatkowych obrażeń od błyskawic i powala, jeżeli masz więcej energii niż ten przeciwnik. 25% przebicie pancerza. Powoduje u ciebie wyczerpanie.'],
2805=>['Mglisty Kształt','Elitarne zaklęcie (czar). Przez 10...45 sek., nie możesz otrzymać, ani zadać obrażeń podczas ataku.','Elitarne zaklęcie (czar). (10...45 sek.) Nie otrzymujesz obrażeń z ataków. Twoje ataki nie zadają obrażeń.'],
2806=>['Ochrona przed Krzywdą','Elitarna ochrona (czar). W miejscu, w którym przebywasz, tworzysz Ochronę przed Krzywdą. Przez 5...15 sek. nie będący duchami sojusznicy w tej okolicy otrzymują po 12...24 pkt. pancerza przeciwko obrażeniom od ognia i po 1...3 pkt. pancerza przeciwko innym obrażeniom.','Elitarna ochrona (czar). (5...15 sek.) Sojusznicy w granicach tej ochrony posiadają +12...24 pkt. pancerza przeciwko obrażeniom od ognia i +1...3 pkt. pancerza przeciwko innym obrażeniom. Nie działa na duchy.'],
2807=>['Skok Błyskawicy','Elitarny czar. Błyskawicznie skaczesz do wybranego przeciwnika. Wybrany przeciwnik otrzymuje 10...70 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicie pancerza, ale powoduje wyczerpanie.','Elitarny czar. Zadaje 10...70 pkt. obrażeń od błyskawic. 25% przebicie pancerza. Natychmiast ruszasz do tego przeciwnika. Powoduje u ciebie wyczerpanie.'],
2808=>['Gniewne Uderzenie (PvP)','Elitarny atak młotem. Jeśli Gniewne Uderzenie trafi, otrzymujesz dawki adrenaliny (1...3). Jeśli trafisz poruszającego się wroga, zadajesz +10...40 pkt. obrażeń, a cel zostaje powalony na ziemię.','Elitarny atak młotem. Jeśli trafisz, otrzymujesz dawki adrenaliny (1...3). Jeśli przeciwnik się poruszał, zadaje mu +10...40 pkt. obrażeń i powala go na ziemię.'],
2809=>['Obsydianowy Płomień','Czar. Wybranemu przeciwnikowi zadajesz 22...92 pkt. obrażeń. Ten czar ignoruje pancerz, ale powoduje wyczerpanie.','Czar. Zadaje 22...92 pkt. obrażeń. Powoduje u ciebie wyczerpanie.'],
2857=>['Egida (PvP)','Zaklęcie (czar). Przez 1...3 sek., wybrany inny członek drużyny nie może być celem wrogich zaklęć, a ataki przeciwko niemu nie udają się.','Zaklęcie (czar). (1...3 sek.) Wybrany członek drużyny nie może być celem wrogich zaklęć. Ataki przeciwko niemu nie udają się. Nie można użyć na sobie.'],
2858=>['"Pilnujcie się!!" (PvP)','Okrzyk. Członkowie drużyny w zasięgu słuchu na 10 sek. otrzymują +5...25 pkt. pancerza. Ten zaśpiew przestanie działać po otrzymaniu 1...3 ataków.','Okrzyk. (10 sek.) Członkowie drużyny w zasięgu słuchu posiadają +5...25 pkt. pancerza. Przestanie działać po otrzymaniu 1...3 ataków.'],
2859=>['Osłabienie (PvP)','Czar. Przez 10...30 sek. wybrany przeciwnik cierpi na osłabienie.','Czar. Wywołuje przypadłość osłabienie (10...30 sek.).'],
2860=>['Eteryczna Odnowa (PvP)','Elitarne zaklęcie (czar). Przez 10 sek., za każdym razem, kiedy rzucasz czar, otrzymujesz 1...3 pkt. energii i 5...20 pkt. żywotności za każde zaklęcie, które masz na sobie.','Elitarne zaklęcie (czar). (10 sek.) Za każdym razem, kiedy rzucasz czar, otrzymujesz 1...3 pkt. energii i 5...20 pkt. żywotności, za każde zaklęcie, które masz na sobie.'],
2861=>['Przeszywający Atak (PvP)','Strzał z łuku. Jeśli Przeszywający Atak trafi, zadajesz +5...15 pkt. obrażeń. Ten atak ma 10% przebicie pancerza.','Strzał z łuku. Zadaje +5...15 pkt. obrażeń. 10% przebicie pancerza.'],
2862=>['Cienisty Kształt (PvP)','Elitarne zaklęcie (czar). Przez 5...15 sek. wszystkie wrogie czary, których jesteś celem, zawodzą oraz wszystkie ataki na ciebie nie trafiają. Gdy Cienisty Kształt przestanie działać, zostaje ci tylko 5...50 pkt. żywotności.','Elitarne zaklęcie (czar). (5...15 sek.) Wrogie czary, których jesteś celem zawodzą, a ataki w ciebie nie trafiają. Efekt końcowy: twoja żywotność spada do 5...50 pkt.'],
2863=>['Niezgoda (PvP)','Elitarny czar. Jeżeli wybrany przeciwnik cierpi na przypadłość i jest pod wpływem klątwy lub zaklęcia, przeciwnik ten otrzymuje 30...110 pkt. obrażeń.','Elitarny czar. Zadaje 30...110 pkt. obrażeń. Bez efektu, chyba że wybrany przeciwnik jest pod działaniem przypadłości i ma na sobie klątwę lub zaklęcie.'],
2864=>['Rozdzielający Atak (PvP)','Strzał z łuku. Jeśli Rozdzielający Atak trafi, zadajesz +5...15 pkt. obrażeń. Ten atak ma 10% przebicie pancerza.','Strzał z łuku. Zadaje +5...15 pkt. obrażeń. 10% przebicie pancerza.'],
2866=>['Ciało z Mego Ciała (PvP)','Czar. Tracisz połowę aktualnej liczby punktów żywotności. Wskrzeszasz wybranego członka drużyny z twoim aktualnym poziomem żywotności i z 5...20% pkt. energii.','Czar. Wskrzeszasz wybranego członka drużyny (połowa twojej aktualnej żywotności i 5...20% energii). Tracisz połowę żywotności.'],
2867=>['Gniew Przodków (PvP)','Umiejętność. Przez 3 sek., przeciwnicy w bezpośrednim sąsiedztwie wybranego sojusznika otrzymują co sekundę 4...50 pkt. obrażeń od błyskawic.','Umiejętność. (3 sek.) Przeciwnikom bezpośrednio przy wybranym sojuszniku zadaje co sekundę po 4...50 pkt. obrażeń od błyskawic.'],
2868=>['Odłamkowy Oręż (PvP)','Czar z broni. Przez 20 sek. wskazany sprzymierzeniec otrzymuje Odłamkowy Oręż. Kolejne ataki sojusznika (1...5 ) zadają 5...40 pkt.obrażeń maksymalnie 4 pobliskim wrogom.','Czar z broni. (20 sek.) Ataki zadają po 5...40 pkt. obrażeń 3 przeciwnikom w bezpośredniej odległości. Koniec po 1...5 atakach.'],
2869=>['Remedium Zabójcy (PvP)','Zaklęcie (czar). Przez 30 sek. kolejne użyte przez ciebie umiejętności związane z atakiem (w liczbie 1...10) usuwają po jednej przypadłości.','Zaklęcie (czar). (30 sek.) Twoje następne umiejętności związane z atakami w liczbie 1...10 usuwają po jednej przypadłości.'],
2871=>['Światło Wybawienia (PvP)','Elitarny czar. Wszyscy członkowie drużyny odzyskują 5...70 pkt. żywotności. Wszystkie twoje modlitwy ofensywne są niedostępne przez 20 sek.','Elitarny czar. Przywraca 5...70 pkt. żywotności całej drużynie. Blokuje twoje modlitwy ofensywne (20 sek.).'],
2872=>['Sygnet Śmiertelnego Paktu (PvP)','Sygnet. Wskrzeszasz wybranego członka drużyny, który powraca do życia z tyloma punktami żywotności ile masz ich ty i 15...100% maksymalnych pkt. energii. Kiedy następnym razem ten sojusznik zginie w ciągu 120 sek., zginiesz i ty.','Sygnet. Wskrzesza wybranego członka drużyny z twoim aktualnym poziomem żywotności i 15...100% maksymalnej energii. W ciągu 120 sek. umrzesz, kiedy następnym razem zginie ten członek drużyny.'],
2875=>['Rzut Grabieżcy (PvP)','Atak włócznią. Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli trafi poruszającego się przeciwnika, zadaje 5...40 pkt. dodatkowych obrażeń.','Atak włócznią. Zadaje +5...20 pkt. obrażeń. Zadaje 5...40 pkt. dodatkowych obrażeń, jeżeli cel porusza się.'],
2876=>['Obronny Hymn (PvP)','Elitarny zaśpiew. Przez 4...10 sek. każdy członek drużyny w zasięgu słuchu ma 50% szans na blokowanie ataków. Zaśpiew przestanie działać, kiedy członek drużyny trafi używając umiejętności związanej z atakami.','Elitarny zaśpiew. (4...10 sek.) Członkowie drużyny w zasięgu słuchu mają 50% szans na blokowanie. Przestanie działać, kiedy trafi umiejętność związana z atakiem.'],
2877=>['Ballada Odnowy (PvP)','Zaśpiew. Przez 10 sek., każdy sojusznik w zasięgu słuchu z następnym otrzymaniem obrażeń, dostanie 15...75 pkt. żywotności.','Zaśpiew. (10 sek.) Członkowie drużyny w zasięgu słuchu otrzymują po 15...75 pkt. żywotności, kiedy następnym razem otrzymają obrażenia.'],
2878=>['Pieśń Odnowy (PvP)','Elitarny zaśpiew. Przez 10 sek. każdy członek drużyny w zasięgu słuchu z następnym użyciem umiejętności, otrzyma 45...110 pkt. żywotności.','Elitarny zaśpiew. (10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoją następną umiejętnością otrzymują 45...110 pkt. żywotności.'],
2879=>['"Nadchodzą!" (PvP)','Elitarny okrzyk. Przez 4...10 sek., wszyscy sojusznicy w zasięgu słuchu poruszają się o 33% szybciej i zyskują 5...15 pkt. żywotności na sekundę podczas ruchu.','Elitarny okrzyk. (4...10 sek.) Wszyscy sojusznicy w zasięgu słuchu poruszają się o 33% szybciej i zyskują 5...15 pkt. żywotności na sekundę podczas ruchu.'],
2880=>['Nie Poddawajcie Się! (PvP)','Okrzyk. Przez 10 sek. wszyscy członkowie drużyny w zasięgu słuchu i mający mniej niż 75% pkt. żywotności, posiadają regenerację żywotności +1...5.','Okrzyk. (10 sek.) Członkowie drużyny w zasięgu słuchu posiadają regenerację żywotności +1...5. Działa tylko na członków drużyny posiadających mniej niż 75% żywotności.'],
2883=>['"Za Większą Sprawiedliwość!" (PvP)','Okrzyk. Przez 8 sekund, za każdym razem, kiedy trafisz podczas ataku, otrzymujesz adrenalinę w liczbie dawek: 1.','Okrzyk. (8 sekund). Otrzymujesz adrenalinę w liczbie dawek: 1 za każdym razem, kiedy trafisz podczas ataku.'],
2884=>['Mistyczna Regeneracja (PvP)','Zaklęcie (czar). Na 5...20 sek. otrzymujesz regenerację żywotności +1...4 na każde zaklęcie, pod którego jesteś działaniem (maksymalnie 3).','Zaklęcie (czar). (5...20 sek.) Posiadasz regenerację żywotności +1...4 na każde zaklęcie, pod którego jesteś działaniem (maksymalnie 3).'],
2885=>['Osłabiająca Krew (PvP)','Czar. Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu cierpią na osłabienie przez 1...16 sek.','Czar. Osłabia (1...16 sek.) wybranego przeciwnika i wszystkich przeciwników w pobliżu.'],
2887=>['Sygnet Osądu (PvP)','Sygnet elitarny. Cel zostaje powalony. Wybrany przeciwnik i wszyscy przeciwnicy przy nim otrzymują 5...50 pkt. świętych obrażeń. Sygnet ma połowę normalnego zasięgu.','Elitarny sygnet o połowie zasięgu. Powala cel. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 5...50 pkt. świętych obrażeń.'],
2891=>['Aura Nieustępliwości (PvP)','Elitarne zaklęcie (czar). Przywraca do życia martwego członka drużyny z pełną żywotnością i energią. Jeśli przestaniesz utrzymywać to zaklęcie lub jeśli zostanie ono zdjęte, ten członek drużyny umrze i pozostawi zużyte ciało. Śmierci poniesione podczas działania Aury Nieustępliwości nie zwiększają kary za śmierć. (50% szans na niepowodzenie, gdy wartość Łaski Bogów wynosi 4 lub mniej).','Elitarne zaklęcie (czar). Wskrzesza wybranego członka drużyny (pełna żywotność, pełna energia). Efekt końcowy: ten sojusznik umiera i zostawia zużyte ciało. Nie zwiększa kary za śmierć. 50% szans na niepowodzenie, chyba że wartość Łaski Bogów wynosi 5 lub więcej.'],
2892=>['Duchowa Więź (PvP)','Zaklęcie (czar). Przez 8 sek., za każdym razem, kiedy wybrany sojusznik z kolejnych 10 ataków lub czarów otrzyma więcej niż 50 pkt. obrażeń, dostanie 30...90 pkt. żywotności.','Zaklęcie (czar). (8 sek.) Dodaje 30...90 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik otrzymuje więcej niż 50 pkt. obrażeń. Przestanie działać, jeśli ten sojusznik otrzyma obrażenia z 10 ataków lub czarów.'],
2893=>['Ochronny Oręż (PvP)','Czar z broni. Na 3...8 sek. wybrany sojusznik otrzymuje Ochronny Oręż, który zapewnia mu regenerację żywotności +2...4 oraz 50% szans na blokowanie ciosów. Ochronny Oręż przestanie działać, jeżeli ten sojusznik zaatakuje.','Czar z broni. (3...8 sek.) Regeneracja żywotności +2...4. 50% szans na blokowanie.Kończy się, jeżeli wybrany sojusznik zaatakuje.'],
2895=>['Dar Pogromcy (PvP)','Zaklęcie (czar). Przez 4 sek. twoje czary oparte na Modlitwach Ofensywnych zapewniają podwójną premię pochodzącą od Łaski Bogów.','Zaklęcie (czar). (4 sek.) Dla umiejętności z Modlitw Ofensywnych punkty żywotności otrzymywane dzięki Łasce Bogów są podwajane.'],
2925=>['Strzał Łowcy Ospałych (PvP)','Strzał z łuku. Jeżeli atak trafi, wybrany przeciwnik otrzymuje +5...15 pkt. obrażeń. Jeżeli przeciwnik ten nie używa umiejętności, to Strzał Łowcy Ospałych zadaje dodatkowe +5...20 pkt. obrażeń.','Strzał z łuku. Zadaje +5...15 pkt. obrażeń. Zadaje +5...20 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik nie używa umiejętności.'],
2959=>['Mistrzowska Sprawność (PvP)','Postawa elitarna. Przez 1...20 sek. atakujesz o 15% szybciej, a twoje Umiejętności Strzeleckie zwiększają się o 1.','Postawa elitarna. (1...20 sek.) Atakujesz o 15% szybciej i posiadasz +1 do Umiejętności Strzeleckich.'],
2965=>['Sygnet Duchów (PvP)','Sygnet elitarny. Otrzymujesz 3...12 pkt. energii za każdego ducha w zasięgu słuchu.','Sygnet elitarny. Otrzymujesz 3...12 pkt. energii. Bez efektu, jeśli nie jesteś w zasięgu słuchu ducha.'],
2966=>['Sygnet Niematerialnej Potęgi (PvP)','Sygnet elitarny. Ataki wybranego, sojuszniczego przyzwanego stworzenia zadają 5...35 pkt. dodatkowych obrażeń. Po 10 sek. stworzenie to zostaje zniszczone.','Sygnet elitarny. Wybrane, sojusznicze przyzwane stworzenie zadaje +5...35 pkt. obrażeń. Po 10 sek. stworzenie to zostaje zniszczone.'],
2969=>['Czytanie Wiatru (PvP)','Przygotowanie. Przez 24 sek. twoje strzały lecą dwa razy szybciej.','Przygotowanie. (24 sek.) Twoje strzały lecą dwa razy szybciej.'],
2998=>['Kruchość (PvP)','Klątwa (czar). Przez 8...20 sek., wybrany cel i sąsiadujący przeciwnicy otrzymują 5...20 pkt. obrażeń za każdym razem, kiedy zaczynają cierpieć lub zdrowieć z przypadłości.','Klątwa (czar). Klątwa działa także na przeciwników bezpośrednio przy celu (8...20 sek.). Przeciwnicy ci otrzymują 5...20 obrażeń za każdym razem gdy tracą lub otrzymują jakąś przypadłość.'],
2999=>['Siła Honoru (PvP)','Zaklęcie (czar). Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik zadaje 1...5 pkt. dodatkowych obrażeń w walce wręcz.','Zaklęcie (czar). W walce wręcz wybrany sojusznik zadaje 1...5 pkt. dodatkowych obrażeń.'],
3002=>['Wytrzymałość Wojownika (PvP)','Postawa elitarna. Przez 5...35 sek., za każdym razem kiedy trafisz w walce wręcz, otrzymujesz 3 punkty Energii. Wytrzymałość Wojownika nie może zwiększyć twojej energii powyżej 10...25 pkt.','Postawa elitarna. (5...35 sek.) Otrzymujesz 3 punkty Energii, za każdym razem, kiedy twój atak wręcz trafi. Nie otrzymujesz energii, jeżeli masz więcej niż 10...25 pkt. energii.'],
3003=>['Zbroja Nieczułości (PvP)','Zaklęcie (czar). Przez 10...35 sek. otrzymywane przez ciebie obrażenia bazowe zostają zmniejszone o 10, jeżeli rzucasz rytuał spętania.','Zaklęcie (czar). (10...35 sek.) Posiadasz bazową redukcję obrażeń 10, jeżeli rzucasz rytuał spętania.'],
3005=>['Przymierze (PvP)','Rytuał spętania. Tworzysz 1...8 poziomowego ducha. Za każdym razem, kiedy nie będący duchem sojusznik w zasięgu otrzymuje obrażenia lub zostaje mu wykradziona żywotność, efekty zostają zmniejszone o 15 pkt., a duch otrzymuje 15 pkt. obrażeń. Duch ginie po 30...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 30...60 sek.). Za każdym razem, kiedy nie będący duchem sojusznik w zasięgu otrzymuje obrażenia lub zostaje mu wykradziona żywotność, efekty te zostają zmniejszone o 15, a duch otrzymuje 15 pkt. obrażeń.'],
3006=>['Pieśń Cienia (PvP)','Rytuał spętania. Tworzy ducha o poziomie 1...6. Ataki ducha zadają 5...20 pkt. obrażeń i powodują ślepotę przez 1...6 sek. Duch umiera po 30 sekundach.','Rytuał spętania. Tworzy ducha o poziomie 1...6 (długość życia: 30 sek.). Jego ataki zadają 5...20 pkt. obrażeń i powodują ślepotę (1...6 sek.).'],
3007=>['Ból (PvP)','Rytuał spętania. Tworzysz 1...8 poziomowego ducha. Ataki tego ducha zadają 5...30 pkt. obrażeń. Ten duch ginie po 30...150 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 30...150 sek.). Jego ataki zadają 5...30 pkt. obrażeń.'],
3008=>['Zniszczenie (PvP)','Rytuał spętania. Tworzysz ducha na poziomie 1...10, który ginie po 30 sek. Gdy ten duch ginie, wszyscy przeciwnicy w okolicy otrzymują 1...10 pkt. obrażeń za każdą sekundę życia ducha (maksymalnie 150 pkt. obrażeń).','Rytuał spętania. Tworzy ducha na poziomie 1...10 (czas życia 30 sek.). W momencie śmierci zadaje wszystkim przeciwnikom w okolicy po 1...10 pkt. obrażeń na każdą sekundę swojego życia (maksymalnie 150 pkt. obrażeń).'],
3009=>['Ukojenie (PvP)','Rytuał spętania. Tworzysz 1...8 poziomowego ducha. Wszyscy przeciwnicy w jego zasięgu otrzymują adrenalinę dwa razy wolniej. Ten duch ginie po 15...45 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 15...45 sek.). Przeciwnicy w zasięgu dwa razy dłużej gromadzą adrenalinę.'],
3010=>['Przemieszczenie (PvP)','Rytuał spętania. Tworzysz 1...10 poziomowego ducha. Wszyscy sojusznicy nie-duchy w jego zasięgu mają 75% szans na blokowanie ataków. Za każdym razem, gdy atak zostanie w ten sposób zablokowany, duch otrzyma 60 pkt. obrażeń. Duch ginie po 30...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...10 (czas życia 30...60 sek.). Sojusznicy nie-duchy w zasięgu mają 75% szans na blokowanie. Efekt zablokowania: ten duch otrzymuje 60 pkt. obrażeń.'],
3011=>['Zabezpieczenie (PvP)','Elitarny rytuał spętania. Tworzysz 1...10 poziomowego ducha. Co 4 sek. ten duch leczy jednego nie będącego duchem sojusznika w okolicy dodając mu 10...115 pkt. żywotności. Ten duch ginie po 90 sek.','Elitarny rytuał spętania. Tworzy ducha na poziomie 1...10 (czas życia 90 sek.). Co 4 sek. ten duch leczy jednego sojusznika nie-ducha, dodając mu 10...115 pkt. żywotności.'],
3012=>['Życie (PvP)','Rytuał spętania. Tworzysz 1...10 poziomowego ducha. Gdy ten duch ginie, wszyscy nie będący duchami sojusznicy w jego zasięgu otrzymują 1...7 pkt. żywotności za każdą sekundę życia tego ducha. Ten duch ginie po 20 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...10 (czas życia 20 sek.). Działa na sojuszników nie-duchy w zasięgu. Efekt końcowy: dodaje 1...7 pkt. żywotności na każdą sekundę życia tego ducha.'],
3013=>['Rekonwalescencja (PvP)','Rytuał spętania. Tworzy ducha o poziomie 1...10. Sojusznicy w jego zasięgu, którzy nie są duchami, otrzymują premię +1...3 do regeneracji żywotności. Duch umiera po 15...45 sek.','Rytuał spętania. Tworzy ducha o poziomie 1...10 (długość życia: 15...45 sek.). Sojusznicy w jego zasięgu, którzy nie są duchami, otrzymują premię +1...3 do regeneracji żywotności.'],
3014=>['Dysonans (PvP)','Rytuał spętania. Tworzysz 1...8 poziomowego ducha. Ten duch zadaje 5...20 pkt. obrażeń, a czynność każdego kto otrzyma od niego obrażenia, zostaje przerwana. Duch ginie po 10...25 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 10...25 sek.). Jego ataki zadają 5...20 pkt. obrażeń i przerywają czynności.'],
3015=>['Uziemienie (PvP)','Rytuał spętania. Tworzysz 1...10 poziomowego ducha. Wszyscy nie będący duchami przeciwnicy powaleni w zasięgu tego ducha, zostają powaleni na przynajmniej 3 sek. Za każdym razem, kiedy tak się dzieje, ten duch traci 50...25 pkt. żywotności. Ten duch ginie po 15...45 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...10 (czas życia 15...45 sek.). Za każdym razem, kiedy przeciwnik nie-duch w zasięgu zostanie powalony, będzie powalony przez przynajmniej 3 sek. Koszt powalenia: ten duch traci 50...25 pkt. żywotności.'],
3016=>['Schronienie (PvP)','Rytuał spętania. Tworzysz 1...8 poziomowego ducha. Nie będący duchami sojusznicy w jego zasięgu od pojedynczego ataku nie mogą stracić więcej niż 10% maksymalnych pkt. żywotności. Za każdym razem, kiedy ten duch zapobiega obrażeniom, traci 75...45 pkt. żywotności. Duch ginie po 30...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 30...60 sek.). Sojusznicy nie-duchy w zasięgu, od pojedynczego ataku nie mogą stracić więcej niż 10% maksymalnych pkt. żywotności. Koszt ochrony przed obrażeniami: ten duch traci 75...45 pkt. żywotności.'],
3017=>['Antyzaklęcie (PvP)','Rytuał spętania. Tworzysz 1...8 poziomowego ducha. Ten duch zadaje 5...20 pkt. obrażeń, a każdy kto otrzyma od niego obrażenia, traci jedno zaklęcie. Duch ginie po 15...40 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 15...40 sek.). Jego ataki zadają 5...20 pkt. obrażeń i usuwają zaklęcie.'],
3018=>['Odnowa (PvP)','Rytuał spętania. Tworzysz 1...10 poziomowego ducha. Gdy ten duch ginie, wszyscy członkowie drużyny w okolicy zostają wskrzeszeni z 5...50% pkt. żywotności i z zerem pkt. energii. Ten duch ginie po 30 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...10 (czas życia 30 sek.). Efekt końcowy: wskrzesza martwych członków drużyny w okolicy (5...50% żywotności, 0 pkt. energii).'],
3019=>['Pieśń Krwi (PvP)','Rytuał spętania. Tworzysz ducha na poziomie 1...8, który ginie po 30...150 sek. Ataki tego ducha wykradają do 5...25 pkt. żywotności.','Rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 30...150 sek.). Jego ataki wykradają 5...25 pkt. żywotności.'],
3020=>['Żądza Wędrowania (PvP)','Elitarny rytuał spętania. Tworzysz 1...8 poziomowego ducha. Za każdym razem, kiedy ten duch trafia stojącego w miejscu przeciwnika, ten przeciwnik zostaje powalony, a duch traci 70...50 pkt. żywotności. Duch ginie po 30...60 sek.','Elitarny rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 30...60 sek.). Jego ataki powalają przeciwników stojących w miejscu. Koszt powalenia: ten duch traci 70...50 pkt. żywotności.'],
3021=>['Żar Sawanny (PvP)','Elitarny czar. W miejscu, gdzie znajduje się wybrany przeciwnik tworzysz Żar Sawanny. Przez 5 sek. wszyscy przeciwnicy w pobliżu otrzymują co sekundę 5...20 pkt. obrażeń od ognia za każdą sekundę działania tego czaru.','Elitarny czar. W każdej sekundzie od rzucenia czaru zadaje 5...20 pkt. obrażeń od ognia (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca znajdowania się celu.'],
3022=>['Spojrzenie Furii (PvP)','Rytuał spętania. Niszczy wybranego sprzymierzonego ducha, by stworzyć Ducha Furii poziomu 1...10. Ataki tego ducha zadają 5...20 pkt. obrażeń. Duch umiera po 30...60 sek.','Rytuał spętania. Niszczy sprzymierzonego ducha. Tworzy ducha o poziomie 1...10 (długość życia: 30...60 sek.). Jego ataki zadają 5...20 pkt. obrażeń.'],
3023=>['Katusze (PvP)','Rytuał spętania. Tworzysz 1...7 poziomowego ducha. Ataki tego ducha zadają 5...20 pkt. obrażeń, a przeciwnikom pod działaniem klątw zadają podwójne obrażenia. Duch ginie po 15...45 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...7 (czas życia 15...45 sek.). Jego ataki zadają 5...20 pkt. obrażeń. Podwójne obrażenia dla przeciwników pod działaniem klątwy.'],
3024=>['Wzmocnienie (PvP)','Rytuał spętania. Tworzysz 1...10 poziomowego ducha. Wszyscy sojusznicy w jego zasięgu, którzy trzymają przedmiot otrzymują 15...45 pkt. do maksymalnej żywotności i 10 pkt. do maksymalnej energii. Duch ginie po 15...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...10 (czas życia 15...60 sek.). Sojusznicy w zasięgu, którzy trzymają przedmiot, otrzymują 15...45 pkt. do maksymalnej żywotności i 10 pkt. do maksymalnej energii.'],
3025=>['Ozdrowienie (PvP)','Rytuał spętania. Tworzysz 1...10 poziomowego ducha. Przypadłości, na które cierpią sojusznicy w jego zasięgu kończą się o 20...50% szybciej. Duch ginie po 30...60 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...10 (czas życia 30...60 sek.). Przypadłości, na które cierpią sojusznicy w zasięgu, kończą się o 20...50% szybciej.'],
3026=>['Po Oczach! (PvP)','Okrzyk. Przez 10 sek., następny atak wykonany przez każdego sojusznika w zasięgu słuchu ma dodatkowe 30...75% szans na trafienie krytyczne.','Okrzyk. (10 sek.) Sojusznicy w zasięgu słuchu mają +30...75% szans na wykonanie trafienia krytycznego w czasie swojego następnego ataku.'],
3027=>['Ustój! (PvP)','Okrzyk. Przez 5...15 sek., następnym razem, gdy wybrany sojusznik inny niż ty ma zostać powalony, 1 przeciwnik w pobliżu otrzymuje w zamian 15...90 pkt. obrażeń.','Okrzyk. (5...15 sek.) Ochroni przed następnym powaleniem i zadaje 15...90 pkt. obrażeń jednemu przeciwnikowi w pobliżu wybranego sojusznika. Na cel nie można wybrać siebie.'],
3028=>['Ognisty Finał (PvP)','Echo. Przez 10...35 sek., za każdym razem, kiedy zaśpiew lub okrzyk przestaną działać na wybranym sojuszniku nie-duchu, wszyscy przeciwnicy bezpośrednio przy tym sojuszniku zaczną płonąć przez 1...5 sek.','Echo. (10...35 sek.) U przeciwników w bezpośredniej odległości wywołuje przypadłość płonięcie (1...5 sek.), za każdym razem, kiedy zaśpiew lub okrzyk przestanie działać na wybranym sojuszniku. Na cel nie można wybrać ducha.'],
3029=>['Zaśpiew Odpędzenia Ostrzy (PvP)','Echo. Przez 20 sek. wybrany sojusznik nie-duch posiada +10...40 pkt. pancerza przeciwko obrażeniom ciętym. To echo jest ponownie nakładane za każdym razem, kiedy przestanie na tym sojuszniku działać zaśpiew lub okrzyk.','Echo. (20 sek.) Wybrany sojusznik posiada +10...40 pkt. pancerza przeciwko obrażeniom ciętym. Odnowienie: za każdym razem, kiedy przestaje na tym sojuszniku działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
3030=>['Sygnet Powrotu (PvP)','Sygnet. Wskrzeszasz wybranego członka drużyny, który zmartwychwstaje z 5...20% pkt. żywotności i 1...4% pkt. energii na każdego członka drużyny w zasięgu słuchu.','Sygnet. Wskrzesza wybranego członka drużyny (5...20% pkt. żywotności i 1...4% pkt. energii na każdego członka drużyny w zasięgu słuchu).'],
3031=>['Łapy Precz! (PvP)','Okrzyk. Przez 20 sek. następne 1...5 umiejętności oparte na dotyku, użyte przeciwko tobie nie zadziałają.','Okrzyk. (20 sek.) Następne 1...5 umiejętności oparte na dotyku, użyte przeciwko tobie nie zadziałają.'],
3032=>['Utrzymać Pozycje! (PvP)','Okrzyk. Przez 5...20 sek., wszyscy członkowie drużyny w zasięgu słuchu otrzymują +24 pkt. pancerza, jeśli się nie poruszają. Efekt przestaje działać na sojuszniku, jeśli ten zaatakuje.','Okrzyk. (5...20 sek.) Członkowie drużyny w zasięgu słuchu otrzymują +24 pkt. pancerza, jeżeli się nie poruszają. Przestaje działać, jeśli dany sojusznik zaatakuje.'],
3033=>['Jeszcze Tu Wrócimy! (PvP)','Okrzyk. Przez 10 sek., za każdym razem, kiedy członkowie drużyny w zasięgu słuchu użyją umiejętności wskrzeszającej, zmartwychwstający sojusznicy powracają do życia z dodatkowymi 10...75% pkt. żywotności i 5...50% pkt. energii.','Okrzyk. (10 sek.) Za każdym razem, kiedy członkowie drużyny w zasięgu słuchu użyją umiejętności wskrzeszającej, zmartwychwstający sojusznicy powracają do życia z dodatkowymi 10...75% pkt. żywotności i 5...50% pkt. energii.'],
3034=>['Odnajdźcie Ich Słabości! (PvP)','Okrzyk. Przez 5...20 sek., kiedy następnym razem wybrany sojusznik spowoduje obrażenia krytyczne, to zada też głęboka ranę na 5...20 sek.','Okrzyk. (5...20 sek.) Z następnym trafieniem krytycznym wybrany sojusznik wywołuje przypadłość głęboka rana (5...20 sek.).'],
3035=>['Trzymać Się! (PvP)','Okrzyk. Wszyscy sojusznicy w zasięgu słuchu i posiadający mniej niż 75% pkt. żywotności otrzymują 1...10 pkt. energii.','Okrzyk. Sojusznicy w zasięgu słuchu otrzymują 1...10 pkt. energii. Działa tylko na sojuszników posiadających mniej niż 75% żywotności.'],
3036=>['"Pomocy!" (PvP)','Okrzyk. Wskazany sojusznik niebędący duchem zyskuje 5...50 pkt. zdrowia. Przez 1...10 sek. zaklęcia innych sojuszników, których celem jest ten sojusznik, są rzucane o 50% szybciej.','Okrzyk. (1...10 sek.) Wskazany sojusznik niebędący duchem zyskuje 5...50 pkt. zdrowia, zaklęcia sojuszników rzucane na niego są rzucane o 50% szybciej.'],
3037=>['Wycofać Się! (PvP)','Okrzyk. Przez 4...10 sek. wszyscy poruszający się sojusznicy w zasięgu słuchu otrzymują 5...15 pkt. żywotności na sek., a ich szybkość zwiększa się o 33%. "Wycofać Się!" przestanie działać na sojuszniku z jego kolejnym trafionym atakiem.','Okrzyk. (4...10 sek.) Wszyscy poruszający się sojusznicy w zasięgu słuchu otrzymują 5...15 pkt. żywotności na sek., a ich szybkość ruchu zwiększa się o 33%. Przestanie działać na sojusznika, jeśli jego atak trafi.'],
3038=>['Agonia (PvP)','Rytuał spętania. Tworzysz 1...8 poziomowego ducha. Obecność ducha powoduje, że każdy przeciwnik w jego zasięgu słuchu co sekundę traci 3...10 pkt. żywotności. Duch traci 3...10 pkt. żywotności, na każdego przeciwnika, który w ten sposób ucierpi. Duch ginie po 30...90 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...8 (czas życia 30...90 sek.). Przeciwnicy w zasięgu słuchu co sekundę tracą 3...10 pkt. żywotności. Ten duch traci 3...10 pkt. żywotności na każdego przeciwnika, który traci żywotność.'],
3039=>['Odmłodzenie (PvP)','Rytuał spętania. Tworzysz 1...16 poziomowego ducha. Duch uzdrawia każdego członka drużyny w zasięgu słuchu, w każdej sekundzie dodając mu 3...10 pkt. żywotności. Duch traci 3...10 pkt. żywotności, na każdego członka drużyny uzdrowionego w ten sposób. Duch ginie po 30...90 sek.','Rytuał spętania. Tworzy ducha na poziomie 1...16 (czas życia 30...90 sek.). Członkowie drużyny w zasięgu słuchu otrzymują co sekundę po 3...10 pkt. żywotności. Koszt uleczenia: ten duch traci 3...10 pkt. żywotności.'],
3040=>['Hymn Rozproszenia (PvP)','Zaśpiew. Przez 1...10 sek. następna umiejętność związana z atakami, używana przez każdego sojusznika w zasięgu słuchu, przerywa także czynność przeciwnika.','Zaśpiew. (1...10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem przerywają czynność przeciwnika.'],
3045=>['Uzdrowienie Zwierzęcia (PvP)','Umiejętność. Leczysz swojego zwierzęcego towarzysza dodając mu 40...120 pkt. żywotności. Jeśli jest martwy, wskrzeszasz go z 10...58% punktami żywotności. Jeśli masz na wyposażeniu Uzdrowienie Zwierzęcia, twój towarzysz będzie podróżował wraz z tobą.','Umiejętność. Twój zwierzęcy towarzysz otrzymuje 40...120 pkt. żywotności. Wskrzesza twojego zwierzęcego towarzysza (10...58% żywotności). Jeśli masz na wyposażeniu Uzdrowienie Zwierzęcia, twój towarzysz będzie podróżował wraz z tobą.'],
3047=>['Natarcie Melandru (PvP)','Atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Natarcie Melandru, które zadaje +5...20 pkt. obrażeń. Jeśli atak trafi przeciwnika pod działaniem zaklęcia, to przeciwnik ten i wrogowie znajdujący się bezpośrednio przy nim otrzymają +5...35 pkt. dodatkowych obrażeń.','Atak zwierzaka. Zadaje +5...20 pkt. obrażeń. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po +5...35 pkt. dodatkowych obrażeń, jeżeli ten przeciwnik jest pod działaniem zaklęcia.'],
3048=>['Całun Boleści (PvP)','Zaklęcie (czar). Przez 30...60 sek., jeżeli masz mniej niż 50% pkt. żywotności, masz 75% szansy na zablokowanie ataków.','Zaklęcie (czar). (30...60 sek.) Masz 75% szans na blokowanie. Bez efektu, chyba że twoja żywotność jest poniżej 50%.'],
3049=>['Niewidoczna Furia (PvP)','Postawa. Przez 15...60 sek., twoich ataków nie mogą zablokować oślepieni przeciwnicy.','Postawa. (15...60 sek.) Nie możesz zostać zablokowany przez oślepionych przeciwników.'],
3050=>['Drapieżcza Więź (PvP)','Okrzyk. Przez 5...20 s, ataki twojego zwierzęcego towarzysza leczą cię, dodając ci 1...31 pkt. żywotnoci.','Okrzyk. (5...20 s) Otrzymujesz 1...31 pkt. żywotności, za każdym razem, kiedy twój zwierzęcy towarzysz wykona udany atak.'],
3051=>['Rozszalałe Uderzenie (PvP)','Elitarny atak zwierzaka. Twój zwierzęcy towarzysz wykonuje Rozszalałe Uderzenie, które zadaje +3...23 pkt. obrażeń (maksymalna premia to 60 pkt.) na każdą odnawiającą się umiejętność Panowania nad Zwierzętami.','Elitarny atak zwierzaka. Zadaje +3...23 pkt. obrażeń (maksymalnie 60) za każdą odnawiającą się umiejętność Panowania nad Zwierzętami.'],
3053=>['Sygnet Śmiertelnego Zepsucia (PvP)','Sygnet. Musi następować po podwójnym ataku. Zaatakowany wróg otrzymuje 5...35 pkt. obrażeń za każdą posiadaną przypadłość (maksymalnie 130 pkt. obrażeń).','Sygnet. Zadaje 5...35 pkt. obrażeń (maksymalnie 130) za każdą przypadłość na wybranym przeciwniku. Musi nastąpić po ataku podwójnym.'],
3054=>['Masochizm (PvP)','Zaklęcie (czar). Przez 30 s, za każdym razem, kiedy poświęcisz punkty żywotności, otrzymasz 1...3 pkt. energii.','Zaklęcie (czar). (30 s) Otrzymasz 1...3 energii za każdym razem, gdy poświęcisz żywotność.'],
3058=>['Bluźniercza Uczta (PvP)','Czar. Wykradasz do 10...65 pkt. żywotności od maksymalnie 1...4 przeciwników w okolicy.','Czar. Wykrada 10...65 pkt. żywotności od 1...4 przeciwników w twojej okolicy.'],
3059=>['Sygnet Agonii (PvP)','Sygnet. Krwawisz przez 25 sek. Wszyscy przeciwnicy w pobliżu otrzymują 10...70 pkt. obrażeń.','Sygnet. Przeciwnikom w pobliżu ciebie zadaje po 10...70 pkt. obrażeń. Krwawisz (25 sek.).'],
3060=>['Ucieczka (PvP)','Postawa elitarna. Przez 1...8 sek., poruszasz się o 33% szybciej i masz 75% szansy na zablokowanie ataków. Ucieczka przestaje działać po wykonaniu ataku wręcz.','Postawa elitarna. (1...8 sek.) Poruszasz się o 33% szybciej i masz 75% szans na zablokowanie ataków. Przestaje działać po wykonaniu ataku wręcz.'],
3061=>['Zabójczy Kwiat (PvP)','Atak podwójny. Musi nastąpić po ataku drugą ręką. Zabójczy Kwiat zadaje wybranemu przeciwnikowi +20...45 pkt. obrażeń, wszyscy przeciwnicy bezpośrednio przy nim otrzymują 20...45 pkt. obrażeń.','Atak podwójny. Zadaje +20...45 pkt. obrażeń. Działa także na przeciwników bezpośrednio przy wybranym przeciwniku. Musi nastąpić po ataku drugą ręką.'],
3062=>['Finał Odnowy (PvP)','Echo. Przez 10...35 sek., przez kilka (5) następnych razy, kiedy okrzyk lub zaśpiew przestaną działać na wybranym sojuszniku nie-duchu, odzyskuje on 15...75 pkt. żywotności.','Echo. (10...35 sek.) Wybrany sojusznik odzyskuje 15...75 pkt. żywotności przez kilka (5) następnych razy, kiedy przestaje na nim działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
3063=>['Mantra Zdecydowania (PvP)','Postawa. Przez 5 sek., twoje czynności nie mogą być przerwane, ale za każdym razem, gdy byłyby przerwane, tracisz 10...4 pkt. energii albo Mantra Zdecydowania przestanie działać.','Postawa. (5 sek.) Chroni cię przed przerwaniami. Koszt ochrony: utrata 10...4 pkt. energii lub koniec Mantry Zdecydowania.'],
3141=>['Błyskawiczny refleks (PvP)','Postawa. Przez 5...11 sek., masz 75% szans na zablokowanie atak&oacute;w wręcz i strzeleckich, a dodatkowo atakujesz o 33% szybciej.','Postawa. (5...11 sek.) Atakujesz o 33% szybciej i masz 75% szans na blokowanie.'],
3143=>['Cios Odnowy (PvP)','Atak młotem. Jeśli Cios Odnowy trafi, zadaje +5...20 pkt. obrażeń. Jeśli trafisz powalonego wroga, otrzymujesz 3 pkt. energii, a atak ten natychmiast się odnawia.','Atak młotem. Zadaje +5...20 pkt. obrażeń. Otrzymujesz 3 pkt. energii, zaś atak ten natychmiast się odnawia, jeśli wybrany przeciwnik był powalony.'],
3144=>['Jedność w Uzdrowieniu (PvP)','Umiejętność elitarna. Jeśli żywotność twojego zwierzęcego towarzysza jest poniżej 75%, obaj otrzymujecie po 25...145 pkt. żywotności. Jeśli tw&oacute;j zwierzęcy towarzysz jest martwy, powraca do życia z 50% pkt. żywotności.','Umiejętność elitarna. Przywraca tobie i twojemu zwierzęcemu towarzyszowi po 25...145 pkt. żywotności. Jeśli zwierzęcy towarzysz nie żyje, zostaje wskrzeszony z 50% żywotności. Bez efektu, chyba że któryś z was ma poniżej 75% żywotności..'],
3145=>['Szklane Strzały (PvP)','Elitarne przygotowanie. Przez 10...35 sek., twoje strzały po trafieniu zadają +6...18 pkt. obrażeń, a jeśli zostaną zablokowane, to powodują, że na 10...20 sek. cel zaczyna krwawić.','Elitarne przygotowanie. (10...35 sek.) Twoje strzały zadają +6...18 pkt. obrażeń. Wywołuje przypadłość krwawienie (10...20 sek.), jeżeli zostanie zablokowana.'],
3147=>['Ostra Strzała (PvP)','Strzał z łuku. Jeśli atak trafi, zadajesz +5...15 pkt. obrażeń. Jeśli jest to trafienie krytyczne, zdajesz dodatkowe +5...30 pkt. obrażeń.','Strzał z łuku. Zadaje +5...15 pkt. obrażeń. Zadaje +5...30 pkt. dodatkowych obrażeń, jeżeli wykonasz trafienie krytyczne.'],
3148=>['Hymn Zazdrości (PvP)','Zaśpiew. Przez 10 sek., następna umiejętność związana z atakiem, użyta przez każdego sojusznika w zasięgu słuchu zadaje +10...20 pkt. obrażeń przeciwnikom posiadającym więcej niż 50% pkt. żywotności.','Zaśpiew. (10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem zadają +10...20 pkt. obrażeń. Dodatkowe obrażenia zadawane są tylko przeciwnikom, kt&oacute;rzy mają więcej niż 50% żywotności.'],
3149=>['Zaśpiew Ozdrowienia (PvP)','Echo. Przez 15 sek., posiadasz regenerację żywotności + 2...3. To echo jest ponownie nakładane za każdym razem, kiedy przestaje na tobie działać pieśń lub okrzyk.','Echo. (15 sek.) Otrzymujesz regenerację żywotności +2...3. Odnowienie: za każdym razem, gdy przestaje na tobie działać pieśń lub okrzyk.'],
3151=>['Empatia (PvP)','Klątwa (czar). Przez 5...15 sek., za każdym razem, kiedy wybrany przeciwnik atakuje, ten przeciwnik otrzymuje 15...45 pkt. obrażeń.','Klątwa (czar). (5...15 sek.) Wybrany przeciwnik otrzymuje 15...45 pkt. obrażeń, za każdym razem, kiedy atakuje.'],
3152=>['Okulawiające Katusze (PvP)','Elitarna klątwa (czar). Przez 5...20 sek., wybrany przeciwnik porusza się 50% wolniej oraz cierpi na -2...6 degeneracji pkt. żywotności.','Elitarna klątwa (czar). (5...20 sek.) Wybrany przeciwnik porusza się o 50% wolniej i cierpi na degenerację żywotności -2...6.'],
3156=>['Postawa Żołnierza (PvP)','Postawa elitarna. Przez 4...10 sek., kiedy będziesz pod działaniem okrzyku lub pieśni, atakujesz o 33% szybciej.','Postawa elitarna. (4...10 sek.) Atakujesz o 33% szybciej, jeżeli jesteś pod działaniem okrzyku lub pieśni.'],
3157=>['Niszczycielską Była Glewia (PvP)','Elitarny czar z przedmiotu. Trzymaj prochy Glewii przez maksymalnie 30...60 sek. Kiedy je trzymasz, wszystkie umiejętności Rytualisty otrzymują 10% do penetracji pancerza. Gdy upuścisz jej prochy, wszyscy przeciwnicy w okolicy otrzymają 15...85 pkt. obrażeń od błyskawic.','Elitarny czar z przedmiotu. (30...60 sek.) Twoje umiejętności Rytualisty otrzymują 10% do penetracji pancerza. Efekt upuszczenia: wszyscy przeciwnicy w okolicy otrzymują po 15...85 pkt. obrażeń od błyskawic.'],
3179=>['Mantra Sygnetów (PvP)','Postawa. Przez 10...40 sek., otrzymujesz +3 do pancerza za każdy sygnet na wyposażeniu. Za każdym razem, gdy użyjesz jakiegoś sygnetu, otrzymujesz 5...60 żywotności.','Postawa. (10...40 sek.) Otrzymujesz +3 do pancerza za każdy sygnet na wyposażeniu. Za każdym razem, gdy użyjesz jakiegoś sygnetu, otrzymujesz 5...60 żywotności.'],
3180=>['Rozbicie Urojeń (PvP)','Czar. Zdejmij jedną klątwę mesmera z wybranego przeciwnika. Jeśli klątwa zostanie usunięta, to ten przeciwnik odniesie 15...75 pkt. obrażeń, wszyscy wrogowie w jego bezpośrednim sąsiedztwie odniosą 75% tych obrażeń.','Czar. Zdejmuje jedną klątwę mesmera z wyznaczonego przeciwnika. Skutek zdjęcia: 15...75 pkt. obrażeń dla celu i 75% tych obrażeń dla wszystkich sąsiednich przeciwników.'],
3181=>['Iluzoryczna Broń (PvP)','Elitarne zaklęcie (czar). Przez 30 sekund, twoje ataki nie trafiają ani nie chybiają. Zamiast tego Iluzoryczna Broń zadajee 20...60 pkt. obrażeń twoim celom przy każdym ataku wręcz.','Elitarne zaklęcie (czar). (30 sek.) Zadaje 20...60 pkt. obrażeń przeciwnikom zamiast innych obrażeń lub efektów z ataków wręcz. Twoje ataki wręcz nie trafiają ani nie chybiają.'],
3183=>['Migrena (PvP)','Elitarna klątwa (czar). Przez 4...16 sek., wybrany przeciwnik cierpi na -1...8 degeneracji pkt. żywotności oraz uaktywnia umiejętności 100% dłużej.','Elitarna klątwa (czar). (4...16 sek.) Powoduje degenerację żywotności -1...8 i dwukrotnie wydłuża czas aktywacji umiejętności.'],
3184=>['Nagromadzenie Bólu (PvP)','Czar. Wybrany przeciwnik otrzymuje 10...35 pkt. obrażeń. Jeżeli wybrany przeciwnik jest pod wpływem 2 lub więcej klątw, to otrzymuje głęboką ranę na 5...20 sek.','Czar. Zadaje 10...35 pkt. obrażeń. Wywołuje głęboką ranę (5...20 sek.), jeżeli wybrany przeciwnik jest pod działaniem 2 lub więcej klątw.'],
3185=>['Psychiczna Niestabilność (PvP)','Elitarny czar. Przerywa akcję wybranego przeciwnika. Jeśli tą akcją jest umiejętność, przeciwnik i wszyscy wrogowie w bezpośrednim sąsiedztwie zostają powaleni na 2...3 sek. (50% szans na niepowodzenie, jeśli Szybkie Rzucanie Czarów jest na poziomie 4 lub mniejszym.)','Elitarny czar. Przerywa akcję. Efekt przerwania: jeśli tą akcją jest umiejętność, przeciwnik i wszyscy wrogowie w bezpośrednim sąsiedztwie zostają powaleni na 2...3 sek. 50% szans na niepowodzenie, chyba że Szybkie Rzucanie Czarów jest na poziomie 5 lub wyższym.'],
3186=>['Wspólny Ciężar (PvP)','Elitarna klątwa (czar). Przez 5...20 sek. wybrany przeciwnik i wszyscy przeciwnicy na obszarze ataku rzucają zaklęcia i poruszają się o 33% wolniej.','Elitarna klątwa (czar). Klątwa działa także na przeciwników w pobliżu twojego celu (5...20 sek.). Ci przeciwnicy atakują, rzucają zaklęcia i poruszają się o 33% wolniej.'],
3187=>['Kradzież Szybkości (PvP)','Elitarna klątwa (czar). Przez 1...10 sek., cel i wszyscy przeciwnicy w jego sąsiedztwie rzucają czary 100% dłużej. Twoje czary wycelowane w tych przeciwników rzucane są 50% szybciej.','Elitarna klątwa (czar). Klątwa działa także na wrogów w bezpośrednim sąsiedztwie (1...10 sek.). Podwaja czas rzucania czarów. Twoje czary wycelowane w przeciwników pod działaniem klątwy, rzucane są 50% szybciej.'],
3188=>['Nienaturalny Sygnet (PvP)','Sygnet. Wybrany przeciwnik otrzymuje 10...60 pkt. obrażeń. Jeśli jest on pod działaniem klątwy lub zaklęcia, przeciwnicy w bezpośrednim sąsiedztwie celu otrzymują 10...60 pkt. obrażeń. Wszystkie twoje umiejątności nie będące umiejętnościami mesmera zostają wyłączone na 10 sekund.','Sygnet. Zadaje 10...60 pkt. obrażeń. Zadaje 10...60 pkt. obrażeń innym wrogom w sąsiedztwie, jeśli cel jest pod działaniem klątwy lub zaklęcia. Wszystkie twoje umiejątności nie będące umiejętnościami mesmera zostają wyłączone (10 sekund).'],
3189=>['Duchowy Ból (PvP)','Czar. Wybrany przeciwnik otrzymuje 5...40 pkt. obrażeń. Wszystkie wrogie przywołane stworzenia na obszarze w pobliżu wroga otrzymują 25...125 pkt. obrażeń.','Czar. Zadaje 5...40 pkt. obrażeń. Zadaje 25...125 pkt. obrażeń wrogim przywołanym stworzeniom w rejonie wybranego przeciwnika.'],
3190=>['Frustracja (PvP)','Klątwa (czar). Przez 5...20 sek., wybrany przeciwnik rzuca czary o 50% wolniej i otrzymuje 5...50 pkt. obrażeń za każdym razem, kiedy jego akcja zostanie przerwana.','Klątwa (czar). (5...20 sek.) Powoduje, że rzucanie czarów jest wolniejsze o 50%. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń, za każdym razem, kiedy jego akcje zostaną przerwane.'],
3191=>['Nieufność (PvP)','Klątwa (czar). Przez 6 sek. następny czar wybranego przeciwnika wymierzony przeciwko twojemu sojusznikowi zawiedzie, przeciwnik ten odniesie 10...60 pkt. obrażeń, a wszyscy przeciwnicy w jego pobliżu odniosą 75% tych obrażeń.','Klątwa (czar). (6 sek.). Następny czar wybranego przeciwnika wymierzony przeciwko twojemu sojusznikowi zawiedzie, przeciwnik ten odniesie 10...60 pkt. obrażeń, a przeciwnicy w jego pobliżu odniosą 75% tych obrażeń.'],
3192=>['Zagadka Zaklinacza (PvP)','Elitarna klątwa (czar). Przez 10 sek. wybrany przeciwnik rzuca zaklęcia 100...200% wolniej. Jeśli w momencie nałożenia klątwy wybrany przeciwnik nie znajduje się pod działaniem żadnego zaklęcia, przeciwnik ten odnosi 10...100 pkt. obrażeń, a wszyscy wrogowie w jego bezpośrednim sąsiedztwie odnoszą 75% tych obrażeń.','Elitarna klątwa (czar). Spowalnia o 100...200% rzucanie zaklęć (10 sek.). Początkowy efekt: jeśli wybrany przeciwnik nie jest pod wpływem zaklęcia, zadaje mu 10...100 pkt. obrażeń, a sąsiadującym z nim przeciwnikom zadaje 75% tych obrażeń.'],
3193=>['Sygnet Niezgrabności (PvP)','Sygnet. Jeśli wybrany przeciwnik atakuje, zarówno on, jak i wrogowie w jego sąsiedztwie przerywają wykonywanie akcji i otrzymują 15...60 pkt. obrażeń. Wszyscy przeciwnicy korzystający z umiejętności ataku zostają powaleni.','Sygnet. Przerywa atak wybranego przeciwnika i sąsiadujących z nim wrogów. Efekt przerwania: zadaje 15...60 pkt. obrażeń. Powala wrogów używających umiejętności ataku.'],
3194=>['Zwierciadło Antyzaklęcia (PvP)','Czar. Z wybranego przeciwnika zdejmujesz jedno zaklęcie. To samo zaklęcie tracą wszyscy członkowie drużyny tego przeciwnika.','Czar. Usuwa jedno zaklęcie z wybranego przeciwnika. To samo zaklęcie tracą także członkowie jego drużyny.'],
3195=>['Błędne Oko (PvP)','Klątwa (czar). Przez 4 sek., następnym razem, gdy wybrany przeciwnik wykona atak, zostanie on przerwany, a wszyscy przeciwnicy w pobliżu otrzymają po 10...92 pkt. obrażeń.','Klątwa (czar). (4 sek.) Przerywa następny atak wybranego przeciwnika. Efekt przerwania: 10...92 pkt. obrażeń dla przeciwników w pobliżu.'],
3196=>['Przewidziane Ryzyko (PvP)','Klątwa (czar). Przez 3...12 sek., ataki wybranego przeciwnika zadają +10 obrażeń, ale istnieje 50% szansy, że obrażenia z każdego ataku otrzyma właśnie ten wróg. (Maksymalnie 15...60.)','Klątwa (czar). Wybrany przeciwnik zadaje +10 pkt. obrażeń podczas ataków (3...12 sek.). Istnieje 50% szansy, że obrażenia z każdego ataku (maksymalnie 15...60) otrzyma właśnie ten wróg.'],
3204=>['Ignorowanie Bólu (PvP)','Postawa elitarna. Przez 20 sek. otrzymujesz dodatkowo 90...300 pkt. żywotności oraz 20 pkt. pancerza.','Postawa elitarna. (20 sek.) Otrzymujesz +90...300 do maksymalnej żywotności i +20 do pancerza.'],
3232=>['Uzdrowienie Drużyny (PvP)','Czar. Przywraca 30...75 pkt. żywotności całej drużynie.','Czar. Przywraca żywotność (30...75) całej drużyny.'],
3233=>['Łup Zwycięzcy (PvP)','Elitarna klątwa (czar). Przez najbliższe 3...15 sek., za każdym razem, gdy wybrany wróg zaatakuje lub rzuci czar na istotę mającą mniej żywotności od niego, straci 15...75 pkt. żywotności.','Elitarna klątwa (czar). (3...15 sek.) Powoduje utratę 15...75 pkt. żywotności za każdym razem, gdy wybrany wróg zaatakuje lub rzuci czar na stworzenie mające mniej żywotności od niego.'],
3234=>['Wizje Żalu (PvP)','Elitarna klątwa (czar). Przez 10 sek., wybrany wróg i wszyscy wrogowie w jego bezpośrednim sąsiedztwie otrzymują 10...30 pkt. obrażeń za każdym razem, gdy użyją umiejętności, oraz dodatkowe 5...40 pkt. obrażeń, jeśli nie mają na sobie innej klątwy mesmera.','Elitarna klątwa (czar). Klątwa działa również na wrogów stojących w bezpośrednim sąsiedztwie celu (10 sek.). Otrzymują oni 10...30 pkt. obrażeń za każdym razem, gdy użyją umiejętności, i kolejne 5...40 pkt. obrażeń, jeśli nie ciąży na nich żadna inna klątwa mesmera.'],
3251=>['Lisie Kły (PvP)','Atak drugą ręką. Musi nastąpić po ataku poprzedzającym. Lisich Kłów nie da się zablokować. Po trafieniu zdolność zadaje +10...25 obrażeń.','Atak drugą ręką. Zadaje +10...25 pkt. obrażeń. Nie do zablokowania. Musi nastąpić po ataku poprzedzającym.'],
3252=>['Dzikie Uderzenie (PvP)','Atak drugą ręką. Musi nastąpić po ataku poprzedzającym. W przypadku trafienia atak zadaje +10...35 obrazeń i postawa używana przez cel zostaje zakończona. Nie do zablokowania.','Atak drugą ręką. Zadaje +10...35 pkt. obrażeń. Usuwa postawę wroga. Nie do zablokowania. Musi nastąpić po ataku poprzedzającym.'],
3263=>['Wypędzające Uderzenie (PvP)','Atak wręcz. Jeśli ten atak trafi, zadajesz +10...60 pkt. świętych obrażeń. Zadaje podwójne obrażenia przywołanym stworzeniom.','Atak wręcz. Zadaje 10...60 pkt. świętych obrażeń. Zadaje podwójne obrażenia przywołanym stworzeniom.'],
3264=>['Zamach Podwójnego Księżyca (PvP)','Atak wręcz. Tracisz 1 zaklęcie derwisza i otrzymujesz 10...20 pkt. żywotności. Jeśli stracisz zaklęcie w ten sposób, nie można cię zablokować, atakujesz dwukrotnie, każdy twój cios zadaje 25% obrażeń mniej i otrzymujesz 10...30 pkt. żywotności.','Atak wręcz. Tracisz 1 z zaklęć derwisza. Otrzymujesz 10...20 pkt. żywotności. Efekt usunięcia: nieblokowalny, atakuje podwójnie, każdy atak każdy cios zadaje 25% obrażeń mniej i otrzymujesz 10...30 pkt. żywotności.'],
3265=>['Niepowstrzymywalny Zamach (PvP)','Atak kosą. Zadaje +3...15 pkt. obrażeń i tracisz 1 zaklęcie derwisza. Jeśli stracisz w ten sposób jakieś zaklęcie Niepowstrzymywalny Zamach nie może zostać zablokowany i usuwa jedną postawę.','Atak kosą. Zadaje +3...15 pkt. obrażeń. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Nie do zablokowania, usuwa postawę.'],
3266=>['Nabożny Szturm (PvP)','Atak wręcz. Usuwasz 1 zaklęcie derwisza. Jeśli zaklęcie derwisza zostało usunięte, umiejętność ta odnawia się 75% szybciej, zaś wrogowie w bezpośrednim sąsiedztwie otrzymują 15...40 pkt. obrażeń.','Atak wręcz. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Umiejętność ta odnawia się 75% szybciej, a wrogowie w bezpośrednim sąsiedztwie otrzymują 15...40 pkt. obrażeń.'],
3269=>['Wiodące Dłonie (PvP)','Zaklęcie (czar). Przez 20 sek., twoich kolejnych 0...3 ataków nie można zablokować Kiedy ta umiejętność zostaje uaktywniona, usuwa ślepotę.','Zaklęcie (czar). (20 sek.) Twoje kolejne ataki (0...3) nie mogą zostać zablokowane. Efekt początkowy: Usuwa ślepotę.'],
3270=>['Awatar Dwayny (PvP)','Elitarna forma. Przez 10...90 sek. twoje ataki zadają święte obrażenia. Za każdym razem, gdy używasz umiejętności ofensywnej derwisza, tracisz 1 klątwę. Za każdym razem, gdy tracisz zaklęcie derwisza, odzyskujesz 5...50 pkt. żywotności. Ta umiejętność zostanie wyłączona na 45 sek.','Elitarna forma. (10...90 sek.) Zadajesz święte obrażenia. Za każdym razem, gdy używasz umiejętności ataku derwisza, tracisz 1 klątwę. Przywracasz sobie 5...50 pkt. żywotności, za każdym razem gdy stracisz zaklęcie derwisza. Ta umiejętność zostanie wyłączona na 45 sek.'],
3271=>['Awatar Melandru (PvP)','Elitarna forma. Przez 10...90 sek., masz +100 do żywotności, +30 do pancerza przeciwko żywiołom, a twoje ataki zadają obrażenia od ziemi. Za każdym razem gdy stracisz zaklęcie derwisza, tracisz 2 przypadłości. Umiejętność zostaje zablokowana na 45 sekund.','Elitarna forma. (10...90 sek.) Otrzymujesz +100 do maksymalnej żywotności, +30 do pancerza przeciwko żywiołom, a twoje ataki zadają obrażenia od ziemi. Leczysz u siebie 2 przypadłości za każdym razem, gdy stracisz zaklęcie derwisza. Umiejętność zostaje zablokowana na 45 sekund.'],
3272=>['Mistyczne Uzdrowienie (PvP)','Czar. Odzyskujesz 5...65 pkt. żywotności. Przywracasz także 5...65 żywotności wszystkim członkom drużyny będącym pod wpływem zaklęcia.','Czar. Odzyskujesz 5...65 pkt. żywotności. Przywraca także 5...65 żywotności wszystkim członkom drużyny będącym pod wpływem zaklęcia.'],
3273=>['Sygnet Nabożnej Powściągliwości (PvP)','Sygnet. Tracisz 1 zaklęcie derwisza i powodujesz okulawienie wybranego wroga na 5...15 sek. Jeśli zaklęcie zostanie usunięte, ta umiejętność odnowi się 50% szybciej.','Sygnet. (5...15 sek.) Okulawia wybranego wroga i usuwa 1 z twoich zaklęć derwisza. Efekt usunięcia: Odnawia się 50% szybciej.'],
3289=>['Gorączkowe Sny (PvP)','Elitarna klątwa (czar). Przez 5...15 sek., za każdym razem, kiedy wybrany przeciwnik zaczyna cierpieć na nową przypadłość, wszyscy przeciwnicy w okolicy zaczynają cierpieć na tę samą przypadłość.','Elitarna klątwa (czar). (5...15 sek.) Przeciwnicy w okolicy otrzymują wszystkie nowe przypadłości, które dostaje wybrany wróg.'],
3346=>['Ciernista Aura (PvP)','Zaklęcie błysku (czar). Wszyscy wybrani przeciwnicy zaczynają krwawić przez 5...15 sek. Następnie, przez 30 sek. zaklęcie to nic nie robi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostaną okulawieni na 3...8 sek.','Zaklęcie błysku (czar). (30 sek.) Efekt początkowy: Powoduje krwawienie (5...15 sek.) u pobliskich wrogów. Efekt końcowy: Powoduje okulawienie (3...8 sek.) u pobliskich wrogów.'],
3347=>['Pyłowe Okrycie (PvP)','Zaklęcie błysku (czar). Wszyscy przeciwnicy w pobliżu otrzymują 10...40 pkt. obrażeń od ziemi. Przez 30 sek., twoje ataki zadają obrażenia od ziemi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostaną oślepieni na 1...4 sek.','Zaklęcie błysku (czar). (30 sek.) Twoje ataki zadają obrażenia od ziemi. Efekt początkowy: Zadaje 10...40 obrażeń od ziemi pobliskim wrogom. Efekt końcowy: Wywołuje oślepienie (1...4 sek.) u pobliskich wrogów.'],
3348=>['Pośpiech Lyssy (PvP)','Zaklęcie błysku (czar). Przez 3...15 sek., twoje zaklęcia derwisza odnawiają się o 33% szybciej. Kiedy uaktywnisz to zaklęcie, przerwane zostają akcje wykonywane przez wszystkich przeciwników w bezpośrednim sąsiedztwie. Kiedy to zaklęcie dobiegnie końca, przerwane zostają akcje wykonywane przez wszystkich przeciwników w bezpośrednim sąsiedztwie. 50% szansy na porażkę, chyba że Modlitwy Wiatru są na co najmniej 5 poziomie.','Zaklęcie błysku (czar). (3...15 sek.) Twoje zaklęcia derwisza odnawiają się 33% szybciej. Efekt początkowy: Przerywa akcje wszystkich wrogów w bezpośrednim sąsiedztwie. Efekt końcowy: Przerywa akcje wszystkich wrogów w bezpośrednim sąsiedztwie. (50% szansy na porażkę, chyba że Modlitwy Wiatru są na co najmniej 5 poziomie.)'],
3365=>['Napaść (PvP)','Elitarne zaklęcie błysku (czar). Przez 2...8 sek. atakujesz i zdobywasz adrenalinę 25% szybciej.','Elitarne zaklęcie błysku (czar). (2...8 sek.) Atakujesz i zdobywasz adrenalinę 25% szybciej.'],
3366=>['Serce Furii (PvP)','Postawa. Przez 2...10 sek. atakujesz o 25% szybciej.','Postawa. (2...10 sek.) Atakujesz 25% szybciej.'],
3367=>['Raniące Uderzenie (PvP)','Elitarny atak kosą. Jeśli ten atak dojdzie celu, docelowy wróg zaczyna krwawić przez 5...20 sek. i tracisz 1 zaklęcie derwisza. Jeśli doszło do usunięcia zaklęcia, docelowy wróg otrzymuje także głęboką ranę na 5...20 sek.','Elitarny atak kosą. Wywołuje przypadłość krwawienie (5...20 sek.). Usuwa jedno zaklęcie derwisza. Efekt usunięcia: Powoduje głęboką ranę (5...20 sek.).'],
3368=>['Nabożna Furia (PvP)','Postawa. Usuwa jedno zaklęcie derwisza. Przez 1...5 sek. atakujesz o 25% szybciej. Jeśli zostało usunięte jakieś zaklęcie, postawa ta trwa dwa razy dłużej.','Postawa. (1...5 sek.) Atakujesz 25% szybciej i usuwasz 1 ze swoich zaklęć derwisza. Efekt usunięcia: Postawa ta trwa dwa razy dłużej.'],
3373=>['Iluzja Pośpiechu (PvP)','Zaklęcie (czar). Przez 5...11 sek. poruszasz się o 33% szybciej. Gdy ta zdolność przestanie działać, ulegniesz okaleczeniu na 3 sek.','Zaklęcie (czar). (5...11 sek.) Poruszasz się o 33% szybciej. Efekt zakończenia: ulegasz okaleczeniu (3 sek.)'],
3374=>['Iluzja Bólu (PvP)','Klątwa (czar). Przez 8 s wskazany wróg otrzymuje -3...10 do regeneracji żywotności oraz 3...10 pkt. obrażeń na sekundę. Gdy efekt dobiegnie końca lub zostanie nałożony ponownie, wróg ten zostanie uleczony z 36...120 pkt. obrażeń.','Klątwa (czar). (8 sek.) Cel otrzymuje -3...10 do regeneracji żywotności i otrzymuje 3...10 pkt. obrażeń na sekundę. Efekt zakończenia: cel odzyskuje 36...120 pkt. żywotności. Ponowne nałożenie kończy efekt.'],
3375=>['Aura Przywrócenia (PvP)','Zaklęcie (czar). Przez 60 sekund otrzymujesz 0...1 pkt. energii, a przy każdym rzuceniu czaru odzyskujesz żywotność o wartości 200...400% kosztu energii.','Zaklęcie (czar). (60 sekund.) Otrzymujesz 0...1 pkt. energii, a przy każdym rzuceniu czaru odzyskujesz żywotność o wartości 200...400% kosztu energii.'],
3386=>['Sieć Zakłócenia (PvP)','Klątwa (czar). Przerywa czynność wykonywaną przez cel. Przez 10 sek. cel będzie pod wpływem Sieci Zakłócenia. Gdy efekt ten dobiegnie końca, czynność wykonywana przez wroga zostanie ponownie przerwana.','Klątwa (czar). (10 sek.) Efekt początkowy: przerywa wykonywanie umiejętności. Efekt końcowy: przerywa wykonywanie umiejętności.'],
3396=>['Młot Błyskawic (PvP)','Czar. Wybrany przeciwnik otrzymuje 10...100 pkt. obrażeń od elektryczności. Młot Błyskawic ma 25% penetrację pancerza.','Czar. Zadaje 10...100 pkt. obrażeń od elektryczności. 25% penetracji pancerza.'],
3397=>['Żywiołowy Płomień (PvP)','Zaklęcie (czar). Przez 5...20 sek., za każdym razem, kiedy nałożysz klątwę żywiołu na wybranego przeciwnika, zacznie on płonąć przez 1...2 sek.','Zaklęcie (czar). (5...20 sek.) Powoduje podpalenie (przez 1...2 sek.) za każdym razem, kiedy rzucisz klątwę żywiołu na cel.'],
3398=>['Śliskie Podłoże (PvP)','Czar. Jeśli przeciwnik się porusza lub jest oślepiony, zostaje powalony. (50% szansy na porażkę przy Magii Wody na poziomie 4 lub mniej.)','Czar. Powoduje powalenie, jeżeli przeciwnik jest w ruchu lub jest oślepiony. (50% szansy na porażkę jeśli Magia Wody nie jest na poziomie 5 lub wyższym.)'],
3422=>['Totem Czasu','Elitarna ochrona (czar). Tworzysz Totem Czasu w miejscu, w którym się znajdujesz. Przez 6...20 sek, wszyscy nieduchowi sojusznicy rzucający czary w tym obszarze robią to 15...20% szybciej a ich umiejętności odnawiają się 15...20% szybciej. Umiejętność PvE','Elitarna ochrona (czar). (6...20 sek.) Sojusznicy w zasięgu totemu rzucają czary o 15...20% szybciej i ich zdolności odnawiają się o 15...20% szybciej. Przyjazne duchy nie są objęte tym efektem. Umiejętność PvE'],
3423=>['Złodziej Dusz','Elitarne zaklęcie (czar). Przez 3...30 sek, twoje ataki kosztują cię 15...20 punktów życia i zadają 15...20 więcej obrażeń. Umiejętność PvE','Elitarne zaklęcie (czar). (3...30 sek.) Ataki zadają +15...20 obrażeń i kosztują cię 15...20 punktów życia. Umiejętność PvE'],
3424=>['Ponad Limit','Elitarne zaklęcie (czar). Podczas utrzymywania tego zaklęcia, rzucasz czary 20...50% szybciej i odnawiasz je o 40...80% szybciej ale stale otrzymujesz efekt Przemęczenia. Umiejętność PvE','Elitarne zaklęcie (czar). Czary są rzucane o 20...50% szybciej i odnawiają się o 40...80% szybciej. Podczas działania stale otrzymujesz efekt Przemęczenia. Umiejętność PvE'],
3425=>['Wyrok','Elitarny atak wręcz. Atakujesz cel oraz pobliskich przeciwników. Każdy atak, który trafi zadaje +13...30 Świętych obrażeń i powala atakujących przeciwników. Umiejętność PvE','Elitarny atak wręcz. Zadaje celowi oraz pobliskim przeciwnikom +13...30 Świętych obrażeń. Powoduje powalenie atakujących przeciwników. Umiejętność PvE'],
3426=>['Postawa Siedmiu Broni','Postawa elitarna. Przez 3...20 sek, atrybuty twojej broni są zwiększone o 1...15 i atakujesz o 33 % szybciej. Umiejętność PvE','Postawa elitarna. (3...20 sek.) Atrybuty broni są zwiększone o 1...15. Atakujesz o 33 % szybciej. Umiejętność PvE'],
3427=>['„Razem jako jedność!"','Elitarny okrzyk. Przez 3...15 sek, wszyscy członkowie drużyny w twoim pobliżu lub w pobliżu twojego chowańca zadają +5...15 obrażeń swoimi atakami i otrzymują +1...7 regeneracji zdrowia. Umiejętność PvE','Elitarny okrzyk. (3...15 sek.) Wszyscy członkowie drużyny w twoim pobliżu lub w pobliżu twojego chowańca zadają +5...15 obrażeń i otrzymują +1...7 regeneracji zdrowia. Umiejętność PvE'],
3428=>['Cienista Kradzież','Umiejętność elitarna. Używasz Cienistego Kroku do wybranego przeciwnika. Przez 5...20 sek, atrybuty tego przeciwnika są zmniejszane o 1...5 a twoje zwiększane o 1...5. Ta umiejętność jest zaliczana do Głównego ataku. Umiejętność PvE','Umiejętność elitarna. Używasz Cienistego Kroku do wybranego przeciwnika. Przez 5...20 sek, atrybuty tego przeciwnika są zmniejszane o 1...5 a twoje zwiększane o 1...5. Umiejętność jest zaliczana do Głównego ataku. Umiejętność PvE'],
3429=>['Bronie Trzech Kuźni','Elitarny czar z broni. Przez 3...20 sek, każdy nieduchowy sojusznik w zasięgu słuchu otrzymuje efekt losowego Zaklęcia broni. Umiejętność PvE','Elitarny czar z broni. (3...20 sek.) Sojusznicy w zasięgu słuchu otrzymują efekt losowego Zaklęcia broni. Przyjazne duchy nie są objęte tym efektem. Umiejętność PvE'],
3430=>['Przysięga Zmian','Elitarne zaklęcie (czar). Przez 3...10 sek, otrzymujesz +1...6 regeneracji energii. Ta umiejętność jest automatycznie używana za każdym razem, gdy użyjesz umiejętności innej niż derwisza. Umiejętność PvE','Elitarne zaklęcie (czar). (3...10 sek.) Otrzymujesz +1...6 regeneracji energii. Odnowienie: za każdym razem, gdy użyjesz umiejętności innej niż derwisza. Umiejętność PvE'],
3431=>['Heroiczny Śpiew','Elitarne echo. Przez 3...15 sek, wybrani nieduchowi sojusznicy otrzymują +1...3 do wszystkich atrybutów. To echo jest automatycznie używane za każdym razem, gdy na sojuszniku kończy się efekt okrzyku lub śpiewu. Umiejętność PvE','Elitarne echo. (3...15 sek.) Cel otrzymuje +1...3 do wszystkich atrybutów. Odnowienie: za każdym razem, gdy na sojuszniku kończy się efekt okrzyku lub śpiewu. Nie można użyć na duchach. Umiejętność PvE'],
3437=>['Kosa Farmera (PvP)','Atak kosą. Jeśli atak trafi, zadaje +5...35 pkt. obrażeń. Jeżeli trafisz więcej niż jednego przeciwnika, atak natychmiast się odnawia.','Atak kosą. Zadaje +5...35 pkt. obrażeń. Natychmiast się odnawia, jeżeli trafisz więcej niż jednego przeciwnika.'],
3442=>['Potężny Rzut (PvP)','Atak włócznią. Twoja włócznia leci trzy razy szybciej. Jeśli trafi, zadajesz +10...40 pkt. obrażeń.','Atak włócznią. Zadaje +10...40 pkt. obrażeń. Ta włócznia leci trzy razy szybciej.'],
3443=>['Furia','Postawa. Przez 8 sek. atakujesz o 33% szybciej, ale odnosisz 200...150% obrażeń.','Postawa. (8 sek.) Atakujesz o 33% szybciej. Odnosisz 200...150% obrażeń.'],
3444=>['Sto Ostrzy','Umiejętność elitarna. Przez 15 sek., za każdym razem, kiedy zaatakujesz mieczem, wszyscy przeciwnicy bezpośrednio przy tobie otrzymają po 10...30 pkt. obrażeń ciętych.','Umiejętność elitarna. (15 sek.) Przeciwnikom bezpośrednio przy tobie zadaje po 10...30 pkt. obrażeń ciętych, jeśli atakujesz mieczem.'],
3445=>['Odnowienie Natury','Obrządek natury. Create a level 1...10 spirit. For 30...240 seconds, enchantments and hexes cast by non-spirit creatures take 50...75% longer to cast, and it costs twice as much Energy to maintain enchantments. This spirit dies after 30...240 seconds.','Obrządek natury. Creates a level 1...10 spirit (30...240 second lifespan). For creatures in range, enchantments and Hexes take 50...75% longer to cast and it costs twice as much Energy to maintain enchantments. Does not affect spirits.'],
3446=>['Soul Ignition','Zaklęcie (czar). While you maintain this enchantment, reduce Overcast at a rate of 1...2 per second. You and all adjacent foes are afflicted with burning while this enchantment is active.','Zaklęcie (czar). Reduce Overcast by 1...2 per second. You and all adjacent foes are afflicted with burning.'],
3447=>['Zmartwienie Marnotrawcy','Klątwa (czar). Po 3 sek. wybrany przeciwnik odniesie 20...100 pkt. obrażeń, a wszyscy sąsiadujący z nim wrogowie odniosą 75% tych obrażeń. Jeśli wybrany przeciwnik zdoła użyć umiejętności, Zmartwienie Marnotrawcy przestanie działać i nie zadaje obrażeń.','Klątwa (czar). (3 sek.). Efekt końcowy: zadaje 20...100 pkt. obrażeń przeciwnikowi i 75% tych obrażeń sąsiadującym z nim wrogom. Nie ma efektu i kończy się wcześniej, jeżeli wybrany przeciwnik używa umiejętności.'],
3448=>['Pokój i Harmonia','Elitarne zaklęcie (czar). Wybrany sojusznik traci klątwy i przypadłości w liczbie 0...4. Przez 1...3 sek. przypadłości i klątwy na tym sojuszniku trwają o 90% krócej. Wszystkie twoje umiejętności związane z Modlitwami Ofensywnymi zostają zablokowane na 20 sek.','Elitarne zaklęcie (czar). Wybrany sojusznik traci klątwy i przypadłości w liczbie 0...4. Przypadłości i klątwy na tym sojuszniku trwają o 90% krócej (1...3 sek.). Wyłącza twoje umiejętności Modlitw Ofensywnych (20 sek.).'],
3449=>['Uderzenie Obrońcy','Atak wręcz. Jeśli atak trafi przeciwnika w ruchu, zadajesz 10...40 pkt. dodatkowych obrażeń.','Atak wręcz. Zadaje +10...40 pkt. obrażeń, jeżeli cel się porusza.'],
3450=>['Okulawiający Strzał','Elitarny strzał z łuku. Jeśli Okulawiający Strzał trafi, twój cel zostanie okulawiony na 4...14 sek. Tego ataku nie można zablokować.','Elitarny strzał z łuku. Nie do zablokowania. Powoduje okulawienie (4...14 sek.).'],
3451=>['Ryk Otyugha','Okrzyk. Przez 5...15 sek., twój zwierzęcy towarzysz posiada +24 pkt. pancerza, dodatkowo jego ataków nie można zablokować.','Okrzyk. (5...15 sek.) Twój zwierzęcy towarzysz ma +24 pkt. pancerza, a jego ataków nie można blokować.'],
3452=>['Całun Cienia','Elitarna klątwa (czar). Przez 2...7 sek. wybrany przeciwnik nie może być celem zaklęć.','Elitarna klątwa (czar). (2...7 sek.) Wybrany przeciwnik nie może być celem zaklęć.'],
3453=>['Pęd','Postawa. Przez 3 sek. biegasz o 50% szybciej. Każde 2 pkt. przydzielone do Sztuki Cienia skracają odnawianie o 1 sek. (maks. 6 sek.).','Postawa. (3 sek.) Poruszasz się o 50% szybciej. Każde 2 pkt. przydzielone do Sztuki Cienia skracają odnawianie o 1 sek. (maks. 6 sek.).'],
3454=>['Uzdrawiający Strażnik','Zaklęcie (czar). Przez 1...4 sek., wszyscy członkowie drużyny w zasięgu słuchu mają 75% szans na blokowanie ataków. Jeśli atak zostanie zablokowany, wszyscy sojusznicy w zasięgu słuchu odzyskują 10...35 pkt. żywotności, a Uzdrawiający Strażnik przestaje działać.','Zaklęcie (czar). (1...4 sek.) Członkowie drużyny w zasięgu słuchu mają 75% szans na zablokowanie ataków. Efekt zablokowania: Sojusznicy w zasięgu słuchu odzyskują 10...35 pkt. żywotności, a Uzdrawiający Strażnik przestaje działać.'],
3455=>['Skuteczne Uderzenie','Atak młotem. Jeśli Skuteczne Uderzenie trafi, zadajesz +5...20 pkt. obrażeń i otrzymujesz 2...4 pkt. energii. Jeśli przeciwnik był osłabiony, ataku tego nie można zablokować.','Atak młotem. Zadaje +5...20 pkt. obrażeń, a ty otrzymujesz 2...4 pkt. energii. Nie do zablokowania, jeżeli wybrany przeciwnik jest osłabiony.'],
3456=>['"Tchórz!"','Elitarny okrzyk. Jeśli przeciwnik się porusza, zostaje powalony.','Elitarny okrzyk. Powoduje powalenie, jeżeli wybrany przeciwnik jest w ruchu.'],
3457=>['Zastawa Obrońcy','Umiejętność. Przez 4...8 sek., sojusznicy bezpośrednio przy tobie mają 75% szans na blokowanie ataków. Zastawa Obrońcy skończy się, jeśli się poruszysz.','Umiejętność. (4...8 sek.) Sojusznicy w bezpośredniej odległości mają 75% szans na blokowanie. Przestanie działać, jeśli się ruszysz.'],
3458=>['Pierwotny Szał','Postawa elitarna. Przez 1...9 sek. atakujesz 33% szybciej i poruszasz się 33% szybciej, ale odnosisz 200...150% obrażeń.','Postawa elitarna. (1...9 sek.) Atakujesz 33% szybciej i poruszasz się 33% szybciej. Odnosisz 200...150% obrażeń.'],
3459=>['Strzał Melandru','Elitarny strzał z łuku. Jeśli Strzał Melandru trafi, przeciwnik zaczyna krwawić przez 5...25 sek. Jeśli trafiony zostanie powalony lub poruszający się przeciwnik , to otrzyma +10...25 pkt. obrażeń i będzie okulawiony przez 5...15 sek.','Elitarny strzał z łuku. Wywołuje krwawienie (5...25 sek.). Zadaje +10...25 pkt. obrażeń oraz powoduje okulawienie (5...15 sek.), jeżeli twój cel się porusza lub jest powalony.'],
3460=>['Spokój','Obrządek natury. Tworzysz 1...10 poziomowego ducha. Zaklęcia rzucane przez stworzenia nie-duchy w jego zasięgu kończą się o 10...30% szybciej. Ten duch ginie po 15...120 sek.','Obrządek natury. Tworzy ducha na poziomie 1...10 (czas życia 15...120 sek.). Zaklęcia na stworzeniach w zasięgu przestają działać o 10...30% szybciej. Nie działa na duchy.'],
3461=>['Skręcenie Duszy','Umiejętność elitarna. Przez 5...45 sek. twoje rytuały spętania kosztują 15 pkt. energii mniej (minimalnie 5) i odnawiają się o 25...50% szybciej. Skręcenie Duszy kończy się po przeprowadzeniu określonej liczby rytuałów spętania (1...3).','Umiejętność elitarna. (5...45 sek.) Twoje rytuały spętania kosztują 15 pkt. energii mniej (minimalnie 5) i odnawiają się o 25...50% szybciej. Kończy się po przeprowadzeniu określonej liczby rytuałów spętania (1...3).'],
3462=>['Prowadzony Oręż','Czar z broni. Przez 4...10 sek., ciosy tego sojusznika nie mogą być blokowane.','Czar z broni. (4...10 sek.) Ataków nie można blokować.'],
3463=>['Dokuczliwość','Elitarny czar. Jeżeli wybrany przeciwnik używa umiejętności, aktualnie wykonywana czynność tego przeciwnika i czynność każdego przeciwnika w okolicy zostają przerwane. Dodatkowo wykradasz 0...5 energii od wszystkich wrogów w okolicy.','Elitarny czar. Przerywa umiejętność. Efekt przerwania: przerywasz także czynności innych wrogów w okolicy i wykradasz 0...5 energii od wszystkich wrogów w okolicy.'],
3464=>['Atak na Oślep','Postawa. Przez 1...15 sek. atakujesz o 33% szybciej, ale poruszasz się o 33% wolniej. Kończy się, gdy użyjesz umiejętności ataku dystansowego.','Postawa. (1...15 sek.) Atakujesz o 33% szybciej. Kończy się, gdy użyjesz umiejętności ataku dystansowego. Poruszasz się o 33% wolniej.'],
3465=>['Uderzenie w Szarży','Postawa elitarna. Przez 1...10 sek. biegasz o 33% szybciej. Twoje kolejne trafienie wręcz zadaje +10...80 pkt. obrażeń, a ta postawa przestaje działać. Postawa przestanie działać, kiedy użyjesz umiejętności.','Postawa elitarna. (1...10 sek.) Poruszasz się o 33% szybciej i w następnym celnym ataku wręcz zadajesz +10...80 pkt. obrażeń. Przestanie działać, kiedy trafisz lub jeśli użyjesz umiejętności.'],
3466=>['Rozwścieczający Żar','Elitarny obrządek natury. Create a level 1...10 spirit. Non-spirit creatures within its range gain adrenaline 33...66% as fast. This spirit dies after 30...120 seconds.','Elitarny obrządek natury. Creates a level 1...10 spirit (30...120 second lifespan). Adrenaline gain increased by 33...66% for creatures in range.'],
3467=>['Mistyczne Zepsucie','Zaklęcie błysku (czar). Wszyscy wrogowie w bezpośrednim sąsiedztwie cierpią przez 2...6 sek. z powodu choroby. Przez 20 sek. nic się nie dzieje. Czas trwania choroby zostaje podwojony, jeśli w momencie aktywacji tej umiejętności znajdujesz się pod wpływem zaklęcia. Kiedy zaklęcie to dobiegnie końca, wszyscy członkowie drużyny w zasięgu słuchu zostają wyleczeni z chorób.','Zaklęcie błysku (czar). (20 sek.) Efekt początkowy: Wszyscy wrogowie w bezpośrednim sąsiedztwie zaczynają chorować (2...6 sek). Podwojony czas trwania, jeśli już znajdujesz się pod wpływem zaklęcia. Efekt końcowy: Członkowie drużyny w zasięgu słuchu przestają chorować.'],
3468=>['Uścisk Grabieżcy','Zaklęcie błysku (czar). Przez 5...20 sek. ataki wręcz przeciwko poruszającym się wrogom dodatkowo okulawiają ich na 2...9 sek. Kiedy rzucisz to zaklęcie, przestaje działać na ciebie okulawienie i 1 inna przypadłość. Zaklęcie to kończy się, kiedy okulawisz przeciwnika 1...3 razy.','Zaklęcie błysku (czar). (5...20 sek.) Atakowanie wręcz poruszających się przeciwników dodatkowo ich okulawia. Początkowy efekt: przestaje na ciebie działać okulawienie i 1 inna przypadłość. Kończy się, gdy okulawisz przeciwników 1...3 razy.'],
3469=>['Okrycie Mirażem','Zaklęcie błysku (czar). Przez 1...7 sek., otrzymujesz dodatkowe 30...60% szans na zablokowanie ataków. Gdy rzucisz to zaklęcie, wszyscy pobliscy wrogowie zostaną trafieni za 10...40 pkt. obrażeń od ziemi.','Zaklęcie błysku (czar). (1...7 sek.) Masz 30...60% szans na blok. Efekt początkowy: Zadaje 10...40 obrażeń od ziemi pobliskim wrogom.'],
3470=>['Ulotna Stabilność','Zaklęcie błysku (czar). Przez 2...8 sek., nie możesz zostać powalony i poruszasz się 25% szybciej. Zaklęcie to kończy się przed czasem, jeśli zapobiegnie powaleniu.','Zaklęcie błysku (czar). (2...8 sek.) Nie możesz zostać powalony i poruszasz się 25% szybciej. Kończy się, jeśli zapobiegnie powaleniu.'],
3471=>['Nabożne Przywrócenie','Czar. Otrzymujesz 80...150 żywotności i usuwasz 1 zaklęcie derwisza. Jeśli usunięto w ten sposób zaklęcie, tracisz także klątwy w liczbie 1.','Czar. Otrzymujesz 80...150 żywotności i usuwasz 1 zaklęcie derwisza. Efekt usunięcia: Tracisz klątwy w liczbie 1.'],
3472=>['Wirująca Szarża','Zaklęcie błysku (czar). Przez 1...6 sek., poruszasz się o 33% szybciej niż normalnie. Kiedy następnym razem trafisz wroga, wszyscy pozostali przeciwnicy w pobliżu otrzymują 10...50 pkt. obrażeń od zimna, a zaklęcie dobiega końca.','Zaklęcie błysku (czar). (1...6 sek.) Poruszasz się 33% szybciej. Zadaje 10...50 obrażeń od zimna wszystkim wrogom w pobliżu, kiedy następnym razem trafisz jakiegoś przeciwnika, a to zaklęcie się skończy.'],
3473=>['Rozcinacz Aur','Atak wręcz. Jeśli atak trafi, powoduje krwawienie przez 5...15 sek. Jeśli znajdujesz się pod wpływem zaklęcia, atak powoduje także pęknięcie zbroi przez 1...10 sek.','Atak wręcz. (5...15 sek.) Wywołuje krwawienie. Powoduje także pęknięcie zbroi (1...10 sek.), jeśli znajdujesz się pod wpływem zaklęcia.'],
];}
